INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38347, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卒業は、人生の分岐を立つという重い選択だった。", "corrected_sentence": "卒業は、人生の分岐に立つという重い選択だった。", "error_description": "「立つ」は場所を「に」で示す。「分岐を立つ」は「を」が誤り。正しくは「分岐に立つ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38347, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の人生は、あの夏の決断で分岐された。", "corrected_sentence": "彼女の人生は、あの夏の決断で分岐した。", "error_description": "「分岐する」は自動詞なので受け身にできない。「分岐された」は誤り。正しくは「分岐した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f88fa1-f980-4b9e-84c4-791813dcf5b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38348, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「車を駆る」の〈を〉。走らせる対象の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す〈に〉で、目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す〈へ〉で、目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す〈と〉で、ここでは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「車を駆る」の〈を〉。走らせる対象の目的語を示す。", "に": "位置や相手を表す〈に〉で、目的語にはならない。", "へ": "方向を表す〈へ〉で、目的語にはならない。", "と": "共同や引用を表す〈と〉で、ここでは意味が通らない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38348, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「馬車を駆る」の〈を〉。走らせる乗り物を示す目的語。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の〈の〉で、目的語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す〈から〉で、目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の〈より〉で、ここでは文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「馬車を駆る」の〈を〉。走らせる乗り物を示す目的語。", "の": "連体修飾の〈の〉で、目的語にはならない。", "から": "起点を表す〈から〉で、目的語にはならない。", "より": "比較の〈より〉で、ここでは文が成り立たない。"}, "error_tags": {"の": "連体修飾", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38348, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "うまやくるまを、はやくはしらせること。", "primary_collocate": null, "pronunciation": "かる", "ipa": "kaɾɯ", "syllable_count": 2, "sentences": [{"text": "武士は馬を駆って、敵の陣地へ向かった。", "target_word": "駆って", "complexity_tier": "T3", "furigana": "武士[ぶし]は馬[うま]を駆[か]って、敵[てき]の陣地[じんち]へ向[む]かった。", "sentence_source": "generated"}, {"text": "彼は夜の高速道路で車を駆り、友人の待つ町へ急いだ。", "target_word": "駆り", "complexity_tier": "T3", "furigana": "彼[かれ]は夜[よる]の高速道路[こうそくどうろ]で車[くるま]を駆[か]り、友人[ゆうじん]の待[ま]つ町[まち]へ急[いそ]いだ。", "sentence_source": "generated"}, {"text": "荒れた山道でも、父は軽トラックを駆って畑まで行く。", "target_word": "駆って", "complexity_tier": "T3", "furigana": "荒[あ]れた山道[やまみち]でも、父[ちち]は軽[けい]トラックを駆[か]って畑[はたけ]まで行[い]く。", "sentence_source": "generated"}, {"text": "馬を駆るには、長い練習と強い体力が必要だ。", "target_word": "駆る", "complexity_tier": "T3", "furigana": "馬[うま]を駆[か]るには、長[なが]い練習[れんしゅう]と強[つよ]い体力[たいりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "王は戦車を駆って、広い野原を一気に走り抜けた。", "target_word": "駆って", "complexity_tier": "T3", "furigana": "王[おう]は戦車[せんしゃ]を駆[か]って、広[ひろ]い野原[のはら]を一気[いっき]に走[はし]り抜[ぬ]けた。", "sentence_source": "generated"}, {"text": "少年はバイクを駆り、海沿いの道を朝まで走り続けた。", "target_word": "駆り", "complexity_tier": "T3", "furigana": "少年[しょうねん]はバイクを駆[か]り、海沿[うみぞ]いの道[みち]を朝[あさ]まで走[はし]り続[つづ]けた。", "sentence_source": "generated"}, {"text": "使者は夜どおし馬を駆って、都に知らせを届けた。", "target_word": "駆って", "complexity_tier": "T3", "furigana": "使者[ししゃ]は夜[よ]どおし馬[うま]を駆[か]って、都[みやこ]に知[し]らせを届[とど]けた。", "sentence_source": "generated"}, {"text": "雪の中でも馬車を駆る御者は、少しも速度を落とさなかった。", "target_word": "駆る", "complexity_tier": "T3", "furigana": "雪[ゆき]の中[なか]でも馬車[ばしゃ]を駆[か]る御者[ぎょしゃ]は、少[すこ]しも速度[そくど]を落[お]とさなかった。", "sentence_source": "generated"}, {"text": "彼女はスポーツカーを駆って、サーキットで最速のタイムを出した。", "target_word": "駆って", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はスポーツカーを駆[か]って、サーキットで最速[さいそく]のタイムを出[だ]した。", "sentence_source": "generated"}, {"text": "馬を駆れば、半日で隣の国まで着くだろう。", "target_word": "駆れ", "complexity_tier": "T3", "furigana": "馬[うま]を駆[か]れば、半日[はんにち]で隣[となり]の国[くに]まで着[つ]くだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駆る", "label": "終止形・連体形"}, {"form": "駆ら", "label": "未然形（駆らない）"}, {"form": "駆り", "label": "連用形（駆ります）"}, {"form": "駆って", "label": "て形"}, {"form": "駆れ", "label": "仮定形（駆れば）"}], "register": "文章語", "sense_fingerprint": "馬や車などの乗り物を操って速く走らせる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38348, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "駆って", "is_correct": true, "explanation": "て形。「馬を駆って」と続けて、乗って走らせた手段を表す。"}, {"text": "駆ら", "is_correct": false, "explanation": "未然形。「駆らて」と続かず、文が成り立たない。"}, {"text": "駆れ", "is_correct": false, "explanation": "仮定形。「〜れば」の意味になり、文が続かない。"}, {"text": "駆られ", "is_correct": false, "explanation": "受身形。「馬を駆られ」は、馬を目的語に取る動詞の受身として成り立たない。"}], "explanations": {"駆って": "て形。「馬を駆って」と続けて、乗って走らせた手段を表す。", "駆ら": "未然形。「駆らて」と続かず、文が成り立たない。", "駆れ": "仮定形。「〜れば」の意味になり、文が続かない。", "駆られ": "受身形。「馬を駆られ」は、馬を目的語に取る動詞の受身として成り立たない。"}, "sentence_index": 0, "correct_answer": "駆って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はバットを駆って、ボールを遠くへ飛ばした。", "explanation": "ここは〈振る〉の意味。バットを振る動作は〈振る〉で表す。〈駆る〉は走らせる対象に使う語で、バットには使わない。"}, {"text": "彼は重い機械を駆って、一日中工場で働いた。", "explanation": "ここは〈操作する〉の意味。機械の操作は〈操る〉で言う。〈駆る〉は走らせる対象に使う語。"}, {"text": "彼は櫂を駆って、川を三時間下った。", "explanation": "ここは〈漕ぐ〉の意味。櫂で舟を進める動作は〈漕ぐ〉で表す。〈駆る〉は走らせる対象に使う語で、櫂には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38348, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駆って", "is_correct": true, "explanation": "て形。「馬を駆って」と続けて、乗って走らせた手段を表す。"}, {"text": "駆る", "is_correct": false, "explanation": "辞書形。読点で続けると文が切れ、手段を表せない。"}, {"text": "駆ろ", "is_correct": false, "explanation": "意志形。「馬を駆ろ、」は文の形が合わない。"}, {"text": "駆られ", "is_correct": false, "explanation": "受身形。「馬を駆られ、」は文が成り立たない。"}], "explanations": {"駆って": "て形。「馬を駆って」と続けて、乗って走らせた手段を表す。", "駆る": "辞書形。読点で続けると文が切れ、手段を表せない。", "駆ろ": "意志形。「馬を駆ろ、」は文の形が合わない。", "駆られ": "受身形。「馬を駆られ、」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "駆って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は筆を駆って、長い手紙を一晩で書き上げた。", "explanation": "ここは〈書く〉の意味。筆で文字を書く動作は〈書く〉で表す。〈駆る〉は走らせる対象に使う語で、筆には使わない。"}, {"text": "荷物を駆れば、半日で隣の国まで着くだろう。", "explanation": "ここは〈運ぶ〉の意味。荷物の運搬は〈運ぶ〉で言う。〈駆る〉は動物や乗り物を走らせる語で、荷物とは結びつかない。"}, {"text": "彼女は箒を駆って、庭の落ち葉を一日中掃いた。", "explanation": "ここは〈掃く〉の意味。箒で掃く動作は〈掃く〉で表す。〈駆る〉は走らせる対象に使う語で、箒には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38348, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は軽トラックを駆るて、朝早く畑まで行く。", "corrected_sentence": "父は軽トラックを駆って、朝早く畑まで行く。", "error_description": "〈駆る〉のて形は「駆って」。「駆るて」は活用形が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "駆り", "is_correct": true, "explanation": "連用形。中止の形で、後ろに続けて二つの動作を述べる。"}, {"text": "駆る", "is_correct": false, "explanation": "辞書形。読点で中止すると文が途切れ、続きが不自然。"}, {"text": "駆れ", "is_correct": false, "explanation": "仮定形。「〜れば」になり、過去の動作を述べる文と合わない。"}, {"text": "駆ら", "is_correct": false, "explanation": "未然形。ここでは文が成り立たない。"}], "correct_form": "駆り", "base_form": "駆る", "form_label": "連用形（中止）", "sentence_index": 1, "explanations": {"駆り": "連用形。中止の形で、後ろに続けて二つの動作を述べる。", "駆る": "辞書形。読点で中止すると文が途切れ、続きが不自然。", "駆れ": "仮定形。「〜れば」になり、過去の動作を述べる文と合わない。", "駆ら": "未然形。ここでは文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38348, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "少年はバイクを駆らて、夜明けまで海沿いの道を走った。", "corrected_sentence": "少年はバイクを駆って、夜明けまで海沿いの道を走った。", "error_description": "〈駆る〉のて形は「駆って」。「駆らて」は未然形に「て」が続くため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "駆る", "is_correct": true, "explanation": "辞書形（連体形）。「駆る御者」と名詞を修飾する形で、文の意味に合う。"}, {"text": "駆り", "is_correct": false, "explanation": "連用形。名詞を修飾できず、「駆り御者は」では文が続かない。"}, {"text": "駆って", "is_correct": false, "explanation": "て形。名詞を修飾できず、文が成り立たない。"}, {"text": "駆ろ", "is_correct": false, "explanation": "意志形。名詞を修飾できず、文の形が合わない。"}], "correct_form": "駆る", "base_form": "駆る", "form_label": "終止形・連体形（名詞を修飾）", "sentence_index": 7, "explanations": {"駆る": "辞書形（連体形）。「駆る御者」と名詞を修飾する形で、文の意味に合う。", "駆り": "連用形。名詞を修飾できず、「駆り御者は」では文が続かない。", "駆って": "て形。名詞を修飾できず、文が成り立たない。", "駆ろ": "意志形。名詞を修飾できず、文の形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38349, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「好奇心に駆られる」の〈に〉。感情や衝動が動かす対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の〈を〉は、受身の文の感情の対象には使えず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す〈と〉で、ここでは意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す〈へ〉で、感情の対象を示す位置には合わない。"}], "correct_answer": "に", "explanations": {"に": "「好奇心に駆られる」の〈に〉。感情や衝動が動かす対象を示す。", "を": "目的語の〈を〉は、受身の文の感情の対象には使えず、文が成り立たない。", "と": "共同や引用を表す〈と〉で、ここでは意味が通らない。", "へ": "方向を表す〈へ〉で、感情の対象を示す位置には合わない。"}, "error_tags": {"を": "目的語の誤用", "と": "共同・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38349, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「馬を駆る」の〈を〉。走らせる対象の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す〈に〉で、目的語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す〈から〉で、目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の〈より〉で、ここでは文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「馬を駆る」の〈を〉。走らせる対象の目的語を示す。", "に": "位置や相手を表す〈に〉で、目的語にはならない。", "から": "起点を表す〈から〉で、目的語にはならない。", "より": "比較の〈より〉で、ここでは文が成り立たない。"}, "error_tags": {"に": "位置・相手", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38349, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "動物や乗り物を走らせる。また、人を強く促して急がせる。", "primary_collocate": null, "pronunciation": "かる", "ipa": "kaɾɯ", "syllable_count": 2, "sentences": [{"text": "しかし、窓辺に佇む幼き我が子の瞳は、白銀に覆われた庭先へと注がれ、抑えきれない生命の衝動に駆られていた。", "target_word": "駆ら", "complexity_tier": "T3", "furigana": "しかし、窓辺[まどべ]に佇[たたず]む幼[おさな]き我[わ]が子[こ]の瞳[ひとみ]は、白銀[はくぎん]に覆[おお]われた庭先[にわさき]へと注[そそ]がれ、抑[おさ]えきれない生命[せいめい]の衝動[しょうどう]に駆[か]られていた。", "sentence_source": "mined"}, {"text": "好奇心に駆られた弟は、立ち入り禁止の扉を開けてしまった。", "target_word": "駆られ", "complexity_tier": "T3", "furigana": "好奇心[こうきしん]に駆[か]られた弟[おとうと]は、立[た]ち入[い]り禁止[きんし]の扉[とびら]を開[あ]けてしまった。", "sentence_source": "generated"}, {"text": "騎士は白い馬を駆って、森の中の道を急いだ。", "target_word": "駆って", "complexity_tier": "T3", "furigana": "騎士[きし]は白[しろ]い馬[うま]を駆[か]って、森[もり]の中[なか]の道[みち]を急[いそ]いだ。", "sentence_source": "generated"}, {"text": "彼は父の古い車を駆って、海まで一人で出かけた。", "target_word": "駆って", "complexity_tier": "T3", "furigana": "彼[かれ]は父[ちち]の古[ふる]い車[くるま]を駆[か]って、海[うみ]まで一人[ひとり]で出[で]かけた。", "sentence_source": "generated"}, {"text": "焦りに駆られた私は、確認もせずに書類を出してしまった。", "target_word": "駆られ", "complexity_tier": "T3", "furigana": "焦[あせ]りに駆[か]られた私[わたし]は、確認[かくにん]もせずに書類[しょるい]を出[だ]してしまった。", "sentence_source": "generated"}, {"text": "罪の意識に駆られ、彼はついに本当のことを話した。", "target_word": "駆られ", "complexity_tier": "T3", "furigana": "罪[つみ]の意識[いしき]に駆[か]られ、彼[かれ]はついに本当[ほんとう]のことを話[はな]した。", "sentence_source": "generated"}, {"text": "恐怖に駆られると、人は冷静に考えられなくなる。", "target_word": "駆られ", "complexity_tier": "T3", "furigana": "恐怖[きょうふ]に駆[か]られると、人[ひと]は冷静[れいせい]に考[かんが]えられなくなる。", "sentence_source": "generated"}, {"text": "隊長は馬を駆り、一番に丘の上へ着いた。", "target_word": "駆り", "complexity_tier": "T3", "furigana": "隊長[たいちょう]は馬[うま]を駆[か]り、一番[いちばん]に丘[おか]の上[うえ]へ着[つ]いた。", "sentence_source": "generated"}, {"text": "馬を駆るのが得意な祖父は、今でも乗馬の話になると熱くなる。", "target_word": "駆る", "complexity_tier": "T3", "furigana": "馬[うま]を駆[か]るのが得意[とくい]な祖父[そふ]は、今[いま]でも乗馬[じょうば]の話[はなし]になると熱[あつ]くなる。", "sentence_source": "generated"}, {"text": "彼女は強い使命感に駆られて、遠い村まで薬を届けに行った。", "target_word": "駆られ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は強[つよ]い使命感[しめいかん]に駆[か]られて、遠[とお]い村[むら]まで薬[くすり]を届[とど]けに行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "駆る", "label": "終止形・連体形"}, {"form": "駆ら", "label": "未然形（駆らない・駆られる）"}, {"form": "駆り", "label": "連用形（駆ります）"}, {"form": "駆って", "label": "て形"}, {"form": "駆れ", "label": "仮定形（駆れば）"}, {"form": "駆られる", "label": "受身形"}], "register": "文章語", "sense_fingerprint": "馬や車を走らせる。また、感情や衝動が人を強く突き動かす。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f31001-e24e-4d36-97fe-2a4a88c33e43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38349, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "駆ら", "is_correct": true, "explanation": "未然形。「れていた」と続いて「駆られていた」となり、衝動に動かされた状態を表す。"}, {"text": "駆る", "is_correct": false, "explanation": "辞書形。「れていた」と続けると形が成り立たない。"}, {"text": "駆ろ", "is_correct": false, "explanation": "意志・命令の形。「れていた」とは続かない。"}, {"text": "駆れ", "is_correct": false, "explanation": "仮定形。「れていた」とは続かず、文が成り立たない。"}], "explanations": {"駆ら": "未然形。「れていた」と続いて「駆られていた」となり、衝動に動かされた状態を表す。", "駆る": "辞書形。「れていた」と続けると形が成り立たない。", "駆ろ": "意志・命令の形。「れていた」とは続かない。", "駆れ": "仮定形。「れていた」とは続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "駆ら"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は庭の芝を駆って、きれいに揃えた。", "explanation": "ここは〈刈る〉（草を切る）の意味。〈駆る〉は乗り物や動物を走らせる語で、芝を切る動作には合わない。"}, {"text": "彼は重い機械を駆って、一日中工場で働いた。", "explanation": "ここは〈操作する〉の意味。機械の操作は〈操る〉で言う。〈駆る〉は走らせる対象に使う語。"}, {"text": "彼は櫂を駆って、川を三時間下った。", "explanation": "ここは〈漕ぐ〉の意味。櫂で舟を進める動作は〈漕ぐ〉で表す。〈駆る〉は走らせる対象に使う語で、櫂には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38349, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駆られ", "is_correct": true, "explanation": "受身形（連用形）。「ると」に続けて、衝動に動かされた状態を一般的に述べる。"}, {"text": "駆って", "is_correct": false, "explanation": "て形。「ると」と続かず、文が成り立たない。"}, {"text": "駆る", "is_correct": false, "explanation": "辞書形。「ると」に続かず、文が成り立たない。"}, {"text": "駆らない", "is_correct": false, "explanation": "否定形。「ると」と続かず、文の意味も合わない。"}], "explanations": {"駆られ": "受身形（連用形）。「ると」に続けて、衝動に動かされた状態を一般的に述べる。", "駆って": "て形。「ると」と続かず、文が成り立たない。", "駆る": "辞書形。「ると」に続かず、文が成り立たない。", "駆らない": "否定形。「ると」と続かず、文の意味も合わない。"}, "sentence_index": 6, "correct_answer": "駆られ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "王は筆を駆って、夕方まで手紙を書き続けた。", "explanation": "ここは〈書く〉の意味。筆で文字を書く動作は〈書く〉で表す。〈駆る〉は走らせる対象に使う語で、筆には使わない。"}, {"text": "彼女は荷物を駆って、遠い村まで薬を届けに行った。", "explanation": "ここは〈運ぶ〉の意味。荷物を運ぶ動作は〈運ぶ〉で表す。〈駆る〉は動物や乗り物を走らせる語。"}, {"text": "彼女は太鼓を駆って、夜中まで村の祭りを盛り上げた。", "explanation": "ここは〈叩く〉の意味。太鼓を打つ動作は〈叩く〉で表す。〈駆る〉は走らせる対象に使う語で、太鼓には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38349, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は高速道路で車を駆るて、友人の家へ急いだ。", "corrected_sentence": "彼は高速道路で車を駆って、友人の家へ急いだ。", "error_description": "〈駆る〉のて形は「駆って」。「駆るて」は活用形が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "駆られ", "is_correct": true, "explanation": "受身形（連用形）。「た」に続けて、衝動に動かされた状態を表す。"}, {"text": "駆ら", "is_correct": false, "explanation": "未然形。「た」に続かず、文が成り立たない。"}, {"text": "駆ろ", "is_correct": false, "explanation": "意志・命令の形。「た」に続かない。"}, {"text": "駆る", "is_correct": false, "explanation": "辞書形。「た」に続かず、受身の意味にもならない。"}], "correct_form": "駆られ", "base_form": "駆る", "form_label": "受身形（連用形・〜た）", "sentence_index": 1, "explanations": {"駆られ": "受身形（連用形）。「た」に続けて、衝動に動かされた状態を表す。", "駆ら": "未然形。「た」に続かず、文が成り立たない。", "駆ろ": "意志・命令の形。「た」に続かない。", "駆る": "辞書形。「た」に続かず、受身の意味にもならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38349, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い使命感に駆られを、友人は山道を走り続けた。", "corrected_sentence": "強い使命感に駆られて、友人は山道を走り続けた。", "error_description": "〈駆られ〉の後に続く助詞は「て」。目的語の「を」は、ここでは文の形が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "駆り", "is_correct": true, "explanation": "連用形。読点で中止して後ろに続ける形で、馬を走らせた動作を表す。"}, {"text": "駆れ", "is_correct": false, "explanation": "仮定形・命令形。「馬を駆れ、」と続けると命令になり、文が成り立たない。"}, {"text": "駆ろう", "is_correct": false, "explanation": "意志形。「馬を駆ろう、」と続けると意志の文になり、文が成り立たない。"}, {"text": "駆らない", "is_correct": false, "explanation": "否定形。「馬を駆らない、」と続けると否定の意味になり、一番に着いた内容と矛盾して文が成り立たない。"}], "correct_form": "駆り", "base_form": "駆る", "form_label": "連用形（中止）", "sentence_index": 7, "explanations": {"駆り": "連用形。読点で中止して後ろに続ける形で、馬を走らせた動作を表す。", "駆れ": "仮定形・命令形。「馬を駆れ、」と続けると命令になり、文が成り立たない。", "駆ろう": "意志形。「馬を駆ろう、」と続けると意志の文になり、文が成り立たない。", "駆らない": "否定形。「馬を駆らない、」と続けると否定の意味になり、一番に着いた内容と矛盾して文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f74069d6-6885-444a-ab73-e4da8b3095d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38350, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「レモンを」の形で、足す対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「レモンが足して」では主語と動作が合わない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す。「レモンに足して」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。ここでは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「レモンを」の形で、足す対象を示す。", "が": "主語を示す。「レモンが足して」では主語と動作が合わない。", "に": "場所や相手を示す。「レモンに足して」では意味が通らない。", "へ": "方向を示す。ここでは意味が通らない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38350, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「いちごを」の形で、足す対象を示す。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「いちごから足して」とは言わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。ここでは続かない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す。「いちごの足して」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「いちごを」の形で、足す対象を示す。", "から": "起点を示す。「いちごから足して」とは言わない。", "より": "比較を示す。ここでは続かない。", "の": "所属や修飾を示す。「いちごの足して」では文が成り立たない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38350, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものに、さらに別のものを加えること。", "primary_collocate": null, "pronunciation": "たす", "ipa": "tasɯ", "syllable_count": 2, "sentences": [{"text": "パンの上にチーズを足して、オーブンで焼きました。", "target_word": "足して", "complexity_tier": "T3", "furigana": "パン[ぱん]の上[うえ]にチーズを足[た]して、オーブンで焼[や]きました。", "sentence_source": "generated"}, {"text": "お皿の上に、レモンを足してください。", "target_word": "足して", "complexity_tier": "T3", "furigana": "お皿[さら]の上[うえ]に、レモンを足[た]してください。", "sentence_source": "generated"}, {"text": "火が弱くなったので、まきを足す。", "target_word": "足す", "complexity_tier": "T3", "furigana": "火[ひ]が弱[よわ]くなったので、まきを足[た]す。", "sentence_source": "generated"}, {"text": "絵に青い色を足すと、空らしくなった。", "target_word": "足す", "complexity_tier": "T3", "furigana": "絵[え]に青[あお]い色[いろ]を足[た]すと、空[そら]らしくなった。", "sentence_source": "generated"}, {"text": "写真の端に、小さなシールを足して飾った。", "target_word": "足して", "complexity_tier": "T3", "furigana": "写真[しゃしん]の端[はし]に、小[ちい]さなシールを足[た]して飾[かざ]った。", "sentence_source": "generated"}, {"text": "植木鉢の土が減ったので、新しい土を足した。", "target_word": "足した", "complexity_tier": "T3", "furigana": "植木鉢[うえきばち]の土[つち]が減[へ]ったので、新[あたら]しい土[つち]を足[た]した。", "sentence_source": "generated"}, {"text": "地図の上に、道順の矢印を足すと、わかりやすくなる。", "target_word": "足すと", "complexity_tier": "T3", "furigana": "地図[ちず]の上[うえ]に、道順[みちじゅん]の矢印[やじるし]を足[た]すと、わかりやすくなる。", "sentence_source": "generated"}, {"text": "ケーキの上に、いちごを足してあげます。", "target_word": "足して", "complexity_tier": "T3", "furigana": "ケーキの上[うえ]に、いちごを足[た]してあげます。", "sentence_source": "generated"}, {"text": "ご飯の上に、のりを足して食べます。", "target_word": "足して", "complexity_tier": "T3", "furigana": "ご飯[はん]の上[うえ]に、のりを足[た]して食[た]べます。", "sentence_source": "generated"}, {"text": "絵の隅に、小さな星を足した。", "target_word": "足した", "complexity_tier": "T3", "furigana": "絵[え]の隅[すみ]に、小[ちい]さな星[ほし]を足[た]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "足す", "label": "辞書形"}, {"form": "足した", "label": "過去形"}, {"form": "足して", "label": "て形"}, {"form": "足さない", "label": "否定形"}, {"form": "足せば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ものをさらに加えて、のせたりくっつけたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38350, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足して", "is_correct": true, "explanation": "ものを上に加える意味で、パンの上にチーズをのせる動作に合い、続く焼く動作ともつながる。"}, {"text": "捨てて", "is_correct": false, "explanation": "捨てるという意味になり、パンの上にのせる文脈と矛盾する。"}, {"text": "消して", "is_correct": false, "explanation": "消すという意味で、上にのせる動作ではない。"}, {"text": "読んで", "is_correct": false, "explanation": "文字や文章を目で追う意味で、チーズには合わず文が成り立たない。"}], "explanations": {"足して": "ものを上に加える意味で、パンの上にチーズをのせる動作に合い、続く焼く動作ともつながる。", "捨てて": "捨てるという意味になり、パンの上にのせる文脈と矛盾する。", "消して": "消すという意味で、上にのせる動作ではない。", "読んで": "文字や文章を目で追う意味で、チーズには合わず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "足して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅で用を足して、電車に乗った。", "explanation": "ここは〈用を済ませる〉の意味。足すは物を上にのせたりくっつけたりすることで、用事を済ませる意味はない。"}, {"text": "ダイエットで体重を足す。", "explanation": "ここは〈減らす〉の意味。足すは何かを加える意味で、体重を減らす話には合わない。"}, {"text": "絵の隅の汚れを足して、きれいにした。", "explanation": "ここは〈消す〉の意味。足すは加える意味で、汚れを取り除く文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38350, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足すと", "is_correct": true, "explanation": "ものを加えるという意味で、地図に矢印を加えるとわかりやすくなる文脈に合う。"}, {"text": "隠すと", "is_correct": false, "explanation": "見えないようにする意味で、わかりやすくなる文脈と合わない。"}, {"text": "破ると", "is_correct": false, "explanation": "壊すという意味で、地図の矢印には使えない。"}, {"text": "叫ぶと", "is_correct": false, "explanation": "大声を出す意味で、地図の文脈に入らない。"}], "explanations": {"足すと": "ものを加えるという意味で、地図に矢印を加えるとわかりやすくなる文脈に合う。", "隠すと": "見えないようにする意味で、わかりやすくなる文脈と合わない。", "破ると": "壊すという意味で、地図の矢印には使えない。", "叫ぶと": "大声を出す意味で、地図の文脈に入らない。"}, "sentence_index": 6, "correct_answer": "足すと"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は腕を足して、重い荷物を持ち上げた。", "explanation": "ここは〈支える〉の意味。足すは物を加えることで、体で荷物を支える動作には合わない。"}, {"text": "テストを足して、点数をつけた。", "explanation": "ここは〈採点する〉の意味。足すは加えることで、答案を評価する動作には合わない。"}, {"text": "今日の天気を足して、予定を立てた。", "explanation": "ここは〈確認する〉の意味。足すは加える意味で、天気を調べる動作とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38350, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ケーキの上に、クリームを足しください。", "corrected_sentence": "ケーキの上に、クリームを足してください。", "error_description": "「足して」のて形が抜けている。「〜てください」には「足して」の形が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "足して", "is_correct": true, "explanation": "「てください」に続くて形。依頼の文に合う。"}, {"text": "足す", "is_correct": false, "explanation": "辞書形で、「てください」には続けられない。"}, {"text": "足した", "is_correct": false, "explanation": "過去形で、依頼の文には合わない。"}, {"text": "足さない", "is_correct": false, "explanation": "否定形で、加えないという意味になり依頼の文と逆になる。"}], "correct_form": "足して", "base_form": "足す", "form_label": "て形", "sentence_index": 1, "explanations": {"足して": "「てください」に続くて形。依頼の文に合う。", "足す": "辞書形で、「てください」には続けられない。", "足した": "過去形で、依頼の文には合わない。", "足さない": "否定形で、加えないという意味になり依頼の文と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38350, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "写真の隅に、日付を足すて、記録しておいた。", "corrected_sentence": "写真の隅に、日付を足して、記録しておいた。", "error_description": "「足す」のて形は「足して」。「足すて」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "足して", "is_correct": true, "explanation": "「てあげます」に続くて形。"}, {"text": "足します", "is_correct": false, "explanation": "丁寧形で、「てあげます」には続かない。"}, {"text": "足そう", "is_correct": false, "explanation": "意向形で、ここでは続かない。"}, {"text": "足せ", "is_correct": false, "explanation": "命令形で、「てあげます」の文には合わない。"}], "correct_form": "足して", "base_form": "足す", "form_label": "て形", "sentence_index": 7, "explanations": {"足して": "「てあげます」に続くて形。", "足します": "丁寧形で、「てあげます」には続かない。", "足そう": "意向形で、ここでは続かない。", "足せ": "命令形で、「てあげます」の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38351, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "ば", "options": [{"text": "ば", "is_correct": true, "explanation": "仮定を示す接続の「ば」。「足せば」となり、条件を表す。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す。「足せに」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。ここでは続かない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すが、動詞の仮定形には続かない。"}], "correct_answer": "ば", "explanations": {"ば": "仮定を示す接続の「ば」。「足せば」となり、条件を表す。", "に": "場所や相手を示す。「足せに」では文が成り立たない。", "へ": "方向を示す。ここでは続かない。", "で": "手段を示すが、動詞の仮定形には続かない。"}, "error_tags": {"に": "場所・相手", "へ": "方向", "で": "手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引く", "is_correct": true, "explanation": "数を減らす意味で、足す（加える）の対義語。"}, {"text": "数える", "is_correct": false, "explanation": "数を確かめる意味で、足すの対義語ではない。"}, {"text": "集める", "is_correct": false, "explanation": "まとめて寄せる意味で、対義関係にない。"}, {"text": "作る", "is_correct": false, "explanation": "つくるという意味で、足すの対義語ではない。"}], "correct_answer": "引く", "explanations": {"引く": "数を減らす意味で、足す（加える）の対義語。", "数える": "数を確かめる意味で、足すの対義語ではない。", "集める": "まとめて寄せる意味で、対義関係にない。", "作る": "つくるという意味で、足すの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38351, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「数を」の形で、足す対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「二つの数が足した」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。ここでは続かない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「二つの数から足した」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「数を」の形で、足す対象を示す。", "が": "主語を示す。「二つの数が足した」では意味が通らない。", "より": "比較を示す。ここでは続かない。", "から": "起点を示す。「二つの数から足した」では意味が通らない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引く", "is_correct": true, "explanation": "数を減らす意味で、足す（加える）の対義語。"}, {"text": "測る", "is_correct": false, "explanation": "長さや量を調べる意味で、対義関係にない。"}, {"text": "並べる", "is_correct": false, "explanation": "順に置く意味で、対義関係にない。"}, {"text": "飾る", "is_correct": false, "explanation": "装う意味で、足すの対義語ではない。"}], "correct_answer": "引く", "explanations": {"引く": "数を減らす意味で、足す（加える）の対義語。", "測る": "長さや量を調べる意味で、対義関係にない。", "並べる": "順に置く意味で、対義関係にない。", "飾る": "装う意味で、足すの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38351, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "数を増やすこと。数どうしを合わせて計算すること。", "primary_collocate": null, "pronunciation": "たす", "ipa": "tasɯ", "syllable_count": 2, "sentences": [{"text": "三に五を足すと、八になります。", "target_word": "足す", "complexity_tier": "T3", "furigana": "三[さん]に五[ご]を足[た]すと、八[はち]になります。", "sentence_source": "generated"}, {"text": "10に20を足せば、30です。", "target_word": "足せ", "complexity_tier": "T3", "furigana": "10に20を足[た]せば、30です。", "sentence_source": "generated"}, {"text": "買い物の値段を足したら、五千円になった。", "target_word": "足した", "complexity_tier": "T3", "furigana": "買[か]い物[もの]の値段[ねだん]を足[た]したら、五千円[ごせんえん]になった。", "sentence_source": "generated"}, {"text": "全員の点数を足して、クラスの合計を出します。", "target_word": "足して", "complexity_tier": "T3", "furigana": "全員[ぜんいん]の点数[てんすう]を足[た]して、クラスの合計[ごうけい]を出[だ]します。", "sentence_source": "generated"}, {"text": "1から10までの数を全部足すと、いくつになりますか。", "target_word": "足す", "complexity_tier": "T3", "furigana": "1から10までの数[かず]を全部[ぜんぶ]足[た]すと、いくつになりますか。", "sentence_source": "generated"}, {"text": "参加者の数を足して、全部で何人か調べた。", "target_word": "足して", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]の数[かず]を足[た]して、全部[ぜんぶ]で何人[なんにん]か調[しら]べた。", "sentence_source": "generated"}, {"text": "昨日の分と今日の分を足すと、全部で百ページ読んだことになる。", "target_word": "足す", "complexity_tier": "T3", "furigana": "昨日[きのう]の分[ぶん]と今日[きょう]の分[ぶん]を足[た]すと、全部[ぜんぶ]で百[ひゃく]ページ読[よ]んだことになる。", "sentence_source": "generated"}, {"text": "二つの数を足した答えが、十より大きいか考えてください。", "target_word": "足した", "complexity_tier": "T3", "furigana": "二[ふた]つの数[かず]を足[た]した答[こた]えが、十[じゅう]より大[おお]きいか考[かんが]えてください。", "sentence_source": "generated"}, {"text": "電卓がなくても、小さい数なら頭の中で足せます。", "target_word": "足せます", "complexity_tier": "T3", "furigana": "電卓[でんたく]がなくても、小[ちい]さい数[かず]なら頭[あたま]の中[なか]で足[た]せます。", "sentence_source": "generated"}, {"text": "貯金に毎月五千円を足して、少しずつ増やしている。", "target_word": "足して", "complexity_tier": "T3", "furigana": "貯金[ちょきん]に毎月[まいつき]五千円[ごせんえん]を足[た]して、少[すこ]しずつ増[ふ]やしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "足す", "label": "辞書形"}, {"form": "足した", "label": "過去形"}, {"form": "足して", "label": "て形"}, {"form": "足さない", "label": "否定形"}, {"form": "足せば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "数や量を合わせて増やす、足し算をする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38351, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足す", "is_correct": true, "explanation": "数を加えるという意味で、三に五を加えると八になる文に合う。"}, {"text": "眺める", "is_correct": false, "explanation": "見るという意味で、数の計算には使えない。"}, {"text": "作る", "is_correct": false, "explanation": "つくるという意味で、数の計算の文脈に合わない。"}, {"text": "焼く", "is_correct": false, "explanation": "火を通すという意味で、数の計算には使えない。"}], "explanations": {"足す": "数を加えるという意味で、三に五を加えると八になる文に合う。", "眺める": "見るという意味で、数の計算には使えない。", "作る": "つくるという意味で、数の計算の文脈に合わない。", "焼く": "火を通すという意味で、数の計算には使えない。"}, "sentence_index": 0, "correct_answer": "足す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トイレで用を足して、すぐ戻った。", "explanation": "ここは〈用を済ませる〉の意味。足すは数や物を加えることで、用事を済ませる意味は持たない。"}, {"text": "山道を足して、頂上まで歩いた。", "explanation": "ここは〈進む〉の意味。足すは数や量を加えることで、道を進んで歩く動作を表す言葉ではない。"}, {"text": "ため息を足して、部屋を出た。", "explanation": "ここは〈つく〉の意味。ため息は「つく」ものなので、「足す」とは言わない。足すは数や量を加えること。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38351, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足す", "is_correct": true, "explanation": "数を加えるという意味で、昨日と今日の分を合わせる文に合う。"}, {"text": "包む", "is_correct": false, "explanation": "くるむという意味で、数の計算には使えない。"}, {"text": "始める", "is_correct": false, "explanation": "開始する意味で、計算の文脈に合わない。"}, {"text": "忘れる", "is_correct": false, "explanation": "記憶から消す意味で、計算の文脈に合わない。"}], "explanations": {"足す": "数を加えるという意味で、昨日と今日の分を合わせる文に合う。", "包む": "くるむという意味で、数の計算には使えない。", "始める": "開始する意味で、計算の文脈に合わない。", "忘れる": "記憶から消す意味で、計算の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "足す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "眠気を足して、本を読み続けた。", "explanation": "ここは〈増す〉の意味。足すは人が何かを加えることで、眠気が自然に強まる様子は表せない。"}, {"text": "雨を足して、畑に水をやった。", "explanation": "ここは〈水をやる〉の意味。足すは何かを加えることで、畑に水を与える動作は表さない。"}, {"text": "機嫌を足して、みんなに挨拶した。", "explanation": "ここは〈機嫌を取る〉の意味。足すは加えることで、機嫌を取って人に気を遣う意味は持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38351, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "5に8を足せは、13です。", "corrected_sentence": "5に8を足せば、13です。", "error_description": "仮定形の「ば」が「は」になっている。「足せば」が正しい形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "足せ", "is_correct": true, "explanation": "仮定形の語幹で、「ば」を続けて「足せば」となる形。条件を表す文に合う。"}, {"text": "足さない", "is_correct": false, "explanation": "否定形で、足すことを否定する意味になり文の条件と合わない。"}, {"text": "足そう", "is_correct": false, "explanation": "意向形で、推量や意志の意味になり計算の条件とは合わない。"}, {"text": "足す", "is_correct": false, "explanation": "辞書形で、「ば」には続かない。"}], "correct_form": "足せ", "base_form": "足す", "form_label": "仮定形", "sentence_index": 1, "explanations": {"足せ": "仮定形の語幹で、「ば」を続けて「足せば」となる形。条件を表す文に合う。", "足さない": "否定形で、足すことを否定する意味になり文の条件と合わない。", "足そう": "意向形で、推量や意志の意味になり計算の条件とは合わない。", "足す": "辞書形で、「ば」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38351, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三つの数を足すて、合計を出した。", "corrected_sentence": "三つの数を足して、合計を出した。", "error_description": "「足す」のて形は「足して」。「足すて」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "足した", "is_correct": true, "explanation": "過去形で、足し算の結果を述べる文に合う。"}, {"text": "足して", "is_correct": false, "explanation": "て形で、「答え」を修飾する形にはならない。"}, {"text": "足します", "is_correct": false, "explanation": "丁寧形で、過去の結果を述べる文には合わない。"}, {"text": "足すな", "is_correct": false, "explanation": "禁止の形で、文の内容と合わない。"}], "correct_form": "足した", "base_form": "足す", "form_label": "過去形", "sentence_index": 7, "explanations": {"足した": "過去形で、足し算の結果を述べる文に合う。", "足して": "て形で、「答え」を修飾する形にはならない。", "足します": "丁寧形で、過去の結果を述べる文には合わない。", "足すな": "禁止の形で、文の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
