INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38352, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「命を落とす」の「を」。失う対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「命が落とす」では主語と動詞が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「命に落とす」は成り立たない。「落とす」は対象を「を」で取る。"}, {"text": "の", "is_correct": false, "explanation": "「命の落とす」は文として続かない。"}], "correct_answer": "を", "explanations": {"を": "「命を落とす」の「を」。失う対象を示す。", "が": "「命が落とす」では主語と動詞が合わない。", "に": "「命に落とす」は成り立たない。「落とす」は対象を「を」で取る。", "の": "「命の落とす」は文として続かない。"}, "error_tags": {"が": "主語の誤り", "に": "方向・対象の誤り", "の": "連体修飾の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38352, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いのちは、生きていることです。", "primary_collocate": null, "pronunciation": "いのち", "ipa": "inotɕi", "syllable_count": 3, "sentences": [{"text": "命は一つしかないから、大切にしなければならない。", "target_word": "命", "complexity_tier": "T3", "furigana": "命[いのち]は一[ひと]つしかないから、大切[たいせつ]にしなければならない。", "sentence_source": "generated"}, {"text": "川でおぼれた子どもを助けて、彼は命を守った。", "target_word": "命", "complexity_tier": "T3", "furigana": "川[かわ]でおぼれた子[こ]どもを助[たす]けて、彼[かれ]は命[いのち]を守[まも]った。", "sentence_source": "generated"}, {"text": "医者は患者の命を救うために、一晩中働いた。", "target_word": "命", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]の命[いのち]を救[すく]うために、一晩中[ひとばんじゅう]働[はたら]いた。", "sentence_source": "generated"}, {"text": "犬や猫にも、人間と同じように命がある。", "target_word": "命", "complexity_tier": "T3", "furigana": "犬[いぬ]や猫[ねこ]にも、人間[にんげん]と同[おな]じように命[いのち]がある。", "sentence_source": "generated"}, {"text": "雨の中を走って転んだが、命に別状はなかった。", "target_word": "命", "complexity_tier": "T3", "furigana": "雨[あめ]の中[なか]を走[はし]って転[ころ]んだが、命[いのち]に別状[べつじょう]はなかった。", "sentence_source": "generated"}, {"text": "戦争で多くの人の命が失われた。", "target_word": "命", "complexity_tier": "T3", "furigana": "戦争[せんそう]で多[おお]くの人[ひと]の命[いのち]が失[うしな]われた。", "sentence_source": "generated"}, {"text": "彼女は祖母から命の大切さを教えてもらった。", "target_word": "命", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は祖母[そぼ]から命[いのち]の大切[たいせつ]さを教[おし]えてもらった。", "sentence_source": "generated"}, {"text": "山で道に迷い、命を落とすところだった。", "target_word": "命", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]い、命[いのち]を落[お]とすところだった。", "sentence_source": "generated"}, {"text": "小さな花にも命があると思うと、水をやるのが楽しい。", "target_word": "命", "complexity_tier": "T3", "furigana": "小[ちい]さな花[はな]にも命[いのち]があると思[おも]うと、水[みず]をやるのが楽[たの]しい。", "sentence_source": "generated"}, {"text": "事故のあと、命があっただけでもよかったと皆が言った。", "target_word": "命", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、命[いのち]があっただけでもよかったと皆[みんな]が言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "命", "label": "基本形"}, {"form": "命の", "label": "連体（の）形"}, {"form": "命を", "label": "を格形"}, {"form": "命が", "label": "が格形"}], "register": "neutral", "sense_fingerprint": "人や動物などが生きているという状態、またその生きる力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38352, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "命", "is_correct": true, "explanation": "「命は一つしかない」は、生きることを支える命の意味で、空欄に合う。"}, {"text": "季節", "is_correct": false, "explanation": "「季節は一つしかない」は文として成り立たない。季節は一年に何度も巡ってくるものだから。"}, {"text": "天気", "is_correct": false, "explanation": "「天気は一つしかない」は意味が通らない。天気は日々変わるものだから。"}, {"text": "時刻", "is_correct": false, "explanation": "「時刻は一つしかない」は意味が通らない。時刻は毎日いくつもあるから。"}], "explanations": {"命": "「命は一つしかない」は、生きることを支える命の意味で、空欄に合う。", "季節": "「季節は一つしかない」は文として成り立たない。季節は一年に何度も巡ってくるものだから。", "天気": "「天気は一つしかない」は意味が通らない。天気は日々変わるものだから。", "時刻": "「時刻は一つしかない」は意味が通らない。時刻は毎日いくつもあるから。"}, "sentence_index": 0, "correct_answer": "命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は苦労の多い命を歩んできた。", "explanation": "ここは〈人生〉の意味。人生は歩んでいくものだが、命は生きている状態を指すので「歩む」とは組み合わない。"}, {"text": "古い冷蔵庫の命が来て、買い替えた。", "explanation": "ここは〈寿命〉の意味。寿命は物の使える期間のことで、命は生きている状態を指すので合わない。"}, {"text": "毎日運動して命をつけた。", "explanation": "ここは〈体力〉の意味。体力をつけるは体の力を増やすことで、命には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38352, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命", "is_correct": true, "explanation": "「祖母から命の大切さを教えてもらった」は、生きることの大切さの意味で、空欄に合う。"}, {"text": "駐車場", "is_correct": false, "explanation": "「祖母から駐車場の大切さを」は意味が通らない。駐車場は場所の名前で、大切さを教える対象にはならない。"}, {"text": "段ボール", "is_correct": false, "explanation": "「祖母から段ボールの大切さを」は不自然。段ボールは箱の材料で、教えの対象にはならない。"}, {"text": "綿あめ", "is_correct": false, "explanation": "「祖母から綿あめの大切さを」は意味が通らない。綿あめは菓子の名前で、教えの対象にはならない。"}], "explanations": {"命": "「祖母から命の大切さを教えてもらった」は、生きることの大切さの意味で、空欄に合う。", "駐車場": "「祖母から駐車場の大切さを」は意味が通らない。駐車場は場所の名前で、大切さを教える対象にはならない。", "段ボール": "「祖母から段ボールの大切さを」は不自然。段ボールは箱の材料で、教えの対象にはならない。", "綿あめ": "「祖母から綿あめの大切さを」は意味が通らない。綿あめは菓子の名前で、教えの対象にはならない。"}, "sentence_index": 6, "correct_answer": "命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学に入って、一人暮らしの命を始めた。", "explanation": "ここは〈生活〉の意味。生活は暮らしを送ることで、命は生きている状態を指すので暮らしの方法には使わない。"}, {"text": "誕生日が来て、命が一つ上がった。", "explanation": "ここは〈年齢〉の意味。年齢は何歳かを表すもので、命が上がるという言い方はしない。"}, {"text": "二人は命の出会いをした。", "explanation": "ここは〈運命〉の意味。運命は巡り合わせを表すが、命は生きている状態を指すので「出会い」とは組み合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38352, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は命を大切さを教えてくれた。", "corrected_sentence": "祖父は命の大切さを教えてくれた。", "error_description": "「命の大切さ」と名詞をつなぐには「の」が必要。誤りは「を」で、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38352, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その子は命を取り留める、皆が安心した。", "corrected_sentence": "その子は命を取り留めて、皆が安心した。", "error_description": "「取り留める」は終止形なので、後ろに文を続けるには「取り留めて」（て形）が必要。誤りは「る」で、正しくは「て」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
