INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38354, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「臍をくすぐられる」の対象を示す「を」。くすぐる（他動詞）の目的語として合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、くすぐる対象を示せないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は、くすぐられる対象の格助詞にはならない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す「と」は、くすぐられる対象の格助詞にはならない。"}], "correct_answer": "を", "explanations": {"を": "「臍をくすぐられる」の対象を示す「を」。くすぐる（他動詞）の目的語として合う。", "へ": "方向を示す「へ」は、くすぐる対象を示せないので合わない。", "より": "比較を示す「より」は、くすぐられる対象の格助詞にはならない。", "と": "相手や並列を示す「と」は、くすぐられる対象の格助詞にはならない。"}, "error_tags": {"へ": "方向（対象を示せない）", "より": "比較（対象を示せない）", "と": "相手・並列（対象を示せない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38354, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おなかのまんなかにある、へこんだところのことです。", "primary_collocate": null, "pronunciation": "へそ", "ipa": "heso", "syllable_count": 2, "sentences": [{"text": "赤ちゃんの臍は、おなかの真ん中で小さくへこんでいる。", "target_word": "臍", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの臍[へそ]は、おなかの真[ま]ん中[なか]で小[ちい]さくへこんでいる。", "sentence_source": "generated"}, {"text": "寒い日に、シャツがめくれたまま外に立っていたら、臍が冷えてしまった。", "target_word": "臍", "complexity_tier": "T3", "furigana": "寒い日に、シャツがめくれたまま外に立っていたら、臍[へそ]が冷えてしまった。", "sentence_source": "generated"}, {"text": "母は私の臍を見て、小さいころの話を始めた。", "target_word": "臍", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の臍[へそ]を見[み]て、小[ちい]さいころの話[はなし]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "プールで泳いだあと、臍にたまった水をタオルでふいた。", "target_word": "臍", "complexity_tier": "T3", "furigana": "プールで泳[およ]いだあと、臍[へそ]にたまった水[みず]をタオルでふいた。", "sentence_source": "generated"}, {"text": "臍の下あたりが痛くて、病院で診てもらった。", "target_word": "臍", "complexity_tier": "T3", "furigana": "臍[へそ]の下[した]あたりが痛[いた]くて、病院[びょういん]で診[み]てもらった。", "sentence_source": "generated"}, {"text": "子どもは笑いながら、自分の臍に指を入れようとした。", "target_word": "臍", "complexity_tier": "T3", "furigana": "子[こ]どもは笑[わら]いながら、自分[じぶん]の臍[へそ]に指[ゆび]を入[い]れようとした。", "sentence_source": "generated"}, {"text": "短いシャツだと臍が見えるので、長いシャツを着た。", "target_word": "臍", "complexity_tier": "T3", "furigana": "短[みじか]いシャツだと臍[へそ]が見[み]えるので、長[なが]いシャツを着[き]た。", "sentence_source": "generated"}, {"text": "弟は臍をくすぐられると、大きな声で笑い出す。", "target_word": "臍", "complexity_tier": "T3", "furigana": "弟[おとうと]は臍[へそ]をくすぐられると、大[おお]きな声[こえ]で笑[わら]い出[だ]す。", "sentence_source": "generated"}, {"text": "シャツがめくれて、臍が見えてしまった。", "target_word": "臍", "complexity_tier": "T3", "furigana": "シャツがめくれて、臍[へそ]が見[み]えてしまった。", "sentence_source": "generated"}, {"text": "体を前に曲げると、臍のあたりに力が入るのがわかる。", "target_word": "臍", "complexity_tier": "T3", "furigana": "体[からだ]を前[まえ]に曲[ま]げると、臍[へそ]のあたりに力[ちから]が入[はい]るのがわかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "臍", "label": "基本形"}, {"form": "臍の", "label": "連体（の）形"}, {"form": "臍を", "label": "を格形"}, {"form": "臍が", "label": "が格形"}], "register": "neutral", "sense_fingerprint": "体のおなかの中央にある小さなくぼみ（体の部位）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38354, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "臍", "is_correct": true, "explanation": "おなかの中央にある小さなくぼみを指す語。「おなかの真ん中で小さくへこんでいる」の主語として合う。"}, {"text": "肘", "is_correct": false, "explanation": "肘は腕の関節の部位で、おなかの真ん中にはない。この文の主語にはならない。"}, {"text": "踵", "is_correct": false, "explanation": "踵は足の後ろの部分で、おなかのくぼみとして述べる文には合わない。"}, {"text": "眉", "is_correct": false, "explanation": "眉は顔にある部位で、おなかの真ん中で小さくへこんでいる対象にはならない。"}], "explanations": {"臍": "おなかの中央にある小さなくぼみを指す語。「おなかの真ん中で小さくへこんでいる」の主語として合う。", "肘": "肘は腕の関節の部位で、おなかの真ん中にはない。この文の主語にはならない。", "踵": "踵は足の後ろの部分で、おなかのくぼみとして述べる文には合わない。", "眉": "眉は顔にある部位で、おなかの真ん中で小さくへこんでいる対象にはならない。"}, "sentence_index": 0, "correct_answer": "臍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食べすぎて、臍がぱんぱんに張っている。", "explanation": "ここは〈お腹〉の意味。臍は中央のくぼみで、食べすぎで張るのはお腹全体なので合わない。"}, {"text": "首の後ろに大きな臍があって、気になる。", "explanation": "ここは〈ほくろ〉の意味。臍はおなかの中央にしかなく、首の後ろにはできない。"}, {"text": "ぶつけて臍が割れてしまった。", "explanation": "ここは〈爪〉の意味。爪は割れるが、臍は体の部位のくぼみなので割れるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38354, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "臍", "is_correct": true, "explanation": "おなかの中央のくぼみを指す語。「短いシャツで見える」対象として合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の一部で、短いシャツだと見えるという文の対象として成り立たない。"}, {"text": "星", "is_correct": false, "explanation": "星は空にあるもので、シャツの丈と関係する対象としては合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は足に履くもので、シャツの丈によって見える対象にはならない。"}], "explanations": {"臍": "おなかの中央のくぼみを指す語。「短いシャツで見える」対象として合う。", "窓": "窓は建物の一部で、短いシャツだと見えるという文の対象として成り立たない。", "星": "星は空にあるもので、シャツの丈と関係する対象としては合わない。", "靴": "靴は足に履くもので、シャツの丈によって見える対象にはならない。"}, "sentence_index": 6, "correct_answer": "臍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "顔に臍が三本ついた。", "explanation": "ここは〈皺〉の意味。臍は体にある一つのくぼみで、顔の筋状のしわの代わりにはならない。"}, {"text": "車のドアに臍ができた。", "explanation": "ここは〈凹み〉の意味。臍は人の体の部位で、車にできたへこみには使わない。"}, {"text": "臍が苦しくて、息がしにくい。", "explanation": "ここは〈胸〉の意味。臍はおなかの中央にあり、呼吸の苦しさを感じる場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38354, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は孫の臍が笑いながらのぞき込んだ。", "corrected_sentence": "祖母は孫の臍を笑いながらのぞき込んだ。", "error_description": "「のぞき込む」は他動詞なので、目的語の「臍」には「を」が必要。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38354, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "臍を痛くて、夜中に目が覚めた。", "corrected_sentence": "臍が痛くて、夜中に目が覚めた。", "error_description": "形容詞「痛い」の主語は「臍」なので「が」が必要。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38355, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「臍が乾く」の主語を示す「が」。乾く（自動詞）の主語として合う。"}, {"text": "を", "is_correct": false, "explanation": "乾く（自動詞）は目的語を取らないので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す「に」は、乾く主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」は、乾く主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「臍が乾く」の主語を示す「が」。乾く（自動詞）の主語として合う。", "を": "乾く（自動詞）は目的語を取らないので、「を」は合わない。", "に": "場所や相手を示す「に」は、乾く主語にはならない。", "で": "手段や場所を示す「で」は、乾く主語の位置には合わない。"}, "error_tags": {"を": "目的語（自動詞には不可）", "に": "場所・相手（主語にならない）", "で": "手段・場所（主語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38355, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「臍を見て」の目的語を示す「を」。見る（他動詞）の対象として合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、見る対象を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "引用や相手を示す「と」は、見る対象の格助詞にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は、見る対象を示す格助詞にはならない。"}], "correct_answer": "を", "explanations": {"を": "「臍を見て」の目的語を示す「を」。見る（他動詞）の対象として合う。", "へ": "方向を示す「へ」は、見る対象を示せないので合わない。", "と": "引用や相手を示す「と」は、見る対象の格助詞にはならない。", "より": "比較を示す「より」は、見る対象を示す格助詞にはならない。"}, "error_tags": {"へ": "方向（対象を示せない）", "と": "引用・相手（対象を示せない）", "より": "比較（対象を示せない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38355, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "へそ。お腹の中央にある、臍帯（へその緒）が取れたあとのくぼみ。", "primary_collocate": null, "pronunciation": "へそ", "ipa": "heso", "syllable_count": 2, "sentences": [{"text": "生まれたばかりの赤ちゃんの臍は、まだ少し赤い。", "target_word": "臍", "complexity_tier": "T3", "furigana": "生[う]まれたばかりの赤[あか]ちゃんの臍[へそ]は、まだ少[すこ]し赤[あか]い。", "sentence_source": "generated"}, {"text": "赤ちゃんの臍が乾くまで、看護師に消毒のしかたを教わった。", "target_word": "臍", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの臍[へそ]が乾[かわ]くまで、看護師[かんごし]に消毒[しょうどく]のしかたを教[おそ]わった。", "sentence_source": "generated"}, {"text": "臍は、母親のおなかの中でつながっていたしるしだ。", "target_word": "臍", "complexity_tier": "T3", "furigana": "臍[へそ]は、母親[ははおや]のおなかの中[なか]でつながっていたしるしだ。", "sentence_source": "generated"}, {"text": "臍のまわりが赤くなったので、小児科に連れて行った。", "target_word": "臍", "complexity_tier": "T3", "furigana": "臍[へそ]のまわりが赤[あか]くなったので、小児科[しょうにか]に連[つ]れて行[い]った。", "sentence_source": "generated"}, {"text": "お風呂のとき、赤ちゃんの臍を優しく洗ってあげた。", "target_word": "臍", "complexity_tier": "T3", "furigana": "お風呂[ふろ]のとき、赤[あか]ちゃんの臍[へそ]を優[やさ]しく洗[あら]ってあげた。", "sentence_source": "generated"}, {"text": "大人になっても、臍を見ると生まれたときのことを思う。", "target_word": "臍", "complexity_tier": "T3", "furigana": "大人[おとな]になっても、臍[へそ]を見[み]ると生[う]まれたときのことを思[おも]う。", "sentence_source": "generated"}, {"text": "臍の形は人によって違い、深い人も浅い人もいる。", "target_word": "臍", "complexity_tier": "T3", "furigana": "臍[へそ]の形[かたち]は人[ひと]によって違[ちが]い、深[ふか]い人[ひと]も浅[あさ]い人[ひと]もいる。", "sentence_source": "generated"}, {"text": "医者は赤ちゃんの臍を見て、「きれいに治っていますね」と言った。", "target_word": "臍", "complexity_tier": "T3", "furigana": "医者[いしゃ]は赤[あか]ちゃんの臍[へそ]を見[み]て、「きれいに治[なお]っていますね」と言[い]った。", "sentence_source": "generated"}, {"text": "臍に汚れがたまらないよう、毎日そっと拭いている。", "target_word": "臍", "complexity_tier": "T3", "furigana": "臍[へそ]に汚[よご]れがたまらないよう、毎日[まいにち]そっと拭[ふ]いている。", "sentence_source": "generated"}, {"text": "生まれて一週間たつと、赤ちゃんの臍は乾いて小さくなる。", "target_word": "臍", "complexity_tier": "T3", "furigana": "生[う]まれて一週間[いっしゅうかん]たつと、赤[あか]ちゃんの臍[へそ]は乾[かわ]いて小[ちい]さくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "臍", "label": "基本形"}, {"form": "臍の", "label": "連体（の）形"}, {"form": "臍を", "label": "を格形"}, {"form": "臍が", "label": "が格形"}], "register": "neutral", "sense_fingerprint": "生まれたあと臍帯が取れて残る、お腹の中央のくぼみ（出産・赤ちゃんとの関わりで見る体の部位）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38355, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "臍", "is_correct": true, "explanation": "生まれたあとに残るおなかのくぼみを指す語。まだ赤い部位として文の主語に合う。"}, {"text": "眉", "is_correct": false, "explanation": "眉は顔の部位で、生まれたばかりの赤ちゃんの赤さを述べる対象として合わない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は機械で、赤ちゃんの体の部位として赤いと述べる文の主語にはならない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は道具で、赤ちゃんの体の部位として述べる文の主語にならない。"}], "explanations": {"臍": "生まれたあとに残るおなかのくぼみを指す語。まだ赤い部位として文の主語に合う。", "眉": "眉は顔の部位で、生まれたばかりの赤ちゃんの赤さを述べる対象として合わない。", "電話": "電話は機械で、赤ちゃんの体の部位として赤いと述べる文の主語にはならない。", "鍵": "鍵は道具で、赤ちゃんの体の部位として述べる文の主語にならない。"}, "sentence_index": 0, "correct_answer": "臍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "臍は、母親とつながっていた細い管で、栄養を運んでいた。", "explanation": "ここは〈臍の緒（へその緒）〉の意味。臍は取れたあとに残るくぼみで、管そのものではない。"}, {"text": "臍が伸びてきたので、切ってあげた。", "explanation": "ここは〈爪〉の意味。臍は伸びるものではないので、切る対象にならない。"}, {"text": "臍が取れたので、新しいのをつけた。", "explanation": "ここは〈ボタン〉の意味。臍は体の一部で、取れて付け替えるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38355, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "臍", "is_correct": true, "explanation": "おなかの中央のくぼみを指す語。「深い・浅い」で形を述べる主語として合う。"}, {"text": "夢", "is_correct": false, "explanation": "夢は睡眠中の体験で、体の形の深さを述べる文の主語には合わない。"}, {"text": "文字", "is_correct": false, "explanation": "文字は書かれた記号で、人によって深い浅いと形が違う対象としては成り立たない。"}, {"text": "空", "is_correct": false, "explanation": "空は天候の対象で、人によって深さが違うという文の主語にはならない。"}], "explanations": {"臍": "おなかの中央のくぼみを指す語。「深い・浅い」で形を述べる主語として合う。", "夢": "夢は睡眠中の体験で、体の形の深さを述べる文の主語には合わない。", "文字": "文字は書かれた記号で、人によって深い浅いと形が違う対象としては成り立たない。", "空": "空は天候の対象で、人によって深さが違うという文の主語にはならない。"}, "sentence_index": 6, "correct_answer": "臍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "赤ちゃんが臍を強く吸うので、お母さんは困っている。", "explanation": "ここは〈乳首〉の意味。授乳で吸われるのは乳首で、臍は吸う対象にならない。"}, {"text": "お母さんは赤ちゃんの臍を三つ編みにした。", "explanation": "ここは〈髪〉の意味。三つ編みにできるのは髪で、臍には使わない。"}, {"text": "臍がぐらぐらして、抜けそうだ。", "explanation": "ここは〈歯〉の意味。歯は揺れて抜けるが、臍は揺れたり抜けたりするものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38355, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看護師は赤ちゃんの臍を乾くまで、消毒した。", "corrected_sentence": "看護師は赤ちゃんの臍が乾くまで、消毒した。", "error_description": "「乾く」は自動詞なので、主語の「臍」には「が」が必要。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38355, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "赤ちゃんの臍と乾くまで、そっと見守った。", "corrected_sentence": "赤ちゃんの臍が乾くまで、そっと見守った。", "error_description": "「乾く」の主語は「臍」なので「が」が必要。「と」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38356, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在を表す「あります」の主語を示す「が」。「湖があります」で成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」は、存在を表す「あります」の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、存在を表す「あります」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」は、「湖とあります」として存在の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "存在を表す「あります」の主語を示す「が」。「湖があります」で成り立つ。", "で": "手段や場所を示す「で」は、存在を表す「あります」の主語にはならない。", "から": "起点を示す「から」は、存在を表す「あります」の主語にはならない。", "と": "並列や相手を示す「と」は、「湖とあります」として存在の主語にはならない。"}, "error_tags": {"で": "手段・場所（存在の主語にならない）", "から": "起点（存在の主語にならない）", "と": "並列・相手（存在の主語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38356, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所を示す「に」。「湖に白い鳥がいました」で成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」は、存在の場所としては「湖を白い鳥がいました」で成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、存在の場所としては合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を示す「より」は、存在の場所にはならない。"}], "correct_answer": "に", "explanations": {"に": "存在の場所を示す「に」。「湖に白い鳥がいました」で成り立つ。", "を": "目的語を示す「を」は、存在の場所としては「湖を白い鳥がいました」で成り立たない。", "へ": "方向を示す「へ」は、存在の場所としては合わない。", "より": "比較や起点を示す「より」は、存在の場所にはならない。"}, "error_tags": {"を": "目的語（存在の場所にならない）", "へ": "方向（存在の場所にならない）", "より": "比較・起点（存在の場所にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38356, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みずが たくさん ある ところ。", "primary_collocate": null, "pronunciation": "みずうみ", "ipa": "mizɯɯmi", "syllable_count": 4, "sentences": [{"text": "朝、湖の水はとても静かでした。", "target_word": "湖", "complexity_tier": "T3", "furigana": "朝(あさ)、湖(みずうみ)の水(みず)はとても静(しず)かでした。", "sentence_source": "generated"}, {"text": "山の上に大きな湖があります。", "target_word": "湖", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)に大(おお)きな湖(みずうみ)があります。", "sentence_source": "generated"}, {"text": "夏休みに家族で湖へ行きました。", "target_word": "湖", "complexity_tier": "T3", "furigana": "夏休(なつやす)みに家族(かぞく)で湖(みずうみ)へ行(い)きました。", "sentence_source": "generated"}, {"text": "この湖は広いので、一周するのに三時間かかります。", "target_word": "湖", "complexity_tier": "T3", "furigana": "この湖(みずうみ)は広(ひろ)いので、一周(いっしゅう)するのに三時間(さんじかん)かかります。", "sentence_source": "generated"}, {"text": "湖の水が冷たかったので、泳ぐのをやめました。", "target_word": "湖", "complexity_tier": "T3", "furigana": "湖(みずうみ)の水(みず)が冷(つめ)たかったので、泳(およ)ぐのをやめました。", "sentence_source": "generated"}, {"text": "湖のまわりを犬と散歩した。", "target_word": "湖", "complexity_tier": "T3", "furigana": "湖(みずうみ)のまわりを犬(いぬ)と散歩(さんぽ)した。", "sentence_source": "generated"}, {"text": "冬は湖が凍るから、釣りができなくなる。", "target_word": "湖", "complexity_tier": "T3", "furigana": "冬(ふゆ)は湖(みずうみ)が凍(こお)るから、釣(つ)りができなくなる。", "sentence_source": "generated"}, {"text": "湖に白い鳥が三羽いました。", "target_word": "湖", "complexity_tier": "T3", "furigana": "湖(みずうみ)に白(しろ)い鳥(とり)が三羽(さんば)いました。", "sentence_source": "generated"}, {"text": "私は湖の近くのホテルに泊まりました。", "target_word": "湖", "complexity_tier": "T3", "furigana": "私(わたし)は湖(みずうみ)の近(ちか)くのホテルに泊(と)まりました。", "sentence_source": "generated"}, {"text": "湖にボートが浮かんでいる。", "target_word": "湖", "complexity_tier": "T3", "furigana": "湖(みずうみ)にボートが浮(う)かんでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "湖", "label": "基本形"}], "register": "標準語", "sense_fingerprint": "大量の水がたまった広い場所（みずうみ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38356, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "水が大量にたまった広い場所を指す語。「朝、〇〇の水は静かだ」の主語として合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の部品で、水の静けさを述べる文の主語にはならない。"}, {"text": "机", "is_correct": false, "explanation": "机は家具で、水の状態を表す主語として成り立たない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は道具で、水が静かだという文の主語には合わない。"}], "explanations": {"湖": "水が大量にたまった広い場所を指す語。「朝、〇〇の水は静かだ」の主語として合う。", "窓": "窓は建物の部品で、水の静けさを述べる文の主語にはならない。", "机": "机は家具で、水の状態を表す主語として成り立たない。", "鍵": "鍵は道具で、水が静かだという文の主語には合わない。"}, "sentence_index": 0, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の小さな湖で、金魚を三匹飼っている。", "explanation": "ここは〈池〉の意味。庭などにある小さな水場は池で、湖は広く大きな水のことなので合わない。"}, {"text": "湖が曲がりくねって流れている。", "explanation": "ここは〈川〉の意味。川は流れるが、湖は水が流れていく場所ではないので合わない。"}, {"text": "喉が渇いたので、湖を一杯飲んだ。", "explanation": "ここは〈水〉の意味。湖は飲める量ではないので、コップ一杯の水と取り違えた言い方として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38356, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "水が大量にたまった広い場所を指す語。「冬は〇〇が凍る」の主語として、凍って釣りができなくなる文に合う。"}, {"text": "砂", "is_correct": false, "explanation": "砂は水をためず、凍って釣りができなくなるという文の主語としては成り立たない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、凍って釣りができなくなる文脈には合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は凍らず、釣りとは関係しないので文の主語に合わない。"}], "explanations": {"湖": "水が大量にたまった広い場所を指す語。「冬は〇〇が凍る」の主語として、凍って釣りができなくなる文に合う。", "砂": "砂は水をためず、凍って釣りができなくなるという文の主語としては成り立たない。", "鍋": "鍋は調理器具で、凍って釣りができなくなる文脈には合わない。", "紙": "紙は凍らず、釣りとは関係しないので文の主語に合わない。"}, "sentence_index": 6, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蛇口をひねると、湖が勢いよく出てきた。", "explanation": "ここは〈水〉の意味。蛇口から出てくるのは水で、湖が蛇口から出てくることはない。"}, {"text": "湖に水を入れて、稲を植えた。", "explanation": "ここは〈田んぼ〉の意味。水田は稲を植える場所で、湖に稲を植える文脈は合わない。"}, {"text": "空から湖が降ってきた。", "explanation": "ここは〈雨〉の意味。雨は空から降るが、湖は空から降ってこないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38356, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は湖な近くの小さな宿に泊まりました。", "corrected_sentence": "私は湖の近くの小さな宿に泊まりました。", "error_description": "「湖」と「近く」は「の」で結ぶ。「な」は形容動詞の語幹に付くので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38356, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝、湖な白い鳥が飛び立った。", "corrected_sentence": "朝、湖の白い鳥が飛び立った。", "error_description": "「湖」と「白い鳥」は「の」で結ぶ。「な」は形容動詞の語幹に付くので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
