INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38357, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「湖は」で主題を示す「は」。文の主題として湖を取り上げる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」は、主題の位置には合わない。「湖を川から流れ込む水がたまってできた」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、「湖へ川から流れ込む」が成り立たず、主題の位置には合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、主題の位置には合わない。"}], "correct_answer": "は", "explanations": {"は": "「湖は」で主題を示す「は」。文の主題として湖を取り上げる。", "を": "目的語を示す「を」は、主題の位置には合わない。「湖を川から流れ込む水がたまってできた」は成り立たない。", "へ": "方向を示す「へ」は、「湖へ川から流れ込む」が成り立たず、主題の位置には合わない。", "から": "起点を示す「から」は、主題の位置には合わない。"}, "error_tags": {"を": "目的語（主題にならない）", "から": "起点（主題にならない）", "へ": "方向（主題にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38357, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "陸地に囲まれた、水がたまった場所。天然のものから人工のものまである。", "primary_collocate": null, "pronunciation": "みずうみ", "ipa": "mizɯɯmi", "syllable_count": 4, "sentences": [{"text": "この湖は山に囲まれていて、海とはつながっていない。", "target_word": "湖", "complexity_tier": "T3", "furigana": "この湖(みずうみ)は山(やま)に囲(かこ)まれていて、海(うみ)とはつながっていない。", "sentence_source": "generated"}, {"text": "川をせき止めて人工の湖を作った。", "target_word": "湖", "complexity_tier": "T3", "furigana": "川(かわ)をせき止(と)めて人工(じんこう)の湖(みずうみ)を作(つく)った。", "sentence_source": "generated"}, {"text": "日本でいちばん大きな湖は滋賀県にあります。", "target_word": "湖", "complexity_tier": "T3", "furigana": "日本(にほん)でいちばん大(おお)きな湖(みずうみ)は滋賀県(しがけん)にあります。", "sentence_source": "generated"}, {"text": "湖の水は海と違って塩辛くない。", "target_word": "湖", "complexity_tier": "T3", "furigana": "湖(みずうみ)の水(みず)は海(うみ)と違(ちが)って塩辛(しおから)くない。", "sentence_source": "generated"}, {"text": "ダムができて、村の跡に新しい湖が生まれた。", "target_word": "湖", "complexity_tier": "T3", "furigana": "ダムができて、村(むら)の跡(あと)に新(あたら)しい湖(みずうみ)が生(う)まれた。", "sentence_source": "generated"}, {"text": "湖の底には、昔の村が沈んでいるそうだ。", "target_word": "湖", "complexity_tier": "T3", "furigana": "湖(みずうみ)の底(そこ)には、昔(むかし)の村(むら)が沈(しず)んでいるそうだ。", "sentence_source": "generated"}, {"text": "雨が少ない年は、湖の水の量が減ってしまう。", "target_word": "湖", "complexity_tier": "T3", "furigana": "雨(あめ)が少(すく)ない年(とし)は、湖(みずうみ)の水(みず)の量(りょう)が減(へ)ってしまう。", "sentence_source": "generated"}, {"text": "この湖は川から流れ込む水がたまってできた。", "target_word": "湖", "complexity_tier": "T3", "furigana": "この湖(みずうみ)は川(かわ)から流(なが)れ込(こ)む水(みず)がたまってできた。", "sentence_source": "generated"}, {"text": "公園の中に、人が作った小さな湖がある。", "target_word": "湖", "complexity_tier": "T3", "furigana": "公園(こうえん)の中(なか)に、人(ひと)が作(つく)った小(ちい)さな湖(みずうみ)がある。", "sentence_source": "generated"}, {"text": "湖の水を調べて、魚の種類をまとめた。", "target_word": "湖", "complexity_tier": "T3", "furigana": "湖(みずうみ)の水(みず)を調(しら)べて、魚(さかな)の種類(しゅるい)をまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "湖", "label": "基本形"}], "register": "標準語", "sense_fingerprint": "陸地に囲まれて水がたまった場所（天然・人工を含む）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 塩辛く (Zipf 1.69)']::text[], '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38357, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "陸地に囲まれて水がたまった場所を指す語。「山に囲まれていて、海とはつながっていない」の主語として合う。"}, {"text": "靴", "is_correct": false, "explanation": "靴は履くもので、山に囲まれて海とつながらない場所の対象にはならない。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は道具で、山に囲まれた場所を述べる主語として成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は場所を指さず、この文の主語には合わない。"}], "explanations": {"湖": "陸地に囲まれて水がたまった場所を指す語。「山に囲まれていて、海とはつながっていない」の主語として合う。", "靴": "靴は履くもので、山に囲まれて海とつながらない場所の対象にはならない。", "鍵": "鍵は道具で、山に囲まれた場所を述べる主語として成り立たない。", "紙": "紙は場所を指さず、この文の主語には合わない。"}, "sentence_index": 0, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖は山から流れ出して、最後は海へ注ぐ。", "explanation": "ここは〈川〉の意味。川は海へ注ぐが、陸地に囲まれた湖は海へ流れ出さないので合わない。"}, {"text": "湯船に湖をためた。", "explanation": "ここは〈水〉の意味。湖は水がたまった場所を指すので、湯船にためる水そのものの代わりには使えない。"}, {"text": "水道の蛇口をひねると、湖が出る。", "explanation": "ここは〈水〉の意味。蛇口から出るのは水で、湖が蛇口から出ることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38357, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湖", "is_correct": true, "explanation": "水がたまった場所を指す語。「雨が少ない年は、〇〇の水の量が減る」の主語として合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は水をためないので、水の量が減るという文の主語に合わない。"}, {"text": "鏡", "is_correct": false, "explanation": "鏡は水を入れる物ではなく、水の量の話には合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "帽子は水をためず、水の量の主語にはならない。"}], "explanations": {"湖": "水がたまった場所を指す語。「雨が少ない年は、〇〇の水の量が減る」の主語として合う。", "窓": "窓は水をためないので、水の量が減るという文の主語に合わない。", "鏡": "鏡は水を入れる物ではなく、水の量の話には合わない。", "帽子": "帽子は水をためず、水の量の主語にはならない。"}, "sentence_index": 6, "correct_answer": "湖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空に湖が浮かんでいる。", "explanation": "ここは〈雲〉の意味。雲は空に浮かぶが、湖は地上の水の場所で空に浮かばないので合わない。"}, {"text": "公園の噴水から湖が高く上がる。", "explanation": "ここは〈噴水〉の意味。噴水から高く上がるのは水で、湖が噴き上がることはない。"}, {"text": "雨で湖が柔らかくなった。", "explanation": "ここは〈土〉の意味。雨で柔らかくなるのは土で、湖は柔らかくならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38357, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ダムで川をせき止めて、大きな湖が作った。", "corrected_sentence": "ダムで川をせき止めて、大きな湖を作った。", "error_description": "「作る」は他動詞なので、目的語の「湖」には「を」が必要。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38357, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダムができたので、村の跡に新しい湖を生まれた。", "corrected_sentence": "ダムができたので、村の跡に新しい湖が生まれた。", "error_description": "「生まれる」は自動詞なので、主語の「湖」には「が」が必要。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38358, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「端を歩く」で、歩く経路の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「道の端が歩くと」では歩く主体にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「道の端と歩くと」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「道の端の歩くと」は動詞に続かない。"}], "correct_answer": "を", "explanations": {"を": "「端を歩く」で、歩く経路の対象を示す。", "が": "「が」は主語を示すが、「道の端が歩くと」では歩く主体にならず不自然。", "と": "「と」は相手や並列を示すが、「道の端と歩くと」は意味が通らない。", "の": "「の」は名詞をつなぐ助詞で、「道の端の歩くと」は動詞に続かない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38358, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「パンの端は」で話題を示し、「かたい」という評価の主題として自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「端をかたいので」は述語として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、「端にかたいので」は述語にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「端とかたいので」は文が続かない。"}], "correct_answer": "は", "explanations": {"は": "「パンの端は」で話題を示し、「かたい」という評価の主題として自然。", "を": "「を」は目的語を示すが、「端をかたいので」は述語として成り立たない。", "に": "「に」は場所や相手を示すが、「端にかたいので」は述語にならず不自然。", "と": "「と」は並列や相手を示すが、「端とかたいので」は文が続かない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38358, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの はし の こと。", "primary_collocate": null, "pronunciation": "はし", "ipa": "haɕi", "syllable_count": 2, "sentences": [{"text": "机の端にコップを置かないでください。", "target_word": "端", "complexity_tier": "T3", "furigana": "机(つくえ)の端(はし)にコップを置(お)かないでください。", "sentence_source": "generated"}, {"text": "道の端を歩くと、車が来ても安全です。", "target_word": "端", "complexity_tier": "T3", "furigana": "道(みち)の端(はし)を歩(ある)くと、車(くるま)が来(き)ても安全(あんぜん)です。", "sentence_source": "generated"}, {"text": "ひもの端を持って、強く引っ張った。", "target_word": "端", "complexity_tier": "T3", "furigana": "ひもの端(はし)を持(も)って、強(つよ)く引(ひ)っ張(ぱ)った。", "sentence_source": "generated"}, {"text": "紙の端が破れてしまった。", "target_word": "端", "complexity_tier": "T3", "furigana": "紙(かみ)の端(はし)が破(やぶ)れてしまった。", "sentence_source": "generated"}, {"text": "ベンチの端に座って、友だちを待った。", "target_word": "端", "complexity_tier": "T3", "furigana": "ベンチの端(はし)に座(すわ)って、友(とも)だちを待(ま)った。", "sentence_source": "generated"}, {"text": "テープの端が見つからなくて困っている。", "target_word": "端", "complexity_tier": "T3", "furigana": "テープの端(はし)が見(み)つからなくて困(こま)っている。", "sentence_source": "generated"}, {"text": "長い廊下の端に、小さな窓がある。", "target_word": "端", "complexity_tier": "T3", "furigana": "長(なが)い廊下(ろうか)の端(はし)に、小(ちい)さな窓(まど)がある。", "sentence_source": "generated"}, {"text": "パンの端はかたいので、私は好きではない。", "target_word": "端", "complexity_tier": "T3", "furigana": "パンの端(はし)はかたいので、私(わたし)は好(す)きではない。", "sentence_source": "generated"}, {"text": "布の端がほつれていたから、針で縫った。", "target_word": "端", "complexity_tier": "T3", "furigana": "布(ぬの)の端(はし)がほつれていたから、針(はり)で縫(ぬ)った。", "sentence_source": "generated"}, {"text": "ノートの端が折れていたので、まっすぐに直した。", "target_word": "端", "complexity_tier": "T3", "furigana": "ノートの端(はし)が折れていたので、まっすぐに直(なお)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "端", "label": "基本形"}], "register": "標準語", "sense_fingerprint": "物の先や縁の部分（はし）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38358, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "端", "is_correct": true, "explanation": "「机の端」は置く位置を示し、「に置く」と自然につながる。"}, {"text": "色", "is_correct": false, "explanation": "「色」は物の色を表すので、コップを置く場所を示せない。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さ」は重量の語で、置く位置を表す名詞として成り立たない。"}, {"text": "名前", "is_correct": false, "explanation": "「名前」は呼び名の語で、コップを置く場所にはならない。"}], "explanations": {"端": "「机の端」は置く位置を示し、「に置く」と自然につながる。", "色": "「色」は物の色を表すので、コップを置く場所を示せない。", "重さ": "「重さ」は重量の語で、置く位置を表す名詞として成り立たない。", "名前": "「名前」は呼び名の語で、コップを置く場所にはならない。"}, "sentence_index": 0, "correct_answer": "端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "川に端をかけて、向こう岸へ渡った。", "explanation": "ここは〈橋〉の意味。端は物の縁を指すので、川にかける橋には使えない。"}, {"text": "この争いは、小さな誤解に端を発している。", "explanation": "ここは〈起こり・始まり〉の意味。「端を発する」は〈〜から始まる〉という別の意味で、ものの縁を指す端の意味では合わない。"}, {"text": "天ぷらを端でつまんで、食べた。", "explanation": "ここは同音の〈箸〉の意味。天ぷらをつまむ道具は箸で、ものの縁を指す端とは書かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38358, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "端", "is_correct": true, "explanation": "「廊下の端に」で窓のある位置を示し、「ある」と自然に合う。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さ」は重量の語で、窓の位置を表せず「廊下の重さに窓がある」は成り立たない。"}, {"text": "声", "is_correct": false, "explanation": "「声」は音声の語で、場所を示す名詞として「廊下の声に窓がある」は不自然。"}, {"text": "味", "is_correct": false, "explanation": "「味」は味覚の語で、廊下の中の位置を示せない。"}], "explanations": {"端": "「廊下の端に」で窓のある位置を示し、「ある」と自然に合う。", "重さ": "「重さ」は重量の語で、窓の位置を表せず「廊下の重さに窓がある」は成り立たない。", "声": "「声」は音声の語で、場所を示す名詞として「廊下の声に窓がある」は不自然。", "味": "「味」は味覚の語で、廊下の中の位置を示せない。"}, "sentence_index": 6, "correct_answer": "端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みの端に、宿題をまとめて終わらせた。", "explanation": "ここは〈終わり〉の意味。端は物の縁を指し、期間の終わりには使わない。"}, {"text": "お釣りの端を切り捨てて、百円にした。", "explanation": "ここは〈端数〉の意味。端だけでは数の端数を指さないので、「端数」という語を使う。"}, {"text": "パソコンの端を操作して、ファイルを開いた。", "explanation": "ここは〈端末〉の意味。パソコンなどの機器は端末と言い、ものの縁を指す端では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38358, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テーブルの端を、コップを置いてください。", "corrected_sentence": "テーブルの端に、コップを置いてください。", "error_description": "場所を示す「に」が正しい。「を」だと端が目的語になり、「置く」の位置が示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38358, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ロープの端が、しっかり結んだ。", "corrected_sentence": "ロープの端を、しっかり結んだ。", "error_description": "結ぶ対象は「を」で示す。「が」だと端が主語になり、「結んだ」の目的語が欠けて文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38359, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「庭の端に」で花を植える場所を示し、「植えた」と合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「庭の端が花を植えた」では植えた主体が不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「端を花を植えた」では二つの目的語が並び不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「端と植えた」では位置を示せない。"}], "correct_answer": "に", "explanations": {"に": "「庭の端に」で花を植える場所を示し、「植えた」と合う。", "が": "「が」は主語を示すが、「庭の端が花を植えた」では植えた主体が不自然。", "を": "「を」は目的語を示すが、「端を花を植えた」では二つの目的語が並び不自然。", "と": "「と」は相手や並列を示すが、「端と植えた」では位置を示せない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38359, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「地図の端に」で書かれている場所を示し、「書いてある」と合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「端を書いてある」では場所を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「地図の端が」では端が書く主体になり、「書いてある」と合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾で、「端の、書いてある」と続けると文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「地図の端に」で書かれている場所を示し、「書いてある」と合う。", "を": "「を」は目的語を示すが、「端を書いてある」では場所を示せない。", "が": "「地図の端が」では端が書く主体になり、「書いてある」と合わない。", "の": "「の」は連体修飾で、「端の、書いてある」と続けると文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38359, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物や場所の、端（はし）・ふち・きわ。", "primary_collocate": null, "pronunciation": "はし", "ipa": "haɕi", "syllable_count": 2, "sentences": [{"text": "公園の端に古い神社がある。", "target_word": "端", "complexity_tier": "T3", "furigana": "公園(こうえん)の端(はし)に古(ふる)い神社(じんじゃ)がある。", "sentence_source": "generated"}, {"text": "庭の端に小さな花を植えた。", "target_word": "端", "complexity_tier": "T3", "furigana": "庭(にわ)の端(はし)に小(ちい)さな花(はな)を植(う)えた。", "sentence_source": "generated"}, {"text": "部屋の端にある棚から本を取った。", "target_word": "端", "complexity_tier": "T3", "furigana": "部屋(へや)の端(はし)にある棚(たな)から本(ほん)を取(と)った。", "sentence_source": "generated"}, {"text": "崖の端に立つと、足がふるえた。", "target_word": "端", "complexity_tier": "T3", "furigana": "崖(がけ)の端(はし)に立(た)つと、足(あし)がふるえた。", "sentence_source": "generated"}, {"text": "机の端に手をぶつけて、痛かった。", "target_word": "端", "complexity_tier": "T3", "furigana": "机(つくえ)の端(はし)に手(て)をぶつけて、痛(いた)かった。", "sentence_source": "generated"}, {"text": "畑の端に、大きな木が一本ある。", "target_word": "端", "complexity_tier": "T3", "furigana": "畑(はたけ)の端(はし)に、大(おお)きな木(き)が一本(いっぽん)ある。", "sentence_source": "generated"}, {"text": "舞台の端から見ると、客席がよく見える。", "target_word": "端", "complexity_tier": "T3", "furigana": "舞台(ぶたい)の端(はし)から見(み)ると、客席(きゃくせき)がよく見(み)える。", "sentence_source": "generated"}, {"text": "地図の端に、小さく名前が書いてある。", "target_word": "端", "complexity_tier": "T3", "furigana": "地図(ちず)の端(はし)に、小(ちい)さく名前(なまえ)が書(か)いてある。", "sentence_source": "generated"}, {"text": "道路の端に自転車を止めないでください。", "target_word": "端", "complexity_tier": "T3", "furigana": "道路(どうろ)の端(はし)に自転車(じてんしゃ)を止(と)めないでください。", "sentence_source": "generated"}, {"text": "ホームの端は危ないので、下がってください。", "target_word": "端", "complexity_tier": "T3", "furigana": "ホームの端(はし)は危(あぶ)ないので、下(さ)がってください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "端", "label": "基本形"}], "register": "標準語", "sense_fingerprint": "物や場所の縁・きわ・外れの部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38359, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "端", "is_correct": true, "explanation": "「公園の端に」は神社がある位置を示し、「ある」と自然に合う。"}, {"text": "音", "is_correct": false, "explanation": "「音」は物音の語で、「公園の音に神社がある」は成り立たない。"}, {"text": "値段", "is_correct": false, "explanation": "「値段」は価格の語で、神社の位置を表せない。"}, {"text": "名前", "is_correct": false, "explanation": "「名前」は呼び名の語で、場所を示す語にならない。"}], "explanations": {"端": "「公園の端に」は神社がある位置を示し、「ある」と自然に合う。", "音": "「音」は物音の語で、「公園の音に神社がある」は成り立たない。", "値段": "「値段」は価格の語で、神社の位置を表せない。", "名前": "「名前」は呼び名の語で、場所を示す語にならない。"}, "sentence_index": 0, "correct_answer": "端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "端で豆をつまんで、食べた。", "explanation": "ここは同音の〈箸〉の意味。箸は食べ物をつまむ道具で、端は物の縁を指すので合わない。"}, {"text": "この騒ぎは、ささいな言い争いに端を発した。", "explanation": "ここは〈起こり・始まり〉の意味。「端を発する」は〈〜から始まる〉という別の意味で、ものの縁を指す端とは使い方が違う。"}, {"text": "タブレットの端を操作して、アプリを開いた。", "explanation": "「端を操作する」は縁の位置を指すだけで操作の対象にならず、不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38359, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "端", "is_correct": true, "explanation": "「舞台の端から」で見る位置を示し、客席がよく見えるという文脈に合う。"}, {"text": "色", "is_correct": false, "explanation": "「色」は色彩の語で、見る位置の起点にならない。"}, {"text": "値段", "is_correct": false, "explanation": "「値段」は価格の語で、見る位置を示せない。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さ」は重量の語で、見る場所の起点にならない。"}], "explanations": {"端": "「舞台の端から」で見る位置を示し、客席がよく見えるという文脈に合う。", "色": "「色」は色彩の語で、見る位置の起点にならない。", "値段": "「値段」は価格の語で、見る位置を示せない。", "重さ": "「重さ」は重量の語で、見る場所の起点にならない。"}, "sentence_index": 6, "correct_answer": "端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お小遣いの端を切り捨てて、千円にした。", "explanation": "ここは〈端数〉の意味。端だけでは数の端数を指さないので、「端数」という語を使う。"}, {"text": "一週間の端に、部屋を掃除した。", "explanation": "ここは〈終わり〉の意味。端は物の縁を指し、期間の終わりには使わない。"}, {"text": "研究の端を開いて、新しい分野に進んだ。", "explanation": "ここは〈端緒（たんしょ）〉の意味。「端緒を開く」は物事の始まりを作ることで、ものの縁を指す端では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38359, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "崖の端と、落ちないように注意してください。", "corrected_sentence": "崖の端から、落ちないように注意してください。", "error_description": "起点を示す「から」が正しい。「と」では並列や相手を示すことになり、「落ちないように」と続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38359, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ポスターの端が、小さく日付を書いた。", "corrected_sentence": "ポスターの端に、小さく日付を書いた。", "error_description": "書く場所は「に」で示す。「が」だと端が書く主体になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38362, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "起点を表す『から』。種を出どころとして花がさく、という自然な因果関係を示す。"}, {"text": "を", "is_correct": false, "explanation": "『を』は対象を示すが、『さく』は目的語を取らないため、『この種を』では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』。『種へ赤い花がさく』は不自然で、結果の関係を表せない。"}, {"text": "に", "is_correct": false, "explanation": "場所を表す『に』。『種に』は咲く場所にならず、『この種に赤い花がさく』は不自然。"}], "correct_answer": "から", "explanations": {"から": "起点を表す『から』。種を出どころとして花がさく、という自然な因果関係を示す。", "を": "『を』は対象を示すが、『さく』は目的語を取らないため、『この種を』では文が成り立たない。", "へ": "方向を表す『へ』。『種へ赤い花がさく』は不自然で、結果の関係を表せない。", "に": "場所を表す『に』。『種に』は咲く場所にならず、『この種に赤い花がさく』は不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "に": "場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38362, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を示す『を』。『種を植える』の目的語として文に合う。"}, {"text": "に", "is_correct": false, "explanation": "方向・位置を表す『に』。『種に植える』では植える対象を示せず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表す『で』。『種で植える』は手段として不自然で、文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の『の』。種を修飾するだけで、動詞『植える』の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "対象を示す『を』。『種を植える』の目的語として文に合う。", "に": "方向・位置を表す『に』。『種に植える』では植える対象を示せず、不自然。", "で": "手段・場所を表す『で』。『種で植える』は手段として不自然で、文の意味が通らない。", "の": "連体修飾の『の』。種を修飾するだけで、動詞『植える』の目的語にはならない。"}, "error_tags": {"に": "方向・位置", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38362, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たねは、あたらしい くさや はなに なる ものです。", "primary_collocate": null, "pronunciation": "たね", "ipa": "tane", "syllable_count": 2, "sentences": [{"text": "春になったので、庭に花の種をまいた。", "target_word": "種", "complexity_tier": "T3", "furigana": "春[はる]になったので、 庭[にわ]に 花[はな]の 種[たね]をまいた。", "sentence_source": "generated"}, {"text": "この種から、赤い花がさく。", "target_word": "種", "complexity_tier": "T3", "furigana": "この 種[たね]から、 赤[あか]い 花[はな]がさく。", "sentence_source": "generated"}, {"text": "小さな種でも、水をやれば芽が出る。", "target_word": "種", "complexity_tier": "T3", "furigana": "小[ちい]さな 種[たね]でも、 水[みず]をやれば 芽[め]が 出[で]る。", "sentence_source": "generated"}, {"text": "すいかを食べるとき、黒い種を出した。", "target_word": "種", "complexity_tier": "T3", "furigana": "すいかを 食[た]べるとき、 黒[くろ]い 種[たね]を 出[だ]した。", "sentence_source": "generated"}, {"text": "鳥がこの木の種を運んで、遠くに落とした。", "target_word": "種", "complexity_tier": "T3", "furigana": "鳥[とり]がこの 木[き]の 種[たね]を 運[はこ]んで、 遠[とお]くに 落[お]とした。", "sentence_source": "generated"}, {"text": "ひまわりの種は、土に入れてから一週間で芽を出した。", "target_word": "種", "complexity_tier": "T3", "furigana": "ひまわりの 種[たね]は、 土[つち]に 入[い]れてから 一週間[いっしゅうかん]で 芽[め]を 出[だ]した。", "sentence_source": "generated"}, {"text": "店で野菜の種を買って、ベランダで育てている。", "target_word": "種", "complexity_tier": "T3", "furigana": "店[みせ]で 野菜[やさい]の 種[たね]を 買[か]って、ベランダで 育[そだ]てている。", "sentence_source": "generated"}, {"text": "種を植えなければ、花は咲かない。", "target_word": "種", "complexity_tier": "T3", "furigana": "種[たね]を 植[う]えなければ、 花[はな]は 咲[さ]かない。", "sentence_source": "generated"}, {"text": "祖父は毎年、あさがおの種を集めておく。", "target_word": "種", "complexity_tier": "T3", "furigana": "祖父[そふ]は 毎年[まいとし]、あさがおの 種[たね]を 集[あつ]めておく。", "sentence_source": "generated"}, {"text": "風が吹いて、たんぽぽの種が空へ飛んでいった。", "target_word": "種", "complexity_tier": "T3", "furigana": "風[かぜ]が 吹[ふ]いて、たんぽぽの 種[たね]が 空[そら]へ 飛[と]んでいった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "種", "label": "基本形"}], "register": "口語（普通体）", "sense_fingerprint": "植物の種子（たね）。土にまくと芽が出て新しい草や花になるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38362, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "種", "is_correct": true, "explanation": "まく対象は種。植物の種子を土にまく、という意味で文に合う。"}, {"text": "葉", "is_correct": false, "explanation": "植物の一部だが、まくものではない。『花の葉をまいた』は意味が通らない。"}, {"text": "根", "is_correct": false, "explanation": "地中に伸びる植物の器官で、まく対象にはならない。『花の根をまいた』は成り立たない。"}, {"text": "幹", "is_correct": false, "explanation": "木の太い部分で、まく対象にはならない。『花の幹をまいた』は不自然で通らない。"}], "explanations": {"種": "まく対象は種。植物の種子を土にまく、という意味で文に合う。", "葉": "植物の一部だが、まくものではない。『花の葉をまいた』は意味が通らない。", "根": "地中に伸びる植物の器官で、まく対象にはならない。『花の根をまいた』は成り立たない。", "幹": "木の太い部分で、まく対象にはならない。『花の幹をまいた』は不自然で通らない。"}, "sentence_index": 0, "correct_answer": "種"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、母は種を研いで、ごはんを炊いた。", "explanation": "研ぐのは米で、〈種〉を研ぐとは言わない。"}, {"text": "夏休みに、壁に種を塗った。", "explanation": "ペンキは塗るものだが、〈種〉を塗るとは言わない。"}, {"text": "砂糖の種をコーヒーに入れた。", "explanation": "砂糖の小さな粒を〈種〉とは言わず、不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38362, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "種", "is_correct": true, "explanation": "育てるために種を買う、という意味になり、文に合う。"}, {"text": "花びら", "is_correct": false, "explanation": "花の一部で、野菜として買って育てるものではないため、文に合わない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "地面に落ちた葉で、買って育てるものではない。『野菜の落ち葉を買って』は成り立たない。"}, {"text": "枯れ草", "is_correct": false, "explanation": "枯れた草で、買って育てるものではないため、『野菜の枯れ草を買って』は不自然。"}], "explanations": {"種": "育てるために種を買う、という意味になり、文に合う。", "花びら": "花の一部で、野菜として買って育てるものではないため、文に合わない。", "落ち葉": "地面に落ちた葉で、買って育てるものではない。『野菜の落ち葉を買って』は成り立たない。", "枯れ草": "枯れた草で、買って育てるものではないため、『野菜の枯れ草を買って』は不自然。"}, "sentence_index": 6, "correct_answer": "種"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鳥が巣で種を産んだ。", "explanation": "鳥が産むのは卵で、〈種〉は産むものではないので合わない。"}, {"text": "おばあちゃんは種を織って、着物を作った。", "explanation": "布は織るものだが、〈種〉を織るとは言わない。"}, {"text": "割れた窓ガラスの種を集めた。", "explanation": "割れたガラスには〈欠片〉を使い、〈種〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38362, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、庭に花の種がまいた。", "corrected_sentence": "先週、庭に花の種をまいた。", "error_description": "『まく』の対象は『を』で示す。『種が』と書くと『種』が主語になり、『まいた』の動作主がなくなって文が成り立たない。『種を』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38362, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小さな一本の種から、大きな木が育った。", "corrected_sentence": "小さな一粒の種から、大きな木が育った。", "error_description": "種を数える助数詞は『粒』。『本』は細長い物を数える助数詞なので、『一本の種』は不自然。『一粒の種』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38364, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「種を蒔く」で蒔く対象を示す自然な目的語。"}, {"text": "が", "is_correct": false, "explanation": "「種が蒔く」は種が主語になり、人が蒔く文脈と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「種と蒔く」は並列や相手を示し、蒔く対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「種の蒔く」は連体修飾となり、文の述語として続かない。"}], "correct_answer": "を", "explanations": {"を": "「種を蒔く」で蒔く対象を示す自然な目的語。", "が": "「種が蒔く」は種が主語になり、人が蒔く文脈と合わない。", "と": "「種と蒔く」は並列や相手を示し、蒔く対象を示せない。", "の": "「種の蒔く」は連体修飾となり、文の述語として続かない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38364, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「春に蒔いた」で蒔いた時期を示し、夏の結果へ続く文脈に合う。"}, {"text": "を", "is_correct": false, "explanation": "「春を蒔いた種」は時期ではなく対象を示すことになり、意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「春が蒔いた」は春が主語になり、蒔く主体として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「春と蒔いた」は並列や相手を示し、時期を表せない。"}], "correct_answer": "に", "explanations": {"に": "「春に蒔いた」で蒔いた時期を示し、夏の結果へ続く文脈に合う。", "を": "「春を蒔いた種」は時期ではなく対象を示すことになり、意味が通らない。", "が": "「春が蒔いた」は春が主語になり、蒔く主体として不自然。", "と": "「春と蒔いた」は並列や相手を示し、時期を表せない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38364, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "たねを土の上に置くことです。", "primary_collocate": null, "pronunciation": "まく", "ipa": "makɯ", "syllable_count": 2, "sentences": [{"text": "春になったら、畑に花の種を蒔きます。", "target_word": "蒔きます", "complexity_tier": "T3", "furigana": "春(はる)になったら、畑(はたけ)に花(はな)の種(たね)を蒔(ま)きます。", "sentence_source": "generated"}, {"text": "祖父は毎年、五月に豆の種を蒔く。", "target_word": "蒔く", "complexity_tier": "T3", "furigana": "祖父(そふ)は毎年(まいとし)、五月(ごがつ)に豆(まめ)の種(たね)を蒔(ま)く。", "sentence_source": "generated"}, {"text": "雨の前に種を蒔いたので、芽が早く出た。", "target_word": "蒔いた", "complexity_tier": "T3", "furigana": "雨(あめ)の前(まえ)に種(たね)を蒔(ま)いたので、芽(め)が早(はや)く出(で)た。", "sentence_source": "generated"}, {"text": "種を蒔かないと、花は咲きません。", "target_word": "蒔かない", "complexity_tier": "T3", "furigana": "種(たね)を蒔(ま)かないと、花(はな)は咲(さ)きません。", "sentence_source": "generated"}, {"text": "子どもたちは小さな庭に朝顔の種を蒔いた。", "target_word": "蒔いた", "complexity_tier": "T3", "furigana": "子(こ)どもたちは小(ちい)さな庭(にわ)に朝顔(あさがお)の種(たね)を蒔(ま)いた。", "sentence_source": "generated"}, {"text": "土をやわらかくしてから、種を蒔いてください。", "target_word": "蒔いて", "complexity_tier": "T3", "furigana": "土(つち)をやわらかくしてから、種(たね)を蒔(ま)いてください。", "sentence_source": "generated"}, {"text": "寒い日は芽が出にくいから、種を蒔かない方がいい。", "target_word": "蒔かない", "complexity_tier": "T3", "furigana": "寒(さむ)い日(ひ)は芽(め)が出(で)にくいから、種(たね)を蒔(ま)かない方(ほう)がいい。", "sentence_source": "generated"}, {"text": "春に蒔いた種が、夏に大きく育った。", "target_word": "蒔いた", "complexity_tier": "T3", "furigana": "春(はる)に蒔(ま)いた種(たね)が、夏(なつ)に大(おお)きく育(そだ)った。", "sentence_source": "generated"}, {"text": "農家の人が広い畑に麦の種を蒔いている。", "target_word": "蒔いて", "complexity_tier": "T3", "furigana": "農家(のうか)の人(ひと)が広(ひろ)い畑(はたけ)に麦(むぎ)の種(たね)を蒔(ま)いている。", "sentence_source": "generated"}, {"text": "母は庭に野菜の種を蒔くのが好きだ。", "target_word": "蒔く", "complexity_tier": "T3", "furigana": "母(はは)は庭(にわ)に野菜(やさい)の種(たね)を蒔(ま)くのが好(す)きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒔く", "label": "辞書形"}, {"form": "蒔きます", "label": "丁寧形"}, {"form": "蒔いた", "label": "過去形"}, {"form": "蒔いて", "label": "て形"}, {"form": "蒔かない", "label": "否定形"}, {"form": "蒔けば", "label": "仮定形"}, {"form": "蒔こう", "label": "意志形"}], "register": "標準語", "sense_fingerprint": "種を土にまき散らして植える（種蒔き）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38364, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蒔きます", "is_correct": true, "explanation": "種を畑にまく動作で、春に花を育てる文脈に合う丁寧形。"}, {"text": "拾います", "is_correct": false, "explanation": "拾うは落ちた物を集める動作で、種を畑に置く文脈には合わない。"}, {"text": "磨きます", "is_correct": false, "explanation": "磨くは表面を擦る動作で、種を畑に撒く場面では成り立たない。"}, {"text": "洗います", "is_correct": false, "explanation": "洗うは汚れを落とす動作で、畑に種を植える文脈に合わない。"}], "explanations": {"蒔きます": "種を畑にまく動作で、春に花を育てる文脈に合う丁寧形。", "拾います": "拾うは落ちた物を集める動作で、種を畑に置く文脈には合わない。", "磨きます": "磨くは表面を擦る動作で、種を畑に撒く場面では成り立たない。", "洗います": "洗うは汚れを落とす動作で、畑に種を植える文脈に合わない。"}, "sentence_index": 0, "correct_answer": "蒔きます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "苗を蒔いて、来年の春に実を取った。", "explanation": "ここは〈植える〉の意味。苗は土に植えるもので、種のように蒔くとは言わない。"}, {"text": "床にゴミを蒔いてしまった。", "explanation": "ここは〈散らかす〉の意味。蒔くは種を土に植える行為で、ゴミを散らす意味では使わない。"}, {"text": "ロープを蒔いて、木にかけた。", "explanation": "ここは同音の〈巻く〉の意味。ロープを巻く動作に蒔くは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38364, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒔かない", "is_correct": true, "explanation": "「種を蒔かない方がいい」で、寒い日は芽が出にくいという理由に合う。"}, {"text": "拾わない", "is_correct": false, "explanation": "拾うは落ちた物を集める動作で、芽が出にくい理由からは続かない。"}, {"text": "磨かない", "is_correct": false, "explanation": "磨くは表面を擦る動作で、種の芽の話題とは噛み合わない。"}, {"text": "食べない", "is_correct": false, "explanation": "食べないは食用の話で、芽が出にくいという理由と結びつかない。"}], "explanations": {"蒔かない": "「種を蒔かない方がいい」で、寒い日は芽が出にくいという理由に合う。", "拾わない": "拾うは落ちた物を集める動作で、芽が出にくい理由からは続かない。", "磨かない": "磨くは表面を擦る動作で、種の芽の話題とは噛み合わない。", "食べない": "食べないは食用の話で、芽が出にくいという理由と結びつかない。"}, "sentence_index": 6, "correct_answer": "蒔かない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の草を蒔いて、きれいにした。", "explanation": "ここは〈刈る〉の意味。草は刈るもので、蒔くとは言わない。"}, {"text": "ケーキにクリームを蒔いた。", "explanation": "ここは〈塗る〉の意味。クリームは塗るか絞るもので、蒔くとは言わない。"}, {"text": "舞台の幕を蒔いて、芝居を始めた。", "explanation": "ここは〈上げる・開ける〉の意味。蒔くは種を土に置く行為で、上げたり開けたりする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38364, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑に大豆の種が蒔いた。", "corrected_sentence": "畑に大豆の種を蒔いた。", "error_description": "蒔く対象の種は「を」で示す。「が」だと種が蒔く主語になり、人が蒔く文として不自然になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "蒔く", "is_correct": true, "explanation": "辞書形。「毎年」の習慣を述べる普通体の文末として正しい。"}, {"text": "蒔き", "is_correct": false, "explanation": "連用形だけでは文が終わらず、非文になる。"}, {"text": "蒔け", "is_correct": false, "explanation": "命令形で、習慣を述べる文末として成り立たない。"}, {"text": "蒔かない", "is_correct": false, "explanation": "否定形。蒔くという習慣を肯定で述べる文の意味と反対になる。"}], "correct_form": "蒔く", "base_form": "蒔く", "form_label": "辞書形", "sentence_index": 1, "explanations": {"蒔く": "辞書形。「毎年」の習慣を述べる普通体の文末として正しい。", "蒔き": "連用形だけでは文が終わらず、非文になる。", "蒔け": "命令形で、習慣を述べる文末として成り立たない。", "蒔かない": "否定形。蒔くという習慣を肯定で述べる文の意味と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38364, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春に種を蒔くて、夏に大きく育てた。", "corrected_sentence": "春に種を蒔いて、夏に大きく育てた。", "error_description": "「蒔く」のて形は「蒔いて」。「蒔くて」は活用の誤りになる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "蒔いた", "is_correct": true, "explanation": "過去形。「春に」蒔いた種が夏に育ったという完了の結果に合う。"}, {"text": "蒔いて", "is_correct": false, "explanation": "て形。連用形なので、名詞「種」を直接修飾して「〜た種」の形にならない。"}, {"text": "蒔こう", "is_correct": false, "explanation": "意志形。「春に蒔こう種が」と名詞を修飾できず、過去に蒔いた結果を表せないので非文になる。"}, {"text": "蒔いたら", "is_correct": false, "explanation": "条件を表す形。「春に蒔いたら種が」と続けると種を修飾できず、文として成り立たない。"}], "correct_form": "蒔いた", "base_form": "蒔く", "form_label": "過去形", "sentence_index": 7, "explanations": {"蒔いた": "過去形。「春に」蒔いた種が夏に育ったという完了の結果に合う。", "蒔いて": "て形。連用形なので、名詞「種」を直接修飾して「〜た種」の形にならない。", "蒔こう": "意志形。「春に蒔こう種が」と名詞を修飾できず、過去に蒔いた結果を表せないので非文になる。", "蒔いたら": "条件を表す形。「春に蒔いたら種が」と続けると種を修飾できず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38365, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「種を蒔いた」で蒔く対象を示す自然な目的語。"}, {"text": "が", "is_correct": false, "explanation": "「種が蒔いた」は種が主語になり、人が蒔いた文脈と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「種と蒔いた」は並列や相手を示し、蒔く対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「種の蒔いた」は連体修飾となり、文の述語として続かない。"}], "correct_answer": "を", "explanations": {"を": "「種を蒔いた」で蒔く対象を示す自然な目的語。", "が": "「種が蒔いた」は種が主語になり、人が蒔いた文脈と合わない。", "と": "「種と蒔いた」は並列や相手を示し、蒔く対象を示せない。", "の": "「種の蒔いた」は連体修飾となり、文の述語として続かない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38365, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「種を蒔くとき」で蒔く対象を示す自然な目的語。"}, {"text": "へ", "is_correct": false, "explanation": "「種へ蒔くとき」は方向を示す形になり、蒔く対象を示す文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「種で蒔くとき」は手段を示す形になり、蒔く対象を示せず文意が合わない。"}, {"text": "より", "is_correct": false, "explanation": "「種より蒔くとき」は比較を示す形になり、蒔く対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「種を蒔くとき」で蒔く対象を示す自然な目的語。", "へ": "「種へ蒔くとき」は方向を示す形になり、蒔く対象を示す文として不自然。", "で": "「種で蒔くとき」は手段を示す形になり、蒔く対象を示せず文意が合わない。", "より": "「種より蒔くとき」は比較を示す形になり、蒔く対象を示せない。"}, "error_tags": {"へ": "direction", "で": "means", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38365, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "植物の種を土の中や上に置いて育てるために植えること。", "primary_collocate": null, "pronunciation": "まく", "ipa": "makɯ", "syllable_count": 2, "sentences": [{"text": "秋に蒔く種と、春に蒔く種は違います。", "target_word": "蒔く", "complexity_tier": "T3", "furigana": "秋(あき)に蒔(ま)く種(たね)と、春(はる)に蒔(ま)く種(たね)は違(ちが)います。", "sentence_source": "generated"}, {"text": "庭にひまわりの種を蒔いたが、まだ芽が出ない。", "target_word": "蒔いた", "complexity_tier": "T3", "furigana": "庭(にわ)にひまわりの種(たね)を蒔(ま)いたが、まだ芽(め)が出(で)ない。", "sentence_source": "generated"}, {"text": "この花は、四月に種を蒔けば、夏に咲く。", "target_word": "蒔けば", "complexity_tier": "T3", "furigana": "この花(はな)は、四月(しがつ)に種(たね)を蒔(ま)けば、夏(なつ)に咲(さ)く。", "sentence_source": "generated"}, {"text": "鉢に種を蒔いて、毎日水をやっている。", "target_word": "蒔いて", "complexity_tier": "T3", "furigana": "鉢(はち)に種(たね)を蒔(ま)いて、毎日(まいにち)水(みず)をやっている。", "sentence_source": "generated"}, {"text": "兄は畑にトマトの種を蒔こうと考えている。", "target_word": "蒔こう", "complexity_tier": "T3", "furigana": "兄(あに)は畑(はたけ)にトマトの種(たね)を蒔(ま)こうと考(かんが)えている。", "sentence_source": "generated"}, {"text": "種を深く蒔きすぎると、芽が出にくい。", "target_word": "蒔き", "complexity_tier": "T3", "furigana": "種(たね)を深(ふか)く蒔(ま)きすぎると、芽(め)が出(で)にくい。", "sentence_source": "generated"}, {"text": "去年蒔いた種が、今年きれいな花になった。", "target_word": "蒔いた", "complexity_tier": "T3", "furigana": "去年(きょねん)蒔(ま)いた種(たね)が、今年(ことし)きれいな花(はな)になった。", "sentence_source": "generated"}, {"text": "先生は、子どもたちに種を蒔くときの注意を説明した。", "target_word": "蒔く", "complexity_tier": "T3", "furigana": "先生[せんせい]は、子[こ]どもたちに種[たね]を蒔[ま]くときの注意[ちゅうい]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "雨のあとの土に、ほうれん草の種を蒔いた。", "target_word": "蒔いた", "complexity_tier": "T3", "furigana": "雨(あめ)のあとの土(つち)に、ほうれん草(そう)の種(たね)を蒔(ま)いた。", "sentence_source": "generated"}, {"text": "育てるために、小さな種を一つずつ蒔いた。", "target_word": "蒔いた", "complexity_tier": "T3", "furigana": "育(そだ)てるために、小(ちい)さな種(たね)を一(ひと)つずつ蒔(ま)いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒔く", "label": "辞書形"}, {"form": "蒔きます", "label": "丁寧形"}, {"form": "蒔いた", "label": "過去形"}, {"form": "蒔いて", "label": "て形"}, {"form": "蒔かない", "label": "否定形"}, {"form": "蒔けば", "label": "仮定形"}, {"form": "蒔こう", "label": "意志形"}], "register": "標準語", "sense_fingerprint": "植物を育てるために種を土に植える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c92b57b-6e70-433b-a166-7450a2630a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38365, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蒔く", "is_correct": true, "explanation": "「秋に蒔く種」で種まきの時期を表し、春の種と区別する文脈に合う。"}, {"text": "磨く", "is_correct": false, "explanation": "磨くは表面を擦る動作で、種の時期を区別する文脈に合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "洗うは汚れを落とす動作で、種を植える時期の区別とは結びつかない。"}, {"text": "砕く", "is_correct": false, "explanation": "砕くは細かくする動作で、種を植える時期を表す文脈に合わない。"}], "explanations": {"蒔く": "「秋に蒔く種」で種まきの時期を表し、春の種と区別する文脈に合う。", "磨く": "磨くは表面を擦る動作で、種の時期を区別する文脈に合わない。", "洗う": "洗うは汚れを落とす動作で、種を植える時期の区別とは結びつかない。", "砕く": "砕くは細かくする動作で、種を植える時期を表す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "蒔く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "球根を蒔いて、春に花を咲かせた。", "explanation": "ここは〈植える〉の意味。球根は土に植えるもので、蒔くとは言わない。"}, {"text": "床に紙くずを蒔いてしまった。", "explanation": "ここは〈散らかす〉の意味。蒔くは種を土に植える行為で、紙くずを散らす意味では使わない。"}, {"text": "テープを蒔いて、箱を留めた。", "explanation": "ここは同音の〈巻く〉の意味。テープを巻く動作に蒔くは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38365, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒔いた", "is_correct": true, "explanation": "「去年蒔いた種」で過去に種を撒いた事実を表し、今年の花へ続く文脈に合う。"}, {"text": "磨いた", "is_correct": false, "explanation": "磨いたは表面を擦った意味で、種が花になる文脈と合わない。"}, {"text": "砕いた", "is_correct": false, "explanation": "砕いたは細かくした意味で、きれいな花になるという結果と結びつかない。"}, {"text": "叩いた", "is_correct": false, "explanation": "叩いたは打つ動作で、種が花になる文脈には合わない。"}], "explanations": {"蒔いた": "「去年蒔いた種」で過去に種を撒いた事実を表し、今年の花へ続く文脈に合う。", "磨いた": "磨いたは表面を擦った意味で、種が花になる文脈と合わない。", "砕いた": "砕いたは細かくした意味で、きれいな花になるという結果と結びつかない。", "叩いた": "叩いたは打つ動作で、種が花になる文脈には合わない。"}, "sentence_index": 6, "correct_answer": "蒔いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑の雑草を蒔いて、きれいにした。", "explanation": "ここは〈刈る〉の意味。雑草は刈るもので、蒔くとは言わない。"}, {"text": "パンにバターを蒔いて、焼いた。", "explanation": "ここは〈塗る〉の意味。バターは塗るもので、蒔くとは言わない。"}, {"text": "舞台の幕を蒔いてから、芝居を始めた。", "explanation": "ここは〈上げる・開ける〉の意味。蒔くは種を土に置いて植えることで、上げたり開けたりする意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38365, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓辺に花の種が蒔いた。", "corrected_sentence": "窓辺に花の種を蒔いた。", "error_description": "蒔く対象の種は「を」で示す。「が」だと種が蒔く主語になり、人が蒔く文として不自然になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "蒔いた", "is_correct": true, "explanation": "過去形。既に撒いた種が芽を出していないという現状を述べる文に合う。"}, {"text": "蒔け", "is_correct": false, "explanation": "命令形は「が」で続かず、非文になる。"}, {"text": "蒔いて", "is_correct": false, "explanation": "て形。「〜たが」の文末の述語として接続できず、文が成り立たない。"}, {"text": "蒔かない", "is_correct": false, "explanation": "否定形。種を撒かなかったことになり、芽が出ないという状況と矛盾する。"}], "correct_form": "蒔いた", "base_form": "蒔く", "form_label": "過去形", "sentence_index": 1, "explanations": {"蒔いた": "過去形。既に撒いた種が芽を出していないという現状を述べる文に合う。", "蒔け": "命令形は「が」で続かず、非文になる。", "蒔いて": "て形。「〜たが」の文末の述語として接続できず、文が成り立たない。", "蒔かない": "否定形。種を撒かなかったことになり、芽が出ないという状況と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38365, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭に、小さな種を蒔った。", "corrected_sentence": "庭に、小さな種を蒔いた。", "error_description": "「蒔く」の過去形は「蒔いた」。「蒔った」は音便の誤りになる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "蒔く", "is_correct": true, "explanation": "辞書形。「蒔くときの」と時点を表す連体形として正しい。"}, {"text": "蒔きます", "is_correct": false, "explanation": "丁寧形。連体修飾の「蒔くとき」に丁寧形は入らない。"}, {"text": "蒔け", "is_correct": false, "explanation": "命令形は「蒔けとき」と連体修飾できず、非文になる。"}, {"text": "蒔こう", "is_correct": false, "explanation": "意志形は「蒔こうとき」と連体修飾できず、非文になる。"}], "correct_form": "蒔く", "base_form": "蒔く", "form_label": "辞書形", "sentence_index": 7, "explanations": {"蒔く": "辞書形。「蒔くときの」と時点を表す連体形として正しい。", "蒔きます": "丁寧形。連体修飾の「蒔くとき」に丁寧形は入らない。", "蒔け": "命令形は「蒔けとき」と連体修飾できず、非文になる。", "蒔こう": "意志形は「蒔こうとき」と連体修飾できず、非文になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7d7b84-b3d9-4330-99a8-9996d6dd38d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38366, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「私の父は」の「は」で、文の主題を示す係助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を先生をしている」となり、目的語が重なって文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「父に小学校の先生をしている」となり、対象を示すが意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「父で小学校の先生をしている」となり、手段の意味になって不自然。"}], "correct_answer": "は", "explanations": {"は": "「私の父は」の「は」で、文の主題を示す係助詞。", "を": "「を先生をしている」となり、目的語が重なって文が成り立たない。", "に": "「父に小学校の先生をしている」となり、対象を示すが意味が通らない。", "で": "「父で小学校の先生をしている」となり、手段の意味になって不自然。"}, "error_tags": {"を": "目的語の重複", "に": "相手・対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
