INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38366, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「父」は、おとうさんのことです。", "primary_collocate": null, "pronunciation": "ちち", "ipa": "tɕitɕi", "syllable_count": 2, "sentences": [{"text": "父は毎朝、六時に起きて散歩に行く。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]は毎朝[まいあさ]、六時[ろくじ]に起[お]きて散歩[さんぽ]に行[い]く。", "sentence_source": "generated"}, {"text": "私の父は小学校の先生をしている。", "target_word": "父", "complexity_tier": "T3", "furigana": "私[わたし]の父[ちち]は小学校[しょうがっこう]の先生[せんせい]をしている。", "sentence_source": "generated"}, {"text": "父と一緒に、日曜日に魚つりへ行った。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]と一緒[いっしょ]に、日曜日[にちようび]に魚[さかな]つりへ行[い]った。", "sentence_source": "generated"}, {"text": "父が作るカレーは、少し辛いけれどおいしい。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]が作[つく]るカレーは、少[すこ]し辛[から]いけれどおいしい。", "sentence_source": "generated"}, {"text": "父は仕事で帰りが遅いので、夕食は母と二人で食べた。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]で帰[かえ]りが遅[おそ]いので、夕食[ゆうしょく]は母[はは]と二人[ふたり]で食[た]べた。", "sentence_source": "generated"}, {"text": "誕生日に、父から新しい自転車をもらった。", "target_word": "父", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、父[ちち]から新[あたら]しい自転車[じてんしゃ]をもらった。", "sentence_source": "generated"}, {"text": "父に電話をして、駅まで迎えに来てもらった。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]に電話[でんわ]をして、駅[えき]まで迎[むか]えに来[き]てもらった。", "sentence_source": "generated"}, {"text": "父は新聞を読みながら、お茶を飲んでいる。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]は新聞[しんぶん]を読[よ]みながら、お茶[ちゃ]を飲[の]んでいる。", "sentence_source": "generated"}, {"text": "うちの父は犬が好きで、毎日散歩に連れていく。", "target_word": "父", "complexity_tier": "T3", "furigana": "うちの父[ちち]は犬[いぬ]が好[す]きで、毎日[まいにち]散歩[さんぽ]に連[つ]れていく。", "sentence_source": "generated"}, {"text": "父の背中を見て、私は働くことの大切さを知った。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]の背中[せなか]を見[み]て、私[わたし]は働[はたら]くことの大切[たいせつ]さを知[し]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "父", "label": "基本形"}], "register": "標準", "sense_fingerprint": "自分のおとうさん", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: 魚つり (Zipf 1.06)']::text[], 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38366, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は食品を冷やす機械で、毎朝起きて散歩に行く主語にはならない。"}, {"text": "父", "is_correct": true, "explanation": "父は人なので、毎朝六時に起きて散歩に行く主語として合う。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は衣類を洗う機械で、散歩に行く主語として文が成り立たない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機は掃除の道具で、散歩に行く主語として文意が合わない。"}], "explanations": {"冷蔵庫": "冷蔵庫は食品を冷やす機械で、毎朝起きて散歩に行く主語にはならない。", "父": "父は人なので、毎朝六時に起きて散歩に行く主語として合う。", "洗濯機": "洗濯機は衣類を洗う機械で、散歩に行く主語として文が成り立たない。", "掃除機": "掃除機は掃除の道具で、散歩に行く主語として文意が合わない。"}, "sentence_index": 0, "correct_answer": "父"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は私の母の弟で、毎年夏に一緒に海へ行く。", "explanation": "ここは〈おじ〉の意味。父は親の一人で、母の弟には使わないので合わない。"}, {"text": "父は私に勉強を教えてくれる、頼れる年上のきょうだいだ。", "explanation": "ここは〈兄〉の意味。父は親にあたり、きょうだいを指す言葉ではないので合わない。"}, {"text": "父は、私の夫の父親で、毎週日曜に家に遊びに来る。", "explanation": "ここは〈義父〉の意味。父は自分の父親を指すので、配偶者の父親には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38366, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電子レンジ", "is_correct": false, "explanation": "電子レンジは調理家電で、電話をかけて駅まで迎えに来てもらう相手にはならない。"}, {"text": "扇風機", "is_correct": false, "explanation": "扇風機は風を送る機械で、電話をかける相手として文が成り立たない。"}, {"text": "父", "is_correct": true, "explanation": "父は人なので、電話をかけて迎えに来てもらう相手として自然に入る。"}, {"text": "炊飯器", "is_correct": false, "explanation": "炊飯器はご飯を炊く機械で、電話をして迎えに来てもらう相手とは言えない。"}], "explanations": {"電子レンジ": "電子レンジは調理家電で、電話をかけて駅まで迎えに来てもらう相手にはならない。", "扇風機": "扇風機は風を送る機械で、電話をかける相手として文が成り立たない。", "父": "父は人なので、電話をかけて迎えに来てもらう相手として自然に入る。", "炊飯器": "炊飯器はご飯を炊く機械で、電話をして迎えに来てもらう相手とは言えない。"}, "sentence_index": 6, "correct_answer": "父"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は母の父親で、私が小さいころはよく遊んでくれた。", "explanation": "ここは〈祖父〉の意味。父は自分の親で、母の父親を指すことはできないので合わない。"}, {"text": "父は私の結婚相手で、一緒に暮らし始めて十年になる。", "explanation": "ここは〈夫〉の意味。父は親を指す語で、配偶者には使えないので合わない。"}, {"text": "父は三歳になって、保育園に通い始めた。", "explanation": "ここは〈息子〉の意味。父は親を指す語で、子どもを指すときには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
