INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38367, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「父の仕事」の「の」で、父を仕事の持ち主として修飾している。"}, {"text": "を", "is_correct": false, "explanation": "「父を仕事について聞かれた」となり、目的語の使い方が文に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「父で仕事について聞かれた」となり、手段の意味になって文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「父へ仕事について聞かれた」となり、方向の意味で不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「父の仕事」の「の」で、父を仕事の持ち主として修飾している。", "を": "「父を仕事について聞かれた」となり、目的語の使い方が文に合わない。", "で": "「父で仕事について聞かれた」となり、手段の意味になって文が成り立たない。", "へ": "「父へ仕事について聞かれた」となり、方向の意味で不自然になる。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
