INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38367, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「父」は、自分の父親を指す言葉です。家族の中で、子どもを育てる男性の親です。", "primary_collocate": null, "pronunciation": "ちち", "ipa": "tɕitɕi", "syllable_count": 2, "sentences": [{"text": "父は一人で私と妹を育ててくれた。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]は一人[ひとり]で私[わたし]と妹[いもうと]を育[そだ]ててくれた。", "sentence_source": "generated"}, {"text": "友だちに、父の仕事について聞かれた。", "target_word": "父", "complexity_tier": "T3", "furigana": "友[とも]だちに、父[ちち]の仕事[しごと]について聞[き]かれた。", "sentence_source": "generated"}, {"text": "父は厳しいが、困ったときはいつも助けてくれる。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]は厳[きび]しいが、困[こま]ったときはいつも助[たす]けてくれる。", "sentence_source": "generated"}, {"text": "母の日には花を、誕生日には父へネクタイを贈った。", "target_word": "父", "complexity_tier": "T3", "furigana": "母[はは]の日[ひ]には花[はな]を、誕生日[たんじょうび]には父[ちち]へネクタイを贈[おく]った。", "sentence_source": "generated"}, {"text": "先生に、父が来週の面談に来られないと伝えた。", "target_word": "父", "complexity_tier": "T3", "furigana": "先生[せんせい]に、父[ちち]が来週[らいしゅう]の面談[めんだん]に来[こ]られないと伝[つた]えた。", "sentence_source": "generated"}, {"text": "父は若いころ、家族のために遅くまで働いていた。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]は若[わか]いころ、家族[かぞく]のために遅[おそ]くまで働[はたら]いていた。", "sentence_source": "generated"}, {"text": "私は父に似て、ひとつのことに集中しすぎる。", "target_word": "父", "complexity_tier": "T3", "furigana": "私[わたし]は父[ちち]に似[に]て、ひとつのことに集中[しゅうちゅう]しすぎる。", "sentence_source": "generated"}, {"text": "父は私が泣いているとき、何も言わずにそばにいてくれた。", "target_word": "父", "complexity_tier": "T3", "furigana": "父[ちち]は私[わたし]が泣[な]いているとき、何[なに]も言[い]わずにそばにいてくれた。", "sentence_source": "generated"}, {"text": "結婚式で、父は涙を見せながら私に手を振った。", "target_word": "父", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]で、父[ちち]は涙[なみだ]を見[み]せながら私[わたし]に手[て]を振[ふ]った。", "sentence_source": "generated"}, {"text": "祖母の話では、父は子どものころ、とても元気な少年だったそうだ。", "target_word": "父", "complexity_tier": "T3", "furigana": "祖母[そぼ]の話[はなし]では、父[ちち]は子[こ]どものころ、とても元気[げんき]な少年[しょうねん]だったそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "父", "label": "基本形"}], "register": "標準", "sense_fingerprint": "自分の父親、子どもを育てる男性の親", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38367, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台風", "is_correct": false, "explanation": "台風は気象現象で、一人で子どもを育てる主語にはならないので文が成り立たない。"}, {"text": "父", "is_correct": true, "explanation": "父は人で、一人で私と妹を育ててくれた主語として自然に入る。"}, {"text": "郵便局", "is_correct": false, "explanation": "郵便局は施設で、子どもを育てる主語として文意が合わない。"}, {"text": "冷凍庫", "is_correct": false, "explanation": "冷凍庫は家電で、私と妹を育てるという文脈には合わない。"}], "explanations": {"台風": "台風は気象現象で、一人で子どもを育てる主語にはならないので文が成り立たない。", "父": "父は人で、一人で私と妹を育ててくれた主語として自然に入る。", "郵便局": "郵便局は施設で、子どもを育てる主語として文意が合わない。", "冷凍庫": "冷凍庫は家電で、私と妹を育てるという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "父"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は、私の夫の母親で、毎年おせち料理を届けてくれる。", "explanation": "ここは〈義母〉の意味。父は男性の親を指すので、夫の母親には使えないので合わない。"}, {"text": "父は、私の母の母で、毎年夏に料理の作り方を教えてくれる。", "explanation": "ここは〈祖母〉の意味。父は自分の父親で、母の母には当たらないので合わない。"}, {"text": "父は、私と結婚して十年になる、最も信頼する人だ。", "explanation": "ここは〈夫〉の意味。父は親を指す語で、配偶者には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38367, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紅茶", "is_correct": false, "explanation": "紅茶は飲み物で、「に似て」と人の性質を述べる文には合わない。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は設備で、性格や行動が似ているという文意には合わない。"}, {"text": "父", "is_correct": true, "explanation": "父は人で、「父に似て、ひとつのことに集中しすぎる」として自然に入る。"}, {"text": "地図", "is_correct": false, "explanation": "地図は道具で、人の性質が似ているという文脈には合わない。"}], "explanations": {"紅茶": "紅茶は飲み物で、「に似て」と人の性質を述べる文には合わない。", "電柱": "電柱は設備で、性格や行動が似ているという文意には合わない。", "父": "父は人で、「父に似て、ひとつのことに集中しすぎる」として自然に入る。", "地図": "地図は道具で、人の性質が似ているという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "父"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は母の弟で、子どものころ、よく釣りに連れていってくれた。", "explanation": "ここは〈叔父〉の意味。父は親の一人で、母の弟には使わないので合わない。"}, {"text": "父は私と同じ学校に通っている、頼れる年上のきょうだいだ。", "explanation": "ここは〈兄〉の意味。父は親にあたり、きょうだいを指す言葉ではないので合わない。"}, {"text": "父は姉の娘で、毎年夏に一緒に旅行へ行く。", "explanation": "ここは〈姪〉の意味。父は親を指す語で、姉の娘には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38367, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父を相談して、進路を決めた。", "corrected_sentence": "父に相談して、進路を決めた。", "error_description": "「相談する」は相手を「に」で示す。「父を」は誤りで、正しくは「父に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38367, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日、父を会う予定だ。", "corrected_sentence": "明日、父に会う予定だ。", "error_description": "「会う」は相手を「に」で示す。「父を」は誤りで、正しくは「父に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
