INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38368, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "ひとりぼっちで、だれかがいなくてつらく感じる気持ち。", "primary_collocate": null, "pronunciation": "さびしい", "ipa": "sabiɕiː", "syllable_count": 4, "sentences": [{"text": "家族が旅行に行って、一人で留守番をして寂しかった。", "target_word": "寂しかった", "complexity_tier": "T3", "furigana": "家族[かぞく]が旅行[りょこう]に行[い]って、一人[ひとり]で留守番[るすばん]をして寂[さび]しかった。", "sentence_source": "generated"}, {"text": "友だちが引っ越したので、毎日が寂しい。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "友[とも]だちが引[ひ]っ越[こ]したので、毎日[まいにち]が寂[さび]しい。", "sentence_source": "generated"}, {"text": "夜、一人で食事をすると、少し寂しくなります。", "target_word": "寂しく", "complexity_tier": "T3", "furigana": "夜[よる]、一人[ひとり]で食事[しょくじ]をすると、少[すこ]し寂[さび]しくなります。", "sentence_source": "generated"}, {"text": "犬がいなくなってから、ぼくはずっと寂しい。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "犬[いぬ]がいなくなってから、ぼくはずっと寂[さび]しい。", "sentence_source": "generated"}, {"text": "一人暮らしを始めた日は、寂しくて眠れなかった。", "target_word": "寂しくて", "complexity_tier": "T3", "furigana": "一人暮[ひとりぐ]らしを始[はじ]めた日[ひ]は、寂[さび]しくて眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "父が出張で、家に誰もいないから寂しい。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "父[ちち]が出張[しゅっちょう]で、家[いえ]に誰[だれ]もいないから寂[さび]しい。", "sentence_source": "generated"}, {"text": "寂しいときは、母に電話をかけます。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "寂[さび]しいときは、母[はは]に電話[でんわ]をかけます。", "sentence_source": "generated"}, {"text": "子どもたちが大きくなって出ていき、寂しいと祖母は言う。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "子[こ]どもたちが大[おお]きくなって出[で]ていき、寂[さび]しいと祖母[そぼ]は言[い]う。", "sentence_source": "generated"}, {"text": "運動会の日、一人だけ参加できなくて寂しかったです。", "target_word": "寂しかった", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の日[ひ]、一人[ひとり]だけ参加[さんか]できなくて寂[さび]しかったです。", "sentence_source": "generated"}, {"text": "寂しくても、明日になれば友だちに会える。", "target_word": "寂しくても", "complexity_tier": "T3", "furigana": "寂[さび]しくても、明日[あした]になれば友[とも]だちに会[あ]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寂しい", "label": "終止形・連体形"}, {"form": "寂しく", "label": "連用形"}, {"form": "寂しかった", "label": "過去形"}, {"form": "寂しくない", "label": "否定形"}, {"form": "寂しければ", "label": "仮定形"}], "register": "一般", "sense_fingerprint": "ひとりぼっちで、だれかがいなくてつらい気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38368, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寂しかった", "is_correct": true, "explanation": "ここは孤独でつらかった気持ちを表す過去形。文に合う。"}, {"text": "遠かった", "is_correct": false, "explanation": "「留守番をして遠かった」は意味が通らない。距離を表す語で、ここは合わない。"}, {"text": "大きかった", "is_correct": false, "explanation": "「留守番をして大きかった」は不自然で、気持ちを表さない。"}, {"text": "重かった", "is_correct": false, "explanation": "「留守番をして重かった」は文脈に合わない。物の重さを表す語。"}], "explanations": {"寂しかった": "ここは孤独でつらかった気持ちを表す過去形。文に合う。", "遠かった": "「留守番をして遠かった」は意味が通らない。距離を表す語で、ここは合わない。", "大きかった": "「留守番をして大きかった」は不自然で、気持ちを表さない。", "重かった": "「留守番をして重かった」は文脈に合わない。物の重さを表す語。"}, "sentence_index": 0, "correct_answer": "寂しかった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパンは寂しいほど硬い。", "explanation": "ここは〈硬い〉の意味。寂しいは一人で感じる孤独な気持ちを表すので、硬さを述べるこの文には合わない。"}, {"text": "明日の試験が寂しくて、よく眠れなかった。", "explanation": "ここは〈不安〉の意味。試験は孤独を感じる対象ではないので、「寂しい」は合わない。"}, {"text": "授業が寂しくて、いつも居眠りをした。", "explanation": "ここは〈退屈〉の意味。授業の退屈さは孤独感とは別なので、「寂しい」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38368, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂しい", "is_correct": true, "explanation": "「寂しいときは」の形で、つらい孤独の気持ちを表す。文に合う。"}, {"text": "硬い", "is_correct": false, "explanation": "「硬いときは、母に電話をかけます」は文脈に合わない。物の硬さを表す語。"}, {"text": "広い", "is_correct": false, "explanation": "「広いときは、母に電話をかけます」は意味が通らない。"}, {"text": "太い", "is_correct": false, "explanation": "「太いときは、母に電話をかけます」は意味をなさない。"}], "explanations": {"寂しい": "「寂しいときは」の形で、つらい孤独の気持ちを表す。文に合う。", "硬い": "「硬いときは、母に電話をかけます」は文脈に合わない。物の硬さを表す語。", "広い": "「広いときは、母に電話をかけます」は意味が通らない。", "太い": "「太いときは、母に電話をかけます」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "寂しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもの体調が寂しくて、夜も眠れない。", "explanation": "ここは〈心配〉の意味。体調を気にかける文に孤独の気持ちは合わないので、「寂しい」は使えない。"}, {"text": "合格の知らせが寂しくて、家族に電話した。", "explanation": "ここは〈嬉しい〉の意味。喜ばしい知らせに対して寂しさを述べるのは合わない。"}, {"text": "夕食は寂しいほど豪華だった。", "explanation": "ここは〈豪華〉の意味。寂しいは一人で感じる孤独な気持ちを表すので、豪華さを述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38368, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "転校の日、友だちがいなくなって寂しくた。", "corrected_sentence": "転校の日、友だちがいなくなって寂しかった。", "error_description": "形容詞「寂しい」の過去形は「寂しかった」。「寂しくた」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "寂しい", "is_correct": true, "explanation": "文末で気持ちを言い切る終止形。ここで正しい。"}, {"text": "寂しく", "is_correct": false, "explanation": "連用形。「寂しくなる」などで使うが、文末では止められないので合わない。"}, {"text": "寂しくない", "is_correct": false, "explanation": "否定形。「毎日が寂しくない」は引っ越しで孤独になった文脈と逆になるので合わない。"}, {"text": "寂しければ", "is_correct": false, "explanation": "仮定形。「もし寂しければ」の意味になり、ここでは合わない。"}], "correct_form": "寂しい", "base_form": "寂しい", "form_label": "終止形", "sentence_index": 1, "explanations": {"寂しい": "文末で気持ちを言い切る終止形。ここで正しい。", "寂しく": "連用形。「寂しくなる」などで使うが、文末では止められないので合わない。", "寂しくない": "否定形。「毎日が寂しくない」は引っ越しで孤独になった文脈と逆になるので合わない。", "寂しければ": "仮定形。「もし寂しければ」の意味になり、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38368, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みが終わって、教室が寂しなくなった。", "corrected_sentence": "夏休みが終わって、教室が寂しくなった。", "error_description": "形容詞「寂しい」は連用形「寂しく」に「なる」が続く。「寂しなく」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "寂しい", "is_correct": true, "explanation": "引用の「と」の前に置く終止形。ここで正しい。"}, {"text": "寂しくて", "is_correct": false, "explanation": "て形。「寂しくてと祖母は言う」とは続かず、引用の形にならないので合わない。"}, {"text": "寂しくない", "is_correct": false, "explanation": "否定形。寂しいと言う内容と逆になるので合わない。"}, {"text": "寂しかろう", "is_correct": false, "explanation": "推量の形。「寂しかろうと言う」は推し量る意味になり、祖母が今感じていると述べる文とは合わない。"}], "correct_form": "寂しい", "base_form": "寂しい", "form_label": "終止形", "sentence_index": 7, "explanations": {"寂しい": "引用の「と」の前に置く終止形。ここで正しい。", "寂しくて": "て形。「寂しくてと祖母は言う」とは続かず、引用の形にならないので合わない。", "寂しくない": "否定形。寂しいと言う内容と逆になるので合わない。", "寂しかろう": "推量の形。「寂しかろうと言う」は推し量る意味になり、祖母が今感じていると述べる文とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
