INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38369, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "人や物が足りず、にぎわいや満足がなくて物足りない様子。", "primary_collocate": null, "pronunciation": "さびしい", "ipa": "sabiɕiː", "syllable_count": 4, "sentences": [{"text": "客がほとんどいない商店街は、寂しい雰囲気だった。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "客[きゃく]がほとんどいない商店街[しょうてんがい]は、寂[さび]しい雰囲気[ふんいき]だった。", "sentence_source": "generated"}, {"text": "懐が寂しいので、今月は外食をやめた。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "懐[ふところ]が寂[さび]しいので、今月[こんげつ]は外食[がいしょく]をやめた。", "sentence_source": "generated"}, {"text": "木の葉が落ちた冬の公園は、どこか寂しい。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "木[き]の葉[は]が落[お]ちた冬[ふゆ]の公園[こうえん]は、どこか寂[さび]しい。", "sentence_source": "generated"}, {"text": "花が一つもない庭は、少し寂しく見える。", "target_word": "寂しく", "complexity_tier": "T3", "furigana": "花[はな]が一[ひと]つもない庭[にわ]は、少[すこ]し寂[さび]しく見[み]える。", "sentence_source": "generated"}, {"text": "にぎやかだった祭りのあとの道は、急に寂しくなった。", "target_word": "寂しく", "complexity_tier": "T3", "furigana": "にぎやかだった祭[まつ]りのあとの道[みち]は、急[きゅう]に寂[さび]しくなった。", "sentence_source": "generated"}, {"text": "友人の結婚式なのに、親戚が来なくて寂しい式だった。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の結婚式[けっこんしき]なのに、親戚[しんせき]が来[こ]なくて寂[さび]しい式[しき]だった。", "sentence_source": "generated"}, {"text": "話す相手がいない毎日は、心が寂しいままだ。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "話[はな]す相手[あいて]がいない毎日[まいにち]は、心[こころ]が寂[さび]しいままだ。", "sentence_source": "generated"}, {"text": "彼がいない教室は、何だか寂しく感じる。", "target_word": "寂しく", "complexity_tier": "T3", "furigana": "彼[かれ]がいない教室[きょうしつ]は、何[なん]だか寂[さび]しく感[かん]じる。", "sentence_source": "generated"}, {"text": "音楽のない車内は寂しいので、ラジオをつけた。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "音楽[おんがく]のない車内[しゃない]は寂[さび]しいので、ラジオをつけた。", "sentence_source": "generated"}, {"text": "最後の曲が終わると、客席はがらんとして、会場は寂しい空気になった。", "target_word": "寂しい", "complexity_tier": "T3", "furigana": "最後[さいご]の曲[きょく]が終[お]わると、客席[きゃくせき]はがらんとして、会場[かいじょう]は寂[さび]しい空気[くうき]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寂しい", "label": "終止形・連体形"}, {"form": "寂しく", "label": "連用形"}, {"form": "寂しかった", "label": "過去形"}, {"form": "寂しくない", "label": "否定形"}, {"form": "寂しければ", "label": "仮定形"}], "register": "一般", "sense_fingerprint": "人や物が足りず、にぎわいや満足がなくて物足りない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: がらん (Zipf 2.15)']::text[], 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38369, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寂しい", "is_correct": true, "explanation": "人や物が少なく、にぎわいがない様子を表す。「寂しい雰囲気」として文に合う。"}, {"text": "太い", "is_correct": false, "explanation": "「太い雰囲気」は意味をなさない。太さを表す語で、ここは合わない。"}, {"text": "四角い", "is_correct": false, "explanation": "「四角い雰囲気」は不自然。形を表す語で、雰囲気の文には合わない。"}, {"text": "大きい", "is_correct": false, "explanation": "「大きい雰囲気」は文として曖昧で、にぎわいのなさを表さない。"}], "explanations": {"寂しい": "人や物が少なく、にぎわいがない様子を表す。「寂しい雰囲気」として文に合う。", "太い": "「太い雰囲気」は意味をなさない。太さを表す語で、ここは合わない。", "四角い": "「四角い雰囲気」は不自然。形を表す語で、雰囲気の文には合わない。", "大きい": "「大きい雰囲気」は文として曖昧で、にぎわいのなさを表さない。"}, "sentence_index": 0, "correct_answer": "寂しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい靴は寂しくて、足が痛い。", "explanation": "ここは〈痛い〉の意味。寂しいは孤独や物足りなさを表すので、足の痛みを述べるこの文には合わない。"}, {"text": "このシャツは寂しいほど派手だ。", "explanation": "ここは〈派手〉の意味。寂しいは華やかさのない状態を表すので、派手さを述べるこの文には合わない。"}, {"text": "このかばんは寂しく、重くてすぐに疲れる。", "explanation": "ここは〈重い〉の意味。寂しいは心の状態を表すので、かばんの重さを述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38369, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂しい", "is_correct": true, "explanation": "心が満たされず物足りない様子を表す。「心が寂しいまま」として文に合う。"}, {"text": "細長い", "is_correct": false, "explanation": "「心が細長いままだ」は意味が通らない。形を表す語で、ここは合わない。"}, {"text": "黄色い", "is_correct": false, "explanation": "「心が黄色いままだ」は意味をなさない。色を表す語で、ここは合わない。"}, {"text": "速い", "is_correct": false, "explanation": "「心が速いままだ」は文として成り立たない。速さを表す語で、ここは合わない。"}], "explanations": {"寂しい": "心が満たされず物足りない様子を表す。「心が寂しいまま」として文に合う。", "細長い": "「心が細長いままだ」は意味が通らない。形を表す語で、ここは合わない。", "黄色い": "「心が黄色いままだ」は意味をなさない。色を表す語で、ここは合わない。", "速い": "「心が速いままだ」は文として成り立たない。速さを表す語で、ここは合わない。"}, "sentence_index": 6, "correct_answer": "寂しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の結果が寂しくて、眠れなかった。", "explanation": "ここは〈心配〉の意味。結果への不安を表す文に「寂しい」は合わない。"}, {"text": "彼の冗談は寂しくて、みんな笑った。", "explanation": "ここは〈面白い〉の意味。笑いを生む冗談を寂しいと言うのは合わない。"}, {"text": "今朝は寂しくて、厚いコートを着た。", "explanation": "ここは〈寒い〉の意味。寂しいは寒さを表さないので、気温を述べるこの文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38369, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りのあとの通りは寂しかく見えた。", "corrected_sentence": "祭りのあとの通りは寂しく見えた。", "error_description": "形容詞「寂しい」の連用形は「寂しく」。「寂しかく」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "寂しい", "is_correct": true, "explanation": "「ので」の前に置く終止形。ここで正しい。"}, {"text": "寂しく", "is_correct": false, "explanation": "連用形。「寂しくて」などの形で、「ので」の前には来ないので合わない。"}, {"text": "寂しくない", "is_correct": false, "explanation": "否定形。「懐が寂しくない」では外食を控えた理由と逆になるので合わない。"}, {"text": "寂しければ", "is_correct": false, "explanation": "仮定形。「寂しければ」の意味になり、ここでは理由を述べる文に合わない。"}], "correct_form": "寂しい", "base_form": "寂しい", "form_label": "終止形", "sentence_index": 1, "explanations": {"寂しい": "「ので」の前に置く終止形。ここで正しい。", "寂しく": "連用形。「寂しくて」などの形で、「ので」の前には来ないので合わない。", "寂しくない": "否定形。「懐が寂しくない」では外食を控えた理由と逆になるので合わない。", "寂しければ": "仮定形。「寂しければ」の意味になり、ここでは理由を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38369, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼がいなくなり、教室はすっかり寂しさなった。", "corrected_sentence": "彼がいなくなり、教室はすっかり寂しくなった。", "error_description": "形容詞「寂しい」は連用形「寂しく」に「なる」が続く。名詞「寂しさ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "寂しく", "is_correct": true, "explanation": "「感じる」の前に置く連用形。ここで正しい。"}, {"text": "寂しい", "is_correct": false, "explanation": "終止形。「寂しい感じる」とは続かないので合わない。"}, {"text": "寂しかった", "is_correct": false, "explanation": "過去形。現在の感覚を述べているので合わない。"}, {"text": "寂しくない", "is_correct": false, "explanation": "否定形。寂しいと感じる内容と逆になるので合わない。"}], "correct_form": "寂しく", "base_form": "寂しい", "form_label": "連用形", "sentence_index": 7, "explanations": {"寂しく": "「感じる」の前に置く連用形。ここで正しい。", "寂しい": "終止形。「寂しい感じる」とは続かないので合わない。", "寂しかった": "過去形。現在の感覚を述べているので合わない。", "寂しくない": "否定形。寂しいと感じる内容と逆になるので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
