INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38370, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "場所を示す。「箱の一面に宛先を書いて」で、宛先を書く場所を表す。正解。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「一面から宛先を書いて」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「一面より宛先を書いて」では文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「箱の一面を宛先を書いて」では目的語が二つ続き、成り立たない。"}], "correct_answer": "に", "explanations": {"に": "場所を示す。「箱の一面に宛先を書いて」で、宛先を書く場所を表す。正解。", "から": "起点を示す。「一面から宛先を書いて」では意味が通らない。", "より": "比較を示す。「一面より宛先を書いて」では文が成り立たない。", "を": "目的語を示す。「箱の一面を宛先を書いて」では目的語が二つ続き、成り立たない。"}, "error_tags": {"から": "起点", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38370, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "そとがわのひらたいところ。", "primary_collocate": null, "pronunciation": "いちめん", "ipa": "itɕimeɴ", "syllable_count": 4, "sentences": [{"text": "箱の一面だけ赤くぬりました。", "target_word": "一面", "complexity_tier": "T3", "furigana": "箱[はこ]の一面[いちめん]だけ赤[あか]くぬりました。", "sentence_source": "generated"}, {"text": "立方体には六つの面があり、私はその一面に名前を書いた。", "target_word": "一面", "complexity_tier": "T3", "furigana": "立方体[りっぽうたい]には六[むっ]つの面[めん]があり、私[わたし]はその一面[いちめん]に名前[なまえ]を書[か]いた。", "sentence_source": "generated"}, {"text": "机の一面にだけ傷がついている。", "target_word": "一面", "complexity_tier": "T3", "furigana": "机[つくえ]の一面[いちめん]にだけ傷[きず]がついている。", "sentence_source": "generated"}, {"text": "このさいころは一面だけ数字が消えている。", "target_word": "一面", "complexity_tier": "T3", "furigana": "このさいころは一面[いちめん]だけ数字[すうじ]が消[き]えている。", "sentence_source": "generated"}, {"text": "壁の一面を白いペンキでぬった。", "target_word": "一面", "complexity_tier": "T3", "furigana": "壁[かべ]の一面[いちめん]を白[しろ]いペンキでぬった。", "sentence_source": "generated"}, {"text": "本棚の一面にシールをはって、目印にした。", "target_word": "一面", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の一面[いちめん]にシールをはって、目印[めじるし]にした。", "sentence_source": "generated"}, {"text": "鏡の一面がくもっていて、姿がよく見えない。", "target_word": "一面", "complexity_tier": "T3", "furigana": "鏡[かがみ]の一面[いちめん]がくもっていて、姿[すがた]がよく見[み]えない。", "sentence_source": "generated"}, {"text": "箱の一面に宛先を書いてから、荷物を送った。", "target_word": "一面", "complexity_tier": "T3", "furigana": "箱[はこ]の一面[いちめん]に宛先[あてさき]を書[か]いてから、荷物[にもつ]を送[おく]った。", "sentence_source": "generated"}, {"text": "石の一面を平らにみがくと、きれいな台になった。", "target_word": "一面", "complexity_tier": "T3", "furigana": "石[いし]の一面[いちめん]を平[たい]らにみがくと、きれいな台[だい]になった。", "sentence_source": "generated"}, {"text": "積み木の一面にだけ絵がかいてあるので、上下をまちがえない。", "target_word": "一面", "complexity_tier": "T3", "furigana": "積[つ]み木[き]の一面[いちめん]にだけ絵[え]がかいてあるので、上下[じょうげ]をまちがえない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一面", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物の外側にある平らな面のひとつ(箱や壁などの一つの面)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: くもっ (Zipf 2.15)','sentence 8 above tier T1: contains vocabulary far above tier T1: みがく (Zipf 1.93)']::text[], '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38370, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一面", "is_correct": true, "explanation": "物の外側にある一つの面を指し、箱をぬる文にそのまま合う。"}, {"text": "一本", "is_correct": false, "explanation": "細長いものを数える語で、箱の面には使えない。"}, {"text": "一冊", "is_correct": false, "explanation": "本やノートを数える語で、箱の面には合わない。"}, {"text": "一粒", "is_correct": false, "explanation": "小さな粒を数える語で、箱をぬる文には合わない。"}], "explanations": {"一面": "物の外側にある一つの面を指し、箱をぬる文にそのまま合う。", "一本": "細長いものを数える語で、箱の面には使えない。", "一冊": "本やノートを数える語で、箱の面には合わない。", "一粒": "小さな粒を数える語で、箱をぬる文には合わない。"}, "sentence_index": 0, "correct_answer": "一面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝刊の一面に、大きな事件が載った。", "explanation": "ここは〈新聞の第一面〉の意味。物の外側の面を指す一面とは別の意味になる。"}, {"text": "箱の一面を、そっと閉めた。", "explanation": "一面は外側の面で、箱を閉めるふたの部分を指すわけではないので合わない。"}, {"text": "この箱には一面が六つある。", "explanation": "ここは〈面〉の意味。一面は一つの面を指すので、六つ数える文には「面」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38370, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一面", "is_correct": true, "explanation": "鏡の表面の一つの面を指し、「くもっていて」の主語に合う。"}, {"text": "一輪", "is_correct": false, "explanation": "花などを数える語で、鏡には合わない。"}, {"text": "一杯", "is_correct": false, "explanation": "器に入ったものを数える語で、鏡の文には合わない。"}, {"text": "一匹", "is_correct": false, "explanation": "動物を数える語で、鏡には使えない。"}], "explanations": {"一面": "鏡の表面の一つの面を指し、「くもっていて」の主語に合う。", "一輪": "花などを数える語で、鏡には合わない。", "一杯": "器に入ったものを数える語で、鏡の文には合わない。", "一匹": "動物を数える語で、鏡には使えない。"}, "sentence_index": 6, "correct_answer": "一面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "箱の一面に手紙が入っている。", "explanation": "手紙は箱の内側にあり、外側の一つの面を指す一面とは合わない。"}, {"text": "本の一面を、一枚めくった。", "explanation": "一面は物の外側の面を指すので、本の紙を一枚めくる文には合わない。"}, {"text": "一面に雪が積もっていた。", "explanation": "ここは〈見渡す限り〉の意味。物の外側の一つの面を指す一面とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38370, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱の一面を絵がかいてある。", "corrected_sentence": "箱の一面に絵がかいてある。", "error_description": "助詞の誤り。「一面」は絵がかかれている場所なので「に」が正しく、「を」では「かいてある」の文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38370, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱の一面を赤くわらった。", "corrected_sentence": "箱の一面を赤くぬった。", "error_description": "動詞の誤り。色を付けるのは「ぬる」で、「笑う」では赤く色をつける意味にならない。正しくは「ぬった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38371, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「にすぎない」を作る「に」。ほんの一部であることを示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「一面がすぎない」では文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「一面をすぎない」では動詞と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「一面へすぎない」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「にすぎない」を作る「に」。ほんの一部であることを示す。正解。", "が": "主語を示す。「一面がすぎない」では文が成り立たない。", "を": "目的語を示す。「一面をすぎない」では動詞と合わない。", "へ": "方向を示す。「一面へすぎない」では意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38371, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「一面を私は初めて知った」で知った対象を表す。正解。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。「一面と知った」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「一面より知った」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体を示す。「一面の、知った」では文が切れてしまう。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「一面を私は初めて知った」で知った対象を表す。正解。", "と": "並列を示す。「一面と知った」では文が成り立たない。", "より": "比較を示す。「一面より知った」では意味が通らない。", "の": "連体を示す。「一面の、知った」では文が切れてしまう。"}, "error_tags": {"と": "並列", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38371, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や物事の全体のうちの、ある特定の側面。", "primary_collocate": null, "pronunciation": "いちめん", "ipa": "itɕimeɴ", "syllable_count": 4, "sentences": [{"text": "明るい彼にも、さびしがり屋という一面がある。", "target_word": "一面", "complexity_tier": "T3", "furigana": "明[あか]るい彼[かれ]にも、さびしがり屋[や]という一面[いちめん]がある。", "sentence_source": "generated"}, {"text": "それは問題の一面にすぎないので、ほかの点も考えるべきだ。", "target_word": "一面", "complexity_tier": "T3", "furigana": "それは問題[もんだい]の一面[いちめん]にすぎないので、ほかの点[てん]も考[かんが]えるべきだ。", "sentence_source": "generated"}, {"text": "彼の意見は一面では正しいが、全部がそうとは言えない。", "target_word": "一面", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は一面[いちめん]では正[ただ]しいが、全部[ぜんぶ]がそうとは言[い]えない。", "sentence_source": "generated"}, {"text": "旅行で友だちの意外な一面を見た。", "target_word": "一面", "complexity_tier": "T3", "furigana": "旅行[りょこう]で友[とも]だちの意外[いがい]な一面[いちめん]を見[み]た。", "sentence_source": "generated"}, {"text": "都会の暮らしには便利な一面もあるが、お金がかかる。", "target_word": "一面", "complexity_tier": "T3", "furigana": "都会[とかい]の暮[く]らしには便利[べんり]な一面[いちめん]もあるが、お金[かね]がかかる。", "sentence_source": "generated"}, {"text": "厳しい先生だが、やさしい一面もある。", "target_word": "一面", "complexity_tier": "T3", "furigana": "厳[きび]しい先生[せんせい]だが、やさしい一面[いちめん]もある。", "sentence_source": "generated"}, {"text": "新しい技術は、危険な一面も持っている。", "target_word": "一面", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]は、危険[きけん]な一面[いちめん]も持[も]っている。", "sentence_source": "generated"}, {"text": "彼女の努力家という一面を、私は初めて知った。", "target_word": "一面", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の努力家[どりょくか]という一面[いちめん]を、私[わたし]は初[はじ]めて知[し]った。", "sentence_source": "generated"}, {"text": "一面だけを見て、人を決めつけてはいけない。", "target_word": "一面", "complexity_tier": "T3", "furigana": "一面[いちめん]だけを見[み]て、人[ひと]を決[き]めつけてはいけない。", "sentence_source": "generated"}, {"text": "この町には、静かな一面とにぎやかな一面がある。", "target_word": "一面", "complexity_tier": "T3", "furigana": "この町[まち]には、静[しず]かな一面[いちめん]とにぎやかな一面[いちめん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一面", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人や物事の全体のうちの、ある特定の側面(意外な一面、別の一面)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: さびし (Zipf 2.39)']::text[], '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38371, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一面", "is_correct": true, "explanation": "人や物事の一つの側面を指し、「さびしがり屋という」の後に合う。"}, {"text": "期限", "is_correct": false, "explanation": "締め切りの時期を表し、性格の話には合わない。"}, {"text": "値段", "is_correct": false, "explanation": "価格を表し、性格を述べる文には合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "何歳かを表し、「さびしがり屋」という性質とはつながらない。"}], "explanations": {"一面": "人や物事の一つの側面を指し、「さびしがり屋という」の後に合う。", "期限": "締め切りの時期を表し、性格の話には合わない。", "値段": "価格を表し、性格を述べる文には合わない。", "年齢": "何歳かを表し、「さびしがり屋」という性質とはつながらない。"}, "sentence_index": 0, "correct_answer": "一面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新聞の一面を、母に読んでもらった。", "explanation": "ここは〈新聞の第一面〉の意味。側面を表す一面とは別の意味になる。"}, {"text": "一面の花畑が、夕日に染まっていた。", "explanation": "ここは〈見渡す限り〉の意味。側面を表す一面は、広がりを言う文には合わない。"}, {"text": "彼の一面を平らにみがいた。", "explanation": "ここは〈物の外側の平らな面〉の意味。性格や側面を表す一面は、みがく対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38371, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一面", "is_correct": true, "explanation": "物事の一つの側面を指し、「危険な」に続けて技術の一面を表す。"}, {"text": "費用", "is_correct": false, "explanation": "お金の額を表す語で、「危険な」とは結びつかない。"}, {"text": "単位", "is_correct": false, "explanation": "数量の基準を表す語で、技術の性質を述べる文には合わない。"}, {"text": "身長", "is_correct": false, "explanation": "人の背の高さを表す語で、技術の文には合わない。"}], "explanations": {"一面": "物事の一つの側面を指し、「危険な」に続けて技術の一面を表す。", "費用": "お金の額を表す語で、「危険な」とは結びつかない。", "単位": "数量の基準を表す語で、技術の性質を述べる文には合わない。", "身長": "人の背の高さを表す語で、技術の文には合わない。"}, "sentence_index": 6, "correct_answer": "一面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ケーキの一面を、母にあげた。", "explanation": "ここは物の外側の面の意味。側面を表す一面とは別で、ケーキを渡す文には合わない。"}, {"text": "屋根の一面が、赤く塗られていた。", "explanation": "ここは物の外側の面の意味。物事の側面を表す一面とは別で、塗られた面の文には合わない。"}, {"text": "彼の一面を、ふきんでふいた。", "explanation": "一面は人の性格や側面を表すので、ふきんでふく物の面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38371, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼には意外な一面をある。", "corrected_sentence": "彼には意外な一面がある。", "error_description": "助詞の誤り。「ある」は存在するものを主語に取るので「が」で受ける。「を」は他動詞の目的語に付くため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38371, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その意見には、賛成できる一面もいる。", "corrected_sentence": "その意見には、賛成できる一面もある。", "error_description": "動詞の誤り。「一面」は存在を表すものなので「ある」が正しく、「いる」は生き物にだけ使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38372, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "移動の方向を示す。「塾へ行きます」で正しい。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「塾が行きます」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「塾を行きます」は動詞と合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す。「塾で行きます」では移動先にならない。"}], "correct_answer": "へ", "explanations": {"へ": "移動の方向を示す。「塾へ行きます」で正しい。正解。", "が": "主語を示す。「塾が行きます」では意味が通らない。", "を": "目的語を示す。「塾を行きます」は動詞と合わない。", "で": "場所や手段を示す。「塾で行きます」では移動先にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
