INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38372, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "べんきょうするところ。せんせいがおしえてくれるところ。", "primary_collocate": null, "pronunciation": "じゅく", "ipa": "dʑɯkɯ", "syllable_count": 2, "sentences": [{"text": "弟は週に三回、塾で算数を習っています。", "target_word": "塾", "complexity_tier": "T3", "furigana": "弟[おとうと]は週[しゅう]に三回[さんかい]、塾[じゅく]で算数[さんすう]を習[なら]っています。", "sentence_source": "generated"}, {"text": "学校が終わると、私はすぐ塾へ行きます。", "target_word": "塾", "complexity_tier": "T3", "furigana": "学校[がっこう]が終[お]わると、私[わたし]はすぐ塾[じゅく]へ行[い]きます。", "sentence_source": "generated"}, {"text": "塾の先生は、わからないところをやさしく教えてくれる。", "target_word": "塾", "complexity_tier": "T3", "furigana": "塾[じゅく]の先生[せんせい]は、わからないところをやさしく教[おし]えてくれる。", "sentence_source": "generated"}, {"text": "夏休みに、友だちといっしょに塾に通うことにした。", "target_word": "塾", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、友[とも]だちといっしょに塾[じゅく]に通[かよ]うことにした。", "sentence_source": "generated"}, {"text": "塾がある日は、夕ごはんを早めに食べます。", "target_word": "塾", "complexity_tier": "T3", "furigana": "塾[じゅく]がある日[ひ]は、夕[ゆう]ごはんを早[はや]めに食[た]べます。", "sentence_source": "generated"}, {"text": "姉は英語を勉強するために、塾をえらんだ。", "target_word": "塾", "complexity_tier": "T3", "furigana": "姉[あね]は英語[えいご]を勉強[べんきょう]するために、塾[じゅく]をえらんだ。", "sentence_source": "generated"}, {"text": "塾で習った漢字を、学校のテストで書けた。", "target_word": "塾", "complexity_tier": "T3", "furigana": "塾[じゅく]で習[なら]った漢字[かんじ]を、学校[がっこう]のテストで書[か]けた。", "sentence_source": "generated"}, {"text": "母は私の成績を心配して、塾を探してくれた。", "target_word": "塾", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の成績[せいせき]を心配[しんぱい]して、塾[じゅく]を探[さが]してくれた。", "sentence_source": "generated"}, {"text": "毎週土曜日の塾が、今は楽しみになっている。", "target_word": "塾", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]土曜日[どようび]の塾[じゅく]が、今[いま]は楽[たの]しみになっている。", "sentence_source": "generated"}, {"text": "塾の先生に質問したら、すぐに答えがわかった。", "target_word": "塾", "complexity_tier": "T3", "furigana": "塾[じゅく]の先生[せんせい]に質問[しつもん]したら、すぐに答[こた]えがわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "塾", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "学校のほかに通い、先生に勉強を教えてもらう学習の場(学習塾)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 夕ごはん (Zipf 1.84)']::text[], '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38372, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塾", "is_correct": true, "explanation": "勉強を教わる場所を指し、「算数を習っています」に合う。"}, {"text": "病院", "is_correct": false, "explanation": "病気を診る場所で、算数を習う文には合わない。"}, {"text": "美容院", "is_correct": false, "explanation": "髪を整える店で、勉強とは結びつかない。"}, {"text": "八百屋", "is_correct": false, "explanation": "野菜を売る店で、算数の学習とは関係ない。"}], "explanations": {"塾": "勉強を教わる場所を指し、「算数を習っています」に合う。", "病院": "病気を診る場所で、算数を習う文には合わない。", "美容院": "髪を整える店で、勉強とは結びつかない。", "八百屋": "野菜を売る店で、算数の学習とは関係ない。"}, "sentence_index": 0, "correct_answer": "塾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、塾で野菜を買った。", "explanation": "塾は勉強を教える所で、野菜を売る店ではないので買い物の文には使えない。"}, {"text": "午後、塾で薬をもらった。", "explanation": "塾は勉強の場所で、薬を渡す所ではないので合わない。"}, {"text": "切手を買うために、塾に寄った。", "explanation": "塾は勉強の場所で、切手を買える所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38372, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塾", "is_correct": true, "explanation": "勉強を教わる場所を指し、「で習った漢字」に合う。"}, {"text": "郵便局", "is_correct": false, "explanation": "手紙や荷物を扱う所で、勉強を習う場所ではない。"}, {"text": "駐車場", "is_correct": false, "explanation": "車を止める場所で、学習の場所にはならない。"}, {"text": "銀行", "is_correct": false, "explanation": "お金を預ける所で、漢字を習う文には合わない。"}], "explanations": {"塾": "勉強を教わる場所を指し、「で習った漢字」に合う。", "郵便局": "手紙や荷物を扱う所で、勉強を習う場所ではない。", "駐車場": "車を止める場所で、学習の場所にはならない。", "銀行": "お金を預ける所で、漢字を習う文には合わない。"}, "sentence_index": 6, "correct_answer": "塾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末、塾で髪を切ってもらった。", "explanation": "塾は勉強の場所で、髪を切る所ではないので散髪の文には合わない。"}, {"text": "夕飯を食べに、塾へ寄って、ラーメンを頼んだ。", "explanation": "塾は勉強の場所で、食事をする所ではないので合わない。"}, {"text": "週末は塾で洗濯をして、服をかわかした。", "explanation": "塾は勉強の場所で、洗濯をして服をかわかす所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38372, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は週に二回、塾を英語を習っている。", "corrected_sentence": "兄は週に二回、塾で英語を習っている。", "error_description": "助詞の誤り。「塾」は習う場所を示すので「で」が正しく、「を」では習う対象のように読まれて誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38372, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は塾を数学を教わっている。", "corrected_sentence": "妹は塾で数学を教わっている。", "error_description": "助詞の誤り。場所を示す「で」が正しく、「を」が二つ続くのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38373, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す。「この塾は教室が広くて」と文を始める。正解。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「この塾を教室が広くて」では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「この塾へ教室が広くて」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「この塾から教室が広くて」は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す。「この塾は教室が広くて」と文を始める。正解。", "を": "目的語を示す。「この塾を教室が広くて」では成り立たない。", "へ": "方向を示す。「この塾へ教室が広くて」は意味が通らない。", "から": "起点を示す。「この塾から教室が広くて」は成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38373, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体を示す。「塾の二階」のように、塾に属する場所を表す。正解。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。「塾と二階には」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「塾より二階には」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「塾を二階には」では動詞に続く目的語がなく、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "連体を示す。「塾の二階」のように、塾に属する場所を表す。正解。", "と": "並列を示す。「塾と二階には」では文が成り立たない。", "より": "比較を示す。「塾より二階には」では意味が通らない。", "を": "目的語を示す。「塾を二階には」では動詞に続く目的語がなく、文が成り立たない。"}, "error_tags": {"と": "並列", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38373, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校の授業などで勉強するための建物や場所。", "primary_collocate": null, "pronunciation": "じゅく", "ipa": "dʑɯkɯ", "syllable_count": 2, "sentences": [{"text": "駅の近くに新しい塾のビルが建った。", "target_word": "塾", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに新[あたら]しい塾[じゅく]のビルが建[た]った。", "sentence_source": "generated"}, {"text": "この塾は教室が広くて、自習室もある。", "target_word": "塾", "complexity_tier": "T3", "furigana": "この塾[じゅく]は教室[きょうしつ]が広[ひろ]くて、自習室[じしゅうしつ]もある。", "sentence_source": "generated"}, {"text": "塾の建物は、学校から歩いて五分のところにある。", "target_word": "塾", "complexity_tier": "T3", "furigana": "塾[じゅく]の建物[たてもの]は、学校[がっこう]から歩[ある]いて五分[ごふん]のところにある。", "sentence_source": "generated"}, {"text": "雨の日は、塾の入口に傘を置いて入る。", "target_word": "塾", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、塾[じゅく]の入口[いりぐち]に傘[かさ]を置[お]いて入[はい]る。", "sentence_source": "generated"}, {"text": "塾の自習室は、夜九時まで使えます。", "target_word": "塾", "complexity_tier": "T3", "furigana": "塾[じゅく]の自習室[じしゅうしつ]は、夜[よる]九時[くじ]まで使[つか]えます。", "sentence_source": "generated"}, {"text": "家から遠い塾は、通うのに時間がかかる。", "target_word": "塾", "complexity_tier": "T3", "furigana": "家[いえ]から遠[とお]い塾[じゅく]は、通[かよ]うのに時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "古い民家が塾に変わり、子どもたちが集まっている。", "target_word": "塾", "complexity_tier": "T3", "furigana": "古[ふる]い民家[みんか]が塾[じゅく]に変[か]わり、子[こ]どもたちが集[あつ]まっている。", "sentence_source": "generated"}, {"text": "塾の二階には、静かに勉強できる部屋がある。", "target_word": "塾", "complexity_tier": "T3", "furigana": "塾[じゅく]の二階[にかい]には、静[しず]かに勉強[べんきょう]できる部屋[へや]がある。", "sentence_source": "generated"}, {"text": "近所の塾は、広い駐輪場があって便利だ。", "target_word": "塾", "complexity_tier": "T3", "furigana": "近所[きんじょ]の塾[じゅく]は、広[ひろ]い駐輪場[ちゅうりんじょう]があって便利[べんり]だ。", "sentence_source": "generated"}, {"text": "塾の前で、友だちと待ち合わせをした。", "target_word": "塾", "complexity_tier": "T3", "furigana": "塾[じゅく]の前[まえ]で、友[とも]だちと待[ま]ち合[あ]わせをした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "塾", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "勉強を教える建物や教室としての塾(場所・施設としてとらえた塾)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38373, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塾", "is_correct": true, "explanation": "学習する建物を指し、「新しい」「ビル」に合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "筆記用具で、ビルの文には合わない。"}, {"text": "猫", "is_correct": false, "explanation": "動物で、建物の文には合わない。"}, {"text": "車", "is_correct": false, "explanation": "乗り物で、ビルとしては成り立たない。"}], "explanations": {"塾": "学習する建物を指し、「新しい」「ビル」に合う。", "鉛筆": "筆記用具で、ビルの文には合わない。", "猫": "動物で、建物の文には合わない。", "車": "乗り物で、ビルとしては成り立たない。"}, "sentence_index": 0, "correct_answer": "塾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅まで、塾に乗って行った。", "explanation": "建物は乗り物ではないので、乗って行く文には合わない。"}, {"text": "塾で本を借りて、家に持ち帰った。", "explanation": "建物の塾は本を貸し出す所ではないので、本を借りる文には合わない。"}, {"text": "塾に手紙を読んでもらった。", "explanation": "建物の塾は人ではないので、手紙を読んでもらう文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38373, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塾", "is_correct": true, "explanation": "建物としての塾を指し、「古い民家が〜に変わり」に合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける器で、民家が変わる文には合わない。"}, {"text": "牛乳", "is_correct": false, "explanation": "飲み物で、建物の文には合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類で、建物の文には合わない。"}], "explanations": {"塾": "建物としての塾を指し、「古い民家が〜に変わり」に合う。", "花瓶": "花を生ける器で、民家が変わる文には合わない。", "牛乳": "飲み物で、建物の文には合わない。", "靴下": "衣類で、建物の文には合わない。"}, "sentence_index": 6, "correct_answer": "塾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この塾は、よく冷えてすぐに溶けた。", "explanation": "建物は冷えて溶けないので、氷の性質を述べる文には合わない。"}, {"text": "その塾は、目を覚ましてあくびをした。", "explanation": "建物はあくびをしないので、生き物の動作を述べる文には合わない。"}, {"text": "この塾は、よく焼けて、かたくなった。", "explanation": "建物は焼けてかたくなることがないので、食べ物の変化を述べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38373, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町の塾を、子どもが集まっている。", "corrected_sentence": "この町の塾に、子どもが集まっている。", "error_description": "助詞の誤り。「集まる」は場所を示す「に」と組むので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38373, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家の近くに塾がいる。", "corrected_sentence": "家の近くに塾がある。", "error_description": "動詞の誤り。建物の存在を表す「ある」が正しく、「いる」は生き物に使うので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38374, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「雨が上がる」の主語を示す「が」。雨が上がるは自然な言い方。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に使うので、自動詞の「上がる」とは合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「雨で上がって」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「雨と上がって」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「雨が上がる」の主語を示す「が」。雨が上がるは自然な言い方。", "を": "「を」は他動詞の目的語に使うので、自動詞の「上がる」とは合わない。", "で": "「で」は場所や手段を示すので、「雨で上がって」は文として成り立たない。", "と": "「と」は並列や相手を示すので、「雨と上がって」は意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38374, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「雨に濡れる」の「に」。濡れた原因や、雨にさらされたことを示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「雨へ濡れた」とは言わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や原因を示すが、「雨から濡れた」とは言わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較に使うので、「雨より濡れた」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「雨に濡れる」の「に」。濡れた原因や、雨にさらされたことを示す。", "へ": "「へ」は方向を示すので、「雨へ濡れた」とは言わない。", "から": "「から」は起点や原因を示すが、「雨から濡れた」とは言わない。", "より": "「より」は比較に使うので、「雨より濡れた」は意味が通らない。"}, "error_tags": {"へ": "方向", "から": "起点・原因", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38374, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あめは、そらからふってくるみずのことです。", "primary_collocate": null, "pronunciation": "あめ", "ipa": "ame", "syllable_count": 2, "sentences": [{"text": "朝から雨がふっているので、かさを持って出かけた。", "target_word": "雨", "complexity_tier": "T3", "furigana": "朝[あさ]から雨[あめ]がふっているので、かさを持[も]って出[で]かけた。", "sentence_source": "generated"}, {"text": "雨が上がって、空に虹が出ました。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]が上[あ]がって、空[そら]に虹[にじ]が出[で]ました。", "sentence_source": "generated"}, {"text": "昨日は強い雨で、電車が止まった。", "target_word": "雨", "complexity_tier": "T3", "furigana": "昨日[きのう]は強[つよ]い雨[あめ]で、電車[でんしゃ]が止[と]まった。", "sentence_source": "generated"}, {"text": "雨の音を聞きながら、本を読んだ。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]の音[おと]を聞[き]きながら、本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "明日は雨になるそうなので、洗濯は今日のうちにします。", "target_word": "雨", "complexity_tier": "T3", "furigana": "明日[あした]は雨[あめ]になるそうなので、洗濯[せんたく]は今日[きょう]のうちにします。", "sentence_source": "generated"}, {"text": "雨のせいで、運動会は来週にのびた。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]のせいで、運動会[うんどうかい]は来週[らいしゅう]にのびた。", "sentence_source": "generated"}, {"text": "長く続いた雨がやみ、川の水が増えている。", "target_word": "雨", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]いた雨[あめ]がやみ、川[かわ]の水[みず]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "雨にぬれたので、家に帰ってすぐ着がえた。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれたので、家[いえ]に帰[かえ]ってすぐ着[き]がえた。", "sentence_source": "generated"}, {"text": "雨の日は、道がすべりやすいので気をつけてください。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、道[みち]がすべりやすいので気[き]をつけてください。", "sentence_source": "generated"}, {"text": "畑には、ひさしぶりの雨がありがたかった。", "target_word": "雨", "complexity_tier": "T3", "furigana": "畑[はたけ]には、ひさしぶりの雨[あめ]がありがたかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雨", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空から降ってくる水としての「あめ」(通常は「雨」と書く)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38374, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨", "is_correct": true, "explanation": "「雨」は空から降ってくる水で、「ふっている」の主語として自然に合う。"}, {"text": "風", "is_correct": false, "explanation": "風は「吹く」もので、「ふる」とは言わないので合わない。"}, {"text": "虹", "is_correct": false, "explanation": "虹は空に「出る」もので、「ふっている」の主語にはならない。"}, {"text": "本", "is_correct": false, "explanation": "本は降るものではないので、「ふっている」と合わない。"}], "explanations": {"雨": "「雨」は空から降ってくる水で、「ふっている」の主語として自然に合う。", "風": "風は「吹く」もので、「ふる」とは言わないので合わない。", "虹": "虹は空に「出る」もので、「ふっている」の主語にはならない。", "本": "本は降るものではないので、「ふっている」と合わない。"}, "sentence_index": 0, "correct_answer": "雨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は子どもに、雨をひとつくれた。", "explanation": "ここは〈飴〉（甘いお菓子）の意味。雨は空から降る水なので、人にあげるものではない。"}, {"text": "遠くで雨が鳴っていて、窓がびりびりふるえた。", "explanation": "ここは〈雷〉の意味。雨は降るもので、鳴るのは雷なので合わない。"}, {"text": "夜のうちに雨がたくさん積もった。", "explanation": "ここは〈雪〉の意味。雪は積もるが、雨は積もらずに流れたりたまったりするので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38374, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨", "is_correct": true, "explanation": "「雨」は降ってやむもので、「長く続いた雨がやみ」と自然に合う。"}, {"text": "紙", "is_correct": false, "explanation": "紙は降るものでもなく、「やむ」の主語にはならない。"}, {"text": "車", "is_correct": false, "explanation": "車は「やむ」ものではないので、この文に合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は降ったりやんだりしないので、文の主語として合わない。"}], "explanations": {"雨": "「雨」は降ってやむもので、「長く続いた雨がやみ」と自然に合う。", "紙": "紙は降るものでもなく、「やむ」の主語にはならない。", "車": "車は「やむ」ものではないので、この文に合わない。", "鍋": "鍋は降ったりやんだりしないので、文の主語として合わない。"}, "sentence_index": 6, "correct_answer": "雨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷凍庫で雨を作って、グラスに入れた。", "explanation": "ここは〈氷〉の意味。雨は空から降る水で、冷凍庫で作るものではないので合わない。"}, {"text": "コップに雨を注いで、ゆっくり飲んだ。", "explanation": "ここは〈水〉の意味。雨は空から降ってくるもので、コップに注いで飲むものではないので合わない。"}, {"text": "手をよく洗おうと、雨を泡立てた。", "explanation": "ここは〈石鹸〉の意味。雨は泡立てて手を洗うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38374, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は朝から雨を降っている。", "corrected_sentence": "今日は朝から雨が降っている。", "error_description": "「降る」の主語になる「雨」には「が」を使う。「雨を」は誤りで、正しくは「雨が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38374, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急に雨を降りだしたので、洗濯物を取り込んだ。", "corrected_sentence": "急に雨が降りだしたので、洗濯物を取り込んだ。", "error_description": "「降る」の対象は「が」で示す。「雨を」は誤りで、正しくは「雨が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38375, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「飴をなめる」の「を」。なめる対象（目的語）を示す。"}, {"text": "が", "is_correct": false, "explanation": "「飴がなめる」は主語が逆になり、なめるのは人なので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すので、「飴になめる」とは言わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「飴でなめる」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「飴をなめる」の「を」。なめる対象（目的語）を示す。", "が": "「飴がなめる」は主語が逆になり、なめるのは人なので不自然。", "に": "「に」は方向や相手を示すので、「飴になめる」とは言わない。", "で": "「で」は手段や場所を示すが、「飴でなめる」は意味が通らない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38375, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「飴をあげる」の「を」。あげる対象（目的語）を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「飴とあげた」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「飴へあげた」とは言わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較に使うので、「飴よりあげた」は合わない。"}], "correct_answer": "を", "explanations": {"を": "「飴をあげる」の「を」。あげる対象（目的語）を示す。", "と": "「と」は並列や相手を示すが、「飴とあげた」は意味が通らない。", "へ": "「へ」は方向を示すので、「飴へあげた」とは言わない。", "より": "「より」は比較に使うので、「飴よりあげた」は合わない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38375, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「飴」は、砂糖や水あめなどで作った、口の中でなめる甘いお菓子。", "primary_collocate": null, "pronunciation": "あめ", "ipa": "ame", "syllable_count": 2, "sentences": [{"text": "母は買い物のあと、子どもに飴をひとつくれた。", "target_word": "飴", "complexity_tier": "T3", "furigana": "母[はは]は買[か]い物[もの]のあと、子[こ]どもに飴[あめ]をひとつくれた。", "sentence_source": "generated"}, {"text": "のどが痛いときは、はちみつの飴をなめるとよい。", "target_word": "飴", "complexity_tier": "T3", "furigana": "のどが痛[いた]いときは、はちみつの飴[あめ]をなめるとよい。", "sentence_source": "generated"}, {"text": "この飴はいちごの味がして、とても甘い。", "target_word": "飴", "complexity_tier": "T3", "furigana": "この飴[あめ]はいちごの味[あじ]がして、とても甘[あま]い。", "sentence_source": "generated"}, {"text": "お祭りの屋台で、かわいい飴を買ってもらった。", "target_word": "飴", "complexity_tier": "T3", "furigana": "お祭[まつ]りの屋台[やたい]で、かわいい飴[あめ]を買[か]ってもらった。", "sentence_source": "generated"}, {"text": "飴をなめながら歩いていたら、口の中がべたべたした。", "target_word": "飴", "complexity_tier": "T3", "furigana": "飴[あめ]をなめながら歩[ある]いていたら、口[くち]の中[なか]がべたべたした。", "sentence_source": "generated"}, {"text": "祖母のかばんには、いつも飴が入っている。", "target_word": "飴", "complexity_tier": "T3", "furigana": "祖母[そぼ]のかばんには、いつも飴[あめ]が入[はい]っている。", "sentence_source": "generated"}, {"text": "小さい子は、大きすぎる飴でのどをつまらせることがある。", "target_word": "飴", "complexity_tier": "T3", "furigana": "小[ちい]さい子[こ]は、大[おお]きすぎる飴[あめ]でのどをつまらせることがある。", "sentence_source": "generated"}, {"text": "先生は、がんばった生徒に飴をあげた。", "target_word": "飴", "complexity_tier": "T3", "furigana": "先生[せんせい]は、がんばった生徒[せいと]に飴[あめ]をあげた。", "sentence_source": "generated"}, {"text": "飴を袋から出して、みんなで分けた。", "target_word": "飴", "complexity_tier": "T3", "furigana": "飴[あめ]を袋[ふくろ]から出[だ]して、みんなで分[わ]けた。", "sentence_source": "generated"}, {"text": "飴がとけて、ポケットの中にくっついてしまった。", "target_word": "飴", "complexity_tier": "T3", "furigana": "飴[あめ]がとけて、ポケットの中[なか]にくっついてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飴", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "砂糖や水あめで作った、口の中でなめる甘いお菓子(キャンディー)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38375, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飴", "is_correct": true, "explanation": "「飴」は甘いお菓子で、子どもにひとつあげられるものなので自然に合う。"}, {"text": "虹", "is_correct": false, "explanation": "虹は物ではなく、「ひとつくれた」と渡せるものではない。"}, {"text": "風", "is_correct": false, "explanation": "風は目に見えず、あげたりもらったりできるものではない。"}, {"text": "空", "is_correct": false, "explanation": "空は物ではないので、「ひとつくれた」とは言わない。"}], "explanations": {"飴": "「飴」は甘いお菓子で、子どもにひとつあげられるものなので自然に合う。", "虹": "虹は物ではなく、「ひとつくれた」と渡せるものではない。", "風": "風は目に見えず、あげたりもらったりできるものではない。", "空": "空は物ではないので、「ひとつくれた」とは言わない。"}, "sentence_index": 0, "correct_answer": "飴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日は飴が降るそうなので、傘を持って行くことにした。", "explanation": "ここは〈雨〉の意味。飴は降るものではなく、お菓子なので「降る」とは合わない。"}, {"text": "口の中で飴をかみながら、ふくらませて遊んだ。", "explanation": "ここは〈ガム〉の意味。飴はかんでふくらませるものではないので合わない。"}, {"text": "子どもたちは砂場で、大きな城を作ろうと飴に水を注いで固めた。", "explanation": "ここは〈砂〉の意味。飴は水を注いで城の形に固める材料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38375, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飴", "is_correct": true, "explanation": "「飴」は口に入るほど大きすぎると、のどをつまらせることがあるので自然に合う。"}, {"text": "車", "is_correct": false, "explanation": "車でのどをつまらせることはなく、この文の意味が通らない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋はのどをつまらせるものではないので、この文に合わない。"}, {"text": "電話", "is_correct": false, "explanation": "電話でのどをつまらせることはなく、文の意味が通らない。"}], "explanations": {"飴": "「飴」は口に入るほど大きすぎると、のどをつまらせることがあるので自然に合う。", "車": "車でのどをつまらせることはなく、この文の意味が通らない。", "鍋": "鍋はのどをつまらせるものではないので、この文に合わない。", "電話": "電話でのどをつまらせることはなく、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "飴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汚れた手を、飴を泡立ててよく洗った。", "explanation": "ここは〈石鹸〉の意味。飴は泡立てて手を洗うものではないので合わない。"}, {"text": "朝の飴がとけて、山の景色がはっきり見えた。", "explanation": "ここは〈霧〉の意味。霧が晴れると景色が見えるが、飴がとけても景色は見えないので合わない。"}, {"text": "母は古い飴を縫って、新しいカーテンを作った。", "explanation": "ここは〈布〉の意味。飴は縫ってカーテンにするものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38375, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は飴に好きです。", "corrected_sentence": "弟は飴が好きです。", "error_description": "「好き」の対象は「が」で示す。「飴に」は誤りで、正しくは「飴が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38375, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの帰りに飴がなめながら歩いた。", "corrected_sentence": "祭りの帰りに飴をなめながら歩いた。", "error_description": "「なめる」の目的語は「を」で示す。「飴が」は誤りで、正しくは「飴を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38376, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「山は」と主題を示し、「山は高すぎて」と話題を立てる。"}, {"text": "に", "is_correct": false, "explanation": "「山に高すぎて」は文が続かない。"}, {"text": "で", "is_correct": false, "explanation": "「山で高すぎて」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「山と高すぎて」は並列の形にならず、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「山は」と主題を示し、「山は高すぎて」と話題を立てる。", "に": "「山に高すぎて」は文が続かない。", "で": "「山で高すぎて」は意味が通らない。", "と": "「山と高すぎて」は並列の形にならず、文が成り立たない。"}, "error_tags": {"に": "方向・位置", "で": "場所・手段", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
