INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38376, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "とても高いところ。地面から上に大きくそびえているところ。", "primary_collocate": null, "pronunciation": "やま", "ipa": "jama", "syllable_count": 2, "sentences": [{"text": "家の窓から、雪をかぶった高い山が見えます。", "target_word": "山", "complexity_tier": "T3", "furigana": "家[いえ]の窓[まど]から、雪[ゆき]をかぶった高[たか]い山[やま]が見[み]えます。", "sentence_source": "generated"}, {"text": "山は高すぎて、頂上は雲に隠れていました。", "target_word": "山", "complexity_tier": "T3", "furigana": "山[やま]は高[たか]すぎて、頂上[ちょうじょう]は雲[くも]に隠[かく]れていました。", "sentence_source": "generated"}, {"text": "夏休みに家族で山に登って、きれいな景色を見ました。", "target_word": "山", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに家族[かぞく]で山[やま]に登[のぼ]って、きれいな景色[けしき]を見[み]ました。", "sentence_source": "generated"}, {"text": "海は平らですが、山は地面から高くそびえています。", "target_word": "山", "complexity_tier": "T3", "furigana": "海[うみ]は平[たい]らですが、山[やま]は地面[じめん]から高[たか]くそびえています。", "sentence_source": "generated"}, {"text": "山の上は空気がうすくて、息が苦しくなります。", "target_word": "山", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は空気[くうき]がうすくて、息[いき]が苦[くる]しくなります。", "sentence_source": "generated"}, {"text": "あの山は三千メートル以上あるので、登るのに二日かかります。", "target_word": "山", "complexity_tier": "T3", "furigana": "あの山[やま]は三千[さんぜん]メートル以上[いじょう]あるので、登[のぼ]るのに二日[ふつか]かかります。", "sentence_source": "generated"}, {"text": "朝、山の向こうから太陽がのぼってきました。", "target_word": "山", "complexity_tier": "T3", "furigana": "朝[あさ]、山[やま]の向[む]こうから太陽[たいよう]がのぼってきました。", "sentence_source": "generated"}, {"text": "雨が降ったので、山の水が川に流れこんでいます。", "target_word": "山", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、山[やま]の水[みず]が川[かわ]に流[なが]れこんでいます。", "sentence_source": "generated"}, {"text": "冬になると、山のてっぺんは白い雪でおおわれます。", "target_word": "山", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、山[やま]のてっぺんは白[しろ]い雪[ゆき]でおおわれます。", "sentence_source": "generated"}, {"text": "町の北には大きな山があって、みんなそれを見ながら育ちました。", "target_word": "山", "complexity_tier": "T3", "furigana": "町[まち]の北[きた]には大[おお]きな山[やま]があって、みんなそれを見[み]ながら育[そだ]ちました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "山", "label": "基本形"}, {"form": "山々", "label": "複数形"}], "register": "一般的な標準語", "sense_fingerprint": "地面から高くそびえる大きな自然の高まり。高さと大きさに注目した意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: そびえ (Zipf 2.29)','sentence 4 above tier T1: contains vocabulary far above tier T1: うすく (Zipf 2.37)']::text[], '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38376, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "「山」は雪をかぶった高いところで、窓から見えるものとして自然に合う。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いは嗅ぐもので、窓から見えるものではない。"}, {"text": "味", "is_correct": false, "explanation": "味は舌で感じるもので、見えるものではない。"}, {"text": "痛み", "is_correct": false, "explanation": "痛みは感じるもので、窓から見えるものではない。"}], "explanations": {"山": "「山」は雪をかぶった高いところで、窓から見えるものとして自然に合う。", "匂い": "匂いは嗅ぐもので、窓から見えるものではない。", "味": "味は舌で感じるもので、見えるものではない。", "痛み": "痛みは感じるもので、窓から見えるものではない。"}, "sentence_index": 0, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この山は地面より低くくぼんでいて、雨が降ると水がたまります。", "explanation": "ここは〈谷〉（低くくぼんだ地形）の意味。山は地面から高くそびえるもので、低くくぼんだ場所には使えないので合わない。"}, {"text": "町の中央に古い山が建っていて、一階は店になっている。", "explanation": "ここは〈建物〉の意味。山は人が建てて店を入れるものではなく、自然にできた地形なので合わない。"}, {"text": "夏の公園では、この山で子どもたちが小舟をこいで遊んでいる。", "explanation": "ここは〈池〉の意味。山の上で小舟をこぐことはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38376, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "「山の向こうから太陽がのぼる」は自然で、地形としての山が入る。"}, {"text": "電話", "is_correct": false, "explanation": "電話の向こうから太陽がのぼることはなく、文の意味が通らない。"}, {"text": "紙", "is_correct": false, "explanation": "紙の向こうから太陽がのぼることはなく、文に合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴の向こうから太陽がのぼることはなく、文が成り立たない。"}], "explanations": {"山": "「山の向こうから太陽がのぼる」は自然で、地形としての山が入る。", "電話": "電話の向こうから太陽がのぼることはなく、文の意味が通らない。", "紙": "紙の向こうから太陽がのぼることはなく、文に合わない。", "靴": "靴の向こうから太陽がのぼることはなく、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の海では、山が次々と寄せては砕けて白いしぶきを上げる。", "explanation": "ここは〈波〉の意味。寄せて砕けて白いしぶきを上げるのは波で、山には当てはまらないので合わない。"}, {"text": "町の真ん中を大きな山が流れていて、夏は子どもたちが泳いだ。", "explanation": "ここは〈川〉の意味。山は流れるものではなく、地面の高まりなので合わない。"}, {"text": "漁師は朝早く山へ出て、大きな船を港に止めた。", "explanation": "ここは〈海〉の意味。船を止める港は海にあるもので、山には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38376, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年の夏、あの山を高すぎて登れなかった。", "corrected_sentence": "今年の夏、あの山が高すぎて登れなかった。", "error_description": "「高すぎて」の主語は「山が」。「山を」は目的語の「を」で、形容詞には使えない。正しくは「山が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38376, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は子どもの頃から山を住んでいました。", "corrected_sentence": "私は子どもの頃から山に住んでいました。", "error_description": "「住む」は場所を「に」で示す。「山を」は誤りで、正しくは「山に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38377, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「山の斜面」の「の」で、山の一部であることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「山が斜面に沿う」は意味が通らず、文の形が合わない。"}, {"text": "を", "is_correct": false, "explanation": "「山を斜面に沿って」は目的語の形が不自然で、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較に使うので、「山より斜面に沿って」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「山の斜面」の「の」で、山の一部であることを示す。", "が": "「山が斜面に沿う」は意味が通らず、文の形が合わない。", "を": "「山を斜面に沿って」は目的語の形が不自然で、文が成り立たない。", "より": "「より」は比較に使うので、「山より斜面に沿って」は意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
