INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38377, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "周囲より高く盛り上がった地形。多くの場合、頂上や斜面がある。", "primary_collocate": null, "pronunciation": "やま", "ipa": "jama", "syllable_count": 2, "sentences": [{"text": "この山は頂上が平らで、斜面にはたくさんの木が生えています。", "target_word": "山", "complexity_tier": "T3", "furigana": "この山[やま]は頂上[ちょうじょう]が平[たい]らで、斜面[しゃめん]にはたくさんの木[き]が生[は]えています。", "sentence_source": "generated"}, {"text": "山の斜面に沿って、細い道が続いています。", "target_word": "山", "complexity_tier": "T3", "furigana": "山[やま]の斜面[しゃめん]に沿[そ]って、細[ほそ]い道[みち]が続[つづ]いています。", "sentence_source": "generated"}, {"text": "周りの土地より高く盛り上がっているので、あれは丘ではなく山です。", "target_word": "山", "complexity_tier": "T3", "furigana": "周[まわ]りの土地[とち]より高[たか]く盛[も]り上[あ]がっているので、あれは丘[おか]ではなく山[やま]です。", "sentence_source": "generated"}, {"text": "地図で見ると、この山の形は三角形に近いです。", "target_word": "山", "complexity_tier": "T3", "furigana": "地図[ちず]で見[み]ると、この山[やま]の形[かたち]は三角形[さんかくけい]に近[ちか]いです。", "sentence_source": "generated"}, {"text": "山の頂上に立つと、町全体が小さく見えました。", "target_word": "山", "complexity_tier": "T3", "furigana": "山[やま]の頂上[ちょうじょう]に立[た]つと、町[まち]全体[ぜんたい]が小[ちい]さく見[み]えました。", "sentence_source": "generated"}, {"text": "日本は国土の多くが山で、平らな土地はあまり多くありません。", "target_word": "山", "complexity_tier": "T3", "furigana": "日本[にほん]は国土[こくど]の多[おお]くが山[やま]で、平[たい]らな土地[とち]はあまり多[おお]くありません。", "sentence_source": "generated"}, {"text": "兄は毎週末、山の頂上を目指して歩いています。", "target_word": "山", "complexity_tier": "T3", "furigana": "兄[あに]は毎週末[まいしゅうまつ]、山[やま]の頂上[ちょうじょう]を目指[めざ]して歩[ある]いています。", "sentence_source": "generated"}, {"text": "山の反対側の斜面は、日があたらないので雪がとけません。", "target_word": "山", "complexity_tier": "T3", "furigana": "山[やま]の反対側[はんたいがわ]の斜面[しゃめん]は、日[ひ]があたらないので雪[ゆき]がとけません。", "sentence_source": "generated"}, {"text": "地震のあと、山の一部がくずれて道がふさがりました。", "target_word": "山", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、山[やま]の一部[いちぶ]がくずれて道[みち]がふさがりました。", "sentence_source": "generated"}, {"text": "山に囲まれた小さな村で、祖父は生まれ育ちました。", "target_word": "山", "complexity_tier": "T3", "furigana": "山[やま]に囲[かこ]まれた小[ちい]さな村[むら]で、祖父[そふ]は生[う]まれ育[そだ]ちました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "山", "label": "基本形"}, {"form": "山々", "label": "複数形"}], "register": "一般的な標準語", "sense_fingerprint": "頂上や斜面をもつ、周囲より盛り上がった地形。形や構造に注目した意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 頂上 (Zipf 3.68), 平ら (Zipf 3.4), 斜面 (Zipf 3.49)','sentence 8 above tier T1: contains vocabulary far above tier T1: ふさがり (Zipf 2.13)']::text[], '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38377, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "「山」は頂上が平らで斜面に木が生えている地形なので、この文に合う。"}, {"text": "池", "is_correct": false, "explanation": "池には頂上や斜面がないので、「頂上が平らで」と合わない。"}, {"text": "家", "is_correct": false, "explanation": "家に斜面はなく、「頂上が平らで」という説明に合わない。"}, {"text": "船", "is_correct": false, "explanation": "船に頂上や斜面はなく、木が生えることもない。"}], "explanations": {"山": "「山」は頂上が平らで斜面に木が生えている地形なので、この文に合う。", "池": "池には頂上や斜面がないので、「頂上が平らで」と合わない。", "家": "家に斜面はなく、「頂上が平らで」という説明に合わない。", "船": "船に頂上や斜面はなく、木が生えることもない。"}, "sentence_index": 0, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この山は、上から水が勢いよく流れ落ちて、大きな音を立てている。", "explanation": "ここは〈滝〉の意味。水が上から落ちるのは滝で、地面の盛り上がりである山が水を流すことはないので合わない。"}, {"text": "この山は周りより低くくぼんでいて、水がたまりやすい。", "explanation": "ここは〈谷〉の意味。山は周りより高く盛り上がった地形で、低くくぼんでいるのは谷なので合わない。"}, {"text": "この山は一本の大きな木で、枝が家の屋根までのびている。", "explanation": "ここは〈木〉の意味。山は地面の盛り上がりで、一本の木のように枝をのばすことはないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38377, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "「山の頂上を目指して歩く」は自然で、登山の対象として山が入る。"}, {"text": "窓", "is_correct": false, "explanation": "窓には頂上がなく、「頂上を目指して歩く」とは言わない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋には頂上がなく、「頂上を目指して歩く」とは合わない。"}, {"text": "傘", "is_correct": false, "explanation": "傘には頂上がなく、「頂上を目指して歩く」とは言わない。"}], "explanations": {"山": "「山の頂上を目指して歩く」は自然で、登山の対象として山が入る。", "窓": "窓には頂上がなく、「頂上を目指して歩く」とは言わない。", "鍋": "鍋には頂上がなく、「頂上を目指して歩く」とは合わない。", "傘": "傘には頂上がなく、「頂上を目指して歩く」とは言わない。"}, "sentence_index": 6, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この山は屋根の上に煙突があって、家族で住んでいる。", "explanation": "ここは〈家〉の意味。山は人が住むための建物ではなく地形なので合わない。"}, {"text": "町の真ん中の大きな山で、子どもたちが泳いだ。", "explanation": "ここは〈池〉の意味。山は水をためて泳ぐ場所ではないので合わない。"}, {"text": "帆船は大きな山を進み、やがて港に着いた。", "explanation": "ここは〈海〉の意味。山は船が進む場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38377, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小さな村は山を囲まれている。", "corrected_sentence": "小さな村は山に囲まれている。", "error_description": "「囲まれる」は場所を「に」で示す。「山を」は誤りで、正しくは「山に」。「山で」は材料や手段の「で」なので、ここでは使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38377, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は毎朝、山が登っていた。", "corrected_sentence": "祖父は毎朝、山に登っていた。", "error_description": "「登る」の行き先は「に」で示す。「山が」は誤りで、登るのは祖父なので、正しくは「山に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38378, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「麓で」は、そこでお弁当を食べるという動作の場所を表す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「麓に」は存在や到着の場所を表すので、食べる動作の場所としては成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「麓を」は食べる動作の対象を表すが、麓は食べ物ではないので文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「麓へ」は移動の向かう先を表すので、その場でお弁当を食べる文には合わない。"}], "correct_answer": "で", "explanations": {"で": "「麓で」は、そこでお弁当を食べるという動作の場所を表す。正解。", "に": "「麓に」は存在や到着の場所を表すので、食べる動作の場所としては成り立たない。", "を": "「麓を」は食べる動作の対象を表すが、麓は食べ物ではないので文が成り立たない。", "へ": "「麓へ」は移動の向かう先を表すので、その場でお弁当を食べる文には合わない。"}, "error_tags": {"に": "存在・到着の場所", "を": "動作の対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38378, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38378, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "やまのいちばんしたのところ。", "primary_collocate": null, "pronunciation": "ふもと", "ipa": "ɸɯmoto", "syllable_count": 3, "sentences": [{"text": "山の麓に小さな村があって、祖父はそこに住んでいます。", "target_word": "麓", "complexity_tier": "T3", "furigana": "山[やま]の麓[ふもと]に小[ちい]さな村[むら]があって、祖父[そふ]はそこに住[す]んでいます。", "sentence_source": "generated"}, {"text": "私たちはまず麓でお弁当を食べてから、山に登りました。", "target_word": "麓", "complexity_tier": "T3", "furigana": "私[わたし]たちはまず麓[ふもと]でお弁当[べんとう]を食[た]べてから、山[やま]に登[のぼ]りました。", "sentence_source": "generated"}, {"text": "麓は暖かいのに、頂上は雪が降っていました。", "target_word": "麓", "complexity_tier": "T3", "furigana": "麓[ふもと]は暖[あたた]かいのに、頂上[ちょうじょう]は雪[ゆき]が降[ふ]っていました。", "sentence_source": "generated"}, {"text": "麓の駅からバスに乗ると、登山口まで十分で着きます。", "target_word": "麓", "complexity_tier": "T3", "furigana": "麓[ふもと]の駅[えき]からバスに乗[の]ると、登山口[とざんぐち]まで十分[じゅっぷん]で着[つ]きます。", "sentence_source": "generated"}, {"text": "山の麓には広い畑があり、おいしい野菜がとれます。", "target_word": "麓", "complexity_tier": "T3", "furigana": "山[やま]の麓[ふもと]には広[ひろ]い畑[はたけ]があり、おいしい野菜[やさい]がとれます。", "sentence_source": "generated"}, {"text": "霧が晴れて、麓の町の明かりがよく見えました。", "target_word": "麓", "complexity_tier": "T3", "furigana": "霧[きり]が晴[は]れて、麓[ふもと]の町[まち]の明[あ]かりがよく見[み]えました。", "sentence_source": "generated"}, {"text": "登る前に、麓の店で水と地図を買いました。", "target_word": "麓", "complexity_tier": "T3", "furigana": "登[のぼ]る前[まえ]に、麓[ふもと]の店[みせ]で水[みず]と地図[ちず]を買[か]いました。", "sentence_source": "generated"}, {"text": "雨で山道があぶないので、麓で一晩待つことにしました。", "target_word": "麓", "complexity_tier": "T3", "furigana": "雨[あめ]で山道[やまみち]があぶないので、麓[ふもと]で一晩[ひとばん]待[ま]つことにしました。", "sentence_source": "generated"}, {"text": "頂上まで行かずに、麓の湖のまわりをゆっくり歩きました。", "target_word": "麓", "complexity_tier": "T3", "furigana": "頂上[ちょうじょう]まで行[い]かずに、麓[ふもと]の湖[みずうみ]のまわりをゆっくり歩[ある]きました。", "sentence_source": "generated"}, {"text": "桜は麓から咲きはじめて、だんだん上のほうへ広がっていきます。", "target_word": "麓", "complexity_tier": "T3", "furigana": "桜[さくら]は麓[ふもと]から咲[さ]きはじめて、だんだん上[うえ]のほうへ広[ひろ]がっていきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "麓", "label": "基本形"}], "register": "一般的な標準語", "sense_fingerprint": "山のいちばん下にあたる場所。登る前の出発点や、人が暮らす土地として使われる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38378, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "麓", "is_correct": true, "explanation": "「山のいちばん下の部分」を表し、「山の麓に小さな村がある」と自然につながる。正解。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の一部で、山の中の村の位置を示す言葉としては入らない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車券などのことで、場所を表せないので村の位置には合わない。"}, {"text": "鏡", "is_correct": false, "explanation": "鏡は持ち運ぶ道具で、山と村の位置関係を表す言葉ではないので入らない。"}], "explanations": {"麓": "「山のいちばん下の部分」を表し、「山の麓に小さな村がある」と自然につながる。正解。", "窓": "窓は建物の一部で、山の中の村の位置を示す言葉としては入らない。", "切符": "切符は乗車券などのことで、場所を表せないので村の位置には合わない。", "鏡": "鏡は持ち運ぶ道具で、山と村の位置関係を表す言葉ではないので入らない。"}, "sentence_index": 0, "correct_answer": "麓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の麓に、新しいペンを一本置いた。", "explanation": "ここは「物の下のほう」の意味。麓は山のふもとの地域にしか使わないので、机には言えない。"}, {"text": "このチームは選手の麓が広い。", "explanation": "ここは〈裾野〉の意味（分野の人材の層の厚さ）。麓は山の低い場所を指すので、人材の広がりには使わない。"}, {"text": "崖から落ちないように、麓をよく見て歩いた。", "explanation": "ここは〈足元〉の意味（足の下の地面）。麓は山すその地域のことなので、足もとの地面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38378, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "麓", "is_correct": true, "explanation": "「麓の店」は山のふもとにある店を表し、登る前に買い物をする文に自然に入る。正解。"}, {"text": "天井", "is_correct": false, "explanation": "天井は建物の上の面で、山を登る前の店の場所としては入らない。"}, {"text": "床", "is_correct": false, "explanation": "床は部屋の下の面で、山の店の場所を示す言葉としては合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の一部で、店の所在地を表せないので入らない。"}], "explanations": {"麓": "「麓の店」は山のふもとにある店を表し、登る前に買い物をする文に自然に入る。正解。", "天井": "天井は建物の上の面で、山を登る前の店の場所としては入らない。", "床": "床は部屋の下の面で、山の店の場所を示す言葉としては合わない。", "窓": "窓は建物の一部で、店の所在地を表せないので入らない。"}, "sentence_index": 6, "correct_answer": "麓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "橋の麓で待ち合わせをした。", "explanation": "ここは〈たもと〉の意味（橋のそば）。麓は山の下の地域のことで、橋には使わない。"}, {"text": "並木の麓で休んだ。", "explanation": "ここは〈根元〉の意味（木の根のあたり）。麓は山のふもとの地域を指すので、並木の根元には使わない。"}, {"text": "腕の麓をさすった。", "explanation": "ここは〈付け根〉の意味（体の部分がつながるところ）。麓は山のふもとの地域を指すので、体の部分には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38378, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の麓を小さな店があります。", "corrected_sentence": "山の麓に小さな店があります。", "error_description": "「店がある」の場所は「麓に」で示す。「麓を」は目的語を表すので、存在を表す文では成り立たない。「に」が「を」になった誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38378, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、麓を宿でゆっくり休みましょう。", "corrected_sentence": "雨の日は、麓の宿でゆっくり休みましょう。", "error_description": "「麓の宿」は「麓にある宿」の意味で、「の」が正しい。「麓を宿」は目的語を表す「を」になるので文が成り立たない。「の」が「を」になった誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
