INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38380, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みずが はしる ところ。", "primary_collocate": null, "pronunciation": "みち", "ipa": "mitɕi", "syllable_count": 2, "sentences": [{"text": "大雨のあと、水が流れる道ができて、庭の土が削られた。", "target_word": "道", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のあと、水[みず]が流[なが]れる道[みち]ができて、庭[にわ]の土[つち]が削[けず]られた。", "sentence_source": "generated"}, {"text": "畑に水を引くために、水の道を掘った。", "target_word": "道", "complexity_tier": "T3", "furigana": "畑[はたけ]に水[みず]を引[ひ]くために、水[みず]の道[みち]を掘[ほ]った。", "sentence_source": "generated"}, {"text": "雨水が流れる道がないと、庭に水がたまってしまう。", "target_word": "道", "complexity_tier": "T3", "furigana": "雨水[あまみず]が流[なが]れる道[みち]がないと、庭[にわ]に水[みず]がたまってしまう。", "sentence_source": "generated"}, {"text": "山の水が川へ流れる道を、石で守っている。", "target_word": "道", "complexity_tier": "T3", "furigana": "山[やま]の水[みず]が川[かわ]へ流[なが]れる道[みち]を、石[いし]で守[まも]っている。", "sentence_source": "generated"}, {"text": "雪がとけると、小さな水の道が何本もできた。", "target_word": "道", "complexity_tier": "T3", "furigana": "雪[ゆき]がとけると、小[ちい]さな水[みず]の道[みち]が何本[なんぼん]もできた。", "sentence_source": "generated"}, {"text": "子どもたちは、砂の山に水を流して、水の道を作って遊んだ。", "target_word": "道", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、砂[すな]の山[やま]に水[みず]を流[なが]して、水[みず]の道[みち]を作[つく]って遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "水が流れる道をふさぐと、水があふれてしまう。", "target_word": "道", "complexity_tier": "T3", "furigana": "水[みず]が流[なが]れる道[みち]をふさぐと、水[みず]があふれてしまう。", "sentence_source": "generated"}, {"text": "田んぼの水は、土を掘った細い道を通って、となりの田んぼへ流れていく。", "target_word": "道", "complexity_tier": "T3", "furigana": "田[た]んぼの水[みず]は、土[つち]を掘[ほ]った細[ほそ]い道[みち]を通[とお]って、となりの田[た]んぼへ流[なが]れていく。", "sentence_source": "generated"}, {"text": "雨が止んでも、屋根から落ちた水が流れる道には、まだ水が残っている。", "target_word": "道", "complexity_tier": "T3", "furigana": "雨[あめ]が止[や]んでも、屋根[やね]から落[お]ちた水[みず]が流[なが]れる道[みち]には、まだ水[みず]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "水は低いほうへ流れるので、水の道は自然に谷へ向かう。", "target_word": "道", "complexity_tier": "T3", "furigana": "水[みず]は低[ひく]いほうへ流[なが]れるので、水[みず]の道[みち]は自然[しぜん]に谷[たに]へ向[む]かう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "水が流れていく筋やすじ道。水の通る場所。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 4 words above tier T1 (max 2): 田んぼ (Zipf 3.53), 掘っ (Zipf 3.75), となり (Zipf 3.5), 田んぼ (Zipf 3.53)']::text[], 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38380, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道", "is_correct": true, "explanation": "「水が流れる道ができて」で、水の流れる筋を表す語として文に合う。"}, {"text": "池", "is_correct": false, "explanation": "「水が流れる池ができて」は池が流れるという意味になり、文に合わない。"}, {"text": "音", "is_correct": false, "explanation": "「水が流れる音ができて」は意味が通らず、空欄に入らない。"}, {"text": "石", "is_correct": false, "explanation": "「水が流れる石ができて」は石が流れるという意味になり、文が通らない。"}], "explanations": {"道": "「水が流れる道ができて」で、水の流れる筋を表す語として文に合う。", "池": "「水が流れる池ができて」は池が流れるという意味になり、文に合わない。", "音": "「水が流れる音ができて」は意味が通らず、空欄に入らない。", "石": "「水が流れる石ができて」は石が流れるという意味になり、文が通らない。"}, "sentence_index": 0, "correct_answer": "道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その水の道はこれから、三つの部屋へ電気を送ります。", "explanation": "ここは〈電線〉の意味。電気を送るのは電線で、水が流れる道とは合わない。"}, {"text": "彼は茶道の道を歩み、今では師範になった。", "explanation": "ここは〈修行の道〉の意味。水が流れる筋の意味ではないので、この語義では合わない。"}, {"text": "最後の大きな道を乗り越えて、合格の知らせを受けた。", "explanation": "ここは〈関門〉の意味。試験の山場は「関門」と言い、水が流れる通り道の意味の道とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38380, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道", "is_correct": true, "explanation": "「水が流れる道をふさぐと」で、水の通り道を表す語として文に合う。"}, {"text": "歌", "is_correct": false, "explanation": "「水が流れる歌をふさぐと」は意味が通らず、空欄に入らない。"}, {"text": "紙", "is_correct": false, "explanation": "「水が流れる紙をふさぐと」は意味が通らず、空欄に入らない。"}, {"text": "鍋", "is_correct": false, "explanation": "「水が流れる鍋をふさぐと」は鍋の性質と合わず、文が通らない。"}], "explanations": {"道": "「水が流れる道をふさぐと」で、水の通り道を表す語として文に合う。", "歌": "「水が流れる歌をふさぐと」は意味が通らず、空欄に入らない。", "紙": "「水が流れる紙をふさぐと」は意味が通らず、空欄に入らない。", "鍋": "「水が流れる鍋をふさぐと」は鍋の性質と合わず、文が通らない。"}, "sentence_index": 6, "correct_answer": "道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は水の道を三年間、熱心に勉強した。", "explanation": "ここは〈学問〉の意味。学問の道は言うが、水が流れる筋の意味の道とは合わない。"}, {"text": "この滝は水の道が高くそびえて、見上げるほどだ。", "explanation": "ここは〈滝〉の意味。落ちる水の流れは「滝」で言い、通り道の意味の道とは合わない。"}, {"text": "彼は水の道に乗って、東京の家から出かけた。", "explanation": "ここは〈鉄道〉の意味。鉄道は線路を走るので、水の流れる道とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38380, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨のあと、庭に水が流れる道をできた。", "corrected_sentence": "大雨のあと、庭に水が流れる道ができた。", "error_description": "「できる」の主語は「道が」。「道を」は目的語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38380, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水が流す道をふさぐと、庭に水があふれてしまう。", "corrected_sentence": "雨水が流れる道をふさぐと、庭に水があふれてしまう。", "error_description": "道は水が流れる場所なので「流れる」が正しい。「流す」は他動詞で、道が水を流すという誤った意味になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
