INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38381, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「道は」で主題を示し、道について涼しさを述べている。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示すが、「夏でも涼しい」という主題の述べ方には結びつかない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、ここでは道の性質を述べる文なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示すが、名詞を続けなければ文が成立しない。"}], "correct_answer": "は", "explanations": {"は": "「道は」で主題を示し、道について涼しさを述べている。", "に": "場所や相手を示すが、「夏でも涼しい」という主題の述べ方には結びつかない。", "から": "起点を示すが、ここでは道の性質を述べる文なので合わない。", "の": "連体修飾を示すが、名詞を続けなければ文が成立しない。"}, "error_tags": {"に": "場所・相手", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38381, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人や車が通るための細長い場所。また、人が進む進路。", "primary_collocate": null, "pronunciation": "みち", "ipa": "mitɕi", "syllable_count": 2, "sentences": [{"text": "高校を卒業したばかりの10代の彼が選んだ道は、地方の有機農家で働くことでした。", "target_word": "道", "complexity_tier": "T4", "furigana": "高校[こうこう]を卒業[そつぎょう]したばかりの10代[じゅうだい]の彼[かれ]が選[えら]んだ道[みち]は、地方[ちほう]の有機[ゆうき]農家[のうか]で働[はたら]くことでした。", "sentence_source": "mined"}, {"text": "雨が降ったので、山の道がぬかるんで歩きにくかった。", "target_word": "道", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったので、山[やま]の道[みち]がぬかるんで歩[ある]きにくかった。", "sentence_source": "generated"}, {"text": "駅へ行く道がわからなくて、交番で聞きました。", "target_word": "道", "complexity_tier": "T3", "furigana": "駅[えき]へ行[い]く道[みち]がわからなくて、交番[こうばん]で聞[き]きました。", "sentence_source": "generated"}, {"text": "家の前の道は狭いので、大きい車は入れない。", "target_word": "道", "complexity_tier": "T3", "furigana": "家[いえ]の前[まえ]の道[みち]は狭[せま]いので、大[おお]きい車[くるま]は入[はい]れない。", "sentence_source": "generated"}, {"text": "雪で道が見えなくなり、車をゆっくり走らせた。", "target_word": "道", "complexity_tier": "T3", "furigana": "雪[ゆき]で道[みち]が見[み]えなくなり、車[くるま]をゆっくり走[はし]らせた。", "sentence_source": "generated"}, {"text": "森の中の細い道を、犬と一緒に歩いた。", "target_word": "道", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]の細[ほそ]い道[みち]を、犬[いぬ]と一緒[いっしょ]に歩[ある]いた。", "sentence_source": "generated"}, {"text": "この道をまっすぐ行くと、右に大きな公園があります。", "target_word": "道", "complexity_tier": "T3", "furigana": "この道[みち]をまっすぐ行[い]くと、右[みぎ]に大[おお]きな公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "川のそばの道は、夏でも涼しくて気持ちがいい。", "target_word": "道", "complexity_tier": "T3", "furigana": "川[かわ]のそばの道[みち]は、夏[なつ]でも涼[すず]しくて気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "工事で道がふさがれていたため、遠回りして学校へ行った。", "target_word": "道", "complexity_tier": "T3", "furigana": "工事[こうじ]で道[みち]がふさがれていたため、遠回[とおまわ]りして学校[がっこう]へ行[い]った。", "sentence_source": "generated"}, {"text": "夜の道は暗いから、懐中電灯を持って出かけた。", "target_word": "道", "complexity_tier": "T3", "furigana": "夜[よる]の道[みち]は暗[くら]いから、懐中電灯[かいちゅうでんとう]を持[も]って出[で]かけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人や車が通るための細長い場所。道路や小道、また人が進む進路のこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: ぬかるん (Zipf 2.26)']::text[], 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38381, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道", "is_correct": true, "explanation": "「彼が選んだ道」は進む方向や進路の意味で、文の「働くことでした」と続く。"}, {"text": "色", "is_correct": false, "explanation": "「選んだ色は、働くことでした」は文として成立せず、進路の話にならない。"}, {"text": "数", "is_correct": false, "explanation": "「選んだ数は、働くことでした」は意味が通らず、空欄に入らない。"}, {"text": "音", "is_correct": false, "explanation": "「選んだ音は、働くことでした」は意味が通らず、空欄に入らない。"}], "explanations": {"道": "「彼が選んだ道」は進む方向や進路の意味で、文の「働くことでした」と続く。", "色": "「選んだ色は、働くことでした」は文として成立せず、進路の話にならない。", "数": "「選んだ数は、働くことでした」は意味が通らず、空欄に入らない。", "音": "「選んだ音は、働くことでした」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この建物の道は狭く、車椅子では通れない。", "explanation": "ここは〈廊下〉の意味。建物の中の通路は「廊下」と言い、道とは言わない。"}, {"text": "夜中の電車は、道をゆっくり走っていった。", "explanation": "ここは〈線路〉の意味。電車は線路の上を走るので、道を走るとは言わない。"}, {"text": "夜明け前、飛行機が道を滑り出した。", "explanation": "ここは〈滑走路〉の意味。飛行機は滑走路を使うので、道を滑るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38381, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道", "is_correct": true, "explanation": "「この道をまっすぐ行く」で、進む経路を表す語として文に合う。"}, {"text": "歌", "is_correct": false, "explanation": "「この歌をまっすぐ行くと」は意味が通らず、空欄に入らない。"}, {"text": "紙", "is_correct": false, "explanation": "「この紙をまっすぐ行くと」は意味が通らず、空欄に入らない。"}, {"text": "窓", "is_correct": false, "explanation": "「この窓をまっすぐ行くと」は進む場所として成立せず、文が通らない。"}], "explanations": {"道": "「この道をまっすぐ行く」で、進む経路を表す語として文に合う。", "歌": "「この歌をまっすぐ行くと」は意味が通らず、空欄に入らない。", "紙": "「この紙をまっすぐ行くと」は意味が通らず、空欄に入らない。", "窓": "「この窓をまっすぐ行くと」は進む場所として成立せず、文が通らない。"}, "sentence_index": 6, "correct_answer": "道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その電気工事で、壁の中の道が切れていた。", "explanation": "ここは〈配線〉の意味。電気の線は「配線」と言い、人や水が通る道とは合わない。"}, {"text": "その衛星は、夜も道をぐるぐる回り続けている。", "explanation": "ここは〈軌道〉の意味。天体が回る軌道に使い、人や車が通る道とは違う。"}, {"text": "その鳥は、空に道を描いて飛んでいった。", "explanation": "ここは〈軌跡〉の意味。空中を動いた跡の線を言う語で、通る場所の意味の道とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38381, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降って、山の道をぬかるんでいた。", "corrected_sentence": "雨が降って、山の道がぬかるんでいた。", "error_description": "「ぬかるむ」の主語は「道が」。「道を」は目的語を示すので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38381, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森の中の細い道を、犬と一緒に泳いだ。", "corrected_sentence": "森の中の細い道を、犬と一緒に散歩した。", "error_description": "道を歩く（散歩する）のが自然。「泳いだ」は道では不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38382, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38382, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「古い新聞を溜める」の目的語を示す。溜める対象を表す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「古い新聞に溜めて」では目的語にならず、溜める対象が示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」は、新聞を使って溜める意味になり、目的語の代わりにならない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す「の」は、溜める動作の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「古い新聞を溜める」の目的語を示す。溜める対象を表す格助詞。", "に": "「古い新聞に溜めて」では目的語にならず、溜める対象が示せない。", "で": "手段を示す「で」は、新聞を使って溜める意味になり、目的語の代わりにならない。", "の": "所属や修飾を示す「の」は、溜める動作の目的語にはならない。"}, "error_tags": {"に": "位置", "で": "手段", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38382, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、なくならないように、ひとつのところに おくこと。", "primary_collocate": null, "pronunciation": "ためる", "ipa": "tameɾɯ", "syllable_count": 3, "sentences": [{"text": "引き出しに古い手紙を溜めてあるので、整理しなければならない。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しに古[ふる]い手紙[てがみ]を溜[た]めてあるので、整理[せいり]しなければならない。", "sentence_source": "generated"}, {"text": "小銭を瓶に溜めている。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "小銭[こぜに]を瓶[びん]に溜[た]めている。", "sentence_source": "generated"}, {"text": "母は使わない紙袋を溜めて、なかなか捨てない。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "母[はは]は使[つか]わない紙袋[かみぶくろ]を溜[た]めて、なかなか捨[す]てない。", "sentence_source": "generated"}, {"text": "洗濯物を溜めると、休みの日に大変だ。", "target_word": "溜める", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]を溜[た]めると、休[やす]みの日[ひ]に大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "使い終わった電池を箱に溜めておいて、まとめて捨てに行く。", "target_word": "溜めておいて", "complexity_tier": "T3", "furigana": "使[つか]い終[お]わった電池[でんち]を箱[はこ]に溜[た]めておいて、まとめて捨[す]てに行[い]く。", "sentence_source": "generated"}, {"text": "ごみを溜めておくと、部屋がくさくなる。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "ごみを溜[た]めておくと、部屋[へや]がくさくなる。", "sentence_source": "generated"}, {"text": "古い雑誌を溜めてしまって、引っ越しのときに本当に重かった。", "target_word": "溜めてしまって", "complexity_tier": "T3", "furigana": "古(ふる)い雑誌(ざっし)を溜(た)めてしまって、引(ひ)っ越(こ)しのときに本当(ほんとう)に重(おも)かった。", "sentence_source": "generated"}, {"text": "祖父は古い新聞を溜めて、押し入れにしまっている。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "祖父[そふ]は古[ふる]い新聞[しんぶん]を溜[た]めて、押[お]し入[い]れにしまっている。", "sentence_source": "generated"}, {"text": "切手の余りを引き出しに溜めている。", "target_word": "溜めている", "complexity_tier": "T3", "furigana": "切手[きって]の余[あま]りを引[ひ]き出[だ]しに溜[た]めている。", "sentence_source": "generated"}, {"text": "空き缶を溜めておいて、まとめて売りに行った。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "空[あ]き缶[かん]を溜[た]めておいて、まとめて売[う]りに行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "溜める", "label": "辞書形"}, {"form": "溜めた", "label": "過去形"}, {"form": "溜めて", "label": "て形"}, {"form": "溜めない", "label": "否定形"}, {"form": "溜めれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ものをなくさないように一か所に置いてためておく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38382, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "溜めて", "is_correct": true, "explanation": "「溜めてある」の「て形」。「てある」は前もって物を置いた状態を表すので、ここに合う。"}, {"text": "溜めた", "is_correct": false, "explanation": "過去形。「溜めたある」とは続かず、「〜てあるので」の文型に入らない。"}, {"text": "溜めない", "is_correct": false, "explanation": "否定形。「溜めないある」とは続かず、文の意味も合わない。"}, {"text": "溜める", "is_correct": false, "explanation": "辞書形は「〜てある」の前に置けないので、この文型では使えない。"}], "explanations": {"溜めて": "「溜めてある」の「て形」。「てある」は前もって物を置いた状態を表すので、ここに合う。", "溜めた": "過去形。「溜めたある」とは続かず、「〜てあるので」の文型に入らない。", "溜めない": "否定形。「溜めないある」とは続かず、文の意味も合わない。", "溜める": "辞書形は「〜てある」の前に置けないので、この文型では使えない。"}, "sentence_index": 0, "correct_answer": "溜めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "積み木を溜めて、小さな塔を作った。", "explanation": "ここは〈積む〉（重ねる）と混同。溜めるは時間をかけて集める意味で、重ねて形を作る文には使わない。"}, {"text": "大きな溜め息を溜めて、席に座った。", "explanation": "ここは〈吐く〉（息を外に出す）と混同。溜めるは物などを集めておく意味で、息を外に出す動作には合わない。"}, {"text": "足を溜めて、ボールを蹴った。", "explanation": "ここは〈蹴る〉と混同。溜めるは物を集めて置く意味で、足で蹴る動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38382, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溜めてしまって", "is_correct": true, "explanation": "「〜てしまって」は完了や後悔の気持ちを表す。雑誌がたまって重かったという文脈に合う。"}, {"text": "溜めてしまう", "is_correct": false, "explanation": "辞書形で切ると、後ろの「引っ越しのときに本当に重かった」と続かない。"}, {"text": "溜めさせて", "is_correct": false, "explanation": "使役形で、誰かに溜めさせた意味になり、文脈の主語とずれる。"}, {"text": "溜めます", "is_correct": false, "explanation": "丁寧形は文末で使う形で、読点の後に文を続けられない。"}], "explanations": {"溜めてしまって": "「〜てしまって」は完了や後悔の気持ちを表す。雑誌がたまって重かったという文脈に合う。", "溜めてしまう": "辞書形で切ると、後ろの「引っ越しのときに本当に重かった」と続かない。", "溜めさせて": "使役形で、誰かに溜めさせた意味になり、文脈の主語とずれる。", "溜めます": "丁寧形は文末で使う形で、読点の後に文を続けられない。"}, "sentence_index": 6, "correct_answer": "溜めてしまって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな花束を溜めて、母に渡した。", "explanation": "ここは〈組む・作る〉と混同。溜めるは物を時間をかけて集め置く意味で、花束を組む動作には合わない。"}, {"text": "ボールを溜めて、ゴールに入れた。", "explanation": "ここは〈蹴る〉と混同。溜めるは物を集めて置く意味で、ボールを動かして入れる動作には合わない。"}, {"text": "夏休みに友達を溜めて、一緒に遊んだ。", "explanation": "ここは〈集める〉と混同している。溜めるは物を時間をかけて蓄える意味で、人を呼び集める文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38382, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空き箱が溜めておくと、場所をとる。", "corrected_sentence": "空き箱を溜めておくと、場所をとる。", "error_description": "「溜めておく」の目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "溜めて", "is_correct": true, "explanation": "「溜めている」の「て形」。後ろの「いる」に続く形で、文の意味に合う。"}, {"text": "溜めない", "is_correct": false, "explanation": "否定形。「溜めないいる」とは続かず、文が成り立たない。"}, {"text": "溜めた", "is_correct": false, "explanation": "過去形。「溜めたいる」とは続かず、文が成り立たない。"}, {"text": "溜めれば", "is_correct": false, "explanation": "仮定形。「〜ば」は後ろに条件節を作り、「いる」とはつながらない。"}], "correct_form": "溜めて", "base_form": "溜める", "form_label": "て形", "sentence_index": 1, "explanations": {"溜めて": "「溜めている」の「て形」。後ろの「いる」に続く形で、文の意味に合う。", "溜めない": "否定形。「溜めないいる」とは続かず、文が成り立たない。", "溜めた": "過去形。「溜めたいる」とは続かず、文が成り立たない。", "溜めれば": "仮定形。「〜ば」は後ろに条件節を作り、「いる」とはつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38382, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "使わない服に溜めておくと、クローゼットがいっぱいになる。", "corrected_sentence": "使わない服を溜めておくと、クローゼットがいっぱいになる。", "error_description": "「溜めておく」の目的語は「を」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "溜めて", "is_correct": true, "explanation": "「溜めて、〜」の連用形。文の途中で読点を挟み、後の「しまっている」に続く。"}, {"text": "溜めます", "is_correct": false, "explanation": "丁寧形は文末で使う形で、読点の後に「しまっている」と続けられない。"}, {"text": "溜めよう", "is_correct": false, "explanation": "意向形で「溜めよう」の意味になり、祖父が既に新聞を溜めている文脈と合わない。"}, {"text": "溜められ", "is_correct": false, "explanation": "受身・可能の連用形。新聞が溜められるという意味になり、祖父が溜める文と合わない。"}], "correct_form": "溜めて", "base_form": "溜める", "form_label": "て形", "sentence_index": 7, "explanations": {"溜めて": "「溜めて、〜」の連用形。文の途中で読点を挟み、後の「しまっている」に続く。", "溜めます": "丁寧形は文末で使う形で、読点の後に「しまっている」と続けられない。", "溜めよう": "意向形で「溜めよう」の意味になり、祖父が既に新聞を溜めている文脈と合わない。", "溜められ": "受身・可能の連用形。新聞が溜められるという意味になり、祖父が溜める文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38383, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「水を溜める」の目的語を示す。溜める対象を表す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "溜める（他動詞）の目的語は「を」。「が」を入れると文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、ここでは「バケツに」で位置が既に示されているため合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す「と」は、溜める動作の目的語の代わりにはならない。"}], "correct_answer": "を", "explanations": {"を": "「水を溜める」の目的語を示す。溜める対象を表す格助詞。", "が": "溜める（他動詞）の目的語は「を」。「が」を入れると文が成り立たない。", "へ": "方向を示す「へ」は、ここでは「バケツに」で位置が既に示されているため合わない。", "と": "並列を示す「と」は、溜める動作の目的語の代わりにはならない。"}, "error_tags": {"が": "主語の取り違え", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38383, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「水を溜め」の目的語を示す。溜める対象を表す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「桶に」は既に場所を示している。ここで「水に」とすると目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」は、水を使って溜める意味になり、目的語の代わりにならない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す「の」は、溜める動作の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「水を溜め」の目的語を示す。溜める対象を表す格助詞。", "に": "「桶に」は既に場所を示している。ここで「水に」とすると目的語にならない。", "で": "手段を示す「で」は、水を使って溜める意味になり、目的語の代わりにならない。", "の": "所属や修飾を示す「の」は、溜める動作の目的語にはならない。"}, "error_tags": {"に": "位置", "で": "手段", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38383, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体や物を、使うときのために集めておくこと。", "primary_collocate": null, "pronunciation": "ためる", "ipa": "tameɾɯ", "syllable_count": 3, "sentences": [{"text": "雨水を溜めて、庭の花に水をやります。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "雨水[あまみず]を溜[た]めて、庭[にわ]の花[はな]に水[みず]をやります。", "sentence_source": "generated"}, {"text": "洗車に使うために、大きなバケツに水を溜めておく。", "target_word": "溜めておく", "complexity_tier": "T3", "furigana": "洗車[せんしゃ]に使[つか]うために、大[おお]きなバケツに水[みず]を溜[た]めておく。", "sentence_source": "generated"}, {"text": "災害に備えて、バケツに水を溜めておきました。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "災害[さいがい]に備[そな]えて、バケツに水[みず]を溜[た]めておきました。", "sentence_source": "generated"}, {"text": "農家の人は、雨が少ない年に備えて、池に水を溜めておく。", "target_word": "溜めておく", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は、雨[あめ]が少[すく]ない年[とし]に備[そな]えて、池[いけ]に水[みず]を溜[た]めておく。", "sentence_source": "generated"}, {"text": "ダムは川の水を溜めて、夏の水不足を防ぐ。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "ダムは川[かわ]の水[みず]を溜[た]めて、夏[なつ]の水不足[みずぶそく]を防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "断水になる前に、鍋に水を溜めておこう。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "断水[だんすい]になる前[まえ]に、鍋[なべ]に水[みず]を溜[た]めておこう。", "sentence_source": "generated"}, {"text": "洗い桶にお湯を溜めて、皿をつけておく。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "洗[あら]い桶[おけ]にお湯[ゆ]を溜[た]めて、皿[さら]をつけておく。", "sentence_source": "generated"}, {"text": "父は大きな桶に水を溜め、夏の畑にまいている。", "target_word": "溜め", "complexity_tier": "T3", "furigana": "父[ちち]は大[おお]きな桶[おけ]に水[みず]を溜[た]め、夏[なつ]の畑[はたけ]にまいている。", "sentence_source": "generated"}, {"text": "冬に使うために、倉庫に灯油を溜めておく。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "冬[ふゆ]に使[つか]うために、倉庫[そうこ]に灯油[とうゆ]を溜[た]めておく。", "sentence_source": "generated"}, {"text": "浴槽の栓をしっかり閉めてから、水を溜めてください。", "target_word": "溜めて", "complexity_tier": "T3", "furigana": "浴槽[よくそう]の栓[せん]をしっかり閉[し]めてから、水[みず]を溜[た]めてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "溜める", "label": "辞書形"}, {"form": "溜めた", "label": "過去形"}, {"form": "溜めて", "label": "て形"}, {"form": "溜めない", "label": "否定形"}, {"form": "溜めれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "水などの液体や物を、あとで使うために集めておく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38383, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "溜めて", "is_correct": true, "explanation": "「溜めて、〜ます」の連用形。雨水を集めてから、庭の花に水をやる流れに続く。"}, {"text": "捨てて", "is_correct": false, "explanation": "雨水を捨てると水やりに使えず、庭の花に水をやる文の流れと合わない。"}, {"text": "流して", "is_correct": false, "explanation": "流すと水が残らず、水やりに使う文脈と合わない。"}, {"text": "空けて", "is_correct": false, "explanation": "容器を空にする意味になり、雨水を使って水やりをする文と合わない。"}], "explanations": {"溜めて": "「溜めて、〜ます」の連用形。雨水を集めてから、庭の花に水をやる流れに続く。", "捨てて": "雨水を捨てると水やりに使えず、庭の花に水をやる文の流れと合わない。", "流して": "流すと水が残らず、水やりに使う文脈と合わない。", "空けて": "容器を空にする意味になり、雨水を使って水やりをする文と合わない。"}, "sentence_index": 0, "correct_answer": "溜めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "髪を溜めて、ずっと長くしている。", "explanation": "ここは〈伸ばす〉と混同。溜めるは物を集めて置く意味で、髪が伸びていく状態には合わない。"}, {"text": "試験の結果を溜めて、先生に見せた。", "explanation": "ここは〈提出する〉と混同。溜めるは使うまで集めておく意味で、結果を届ける動作には合わない。"}, {"text": "子犬を溜めて、家で飼うことにした。", "explanation": "ここは〈引き取る〉と混同。溜めるは物を集めておく意味で、生き物を引き取る文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38383, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溜めて", "is_correct": true, "explanation": "「溜めて」の連用形。お湯を洗い桶に集めてから、皿をつける流れに続く。"}, {"text": "壊して", "is_correct": false, "explanation": "壊すと洗い桶が使えず、皿をつける文の流れと合わない。"}, {"text": "割って", "is_correct": false, "explanation": "割ると桶が壊れてしまい、皿をつける動作と合わない。"}, {"text": "投げて", "is_correct": false, "explanation": "投げるとお湯が飛び散り、皿をつける動作の流れと合わない。"}], "explanations": {"溜めて": "「溜めて」の連用形。お湯を洗い桶に集めてから、皿をつける流れに続く。", "壊して": "壊すと洗い桶が使えず、皿をつける文の流れと合わない。", "割って": "割ると桶が壊れてしまい、皿をつける動作と合わない。", "投げて": "投げるとお湯が飛び散り、皿をつける動作の流れと合わない。"}, "sentence_index": 6, "correct_answer": "溜めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紙飛行機を溜めて、大きな箱に入れた。", "explanation": "ここは〈折る〉と混同。溜めるは物を集めておく意味で、紙を形にする動作には合わない。"}, {"text": "夏休みに友達を溜めて、一緒に遊んだ。", "explanation": "ここは〈集める〉と混同している。溜めるは物を時間をかけて蓄える意味で、人を呼び集める文には使わない。"}, {"text": "強い風を溜めて、帆を広げた。", "explanation": "ここは〈受ける〉と混同。溜めるは物を集めておく意味で、風を体で受け止める動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38383, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな桶に雨水が溜めておくと、蚊がわく。", "corrected_sentence": "大きな桶に雨水を溜めておくと、蚊がわく。", "error_description": "「溜めておく」の目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "溜めておく", "is_correct": true, "explanation": "「溜めておく」の辞書形。「洗車に使うために」という目的の文に合う。"}, {"text": "溜めておき", "is_correct": false, "explanation": "連用形（中止形）。文末では終われず、後ろに続く語が必要。"}, {"text": "溜めておかない", "is_correct": false, "explanation": "否定形。「使うために」の目的と反対の意味になり、文が合わない。"}, {"text": "溜めておけば", "is_correct": false, "explanation": "仮定形。条件を表し、「使うために」の目的を述べる文に続かない。"}], "correct_form": "溜めておく", "base_form": "溜める", "form_label": "ておく形", "sentence_index": 1, "explanations": {"溜めておく": "「溜めておく」の辞書形。「洗車に使うために」という目的の文に合う。", "溜めておき": "連用形（中止形）。文末では終われず、後ろに続く語が必要。", "溜めておかない": "否定形。「使うために」の目的と反対の意味になり、文が合わない。", "溜めておけば": "仮定形。条件を表し、「使うために」の目的を述べる文に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38383, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "浴槽に水に溜めておく。", "corrected_sentence": "浴槽に水を溜めておく。", "error_description": "「溜めておく」の目的語は「を」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "溜め", "is_correct": true, "explanation": "「溜め、〜」の連用形（中止形）。読点で文を続け、後の「まいている」に続く。"}, {"text": "溜める", "is_correct": false, "explanation": "辞書形は文の途中で切れず、「、夏の畑にまいている」と続かない。"}, {"text": "溜めよう", "is_correct": false, "explanation": "意向形で「溜めよう」の意味になり、父が水を溜めた文脈と合わない。"}, {"text": "溜められ", "is_correct": false, "explanation": "受身・可能の連用形。水が溜められるという意味になり、父が溜める文と合わない。"}], "correct_form": "溜め", "base_form": "溜める", "form_label": "連用形", "sentence_index": 7, "explanations": {"溜め": "「溜め、〜」の連用形（中止形）。読点で文を続け、後の「まいている」に続く。", "溜める": "辞書形は文の途中で切れず、「、夏の畑にまいている」と続かない。", "溜めよう": "意向形で「溜めよう」の意味になり、父が水を溜めた文脈と合わない。", "溜められ": "受身・可能の連用形。水が溜められるという意味になり、父が溜める文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38384, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『縄』が主題になる文なので『は』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『切れやすい』は形容詞で目的語を取らないので、『を』では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『縄に切れやすい』では文のつながりが不自然で、位置や対象を示す役割も合わない。"}, {"text": "と", "is_correct": false, "explanation": "『縄と切れやすい』では並列の形が成り立たず、文として通らない。"}], "correct_answer": "は", "explanations": {"は": "『縄』が主題になる文なので『は』が正しい。", "を": "『切れやすい』は形容詞で目的語を取らないので、『を』では文が成り立たない。", "に": "『縄に切れやすい』では文のつながりが不自然で、位置や対象を示す役割も合わない。", "と": "『縄と切れやすい』では並列の形が成り立たず、文として通らない。"}, "error_tags": {"を": "目的語", "に": "位置・対象", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38384, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『引っ張る』の目的語が『縄』なので『を』が正しい。"}, {"text": "に", "is_correct": false, "explanation": "『縄に引っ張る』では目的語を示せず、動作の対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "『縄と引っ張る』は並列になり、動作の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「縄の引っ張ったら」は名詞のあとに動詞が続かず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『引っ張る』の目的語が『縄』なので『を』が正しい。", "に": "『縄に引っ張る』では目的語を示せず、動作の対象として不自然。", "と": "『縄と引っ張る』は並列になり、動作の対象にならない。", "の": "「縄の引っ張ったら」は名詞のあとに動詞が続かず、文が成り立たない。"}, "error_tags": {"に": "位置・対象", "と": "並列", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38384, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "なわは、ものをしばったり、つなげたりする、ほそながいものです。", "primary_collocate": null, "pronunciation": "なわ", "ipa": "naɰa", "syllable_count": 2, "sentences": [{"text": "荷物が動かないように、縄でしっかり縛りました。", "target_word": "縄", "complexity_tier": "T3", "furigana": "荷物(にもつ)が動(うご)かないように、縄(なわ)でしっかり縛(しば)りました。", "sentence_source": "generated"}, {"text": "古い縄は切れやすいので、新しいものに替えましょう。", "target_word": "縄", "complexity_tier": "T3", "furigana": "古(ふる)い縄(なわ)は切(き)れやすいので、新(あたら)しいものに替(か)えましょう。", "sentence_source": "generated"}, {"text": "木に縄をかけて、ブランコを作った。", "target_word": "縄", "complexity_tier": "T3", "furigana": "木(き)に縄(なわ)をかけて、ブランコを作(つく)った。", "sentence_source": "generated"}, {"text": "船を港につなぐために、太い縄を使います。", "target_word": "縄", "complexity_tier": "T3", "furigana": "船(ふね)を港(みなと)につなぐために、太(ふと)い縄(なわ)を使(つか)います。", "sentence_source": "generated"}, {"text": "縄が短すぎて、箱を結べませんでした。", "target_word": "縄", "complexity_tier": "T3", "furigana": "縄(なわ)が短(みじか)すぎて、箱(はこ)を結(むす)べませんでした。", "sentence_source": "generated"}, {"text": "父は縄を使って、薪をひとまとめにしました。", "target_word": "縄", "complexity_tier": "T3", "furigana": "父(ちち)は縄(なわ)を使(つか)って、薪(まき)をひとまとめにしました。", "sentence_source": "generated"}, {"text": "細い縄より太い縄のほうが、重い物を支えられる。", "target_word": "縄", "complexity_tier": "T3", "furigana": "細(ほそ)い縄(なわ)より太(ふと)い縄(なわ)のほうが、重(おも)い物(もの)を支(ささ)えられる。", "sentence_source": "generated"}, {"text": "縄を引っ張ったら、結び目がほどけた。", "target_word": "縄", "complexity_tier": "T3", "furigana": "縄(なわ)を引(ひ)っ張(ぱ)ったら、結(むす)び目(め)がほどけた。", "sentence_source": "generated"}, {"text": "犬が縄をかんで、ぼろぼろにしてしまった。", "target_word": "縄", "complexity_tier": "T3", "furigana": "犬(いぬ)が縄(なわ)をかんで、ぼろぼろにしてしまった。", "sentence_source": "generated"}, {"text": "雨にぬれた縄は、重くて持ちにくい。", "target_word": "縄", "complexity_tier": "T3", "furigana": "雨(あめ)にぬれた縄(なわ)は、重(おも)くて持(も)ちにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "縄", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物を縛ったりつないだりする細長いひも状のもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38384, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皿", "is_correct": false, "explanation": "皿は料理を盛る器で、荷物を縛る道具ではないので文が成り立たない。"}, {"text": "縄", "is_correct": true, "explanation": "荷物を縛る細長い繊維製の道具。ここに入るのはこの語だけ。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、荷物を縛るのには使えない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は座る家具で、ものを縛る道具ではない。"}], "explanations": {"皿": "皿は料理を盛る器で、荷物を縛る道具ではないので文が成り立たない。", "縄": "荷物を縛る細長い繊維製の道具。ここに入るのはこの語だけ。", "鍋": "鍋は調理器具で、荷物を縛るのには使えない。", "椅子": "椅子は座る家具で、ものを縛る道具ではない。"}, "sentence_index": 0, "correct_answer": "縄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強風で電線の縄が切れて、停電した。", "explanation": "金属の線は〈ワイヤー〉と言い、〈縄〉は繊維をより合わせた道具なので、ここには合わない。"}, {"text": "靴の縄がほどけたので、結び直した。", "explanation": "靴ひもは〈紐〉と言い、〈縄〉とは言わない。細いひもを指す場面で〈縄〉は合わない。"}, {"text": "自転車の縄が外れて、坂道で止まれなくなった。", "explanation": "自転車のチェーンは〈鎖〉と言う。〈縄〉は繊維をより合わせた道具なので、金属の連なりには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38384, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "縄", "is_correct": true, "explanation": "細い縄と太い縄を比べる文で、重さを支える道具として『縄』だけが入る。"}, {"text": "鏡", "is_correct": false, "explanation": "鏡は姿を映す道具で、重いものを支える話には合わない。"}, {"text": "針", "is_correct": false, "explanation": "針は縫うための細い道具で、重い物を支える太さの比較には合わない。"}, {"text": "瓶", "is_correct": false, "explanation": "瓶は中身を入れる容器で、支える道具として比べる文には合わない。"}], "explanations": {"縄": "細い縄と太い縄を比べる文で、重さを支える道具として『縄』だけが入る。", "鏡": "鏡は姿を映す道具で、重いものを支える話には合わない。", "針": "針は縫うための細い道具で、重い物を支える太さの比較には合わない。", "瓶": "瓶は中身を入れる容器で、支える道具として比べる文には合わない。"}, "sentence_index": 6, "correct_answer": "縄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "針に縄を通すのに手間取り、何度もやり直した。", "explanation": "針に通すのは〈糸〉。〈縄〉は太くて針の穴には通せないので、この場面では合わない。"}, {"text": "髪に縄を結んで、パーティーに出かけた。", "explanation": "髪を結ぶのは〈リボン〉や〈ゴム〉。〈縄〉は髪飾りには使わないので不自然。"}, {"text": "けがをした指に縄を巻いて、手当てをした。", "explanation": "手当てには〈包帯〉を使う。〈縄〉は傷の手当てには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38384, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い箱が落ちないように、縄に強く縛った。", "corrected_sentence": "重い箱が落ちないように、縄で強く縛った。", "error_description": "縄は道具（手段）を表すので『で』が正しい。『に』だと『縄に縛る』となり、縛る道具として文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38384, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "勢いよく縄に引いたら、手をすりむいた。", "corrected_sentence": "勢いよく縄を引いたら、手をすりむいた。", "error_description": "『引く』は目的語（縄）に『を』を使う。『に』は誤りで、『縄に引く』は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38385, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『縄で稲の束を縛る』と道具（手段）を示す、正しい形。"}, {"text": "に", "is_correct": false, "explanation": "『縄に稲の束を縛る』では縄が縛る対象になり、道具の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "『縄へ稲の束を縛る』は方向を示す形で、手段を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「縄を稲の束を縛る」は目的語が二つ並んで文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "『縄で稲の束を縛る』と道具（手段）を示す、正しい形。", "に": "『縄に稲の束を縛る』では縄が縛る対象になり、道具の意味にならない。", "へ": "『縄へ稲の束を縛る』は方向を示す形で、手段を表せない。", "を": "「縄を稲の束を縛る」は目的語が二つ並んで文として成り立たない。"}, "error_tags": {"に": "対象", "へ": "方向", "を": "目的語の重複"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38385, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『縄で固定した』と道具（手段）を示す、正しい形。"}, {"text": "と", "is_correct": false, "explanation": "『縄と固定した』は並列になり、道具の意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "「米俵を縄を固定した」は目的語が二つ並んで文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "『縄より固定した』は比較の形で、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "『縄で固定した』と道具（手段）を示す、正しい形。", "と": "『縄と固定した』は並列になり、道具の意味にならない。", "を": "「米俵を縄を固定した」は目的語が二つ並んで文として成り立たない。", "より": "『縄より固定した』は比較の形で、文が成り立たない。"}, "error_tags": {"と": "並列", "より": "比較", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38385, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "縄とは、繊維をより合わせて作った、細長い道具で、物を縛ったり、引っ張ったりするのに使います。", "primary_collocate": null, "pronunciation": "なわ", "ipa": "naɰa", "syllable_count": 2, "sentences": [{"text": "稲わらをより合わせて、丈夫な縄を作ります。", "target_word": "縄", "complexity_tier": "T3", "furigana": "稲(いね)わらをより合(あ)わせて、丈夫(じょうぶ)な縄(なわ)を作(つく)ります。", "sentence_source": "generated"}, {"text": "農家の人は縄で稲の束を縛っていた。", "target_word": "縄", "complexity_tier": "T3", "furigana": "農家(のうか)の人(ひと)は縄(なわ)で稲(いね)の束(たば)を縛(しば)っていた。", "sentence_source": "generated"}, {"text": "みんなで縄を引っ張って、大きな石を動かした。", "target_word": "縄", "complexity_tier": "T3", "furigana": "みんなで縄(なわ)を引(ひ)っ張(ぱ)って、大(おお)きな石(いし)を動(うご)かした。", "sentence_source": "generated"}, {"text": "縄の端を柱に結んで、動かないようにした。", "target_word": "縄", "complexity_tier": "T3", "furigana": "縄(なわ)の端(はし)を柱(はしら)に結(むす)んで、動(うご)かないようにした。", "sentence_source": "generated"}, {"text": "昔の家では、縄で薪の束をしっかり縛って、物置にしまっていました。", "target_word": "縄", "complexity_tier": "T3", "furigana": "昔(むかし)の家(いえ)では、縄(なわ)で薪(まき)の束(たば)をしっかり縛(しば)って、物置(ものおき)にしまっていました。", "sentence_source": "generated"}, {"text": "この縄は繊維が太くて、とても丈夫です。", "target_word": "縄", "complexity_tier": "T3", "furigana": "この縄(なわ)は繊維(せんい)が太(ふと)くて、とても丈夫(じょうぶ)です。", "sentence_source": "generated"}, {"text": "縄を強く引くと、ぎしぎしと音がした。", "target_word": "縄", "complexity_tier": "T3", "furigana": "縄(なわ)を強(つよ)く引(ひ)くと、ぎしぎしと音(おと)がした。", "sentence_source": "generated"}, {"text": "荷車に積んだ米俵を、縄で固定した。", "target_word": "縄", "complexity_tier": "T3", "furigana": "荷車(にぐるま)に積(つ)んだ米俵(こめだわら)を、縄(なわ)で固定(こてい)した。", "sentence_source": "generated"}, {"text": "手でこすって縄を作る作業は、時間がかかる。", "target_word": "縄", "complexity_tier": "T3", "furigana": "手(て)でこすって縄(なわ)を作(つく)る作業(さぎょう)は、時間(じかん)がかかる。", "sentence_source": "generated"}, {"text": "古い縄が切れて、荷物が地面に落ちた。", "target_word": "縄", "complexity_tier": "T3", "furigana": "古(ふる)い縄(なわ)が切(き)れて、荷物(にもつ)が地面(じめん)に落(お)ちた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "縄", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "わらなどの繊維をより合わせて作った、縛る・引く道具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: ぎしぎし (Zipf 1.64)']::text[], '053a4284-f93e-4167-94a0-5a7bd9defdd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38385, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石", "is_correct": false, "explanation": "石はより合わせて作るものではないので、丈夫な〈作る〉対象として文が成り立たない。"}, {"text": "縄", "is_correct": true, "explanation": "稲わらをより合わせて作る丈夫なものは縄。ここに入るのはこの語だけ。"}, {"text": "砂", "is_correct": false, "explanation": "砂は稲わらを材料にしないので、より合わせて作る文には合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空にあるもので、作るものとして文に合わない。"}], "explanations": {"石": "石はより合わせて作るものではないので、丈夫な〈作る〉対象として文が成り立たない。", "縄": "稲わらをより合わせて作る丈夫なものは縄。ここに入るのはこの語だけ。", "砂": "砂は稲わらを材料にしないので、より合わせて作る文には合わない。", "雲": "雲は空にあるもので、作るものとして文に合わない。"}, "sentence_index": 0, "correct_answer": "縄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "掃除機の縄が抜けて、動かなくなった。", "explanation": "電気のコードは〈コード〉と言う。〈縄〉は繊維をより合わせた道具なので、ここには合わない。"}, {"text": "ボタンを付けるため、縄を針の穴に通した。", "explanation": "針の穴に通すのは〈糸〉。〈縄〉は太すぎて針の穴には通らないので合わない。"}, {"text": "髪を縄で結んで、学校に行った。", "explanation": "髪を結ぶのは〈ゴム〉や〈リボン〉で、〈縄〉は髪には使わないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38385, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "縄", "is_correct": true, "explanation": "強く引くと『ぎしぎし』と音がするのは縄。ここに入るのはこの語だけ。"}, {"text": "花", "is_correct": false, "explanation": "花は引っ張ると音を立てるものではなく、文の内容に合わない。"}, {"text": "水", "is_correct": false, "explanation": "水は引っ張れず、ぎしぎしと音を立てる場面に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は強く引くと破れるが、ぎしぎしという音は立てないので合わない。"}], "explanations": {"縄": "強く引くと『ぎしぎし』と音がするのは縄。ここに入るのはこの語だけ。", "花": "花は引っ張ると音を立てるものではなく、文の内容に合わない。", "水": "水は引っ張れず、ぎしぎしと音を立てる場面に合わない。", "紙": "紙は強く引くと破れるが、ぎしぎしという音は立てないので合わない。"}, "sentence_index": 6, "correct_answer": "縄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "真珠の縄を首にかけて、パーティーに出た。", "explanation": "首につけるのは〈首飾り〉。〈縄〉は装飾品として首にかける語ではないので不自然。"}, {"text": "箸の代わりに縄で豆を一粒ずつつまんだ。", "explanation": "細かい物をつまむのは〈ピンセット〉で、〈縄〉は細かい物をつまめない道具なので、この場面では合わない。"}, {"text": "傷口のガーゼを縄で押さえた。", "explanation": "傷口は〈包帯〉で押さえる。〈縄〉は医療用ではないので、手当ての文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38385, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重い米俵を縄に縛ったら、なかなか解けなかった。", "corrected_sentence": "重い米俵を縄で縛ったら、なかなか解けなかった。", "error_description": "縄は道具（手段）を表すので『で』が正しい。『に』では縄を縛る対象にしてしまい、文の意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38385, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い縄を切れて、荷物が落ちた。", "corrected_sentence": "古い縄が切れて、荷物が落ちた。", "error_description": "『切れる』は自動詞なので主語に『が』を使う。『を』では目的語になり、文として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c498a99-b103-497d-accc-4ff3cadd0b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38386, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「蓋が固い」と、蓋の状態を主語として述べる形。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。固いのは蓋の状態なので「蓋を固くて」では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す。状態の説明には合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「蓋から固くて」では状態の説明にならない。"}], "correct_answer": "が", "explanations": {"が": "「蓋が固い」と、蓋の状態を主語として述べる形。", "を": "目的語を示す。固いのは蓋の状態なので「蓋を固くて」では意味が通らない。", "と": "並列や相手を示す。状態の説明には合わない。", "から": "起点を示す。「蓋から固くて」では状態の説明にならない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38386, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す。「缶の蓋は、指を切りやすい」と蓋について述べる形。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す。蓋の性質を述べる文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す。「缶の蓋の、指を切りやすい」は成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。蓋が指を切りやすいという述語には合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す。「缶の蓋は、指を切りやすい」と蓋について述べる形。", "に": "位置や相手を示す。蓋の性質を述べる文には合わない。", "の": "所属や修飾を示す。「缶の蓋の、指を切りやすい」は成立しない。", "へ": "方向を示す。蓋が指を切りやすいという述語には合わない。"}, "error_tags": {"に": "位置・相手", "の": "所属・修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38386, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをおおうもの。ふた。", "primary_collocate": null, "pronunciation": "ふた", "ipa": "ɸɯta", "syllable_count": 2, "sentences": [{"text": "鍋の蓋をして、弱い火で十分煮ます。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "鍋[なべ]の蓋[ふた]をして、弱[よわ]い火[ひ]で十分[じゅうぶん]煮[に]ます。", "sentence_source": "generated"}, {"text": "瓶の蓋が固くて、なかなか開かなかった。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "瓶[びん]の蓋[ふた]が固[かた]くて、なかなか開[あ]かなかった。", "sentence_source": "generated"}, {"text": "お茶が冷めないように、急須の蓋を閉めておいた。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "お茶[ちゃ]が冷[さ]めないように、急須[きゅうす]の蓋[ふた]を閉[し]めておいた。", "sentence_source": "generated"}, {"text": "ごみ箱の蓋を開けたら、嫌なにおいがした。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "ごみ箱[ばこ]の蓋[ふた]を開[あ]けたら、嫌[いや]なにおいがした。", "sentence_source": "generated"}, {"text": "ペットボトルの蓋をなくしたので、飲み残しがこぼれた。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "ペットボトルの蓋[ふた]をなくしたので、飲[の]み残[のこ]しがこぼれた。", "sentence_source": "generated"}, {"text": "お弁当の蓋に、ご飯がくっついていた。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "お弁当[べんとう]の蓋[ふた]に、ご飯[はん]がくっついていた。", "sentence_source": "generated"}, {"text": "虫が入らないように、水がめに蓋をかけた。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "虫[むし]が入[はい]らないように、水[みず]がめに蓋[ふた]をかけた。", "sentence_source": "generated"}, {"text": "缶の蓋は、指を切りやすいので気をつけてください。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "缶[かん]の蓋[ふた]は、指[ゆび]を切[き]りやすいので気[き]をつけてください。", "sentence_source": "generated"}, {"text": "マンホールの蓋がはずれていて、自転車が落ちそうになった。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "マンホールの蓋[ふた]がはずれていて、自転車[じてんしゃ]が落[お]ちそうになった。", "sentence_source": "generated"}, {"text": "炊飯器の蓋を開けると、白い湯気が顔にかかった。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "炊飯器[すいはんき]の蓋[ふた]を開[あ]けると、白[しろ]い湯気[ゆげ]が顔[かお]にかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蓋", "label": "基本形"}, {"form": "ふた", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "鍋・瓶・箱などの口をおおって閉じる、取りはずせる物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 水がめ (Zipf 1.9)']::text[], 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38386, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蓋", "is_correct": true, "explanation": "鍋の口にかぶせるふたを指し、「鍋の蓋をして」で自然につながる。"}, {"text": "包丁", "is_correct": false, "explanation": "切るための道具で、鍋の上にかぶせて「をして」とは言えない。"}, {"text": "菜箸", "is_correct": false, "explanation": "料理をつまむ箸で、鍋にかぶせる物ではないので「鍋の菜箸をして」は合わない。"}, {"text": "鍋敷き", "is_correct": false, "explanation": "鍋の下に敷く台で、鍋の上にかぶせる物ではない。"}], "explanations": {"蓋": "鍋の口にかぶせるふたを指し、「鍋の蓋をして」で自然につながる。", "包丁": "切るための道具で、鍋の上にかぶせて「をして」とは言えない。", "菜箸": "料理をつまむ箸で、鍋にかぶせる物ではないので「鍋の菜箸をして」は合わない。", "鍋敷き": "鍋の下に敷く台で、鍋の上にかぶせる物ではない。"}, "sentence_index": 0, "correct_answer": "蓋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関の蓋を回して、家に入った。", "explanation": "ここは〈鍵〉（錠）の意味。鍵は回して使うものだが、玄関の錠前を「蓋」とは言わない。"}, {"text": "ワインの蓋を抜いて、グラスに注いだ。", "explanation": "ここは〈栓〉の意味。栓は「抜く」ものだが、蓋は「開ける」ものなので「蓋を抜く」とは言わない。"}, {"text": "寒いので、窓の蓋を閉めて外気を防いだ。", "explanation": "ここは〈戸〉（窓の開閉部）の意味。窓は「閉める」が、窓の戸を「蓋」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38386, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蓋", "is_correct": true, "explanation": "水がめの口にかぶせるふたで、「蓋をかけた」と自然につながる。"}, {"text": "皿", "is_correct": false, "explanation": "食器で、水がめにかぶせて「皿をかけた」とは言わない。"}, {"text": "杓子", "is_correct": false, "explanation": "料理用のしゃくし（杓子）で、水がめにかぶせる物ではない。"}, {"text": "盆", "is_correct": false, "explanation": "物を載せる台で、水がめにかぶせる物ではない。"}], "explanations": {"蓋": "水がめの口にかぶせるふたで、「蓋をかけた」と自然につながる。", "皿": "食器で、水がめにかぶせて「皿をかけた」とは言わない。", "杓子": "料理用のしゃくし（杓子）で、水がめにかぶせる物ではない。", "盆": "物を載せる台で、水がめにかぶせる物ではない。"}, "sentence_index": 6, "correct_answer": "蓋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙の蓋を切って、中身を読んだ。", "explanation": "ここは〈封〉の意味（封筒の口をとじたもの）。封は「切る」ものだが、蓋は容器のふたで封筒には使わない。"}, {"text": "みかんの蓋をむいて、房を食べた。", "explanation": "ここは〈皮〉の意味。みかんの外側の皮は「むく」が、蓋とは言わない。"}, {"text": "ゆで卵の蓋をむいて、塩をかけた。", "explanation": "ここは〈殻〉の意味。卵の外側の硬い部分は「殻をむく」と言い、蓋とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38386, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペットボトルの蓋に固くて、なかなか開かなかった。", "corrected_sentence": "ペットボトルの蓋が固くて、なかなか開かなかった。", "error_description": "「蓋」に付く格助詞の誤り。状態の主語を示す「が」が正しく、「に」だと「蓋に固くて」となり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38386, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍋の蓋を切ると、白い湯気が顔にかかった。", "corrected_sentence": "鍋の蓋を開けると、白い湯気が顔にかかった。", "error_description": "蓋に続く動詞の誤り。蓋は「切る」ではなく「開ける」もの。正しくは「開けると」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38387, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「蓋が固い」と、蓋の状態を主語として述べる形。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。蓋の状態を言うのに「を」は使わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。状態の説明には合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示す。「瓶の蓋で固くて」では状態の説明にならない。"}], "correct_answer": "が", "explanations": {"が": "「蓋が固い」と、蓋の状態を主語として述べる形。", "を": "目的語を示す。蓋の状態を言うのに「を」は使わない。", "へ": "方向を示す。状態の説明には合わない。", "で": "手段・場所を示す。「瓶の蓋で固くて」では状態の説明にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38387, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。「蓋が透明」と蓋の状態を述べる形。"}, {"text": "に", "is_correct": false, "explanation": "位置や方向を示す。蓋の性質を述べる文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す。「蓋と透明」では状態の説明にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「蓋から透明」は不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。「蓋が透明」と蓋の状態を述べる形。", "に": "位置や方向を示す。蓋の性質を述べる文には合わない。", "と": "並列や相手を示す。「蓋と透明」では状態の説明にならない。", "から": "起点を示す。「蓋から透明」は不自然。"}, "error_tags": {"に": "位置・方向", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38387, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "容器などの口をふさぐ物。また、物の上にかぶせる物。", "primary_collocate": null, "pronunciation": "ふた", "ipa": "ɸɯta", "syllable_count": 2, "sentences": [{"text": "鍋の蓋を開けると、おいしそうな匂いがした。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "鍋[なべ]の蓋[ふた]を開[あ]けると、おいしそうな匂[にお]いがした。", "sentence_source": "generated"}, {"text": "瓶の蓋が固くて、なかなか開かない。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "瓶[びん]の蓋[ふた]が固[かた]くて、なかなか開[あ]かない。", "sentence_source": "generated"}, {"text": "蓋をしないと、ご飯が冷めてしまいます。", "target_word": "蓋", "complexity_tier": "T2", "furigana": "蓋[ふた]をしないと、ご飯[はん]が冷[さ]めてしまいます。", "sentence_source": "generated"}, {"text": "弟がペットボトルの蓋を失くして、お茶がこぼれた。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "弟[おとうと]がペットボトルの蓋[ふた]を失[な]くして、お茶[ちゃ]がこぼれた。", "sentence_source": "generated"}, {"text": "湯が沸いたので、やかんの蓋を少し開けた。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "湯[ゆ]が沸[わ]いたので、やかんの蓋[ふた]を少[すこ]し開[あ]けた。", "sentence_source": "generated"}, {"text": "箱の蓋を閉めて、棚の上に置いた。", "target_word": "蓋", "complexity_tier": "T2", "furigana": "箱[はこ]の蓋[ふた]を閉[し]めて、棚[たな]の上[うえ]に置[お]いた。", "sentence_source": "generated"}, {"text": "虫が入らないように、水槽に蓋をかぶせた。", "target_word": "蓋", "complexity_tier": "T4", "furigana": "虫[むし]が入[はい]らないように、水槽[すいそう]に蓋[ふた]をかぶせた。", "sentence_source": "generated"}, {"text": "この容器は蓋が透明なので、中身がよく見える。", "target_word": "蓋", "complexity_tier": "T4", "furigana": "この容器[ようき]は蓋[ふた]が透明[とうめい]なので、中身[なかみ]がよく見[み]える。", "sentence_source": "generated"}, {"text": "蓋を取ると、中には古い写真が入っていた。", "target_word": "蓋", "complexity_tier": "T3", "furigana": "蓋[ふた]を取[と]ると、中[なか]には古[ふる]い写真[しゃしん]が入[はい]っていた。", "sentence_source": "generated"}, {"text": "味噌汁の鍋に蓋をして、弱火で五分煮る。", "target_word": "蓋", "complexity_tier": "T4", "furigana": "味噌汁[みそしる]の鍋[なべ]に蓋[ふた]をして、弱火[よわび]で五分[ごふん]煮[に]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蓋", "label": "基本形"}, {"form": "蓋を", "label": "目的語形"}, {"form": "蓋が", "label": "主語形"}, {"form": "蓋に", "label": "格助詞つき"}], "register": "中立（日常の話し言葉）", "sense_fingerprint": "鍋・瓶・箱などの口や上をおおうふた", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38387, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蓋", "is_correct": true, "explanation": "鍋の口をおおうふたで、「鍋の蓋を開ける」と自然につながる。"}, {"text": "麺棒", "is_correct": false, "explanation": "生地を伸ばす棒で、鍋のふたを開けるとは言わない。"}, {"text": "布巾", "is_correct": false, "explanation": "拭く布で、鍋のふたの代わりに開ける物ではない。"}, {"text": "菜箸", "is_correct": false, "explanation": "料理用の箸で、開けるものではないので「鍋の菜箸を開ける」は合わない。"}], "explanations": {"蓋": "鍋の口をおおうふたで、「鍋の蓋を開ける」と自然につながる。", "麺棒": "生地を伸ばす棒で、鍋のふたを開けるとは言わない。", "布巾": "拭く布で、鍋のふたの代わりに開ける物ではない。", "菜箸": "料理用の箸で、開けるものではないので「鍋の菜箸を開ける」は合わない。"}, "sentence_index": 0, "correct_answer": "蓋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自転車の蓋を回して、施錠した。", "explanation": "ここは〈錠〉（鍵）の意味。自転車の錠は「施錠」するものだが、その部分を「蓋」とは言わない。"}, {"text": "シャンパンの蓋を抜いて、グラスに注いだ。", "explanation": "ここは〈栓〉の意味。栓は「抜く」ものだが、蓋は「抜く」とは言わない。"}, {"text": "本の蓋をめくって、読み始めた。", "explanation": "ここは〈表紙〉の意味。本の外側の覆いは「表紙」と言い、蓋とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38387, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蓋", "is_correct": true, "explanation": "水槽の口にかぶせるふたで、「蓋をかぶせた」と自然につながる。"}, {"text": "包丁", "is_correct": false, "explanation": "切るための道具で、水槽にかぶせる物ではない。"}, {"text": "杓子", "is_correct": false, "explanation": "料理用のしゃくし（杓子）で、水槽にかぶせる物ではない。"}, {"text": "鍋敷き", "is_correct": false, "explanation": "鍋の下に敷く台で、水槽にかぶせる物ではない。"}], "explanations": {"蓋": "水槽の口にかぶせるふたで、「蓋をかぶせた」と自然につながる。", "包丁": "切るための道具で、水槽にかぶせる物ではない。", "杓子": "料理用のしゃくし（杓子）で、水槽にかぶせる物ではない。", "鍋敷き": "鍋の下に敷く台で、水槽にかぶせる物ではない。"}, "sentence_index": 6, "correct_answer": "蓋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "封筒の蓋を切って、中の手紙を読んだ。", "explanation": "ここは〈封〉の意味（封筒の口をとじた部分）。封は「切る」と言うが、蓋は容器のふたで封筒には使わない。"}, {"text": "バナナの蓋をむいて、食べた。", "explanation": "ここは〈皮〉の意味。バナナの外側の皮は「むく」が、蓋とは言わない。"}, {"text": "うずらの卵の蓋をむいて、醤油につけた。", "explanation": "ここは〈殻〉の意味。卵の硬い外側は「殻をむく」と言い、蓋とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38387, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い缶の蓋に固くて、なかなか開かない。", "corrected_sentence": "古い缶の蓋が固くて、なかなか開かない。", "error_description": "蓋に付く格助詞の誤り。状態の主語には「が」を使う。「に」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38387, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ジャムの瓶の蓋を切って、スプーンですくった。", "corrected_sentence": "ジャムの瓶の蓋を開けて、スプーンですくった。", "error_description": "蓋に続く動詞の誤り。蓋は「切る」ではなく「開ける」もの。正しくは「開けて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
