INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38388, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものがなくなって、どこにも見えなくなること。", "primary_collocate": null, "pronunciation": "なくなる", "ipa": "nakɯnaɾɯ", "syllable_count": 4, "sentences": [{"text": "かばんに入れたはずの財布が、どこを探しても無くなっていました。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "かばんに入[い]れたはずの財布[さいふ]が、どこを探[さが]しても無[な]くなっていました。", "sentence_source": "generated"}, {"text": "机の上に置いたペンが無くなったので、友だちに聞きました。", "target_word": "無くなった", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に置[お]いたペンが無[な]くなったので、友[とも]だちに聞[き]きました。", "sentence_source": "generated"}, {"text": "朝まであった自転車が無くなっていて、とても驚きました。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "朝[あさ]まであった自転車[じてんしゃ]が無[な]くなっていて、とても驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "部屋のかぎが無くなって、家に入れませんでした。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "部屋[へや]のかぎが無[な]くなって、家[いえ]に入[はい]れませんでした。", "sentence_source": "generated"}, {"text": "空にあった雲が、いつのまにか無くなって、青空が広がりました。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "空[そら]にあった雲[くも]が、いつのまにか無[な]くなって、青空[あおぞら]が広[ひろ]がりました。", "sentence_source": "generated"}, {"text": "昨日までここにあった看板が無くなっています。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "昨日[きのう]までここにあった看板[かんばん]が無[な]くなっています。", "sentence_source": "generated"}, {"text": "電車の中で傘が無くなったので、駅の人に連絡しました。", "target_word": "無くなった", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で傘[かさ]が無[な]くなったので、駅[えき]の人[ひと]に連絡[れんらく]しました。", "sentence_source": "generated"}, {"text": "鏡の前に置いた指輪が無くなり、家中を探しました。", "target_word": "無くなり", "complexity_tier": "T3", "furigana": "鏡[かがみ]の前[まえ]に置[お]いた指輪[ゆびわ]が無[な]くなり、家中[いえじゅう]を探[さが]しました。", "sentence_source": "generated"}, {"text": "海の近くにあった小さな店が、いつの間にか無くなっていました。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くにあった小[ちい]さな店[みせ]が、いつの間[ま]にか無[な]くなっていました。", "sentence_source": "generated"}, {"text": "引き出しの中の写真が無くなって、だれかが持っていったのだと思いました。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しの中[なか]の写真[しゃしん]が無[な]くなって、だれかが持[も]っていったのだと思[おも]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無くなる", "label": "終止形"}, {"form": "無くなった", "label": "過去形"}, {"form": "無くならない", "label": "否定形"}, {"form": "無くなって", "label": "て形"}, {"form": "無くなれば", "label": "仮定形"}], "register": "一般的な標準語", "sense_fingerprint": "あったはずの物が見つからず、どこにも見えなくなる。紛失や消失に注目した意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38388, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無くなって", "is_correct": true, "explanation": "「て形＋いました」で、財布が消えた状態が続いていたことを表す。正解。"}, {"text": "無くなる", "is_correct": false, "explanation": "辞書形は「いました」に直接続けられず、文が成り立たない。"}, {"text": "無くなれば", "is_correct": false, "explanation": "仮定形は「いました」と続かず、文が成り立たない。"}, {"text": "無くなり", "is_correct": false, "explanation": "連用形は「いました」に直接つながらず、文が不自然になる。"}], "explanations": {"無くなって": "「て形＋いました」で、財布が消えた状態が続いていたことを表す。正解。", "無くなる": "辞書形は「いました」に直接続けられず、文が成り立たない。", "無くなれば": "仮定形は「いました」と続かず、文が成り立たない。", "無くなり": "連用形は「いました」に直接つながらず、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "無くなって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が無くなって、やっと外に出られた。", "explanation": "ここは〈やむ〉の意味（雨が止む）。無くなるは物が見えなくなることで、雨がやむ変化には使わない。"}, {"text": "祖父が無くなって、家族で葬式をした。", "explanation": "ここは〈亡くなる〉の意味（人が死ぬ）。同じ読みの別の語で、無くなるは人の死には使わない。"}, {"text": "日が無くなって、あたりが暗くなった。", "explanation": "ここは〈日が暮れる〉の意味。無くなるは物が見えなくなることで、日暮れの移り変わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38388, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無くなった", "is_correct": true, "explanation": "「傘が無くなったので」の過去の完了の形。正解。"}, {"text": "無くなれ", "is_correct": false, "explanation": "命令形は文を終わらせる形で、「ので」の前に続けて理由を述べることはできない。"}, {"text": "無くなろう", "is_correct": false, "explanation": "意向形は「ので」の前に置けず、理由の文が成り立たない。"}, {"text": "無くす", "is_correct": false, "explanation": "無くすは他動詞で「傘が無くすので」とは続かず、主語の傘と合わない。"}], "explanations": {"無くなった": "「傘が無くなったので」の過去の完了の形。正解。", "無くなれ": "命令形は文を終わらせる形で、「ので」の前に続けて理由を述べることはできない。", "無くなろう": "意向形は「ので」の前に置けず、理由の文が成り立たない。", "無くす": "無くすは他動詞で「傘が無くすので」とは続かず、主語の傘と合わない。"}, "sentence_index": 6, "correct_answer": "無くなった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもが無くなって、みんなで探した。", "explanation": "ここは〈いなくなる〉の意味（その場からいなくなる）。無くなるは人には使わず、物がなくなる意味に限られる。"}, {"text": "風船が無くなって、大きくふくらんだ。", "explanation": "ここは〈ふくらむ〉の意味（大きくなる）。無くなるは消えてなくなる変化で、ふくらむ変化とは合わない。"}, {"text": "体重が無くなった。", "explanation": "ここは〈減る〉の意味（量が少なくなる）。無くなるは全部消えることなので、少しずつ減る変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38388, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "かばんの中から、財布が無くならなっていました。", "corrected_sentence": "かばんの中から、財布が無くなっていました。", "error_description": "「無くなっていました」の形が正しい。「無くならなっていた」は動詞の語幹が誤っていて、日本語として成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無くなった", "is_correct": true, "explanation": "過去の完了を表す形で、「ので」の前に置ける。正解。"}, {"text": "無くなって", "is_correct": false, "explanation": "て形は「ので」の前に置けず、理由の文が成り立たない。"}, {"text": "無くなれば", "is_correct": false, "explanation": "仮定形は「ので」の前に直接つかず、文が成り立たない。"}, {"text": "無くなろう", "is_correct": false, "explanation": "意向形は「ので」の前に置けず、文が不自然になる。"}], "correct_form": "無くなった", "base_form": "無くなる", "form_label": "過去形", "sentence_index": 1, "explanations": {"無くなった": "過去の完了を表す形で、「ので」の前に置ける。正解。", "無くなって": "て形は「ので」の前に置けず、理由の文が成り立たない。", "無くなれば": "仮定形は「ので」の前に直接つかず、文が成り立たない。", "無くなろう": "意向形は「ので」の前に置けず、文が不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38388, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ペンケースから消しゴムが無くなられた。", "corrected_sentence": "ペンケースから消しゴムが無くなった。", "error_description": "無くなるは自動詞で、受け身や尊敬の形にはしない。「無くなられた」は不自然で、「無くなった」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無くなり", "is_correct": true, "explanation": "連用形で、後ろの「家中を探しました」へ続く中止の形。正解。"}, {"text": "無くならない", "is_correct": false, "explanation": "否定形では指輪が消えなかったという意味になり、文の事実と合わない。"}, {"text": "無くなれ", "is_correct": false, "explanation": "命令形は「、」で続けると相手への命令になり、探した事実と合わない。"}, {"text": "無くなる", "is_correct": false, "explanation": "辞書形は「、」で続けると時間の前後が合わず、不自然になる。"}], "correct_form": "無くなり", "base_form": "無くなる", "form_label": "連用形（中止）", "sentence_index": 7, "explanations": {"無くなり": "連用形で、後ろの「家中を探しました」へ続く中止の形。正解。", "無くならない": "否定形では指輪が消えなかったという意味になり、文の事実と合わない。", "無くなれ": "命令形は「、」で続けると相手への命令になり、探した事実と合わない。", "無くなる": "辞書形は「、」で続けると時間の前後が合わず、不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
