INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38389, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "存在していた物が、使われたり、無くなったりして、もうない状態になること。", "primary_collocate": null, "pronunciation": "なくなる", "ipa": "nakɯnaɾɯ", "syllable_count": 4, "sentences": [{"text": "冷蔵庫の牛乳が無くなったので、買いに行きます。", "target_word": "無くなった", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の牛乳[ぎゅうにゅう]が無[な]くなったので、買[か]いに行[い]きます。", "sentence_source": "generated"}, {"text": "今日は人気のパンが、昼前に全部無くなりました。", "target_word": "無くなり", "complexity_tier": "T3", "furigana": "今日[きょう]は人気[にんき]のパンが、昼前[ひるまえ]に全部[ぜんぶ]無[な]くなりました。", "sentence_source": "generated"}, {"text": "お金が無くなる前に、家計簿をつけはじめました。", "target_word": "無くなる", "complexity_tier": "T3", "furigana": "お金[かね]が無[な]くなる前[まえ]に、家計簿[かけいぼ]をつけはじめました。", "sentence_source": "generated"}, {"text": "トイレットペーパーが無くなりそうなので、買っておきます。", "target_word": "無くなり", "complexity_tier": "T3", "furigana": "トイレットペーパーが無[な]くなりそうなので、買[か]っておきます。", "sentence_source": "generated"}, {"text": "みんなで食べたら、ケーキはすぐに無くなってしまいました。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "みんなで食[た]べたら、ケーキはすぐに無[な]くなってしまいました。", "sentence_source": "generated"}, {"text": "水が無くなると山では危険なので、多めに持って行きます。", "target_word": "無くなる", "complexity_tier": "T3", "furigana": "水[みず]が無[な]くなると山[やま]では危険[きけん]なので、多[おお]めに持[も]って行[い]きます。", "sentence_source": "generated"}, {"text": "インクが無くなって、プリンターが動かなくなりました。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "インクが無[な]くなって、プリンターが動[うご]かなくなりました。", "sentence_source": "generated"}, {"text": "砂糖が無くなっていたので、料理の味つけができませんでした。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "砂糖[さとう]が無[な]くなっていたので、料理[りょうり]の味[あじ]つけができませんでした。", "sentence_source": "generated"}, {"text": "時間が無くなってきたので、急いで宿題を終わらせました。", "target_word": "無くなって", "complexity_tier": "T3", "furigana": "時間[じかん]が無[な]くなってきたので、急[いそ]いで宿題[しゅくだい]を終[お]わらせました。", "sentence_source": "generated"}, {"text": "ガソリンが無くなったら、車は止まってしまいます。", "target_word": "無くなったら", "complexity_tier": "T3", "furigana": "ガソリンが無[な]くなったら、車[くるま]は止[と]まってしまいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "無くなる", "label": "終止形"}, {"form": "無くなった", "label": "過去形"}, {"form": "無くならない", "label": "否定形"}, {"form": "無くなって", "label": "て形"}, {"form": "無くなれば", "label": "仮定形"}], "register": "一般的な標準語", "sense_fingerprint": "使ったり減ったりして、残りがもうない状態になる。消費や不足に注目した意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167dea36-e428-4811-927c-f1e671569baa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38389, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "無くなった", "is_correct": true, "explanation": "「冷蔵庫の牛乳が無くなったので」の過去の完了の形。正解。"}, {"text": "無くなって", "is_correct": false, "explanation": "て形は「ので」の前に置けず、理由の文が成り立たない。"}, {"text": "無くなれば", "is_correct": false, "explanation": "仮定形は「ば」で続くので、「ので」の理由文には入らない。"}, {"text": "無くなろう", "is_correct": false, "explanation": "意向形は「ので」の前に置けず、文が不自然になる。"}], "explanations": {"無くなった": "「冷蔵庫の牛乳が無くなったので」の過去の完了の形。正解。", "無くなって": "て形は「ので」の前に置けず、理由の文が成り立たない。", "無くなれば": "仮定形は「ば」で続くので、「ので」の理由文には入らない。", "無くなろう": "意向形は「ので」の前に置けず、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "無くなった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猫が無くなって、家族で探した。", "explanation": "ここは〈いなくなる〉の意味（その場からいなくなる）。無くなるは使い切ったり消えたりする物に使い、動物には使わない。"}, {"text": "体温が無くなって、熱が出た。", "explanation": "ここは〈上がる〉の意味（温度や数値が高くなる）。無くなるは全部なくなる変化なので、上がる変化は表さない。"}, {"text": "友人が無くなって、みんなで悲しんだ。", "explanation": "ここは〈亡くなる〉の意味（人が死ぬ）。同じ読みの別の語で、無くなるは人の死には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38389, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "無くなって", "is_correct": true, "explanation": "「インクが無くなって、プリンターが動かなくなった」の原因を表すて形。正解。"}, {"text": "無くなる", "is_correct": false, "explanation": "辞書形は「、」で続けると原因のつながりが成り立たず、不自然になる。"}, {"text": "無くなれ", "is_correct": false, "explanation": "命令形は文を終わらせる形で、「、」で続けて原因を述べることはできない。"}, {"text": "無くならない", "is_correct": false, "explanation": "否定形は「インクが消えなかった」という意味になり、プリンターが動かなくなった原因として合わない。"}], "explanations": {"無くなって": "「インクが無くなって、プリンターが動かなくなった」の原因を表すて形。正解。", "無くなる": "辞書形は「、」で続けると原因のつながりが成り立たず、不自然になる。", "無くなれ": "命令形は文を終わらせる形で、「、」で続けて原因を述べることはできない。", "無くならない": "否定形は「インクが消えなかった」という意味になり、プリンターが動かなくなった原因として合わない。"}, "sentence_index": 6, "correct_answer": "無くなって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "貯金が無くなって、残高が増えた。", "explanation": "ここは〈増える〉の意味（量が多くなる）。無くなるは消えてなくなる変化なので、増える意味には使わない。"}, {"text": "ロープが無くなって、ぴんと張った。", "explanation": "ここは〈張る〉の意味（ぴんと張りつめる）。無くなるは消える変化なので、張った状態は表さない。"}, {"text": "鍋の取っ手が無くなって、しっかり付いた。", "explanation": "ここは〈付く〉の意味（つけ加わる）。無くなるは消える変化なので、取りつく意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38389, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お米が無くなった前に、スーパーで買っておきます。", "corrected_sentence": "お米が無くなる前に、スーパーで買っておきます。", "error_description": "「〜する前に」には辞書形の「無くなる」を使う。過去形の「無くなった前に」は、すでに起きたことの後という意味になり、文の意図と合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無くなり", "is_correct": true, "explanation": "「ます」の前の形で、「無くなりました」の丁寧な過去の言い方になる。正解。"}, {"text": "無くなる", "is_correct": false, "explanation": "辞書形に「ました」は続かず、「無くなるました」となって誤り。"}, {"text": "無くなれば", "is_correct": false, "explanation": "仮定形は「ました」に続かず、文が成り立たない。"}, {"text": "無くなろう", "is_correct": false, "explanation": "意向形は「ました」に続かず、文が成り立たない。"}], "correct_form": "無くなり", "base_form": "無くなる", "form_label": "連用形（ます形）", "sentence_index": 1, "explanations": {"無くなり": "「ます」の前の形で、「無くなりました」の丁寧な過去の言い方になる。正解。", "無くなる": "辞書形に「ました」は続かず、「無くなるました」となって誤り。", "無くなれば": "仮定形は「ました」に続かず、文が成り立たない。", "無くなろう": "意向形は「ました」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38389, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ガソリンを無くなったら、給油所に寄ります。", "corrected_sentence": "ガソリンが無くなったら、給油所に寄ります。", "error_description": "無くなるは自動詞なので、主語は「が」で示す。「を」は目的語を表すので、無くなる文には合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無くなって", "is_correct": true, "explanation": "「て形＋いた」で、砂糖が無くなった状態が続いていたことを表す。正解。"}, {"text": "無くなった", "is_correct": false, "explanation": "過去形は「いた」と続かず、「無くなったいた」は誤り。"}, {"text": "無くならない", "is_correct": false, "explanation": "否定形は「いた」に直接続かず、「無くならないていた」は成り立たない。"}, {"text": "無くなれ", "is_correct": false, "explanation": "命令形は「いた」に続かず、「無くなれていた」は文が成り立たない。"}], "correct_form": "無くなって", "base_form": "無くなる", "form_label": "て形", "sentence_index": 7, "explanations": {"無くなって": "「て形＋いた」で、砂糖が無くなった状態が続いていたことを表す。正解。", "無くなった": "過去形は「いた」と続かず、「無くなったいた」は誤り。", "無くならない": "否定形は「いた」に直接続かず、「無くならないていた」は成り立たない。", "無くなれ": "命令形は「いた」に続かず、「無くなれていた」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0bd718d-1d24-44b1-b7bb-ee59b8961801') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38390, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す。「野球をやる」と、やる対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。野球を主語にすると「やる」の意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す。「野球とやる」では目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「野球からやる」は不自然。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す。「野球をやる」と、やる対象を表す。", "が": "主語を示す。野球を主語にすると「やる」の意味が合わない。", "と": "相手や並列を示す。「野球とやる」では目的語にならない。", "から": "起点を示す。「野球からやる」は不自然。"}, "error_tags": {"が": "主語", "と": "相手・並列", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38390, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38390, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「やる」は、何かをするという意味です。", "primary_collocate": null, "pronunciation": "やる", "ipa": "jaɾɯ", "syllable_count": 2, "sentences": [{"text": "宿題は夕食の前にやってしまいます。", "target_word": "やって", "complexity_tier": "T2", "furigana": "宿題[しゅくだい]は夕食[ゆうしょく]の前[まえ]にやってしまいます。", "sentence_source": "generated"}, {"text": "日曜日は友達と野球をやる予定です。", "target_word": "やる", "complexity_tier": "T2", "furigana": "日曜日[にちようび]は友達[ともだち]と野球[やきゅう]をやる予定[よてい]です。", "sentence_source": "generated"}, {"text": "試験が近いので、今夜は遅くまで勉強をやる。", "target_word": "やる", "complexity_tier": "T3", "furigana": "試験[しけん]が近[ちか]いので、今夜[こんや]は遅[おそ]くまで勉強[べんきょう]をやる。", "sentence_source": "generated"}, {"text": "一度やると決めたら、最後まで続けなさい。", "target_word": "やる", "complexity_tier": "T3", "furigana": "一度[いちど]やると決[き]めたら、最後[さいご]まで続[つづ]けなさい。", "sentence_source": "generated"}, {"text": "駅前の店で、毎週土曜日に安売りをやっている。", "target_word": "やって", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の店[みせ]で、毎週[まいしゅう]土曜日[どようび]に安売[やすう]りをやっている。", "sentence_source": "generated"}, {"text": "今日の掃除は私がやるから、休んでいていいよ。", "target_word": "やる", "complexity_tier": "T3", "furigana": "今日[きょう]の掃除[そうじ]は私[わたし]がやるから、休[やす]んでいていいよ。", "sentence_source": "generated"}, {"text": "彼は何をやっても、すぐに上手になる。", "target_word": "やって", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]をやっても、すぐに上手[じょうず]になる。", "sentence_source": "generated"}, {"text": "この遊びは小さい子でも簡単にやれる。", "target_word": "やれる", "complexity_tier": "T3", "furigana": "この遊[あそ]びは小[ちい]さい子[こ]でも簡単[かんたん]にやれる。", "sentence_source": "generated"}, {"text": "授業の後、教室で何をやっていたのですか。", "target_word": "やって", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の後[あと]、教室[きょうしつ]で何[なに]をやっていたのですか。", "sentence_source": "generated"}, {"text": "母は毎朝、庭でラジオ体操をやっている。", "target_word": "やって", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、庭[にわ]でラジオ体操[たいそう]をやっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "やる", "label": "辞書形"}, {"form": "やります", "label": "丁寧形"}, {"form": "やって", "label": "て形"}, {"form": "やった", "label": "た形"}, {"form": "やらない", "label": "ない形"}, {"form": "やれる", "label": "可能形"}], "register": "口語（くだけた日常語）", "sense_fingerprint": "宿題・スポーツ・掃除など、ある行為を「する」の意味で行う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38390, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "やって", "is_correct": true, "explanation": "「〜てしまう」に続く て形で、「やってしまいます」と自然につながる。"}, {"text": "やる", "is_correct": false, "explanation": "辞書形は「やるしまう」とは続かない。"}, {"text": "やり", "is_correct": false, "explanation": "連用形のままでは「やりしまう」となり、〜てしまうに続かない。"}, {"text": "やら", "is_correct": false, "explanation": "未然形は「やらしまう」となり、〜てしまうに続かない。"}], "explanations": {"やって": "「〜てしまう」に続く て形で、「やってしまいます」と自然につながる。", "やる": "辞書形は「やるしまう」とは続かない。", "やり": "連用形のままでは「やりしまう」となり、〜てしまうに続かない。", "やら": "未然形は「やらしまう」となり、〜てしまうに続かない。"}, "sentence_index": 0, "correct_answer": "やって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の試験の結果を見て、ショックをやった。", "explanation": "ここは〈受ける〉の意味（ショックを受けた）。「やる」は自分から行う動作で、感情を受ける場合には使わない。"}, {"text": "昨日の夜、外にいて風邪をやった。", "explanation": "ここは〈ひく〉の意味。風邪は「ひく」ものなので、「やる」とは言わない。"}, {"text": "姉が私にお菓子をやった。", "explanation": "ここは〈くれる〉に当たる向き（相手が自分に与える）。「やる」は与える側から相手へ渡す言い方で、この向きでは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38390, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "やって", "is_correct": true, "explanation": "「何をやっても」のて形に「も」が続く、自然な形。"}, {"text": "やれ", "is_correct": false, "explanation": "命令形は「何をやれも」と「も」に続かない。"}, {"text": "やろ", "is_correct": false, "explanation": "意向形の語幹は「やろも」となり、「も」に続かない。"}, {"text": "やれば", "is_correct": false, "explanation": "仮定形は「やれば」となり、「やっても」の形に合わない。"}], "explanations": {"やって": "「何をやっても」のて形に「も」が続く、自然な形。", "やれ": "命令形は「何をやれも」と「も」に続かない。", "やろ": "意向形の語幹は「やろも」となり、「も」に続かない。", "やれば": "仮定形は「やれば」となり、「やっても」の形に合わない。"}, "sentence_index": 6, "correct_answer": "やって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に悩みをやっていた。", "explanation": "ここは〈悩む〉の意味。悩みは「抱える・悩む」ものなので、「やる」とは言わない。"}, {"text": "校長が生徒に表彰状をやった。", "explanation": "ここは〈授ける〉の意味。表彰状は「授ける」ものなので、「やる」とは言わない。"}, {"text": "寺が貧しい人に慈悲をやった。", "explanation": "ここは〈施す〉の意味。慈悲は「施す」ものなので、「やる」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38390, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家の掃除は夕方までにやるしまいます。", "corrected_sentence": "家の掃除は夕方までにやってしまいます。", "error_description": "「〜てしまう」の前は て形の「やって」。辞書形の「やる」は「やるしまいます」とは続けられず、誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "やる", "is_correct": true, "explanation": "辞書形。「予定です」に続き、予定を表す。"}, {"text": "やろう", "is_correct": false, "explanation": "意向形で、「予定です」には続かない。"}, {"text": "やった", "is_correct": false, "explanation": "過去形で、これからの予定の文には合わない。"}, {"text": "やらなかった", "is_correct": false, "explanation": "過去の否定形で、予定の文には合わない。"}], "correct_form": "やる", "base_form": "やる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"やる": "辞書形。「予定です」に続き、予定を表す。", "やろう": "意向形で、「予定です」には続かない。", "やった": "過去形で、これからの予定の文には合わない。", "やらなかった": "過去の否定形で、予定の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38390, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日は朝から部屋の掃除をやりますた。", "corrected_sentence": "明日は朝から部屋の掃除をやります。", "error_description": "丁寧形は「やります」。過去の「やりました」と混同した「やりますた」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "やれる", "is_correct": true, "explanation": "可能形。「簡単にやれる」で、できるという意味になる。"}, {"text": "やれ", "is_correct": false, "explanation": "命令形で、可能の意味にならない。"}, {"text": "やります", "is_correct": false, "explanation": "丁寧形で、可能の意味にはならない。"}, {"text": "やれば", "is_correct": false, "explanation": "仮定形で、「できるなら」の意味になり、可能形とは違う。"}], "correct_form": "やれる", "base_form": "やる", "form_label": "可能形", "sentence_index": 7, "explanations": {"やれる": "可能形。「簡単にやれる」で、できるという意味になる。", "やれ": "命令形で、可能の意味にならない。", "やります": "丁寧形で、可能の意味にはならない。", "やれば": "仮定形で、「できるなら」の意味になり、可能形とは違う。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
