INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38392, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "まだ決まっていない間。今のところ。", "primary_collocate": null, "pronunciation": "とうぶん", "ipa": "toːbɯɴ", "syllable_count": 4, "sentences": [{"text": "次の予定はまだ決まっていないので、当分は家で待ちます。", "target_word": "当分", "complexity_tier": "T3", "furigana": "次[つぎ]の予定[よてい]はまだ決[き]まっていないので、当分[とうぶん]は家[いえ]で待[ま]ちます。", "sentence_source": "generated"}, {"text": "店の場所は決まっていないが、当分は兄の家で仕事をする。", "target_word": "当分", "complexity_tier": "T3", "furigana": "店[みせ]の場所[ばしょ]は決[き]まっていないが、当分[とうぶん]は兄[あに]の家[いえ]で仕事[しごと]をする。", "sentence_source": "generated"}, {"text": "新しい先生が来るまで、当分は田中先生が授業をします。", "target_word": "当分", "complexity_tier": "T3", "furigana": "新[あたら]しい先生[せんせい]が来[く]るまで、当分[とうぶん]は田中[たなか]先生[せんせい]が授業[じゅぎょう]をします。", "sentence_source": "generated"}, {"text": "引っ越し先が決まるまで、当分ホテルに泊まります。", "target_word": "当分", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]し先[さき]が決[き]まるまで、当分[とうぶん]ホテルに泊[と]まります。", "sentence_source": "generated"}, {"text": "会議の日はまだ決まっていません。当分は連絡を待ってください。", "target_word": "当分", "complexity_tier": "T3", "furigana": "会議[かいぎ]の日[ひ]はまだ決[き]まっていません。当分[とうぶん]は連絡[れんらく]を待[ま]ってください。", "sentence_source": "generated"}, {"text": "部長が決まるまで、当分の間、私が代わりをします。", "target_word": "当分", "complexity_tier": "T3", "furigana": "部長[ぶちょう]が決[き]まるまで、当分[とうぶん]の間[あいだ]、私[わたし]が代[か]わりをします。", "sentence_source": "generated"}, {"text": "新しい機械が届くまでは、当分、古いものを使うしかない。", "target_word": "当分", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]が届[とど]くまでは、当分[とうぶん]、古[ふる]いものを使[つか]うしかない。", "sentence_source": "generated"}, {"text": "試験の結果が出るまで、当分は何も決められません。", "target_word": "当分", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]が出[で]るまで、当分[とうぶん]は何[なに]も決[き]められません。", "sentence_source": "generated"}, {"text": "工事の日がまだわからないので、当分は車を駐車場に置いておきます。", "target_word": "当分", "complexity_tier": "T3", "furigana": "工事[こうじ]の日[ひ]がまだわからないので、当分[とうぶん]は車[くるま]を駐車場[ちゅうしゃじょう]に置[お]いておきます。", "sentence_source": "generated"}, {"text": "担当の人が決まるまで、当分は私が電話を受けます。", "target_word": "当分", "complexity_tier": "T3", "furigana": "担当[たんとう]の人[ひと]が決[き]まるまで、当分[とうぶん]は私[わたし]が電話[でんわ]を受[う]けます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "当分", "label": "基本形"}, {"form": "当分の間", "label": "連語形"}], "register": "neutral", "sense_fingerprint": "次のことが決まるまでの間、今のところ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38392, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当分", "is_correct": true, "explanation": "決まるまでの間という意味。次の予定がまだ決まっていない文脈に合う。"}, {"text": "昨日", "is_correct": false, "explanation": "過去の一日を表すので、これから待つ期間を表す文には合わない。"}, {"text": "突然", "is_correct": false, "explanation": "予告なしの出来事を表し、予定が決まるまで待つという説明に合わない。"}, {"text": "毎日", "is_correct": false, "explanation": "反復を表し、期間の見通しを示す文の意味と合わない。"}], "explanations": {"当分": "決まるまでの間という意味。次の予定がまだ決まっていない文脈に合う。", "昨日": "過去の一日を表すので、これから待つ期間を表す文には合わない。", "突然": "予告なしの出来事を表し、予定が決まるまで待つという説明に合わない。", "毎日": "反復を表し、期間の見通しを示す文の意味と合わない。"}, "sentence_index": 0, "correct_answer": "当分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当分の写真を見て、思い出に浸った。", "explanation": "ここは〈当時〉（その頃）と混同。当分は今のところの期間を表し、過去の時点を指す写真には使わない。"}, {"text": "ケーキを当分の大きさに切った。", "explanation": "ここは〈等分〉（同じ大きさに分ける）と混同。当分は期間を表す語で、大きさの意味にはならない。"}, {"text": "練習をしなかったので、負けたのは当分の結果だ。", "explanation": "ここは〈当然〉（もっともなこと）と混同。当分は時間の幅を表し、道理の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38392, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当分", "is_correct": true, "explanation": "届くまでの期間を表す。古いものを使うしかない期間を示すのに合う。"}, {"text": "同時に", "is_correct": false, "explanation": "同時を表す語で、期間を示す文には合わない。"}, {"text": "翌日", "is_correct": false, "explanation": "特定の一日を指すので、届くまでの期間を表す文には合わない。"}, {"text": "全然", "is_correct": false, "explanation": "打ち消しと一緒に使う語なので、肯定の「使うしかない」とは合わない。"}], "explanations": {"当分": "届くまでの期間を表す。古いものを使うしかない期間を示すのに合う。", "同時に": "同時を表す語で、期間を示す文には合わない。", "翌日": "特定の一日を指すので、届くまでの期間を表す文には合わない。", "全然": "打ち消しと一緒に使う語なので、肯定の「使うしかない」とは合わない。"}, "sentence_index": 6, "correct_answer": "当分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当分の立場から、この問題を考えてほしい。", "explanation": "ここは〈当事者〉（その件に関わる人）と混同。当分は時間の幅を表し、立場を指す語ではない。"}, {"text": "会計の当分は、私が引き受けた。", "explanation": "ここは〈担当〉（受け持つこと）と混同。当分は時間の幅を表し、仕事を受け持つ意味にはならない。"}, {"text": "当分の日に、私が教室を掃除する。", "explanation": "ここは〈当番〉（順番に務めること）と混同している。当分は仕事の順番を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38392, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい部長が決まるまで、当分に私が会議に出ます。", "corrected_sentence": "新しい部長が決まるまで、当分は私が会議に出ます。", "error_description": "「当分」の後に「は」を付けて主題を示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38392, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい店長が決まるまで、当分が私が店を開けます。", "corrected_sentence": "新しい店長が決まるまで、当分は私が店を開けます。", "error_description": "「当分」の後に「は」を付けて主題を示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
