INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38393, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "今のところ。しばらくの間。ある状態が続くことを表す副詞。", "primary_collocate": null, "pronunciation": "とうぶん", "ipa": "toːbɯɴ", "syllable_count": 4, "sentences": [{"text": "風邪がひどいので、当分は運動できません。", "target_word": "当分", "complexity_tier": "T3", "furigana": "風邪[かぜ]がひどいので、当分[とうぶん]は運動[うんどう]できません。", "sentence_source": "generated"}, {"text": "この寒さは、当分続くでしょう。", "target_word": "当分", "complexity_tier": "T3", "furigana": "この寒[さむ]さは、当分[とうぶん]続[つづ]くでしょう。", "sentence_source": "generated"}, {"text": "足を怪我したので、当分は歩くのが大変だ。", "target_word": "当分", "complexity_tier": "T3", "furigana": "足[あし]を怪我[けが]したので、当分[とうぶん]は歩[ある]くのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "先月たくさん買ったから、当分、米を買わなくてもいい。", "target_word": "当分", "complexity_tier": "T3", "furigana": "先月[せんげつ]たくさん買[か]ったから、当分[とうぶん]、米[こめ]を買[か]わなくてもいい。", "sentence_source": "generated"}, {"text": "雨の日が続いていて、当分は晴れそうにありません。", "target_word": "当分", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]が続[つづ]いていて、当分[とうぶん]は晴[は]れそうにありません。", "sentence_source": "generated"}, {"text": "給料が出たばかりなので、当分お金には困りません。", "target_word": "当分", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]が出[で]たばかりなので、当分[とうぶん]お金[かね]には困[こま]りません。", "sentence_source": "generated"}, {"text": "旅行から帰ったばかりで、当分どこにも行きたくない。", "target_word": "当分", "complexity_tier": "T3", "furigana": "旅行[りょこう]から帰[かえ]ったばかりで、当分[とうぶん]どこにも行[い]きたくない。", "sentence_source": "generated"}, {"text": "この仕事は忙しくて、当分休みが取れそうにない。", "target_word": "当分", "complexity_tier": "T3", "furigana": "この仕事[しごと]は忙[いそが]しくて、当分[とうぶん]休[やす]みが取[と]れそうにない。", "sentence_source": "generated"}, {"text": "大きな冷蔵庫を買ったので、当分食べ物の心配はありません。", "target_word": "当分", "complexity_tier": "T3", "furigana": "大[おお]きな冷蔵庫[れいぞうこ]を買[か]ったので、当分[とうぶん]食[た]べ物[もの]の心配[しんぱい]はありません。", "sentence_source": "generated"}, {"text": "彼は怒っているから、当分は話しかけないほうがいい。", "target_word": "当分", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[おこ]っているから、当分[とうぶん]は話[はな]しかけないほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "当分", "label": "基本形"}, {"form": "当分の間", "label": "連語形"}], "register": "neutral", "sense_fingerprint": "今の状態がしばらく続くことを表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38393, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当分", "is_correct": true, "explanation": "「当分は〜できない」で、今の状態が続く期間を表す。風邪が続く文脈に合う。"}, {"text": "昨夜", "is_correct": false, "explanation": "過去の一晩を表すので、今後続く状態には合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "たまたまの意味で、続く状態を表す文には合わない。"}, {"text": "真っ先に", "is_correct": false, "explanation": "最初に行う意味で、運動できない期間を表す文には合わない。"}], "explanations": {"当分": "「当分は〜できない」で、今の状態が続く期間を表す。風邪が続く文脈に合う。", "昨夜": "過去の一晩を表すので、今後続く状態には合わない。", "偶然": "たまたまの意味で、続く状態を表す文には合わない。", "真っ先に": "最初に行う意味で、運動できない期間を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "当分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪をひいたのは当分の結果だ。", "explanation": "ここは〈当然〉（もっともなこと）と混同。当分は状態が続く期間を表し、原因や道理には使わない。"}, {"text": "受付の当分は、私が引き受けた。", "explanation": "ここは〈担当〉（受け持つこと）と混同。当分は期間を表す語で、仕事を受け持つ意味にはならない。"}, {"text": "当分の日々、私はまだ子どもだった。", "explanation": "ここは〈当時〉（その頃）と混同。当分は今の状態の継続を表し、過去の時点を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38393, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当分", "is_correct": true, "explanation": "「当分どこにも行きたくない」で、今の気持ちが続く期間を表す。"}, {"text": "同時に", "is_correct": false, "explanation": "同時の意味で、今の気持ちが続く期間を表さない。"}, {"text": "翌日", "is_correct": false, "explanation": "特定の翌日を指し、気持ちが続く期間を表さない。"}, {"text": "大急ぎで", "is_correct": false, "explanation": "急いで行う意味で、行きたくない気持ちの文には合わない。"}], "explanations": {"当分": "「当分どこにも行きたくない」で、今の気持ちが続く期間を表す。", "同時に": "同時の意味で、今の気持ちが続く期間を表さない。", "翌日": "特定の翌日を指し、気持ちが続く期間を表さない。", "大急ぎで": "急いで行う意味で、行きたくない気持ちの文には合わない。"}, "sentence_index": 6, "correct_answer": "当分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当分の本人が、直接話をした。", "explanation": "ここは〈当事者〉（その件に関わる本人）と混同。当分は時間の幅を表し、人を指す語ではない。"}, {"text": "ケーキを当分の大きさに切った。", "explanation": "ここは〈等分〉（同じ大きさに分けること）と混同。当分は時間の幅を表す語で、分量には使わない。"}, {"text": "当分の日に、私が教室を掃除している。", "explanation": "ここは〈当番〉（順番に務めること）と混同している。当分は仕事の順番を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38393, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が続くので、当分が洗濯物を部屋で干します。", "corrected_sentence": "雨が続くので、当分は洗濯物を部屋で干します。", "error_description": "「当分」の後に「は」を付けて主題を示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38393, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天気が悪いので、当分に外出を控えます。", "corrected_sentence": "天気が悪いので、当分は外出を控えます。", "error_description": "「当分」の後に「は」を付けて主題を示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
