INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38394, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "じぶんのこと。", "primary_collocate": null, "pronunciation": "じしん", "ipa": "dʑiɕiɴ", "syllable_count": 3, "sentences": [{"text": "これは私自身の問題です。", "target_word": "自身", "complexity_tier": "T3", "furigana": "これは私自身(わたしじしん)の問題(もんだい)です。", "sentence_source": "generated"}, {"text": "この計画の是非は、自身の目で確かめてから決めたい。", "target_word": "自身", "complexity_tier": "T3", "furigana": "この計画[けいかく]の是非[ぜひ]は、自身[じしん]の目[め]で確[たし]かめてから決めたい。", "sentence_source": "generated"}, {"text": "その答えは、自身の言葉で説明してほしい。", "target_word": "自身", "complexity_tier": "T3", "furigana": "その答[こた]えは、自身[じしん]の言葉[ことば]で説明[せつめい]してほしい。", "sentence_source": "generated"}, {"text": "自身のことは、自分で決めたいです。", "target_word": "自身", "complexity_tier": "T3", "furigana": "自身(じしん)のことは、自分(じぶん)で決(き)めたいです。", "sentence_source": "generated"}, {"text": "彼は自身の失敗を、ごまかさずに認めた。", "target_word": "自身", "complexity_tier": "T3", "furigana": "彼[かれ]は自身[じしん]の失敗[しっぱい]を、ごまかさずに認[みと]めた。", "sentence_source": "generated"}, {"text": "弟は自身の力で、宿題を終わらせた。", "target_word": "自身", "complexity_tier": "T3", "furigana": "弟(おとうと)は自身(じしん)の力(ちから)で、宿題(しゅくだい)を終(お)わらせた。", "sentence_source": "generated"}, {"text": "自身の将来について、まだ考えがまとまらない。", "target_word": "自身", "complexity_tier": "T3", "furigana": "自身[じしん]の将来[しょうらい]について、まだ考[かんが]えがまとまらない。", "sentence_source": "generated"}, {"text": "子どもたちには、自身の持ち物を自分で管理するよう教えている。", "target_word": "自身", "complexity_tier": "T3", "furigana": "子[こ]どもたちには、自身[じしん]の持[も]ち物[もの]を自分[じぶん]で管理[かんり]するよう教[おし]えている。", "sentence_source": "generated"}, {"text": "彼女は、自身の夢について話してくれた。", "target_word": "自身", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は、自身(じしん)の夢(ゆめ)について話(はな)してくれた。", "sentence_source": "generated"}, {"text": "店長は自身の仕事ぶりを、毎日振り返っている。", "target_word": "自身", "complexity_tier": "T3", "furigana": "店長[てんちょう]は自身[じしん]の仕事[しごと]ぶりを、毎日[まいにち]振[ふ]り返[かえ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自身", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "「私自身」「彼自身」のように、じぶんのことを指す「自身」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38394, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自身", "is_correct": true, "explanation": "「私自身」で、自分であることを強める形になり、文が成り立つ。"}, {"text": "手段", "is_correct": false, "explanation": "「私手段」は成り立たず、この位置には入らない。"}, {"text": "行為", "is_correct": false, "explanation": "「私行為」は成り立たず、この位置には入らない。"}, {"text": "対話", "is_correct": false, "explanation": "「私対話」は成り立たず、この位置には入らない。"}], "explanations": {"自身": "「私自身」で、自分であることを強める形になり、文が成り立つ。", "手段": "「私手段」は成り立たず、この位置には入らない。", "行為": "「私行為」は成り立たず、この位置には入らない。", "対話": "「私対話」は成り立たず、この位置には入らない。"}, "sentence_index": 0, "correct_answer": "自身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は自身に満ちた笑顔で話した。", "explanation": "ここは〈自信〉（確信）の意味。〈自身〉は〈自分そのもの〉なので、〈自身に満ちた〉とは言わない。"}, {"text": "入学式で自身紹介をした。", "explanation": "ここは〈自己紹介〉という語。〈自身紹介〉とは言わない。"}, {"text": "受付で自身確認をする。", "explanation": "ここは〈本人確認〉の意味。〈自身確認〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38394, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自身", "is_correct": true, "explanation": "「自身の将来」で、本人の将来を指す形になり、文が成り立つ。"}, {"text": "性格", "is_correct": false, "explanation": "「性格の将来」は意味が成り立たず、この位置には合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢の将来」は意味が成り立たず、この位置には合わない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "「消しゴムの将来」は意味が成り立たず、この位置には合わない。"}], "explanations": {"自身": "「自身の将来」で、本人の将来を指す形になり、文が成り立つ。", "性格": "「性格の将来」は意味が成り立たず、この位置には合わない。", "年齢": "「年齢の将来」は意味が成り立たず、この位置には合わない。", "消しゴム": "「消しゴムの将来」は意味が成り立たず、この位置には合わない。"}, "sentence_index": 6, "correct_answer": "自身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は自身勝手で、周りの意見を聞かない。", "explanation": "ここは〈自分勝手〉という複合語。〈自身勝手〉とは言わない。"}, {"text": "寝る前に、自身の回りを片付けた。", "explanation": "ここは〈身の回り〉（周囲の持ち物）の意味。〈自身の回り〉とは言わない。"}, {"text": "それは自身責任だ。", "explanation": "ここは〈自己責任〉という複合語。〈自身責任〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38394, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このことは、私自身を責任です。", "corrected_sentence": "このことは、私自身の責任です。", "error_description": "名詞の「責任」に続けるには「私自身の責任」と「の」が必要。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38394, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私自身に準備を進めたい。", "corrected_sentence": "私自身で準備を進めたい。", "error_description": "「自身で」は「自分の力で」を表す。「に」は誤りで、正しくは「で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38395, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜にある」で帰属を示す。「私自身に」で原因がその人にあることを表す。"}, {"text": "が", "is_correct": false, "explanation": "「〜がある」では「私自身があると」となり、「原因は私自身にある」の形が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「ある」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「ある」は方向を取らないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「〜にある」で帰属を示す。「私自身に」で原因がその人にあることを表す。", "が": "「〜がある」では「私自身があると」となり、「原因は私自身にある」の形が成り立たない。", "を": "「を」は目的語を示すが、「ある」は目的語を取らないので合わない。", "へ": "「へ」は方向を示すが、「ある」は方向を取らないので合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38395, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38395, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分という人。自分自身。", "primary_collocate": null, "pronunciation": "じしん", "ipa": "dʑiɕiɴ", "syllable_count": 3, "sentences": [{"text": "私にとってこの行為は、自分自身と対話するための重要な手段なのだ。", "target_word": "自身", "complexity_tier": "T3", "furigana": "私(わたし)にとってこの行為(こうい)は、自分自身(じぶんじしん)と対話(たいわ)するための重要(じゅうよう)な手段(しゅだん)なのだ。", "sentence_source": "mined"}, {"text": "失敗の原因は、私自身にあると思います。", "target_word": "自身", "complexity_tier": "T3", "furigana": "失敗(しっぱい)の原因(げんいん)は、私自身(わたしじしん)にあると思(おも)います。", "sentence_source": "generated"}, {"text": "彼は自身の経験をもとに、本を書いた。", "target_word": "自身", "complexity_tier": "T3", "furigana": "彼(かれ)は自身(じしん)の経験(けいけん)をもとに、本(ほん)を書(か)いた。", "sentence_source": "generated"}, {"text": "社長自身が工場を見に行き、問題を確かめた。", "target_word": "自身", "complexity_tier": "T3", "furigana": "社長自身(しゃちょうじしん)が工場(こうじょう)を見(み)に行(い)き、問題(もんだい)を確(たし)かめた。", "sentence_source": "generated"}, {"text": "人のせいにせず、自身の行動を見直すことが大切だ。", "target_word": "自身", "complexity_tier": "T3", "furigana": "人(ひと)のせいにせず、自身(じしん)の行動(こうどう)を見直(みなお)すことが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "この問題は、子どもたち自身で解決させたい。", "target_word": "自身", "complexity_tier": "T3", "furigana": "この問題(もんだい)は、子(こ)どもたち自身(じしん)で解決(かいけつ)させたい。", "sentence_source": "generated"}, {"text": "医者自身が病気になってしまい、診察を休んだ。", "target_word": "自身", "complexity_tier": "T3", "furigana": "医者自身(いしゃじしん)が病気(びょうき)になってしまい、診察(しんさつ)を休(やす)んだ。", "sentence_source": "generated"}, {"text": "作者自身も、その物語の結末に驚いたそうだ。", "target_word": "自身", "complexity_tier": "T3", "furigana": "作者自身(さくしゃじしん)も、その物語(ものがたり)の結末(けつまつ)に驚(おどろ)いたそうだ。", "sentence_source": "generated"}, {"text": "他人の評価より、自身の納得を大切にしたい。", "target_word": "自身", "complexity_tier": "T3", "furigana": "他人(たにん)の評価(ひょうか)より、自身(じしん)の納得(なっとく)を大切(たいせつ)にしたい。", "sentence_source": "generated"}, {"text": "彼女は自身の弱さを認めて、少しずつ変わっていった。", "target_word": "自身", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は自身(じしん)の弱(よわ)さを認(みと)めて、少(すこ)しずつ変(か)わっていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自身", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人を表す語に付いて、その人本人であることを強調する「自身」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38395, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自身", "is_correct": true, "explanation": "「自分」を強める「自身」。「自分自身」の形になり、「自分と対話」の文が成り立つ。"}, {"text": "机", "is_correct": false, "explanation": "「自分机」は成り立たず、この位置には入らない。"}, {"text": "天気", "is_correct": false, "explanation": "「自分天気」は成り立たず、この位置には入らない。"}, {"text": "本棚", "is_correct": false, "explanation": "「自分本棚」は成り立たず、この位置には入らない。"}], "explanations": {"自身": "「自分」を強める「自身」。「自分自身」の形になり、「自分と対話」の文が成り立つ。", "机": "「自分机」は成り立たず、この位置には入らない。", "天気": "「自分天気」は成り立たず、この位置には入らない。", "本棚": "「自分本棚」は成り立たず、この位置には入らない。"}, "sentence_index": 0, "correct_answer": "自身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験の結果に自身がある。", "explanation": "ここは〈自信〉（確信）の場面。〈自身〉は〈自分そのもの〉を表すので、〈〜に自身がある〉とは言わない。"}, {"text": "自身中心的な考え方をする人は、周りが見えなくなりやすい。", "explanation": "ここは〈自己中心的〉という複合語。〈自身中心的〉とは言わない。"}, {"text": "寒さで自身の鼻が赤くなった。", "explanation": "ここは〈体の一部〉の場面。〈自身〉は〈自分という人〉を指すので、〈自身の鼻〉のように体の部分には言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38395, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自身", "is_correct": true, "explanation": "「医者自身」で、医者本人を強める形になり、文が成り立つ。"}, {"text": "患者", "is_correct": false, "explanation": "「医者患者」は成り立たず、この位置には入らない。"}, {"text": "性格", "is_correct": false, "explanation": "「医者性格」は成り立たず、この位置には入らない。"}, {"text": "年齢", "is_correct": false, "explanation": "「医者年齢」は成り立たず、この位置には入らない。"}], "explanations": {"自身": "「医者自身」で、医者本人を強める形になり、文が成り立つ。", "患者": "「医者患者」は成り立たず、この位置には入らない。", "性格": "「医者性格」は成り立たず、この位置には入らない。", "年齢": "「医者年齢」は成り立たず、この位置には入らない。"}, "sentence_index": 6, "correct_answer": "自身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は自身勝手で、周りの意見を聞かない。", "explanation": "ここは〈自分勝手〉という複合語。〈自身勝手〉とは言わない。"}, {"text": "空港で自身確認をする。", "explanation": "ここは〈本人確認〉の意味。〈自身確認〉とは言わない。"}, {"text": "寝る前に、自身の回りを片付けた。", "explanation": "ここは〈身の回り〉（周囲の持ち物）の意味。〈自身の回り〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38395, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その責任は、私自身がある。", "corrected_sentence": "その責任は、私自身にある。", "error_description": "「〜にある」は「に」で所在や帰属を受ける。「が」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38395, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この問題は、私自身に解決したい。", "corrected_sentence": "この問題は、私自身で解決したい。", "error_description": "「自身で」は「自分の力で」を表す。「に」では意味が成り立たず、正しくは「で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38396, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「先住の人々」で、先に住んでいた人々を修飾する連体の「の」。"}, {"text": "へ", "is_correct": false, "explanation": "「先住へ人々に」は方向の「へ」が挨拶の相手と重なり、先住も人々も正しく修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「先住を人々」は目的語の格で、直後の人々と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "「先住で人々」は場所や手段を表し、人々を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「先住の人々」で、先に住んでいた人々を修飾する連体の「の」。", "へ": "「先住へ人々に」は方向の「へ」が挨拶の相手と重なり、先住も人々も正しく修飾できない。", "を": "「先住を人々」は目的語の格で、直後の人々と結びつかない。", "で": "「先住で人々」は場所や手段を表し、人々を修飾できない。"}, "error_tags": {"へ": "方向", "を": "対格", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38396, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「先住の人」で、先に住んでいた人を修飾する連体の「の」。"}, {"text": "へ", "is_correct": false, "explanation": "「先住へ人」は方向を表し、人を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "「先住に人」は位置や相手を表し、人を修飾できず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「先住より人」は比較の格で、人が減る文の主語として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「先住の人」で、先に住んでいた人を修飾する連体の「の」。", "へ": "「先住へ人」は方向を表し、人を修飾できない。", "に": "「先住に人」は位置や相手を表し、人を修飾できず不自然。", "より": "「先住より人」は比較の格で、人が減る文の主語として成り立たない。"}, "error_tags": {"へ": "方向", "に": "位置・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38396, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある場所に初めから住んでいる人たちのこと。", "primary_collocate": null, "pronunciation": "せんじゅう", "ipa": "seɴdʑɯː", "syllable_count": 4, "sentences": [{"text": "この島には、先住の人たちが守ってきた祭りがある。", "target_word": "先住", "complexity_tier": "T3", "furigana": "この島[しま]には、先住[せんじゅう]の人[ひと]たちが守[まも]ってきた祭[まつ]りがある。", "sentence_source": "generated"}, {"text": "新しく来た住民は、先住の人々に挨拶をして回った。", "target_word": "先住", "complexity_tier": "T4", "furigana": "新[あたら]しく来[き]た住民[じゅうみん]は、先住[せんじゅう]の人々[ひとびと]に挨拶[あいさつ]をして回[まわ]った。", "sentence_source": "generated"}, {"text": "先住の人たちは、この谷で何百年も米を作ってきた。", "target_word": "先住", "complexity_tier": "T4", "furigana": "先住[せんじゅう]の人[ひと]たちは、この谷[たに]で何百年[なんびゃくねん]も米[こめ]を作[つく]ってきた。", "sentence_source": "generated"}, {"text": "川のそばの村では、先住の人々と移ってきた人々が助け合っている。", "target_word": "先住", "complexity_tier": "T4", "furigana": "川[かわ]のそばの村[むら]では、先住[せんじゅう]の人々[ひとびと]と移[うつ]ってきた人々[ひとびと]が助[たす]け合[あ]っている。", "sentence_source": "generated"}, {"text": "先住の人たちから、この土地の水の使い方を教わった。", "target_word": "先住", "complexity_tier": "T3", "furigana": "先住[せんじゅう]の人[ひと]たちから、この土地[とち]の水[みず]の使[つか]い方[かた]を教[おそ]わった。", "sentence_source": "generated"}, {"text": "山に道ができる前から、そこには先住の人々が暮らしていた。", "target_word": "先住", "complexity_tier": "T4", "furigana": "山[やま]に道[みち]ができる前[まえ]から、そこには先住[せんじゅう]の人々[ひとびと]が暮[く]らしていた。", "sentence_source": "generated"}, {"text": "町の歴史を知るために、先住の方々に話を聞いた。", "target_word": "先住", "complexity_tier": "T3", "furigana": "町[まち]の歴史[れきし]を知[し]るために、先住[せんじゅう]の方々[かたがた]に話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "先住の人が年々減って、村の祭りを続けるのが難しくなった。", "target_word": "先住", "complexity_tier": "T3", "furigana": "先住[せんじゅう]の人[ひと]が年々[ねんねん]減[へ]って、村[むら]の祭[まつ]りを続[つづ]けるのが難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "地図には、先住の人たちが使っていた古い道が残っている。", "target_word": "先住", "complexity_tier": "T3", "furigana": "地図[ちず]には、先住[せんじゅう]の人[ひと]たちが使[つか]っていた古[ふる]い道[みち]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "新しい家は、先住の人々の暮らしを壊さないように建てられた。", "target_word": "先住", "complexity_tier": "T4", "furigana": "新[あたら]しい家[いえ]は、先住[せんじゅう]の人々[ひとびと]の暮[く]らしを壊[こわ]さないように建[た]てられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "先住", "label": "基本形"}, {"form": "先住の", "label": "連体形（の）"}, {"form": "先住する", "label": "サ変動詞形"}, {"form": "先住した", "label": "た形"}], "register": "文章語（やや硬い書き言葉）", "sense_fingerprint": "村や島など、ある場所に先に住んでいた土地の人たち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38396, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先住", "is_correct": true, "explanation": "「土地に初めから住んでいた人々」の意味で、島の祭りを守ってきた人たちに合う。"}, {"text": "解説", "is_correct": false, "explanation": "「解説の人たち」は意味が通らない。解説は説明することで、人の属性を表さない。"}, {"text": "停電", "is_correct": false, "explanation": "「停電の人たち」は成り立たない。停電は電気が止まる現象で、人には付かない。"}, {"text": "祝日", "is_correct": false, "explanation": "「祝日の人たち」は意味をなさない。祝日は国が定めた休日のことで、人を修飾しない。"}], "explanations": {"先住": "「土地に初めから住んでいた人々」の意味で、島の祭りを守ってきた人たちに合う。", "解説": "「解説の人たち」は意味が通らない。解説は説明することで、人の属性を表さない。", "停電": "「停電の人たち」は成り立たない。停電は電気が止まる現象で、人には付かない。", "祝日": "「祝日の人たち」は意味をなさない。祝日は国が定めた休日のことで、人を修飾しない。"}, "sentence_index": 0, "correct_answer": "先住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新人の私に、先住の社員が仕事のやり方を丁寧に教えてくれた。", "explanation": "ここは〈先輩〉の意味。先住は土地に先に住んでいた人々を指し、職場の先輩には使わないので合わない。"}, {"text": "商談では、先住が新しい条件を三つ出してきた。", "explanation": "ここは〈先方〉（取引相手）の意味。先住は土地に先に住んでいた人々を指し、取引先の意味には使わないので合わない。"}, {"text": "彼は、先住の研究者たちが残した業績を丁寧に読み直した。", "explanation": "ここは〈先人〉の意味。先住は土地の先住者で、学問や分野の先達には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38396, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先住", "is_correct": true, "explanation": "「土地に先に住んでいた人々」の意味で、町の歴史を語る人々に合う。"}, {"text": "豪雨", "is_correct": false, "explanation": "「豪雨の方々」は意味をなさない。豪雨は激しい雨のことで、人を指さない。"}, {"text": "解約", "is_correct": false, "explanation": "「解約の方々」は成り立たない。解約は契約を終わらせることで、人には付かない。"}, {"text": "火災", "is_correct": false, "explanation": "「火災の方々」は意味が通らない。火災は火事のことで、人の属性を表さない。"}], "explanations": {"先住": "「土地に先に住んでいた人々」の意味で、町の歴史を語る人々に合う。", "豪雨": "「豪雨の方々」は意味をなさない。豪雨は激しい雨のことで、人を指さない。", "解約": "「解約の方々」は成り立たない。解約は契約を終わらせることで、人には付かない。", "火災": "「火災の方々」は意味が通らない。火災は火事のことで、人の属性を表さない。"}, "sentence_index": 6, "correct_answer": "先住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三年前、海外から先住の人たちが多くこの町に入ってきた。", "explanation": "ここは〈移民〉の意味。先住は既にその土地にいた人々を指し、後から来た人には使わないので合わない。"}, {"text": "取引の件では、先住の担当者が契約書の修正を求めてきた。", "explanation": "ここは〈先方〉（取引相手）の意味。先住は土地に先に住んでいた人々を指し、取引先の担当者には使わないので合わない。"}, {"text": "サークルの先住の部員が、新入生にフィルムカメラの使い方を教えた。", "explanation": "ここは〈古参〉の意味。先住は土地に昔から住んでいた人々を指し、サークルの古株の部員には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38396, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先住を人々が暮らした谷には、今も古い石垣が残っている。", "corrected_sentence": "先住の人々が暮らした谷には、今も古い石垣が残っている。", "error_description": "「先住の人々」と言うには「の」が必要。「を」は目的語を表すので、「先住」に直接付くと文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38396, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先住に人々が伝えた米作りの技は、今も村の祭りに受け継がれている。", "corrected_sentence": "先住の人々が伝えた米作りの技は、今も村の祭りに受け継がれている。", "error_description": "「先住の人々」の「の」が正しい。「に」にすると「先住に人々」となり、人々を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
