INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38397, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "その土地に昔から住んでいる人々。特に、外国から来た人たちが住む前にいた人々を指す。", "primary_collocate": null, "pronunciation": "せんじゅう", "ipa": "seɴdʑɯː", "syllable_count": 4, "sentences": [{"text": "先住の人々は、外国の船が来る前から海で魚をとっていた。", "target_word": "先住", "complexity_tier": "T4", "furigana": "先住[せんじゅう]の人々[ひとびと]は、外国[がいこく]の船[ふね]が来[く]る前[まえ]から海[うみ]で魚[さかな]をとっていた。", "sentence_source": "generated"}, {"text": "入植者が来た後、先住の人々は住み慣れた土地を失った。", "target_word": "先住", "complexity_tier": "T4", "furigana": "入植者[にゅうしょくしゃ]が来[き]た後[あと]、先住[せんじゅう]の人々[ひとびと]は住[す]み慣[な]れた土地[とち]を失[うしな]った。", "sentence_source": "generated"}, {"text": "政府は、先住の人々の言葉と文化を守る法律を作った。", "target_word": "先住", "complexity_tier": "T4", "furigana": "政府[せいふ]は、先住[せんじゅう]の人々[ひとびと]の言葉[ことば]と文化[ぶんか]を守[まも]る法律[ほうりつ]を作[つく]った。", "sentence_source": "generated"}, {"text": "博物館では、先住の人々が使った道具が展示されている。", "target_word": "先住", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、先住[せんじゅう]の人々[ひとびと]が使[つか]った道具[どうぐ]が展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "外国から来た人々は、先住の人々の土地を勝手に使った。", "target_word": "先住", "complexity_tier": "T4", "furigana": "外国[がいこく]から来[き]た人々[ひとびと]は、先住[せんじゅう]の人々[ひとびと]の土地[とち]を勝手[かって]に使[つか]った。", "sentence_source": "generated"}, {"text": "この国の先住の人々は、長い間独自の宗教を持っていた。", "target_word": "先住", "complexity_tier": "T4", "furigana": "この国[くに]の先住[せんじゅう]の人々[ひとびと]は、長[なが]い間[あいだ]独自[どくじ]の宗教[しゅうきょう]を持[も]っていた。", "sentence_source": "generated"}, {"text": "先住の人々の歴史を、学校で学ぶ機会が増えている。", "target_word": "先住", "complexity_tier": "T3", "furigana": "先住[せんじゅう]の人々[ひとびと]の歴史[れきし]を、学校[がっこう]で学[まな]ぶ機会[きかい]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "先住の人々は、移民が来る前の暮らしを歌で語り伝えている。", "target_word": "先住", "complexity_tier": "T4", "furigana": "先住[せんじゅう]の人々[ひとびと]は、移民[いみん]が来[く]る前[まえ]の暮[く]らしを歌[うた]で語[かた]り伝[つた]えている。", "sentence_source": "generated"}, {"text": "戦争の後、先住の人々の数は大きく減ってしまった。", "target_word": "先住", "complexity_tier": "T3", "furigana": "戦争[せんそう]の後[あと]、先住[せんじゅう]の人々[ひとびと]の数[かず]は大[おお]きく減[へ]ってしまった。", "sentence_source": "generated"}, {"text": "大統領は、先住の人々に対する過去の差別を謝罪した。", "target_word": "先住", "complexity_tier": "T4", "furigana": "大統領[だいとうりょう]は、先住[せんじゅう]の人々[ひとびと]に対[たい]する過去[かこ]の差別[さべつ]を謝罪[しゃざい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "先住", "label": "基本形"}, {"form": "先住の", "label": "連体形（の）"}, {"form": "先住する", "label": "サ変動詞形"}, {"form": "先住した", "label": "た形"}], "register": "文章語（やや硬い書き言葉）", "sense_fingerprint": "外国人や入植者が来る前から土地に住んでいた人々（歴史・社会の文脈）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38397, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先住", "is_correct": true, "explanation": "「先住の人々」で、外国の船より前から海にいた人々を指し、文脈に合う。"}, {"text": "豪雨", "is_correct": false, "explanation": "「豪雨の人々」は意味をなさない。豪雨は激しい雨で、人を修飾しない。"}, {"text": "解約", "is_correct": false, "explanation": "「解約の人々」は成り立たない。解約は契約を終わらせる行為で、人には付かない。"}, {"text": "火災", "is_correct": false, "explanation": "「火災の人々」は意味が通らない。火災は火事のことで、人の属性を表さない。"}], "explanations": {"先住": "「先住の人々」で、外国の船より前から海にいた人々を指し、文脈に合う。", "豪雨": "「豪雨の人々」は意味をなさない。豪雨は激しい雨で、人を修飾しない。", "解約": "「解約の人々」は成り立たない。解約は契約を終わらせる行為で、人には付かない。", "火災": "「火災の人々」は意味が通らない。火災は火事のことで、人の属性を表さない。"}, "sentence_index": 0, "correct_answer": "先住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先住の選手が今日は先発として出場し、試合の流れを作った。", "explanation": "ここは〈先発〉の意味。先住は土地に先に住んでいた人々を指し、試合の出場順は表さないので合わない。"}, {"text": "数年前、先住の人々が新しい土地へ入植した。", "explanation": "ここは〈入植者〉の意味。先住は既に土地に住んでいた人々で、後から移り住む行為の主語にはならないので合わない。"}, {"text": "先住の人々は、仕事を求めて二十年前にこの国へ移民してきた。", "explanation": "ここは〈移民〉の意味。先住はもともとその土地にいた人々を指し、外から移り住んだ人には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38397, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先住", "is_correct": true, "explanation": "「先住の人々の歴史」で、土地に先からいた人々の歴史を指し、文に合う。"}, {"text": "解説", "is_correct": false, "explanation": "「解説の人々の歴史」は意味が通らない。解説は説明のことで、人を表さない。"}, {"text": "停電", "is_correct": false, "explanation": "「停電の人々」は成り立たない。停電は電気が止まる現象で、人には付かない。"}, {"text": "祝日", "is_correct": false, "explanation": "「祝日の人々」は意味をなさない。祝日は休日のことで、人を修飾しない。"}], "explanations": {"先住": "「先住の人々の歴史」で、土地に先からいた人々の歴史を指し、文に合う。", "解説": "「解説の人々の歴史」は意味が通らない。解説は説明のことで、人を表さない。", "停電": "「停電の人々」は成り立たない。停電は電気が止まる現象で、人には付かない。", "祝日": "「祝日の人々」は意味をなさない。祝日は休日のことで、人を修飾しない。"}, "sentence_index": 6, "correct_answer": "先住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先住の担当者から、締め切りを一日早めると連絡があった。", "explanation": "ここは〈先方〉（取引相手）の意味。先住は土地に先に住んでいた人々を指し、取引先の担当者には使わないので合わない。"}, {"text": "彼女は日本のロボット研究の先住として知られている。", "explanation": "ここは〈先駆者〉の意味。先住は土地に昔から住む人々を指し、分野を切り開いた人の意味にはならないので合わない。"}, {"text": "バンドの先住のドラマーが、新曲のリズムを決めた。", "explanation": "ここは〈古参〉の意味。先住は土地に昔から住む人々を指し、長く在籍した仲間には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38397, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先住で人々が暮らしていた谷に、今は新しい町ができた。", "corrected_sentence": "先住の人々が暮らしていた谷に、今は新しい町ができた。", "error_description": "「先住の人々」の「の」が正しい。「で」は場所や手段を表すので、「先住で人々」とは続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38397, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先住を人々は、今も川の魚を大切に守っている。", "corrected_sentence": "先住の人々は、今も川の魚を大切に守っている。", "error_description": "「先住の人々」の「の」が正しい。「を」は目的語を表すので、「先住を人々は」では人々を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38398, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「雨期は」と、雨期を話題として示す「は」です。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、「六月から九月までだ」と続く文の形に合わず不自然です。"}, {"text": "に", "is_correct": false, "explanation": "時点の「に」は、期間を述べる文の主題には付かないので合いません。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」は、季節の範囲を述べる文には合いません。"}], "correct_answer": "は", "explanations": {"は": "正解。「雨期は」と、雨期を話題として示す「は」です。", "を": "目的語の「を」は、「六月から九月までだ」と続く文の形に合わず不自然です。", "に": "時点の「に」は、期間を述べる文の主題には付かないので合いません。", "で": "手段・場所の「で」は、季節の範囲を述べる文には合いません。"}, "error_tags": {"を": "目的語の助詞を誤り", "に": "時点の助詞を誤り", "で": "場所・手段の助詞を誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乾期", "is_correct": true, "explanation": "対義語。雨がたくさん降る季節と対になり、雨の少ない季節を指します。"}, {"text": "冬季", "is_correct": false, "explanation": "季節を表しますが、雨期の対義語ではありません。"}, {"text": "晩夏", "is_correct": false, "explanation": "夏の終わりを指すだけで、雨期と対になる語ではありません。"}, {"text": "積雪", "is_correct": false, "explanation": "雪の量を表す名詞で、季節を表す語ではありません。"}], "correct_answer": "乾期", "explanations": {"乾期": "対義語。雨がたくさん降る季節と対になり、雨の少ない季節を指します。", "冬季": "季節を表しますが、雨期の対義語ではありません。", "晩夏": "夏の終わりを指すだけで、雨期と対になる語ではありません。", "積雪": "雪の量を表す名詞で、季節を表す語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38398, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「雨期が長い年」の「が」は、雨期を主語として示します。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、性質を表す「長い」の文には合いません。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、「長い年」に続く動詞がなく、文が成り立ちません。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は、「長い年」の性質を示す文には合いません。"}], "correct_answer": "が", "explanations": {"が": "正解。「雨期が長い年」の「が」は、雨期を主語として示します。", "へ": "方向の「へ」は、性質を表す「長い」の文には合いません。", "を": "目的語の「を」は、「長い年」に続く動詞がなく、文が成り立ちません。", "から": "起点の「から」は、「長い年」の性質を示す文には合いません。"}, "error_tags": {"へ": "方向の助詞を誤り", "を": "目的語の助詞を誤り", "から": "起点の助詞を誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乾期", "is_correct": true, "explanation": "対義語。雨の多い季節と対になり、雨の少ない季節を指します。"}, {"text": "初雪", "is_correct": false, "explanation": "雪が初めて降ることで、季節を表す語ではありません。"}, {"text": "晩秋", "is_correct": false, "explanation": "秋の終わりを指すだけで、雨期と対になる語ではありません。"}, {"text": "猛暑", "is_correct": false, "explanation": "夏の厳しい暑さを表し、雨期の対義語ではありません。"}], "correct_answer": "乾期", "explanations": {"乾期": "対義語。雨の多い季節と対になり、雨の少ない季節を指します。", "初雪": "雪が初めて降ることで、季節を表す語ではありません。", "晩秋": "秋の終わりを指すだけで、雨期と対になる語ではありません。", "猛暑": "夏の厳しい暑さを表し、雨期の対義語ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38398, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "雨がたくさん降る季節のことです。", "primary_collocate": null, "pronunciation": "うき", "ipa": "ɯki", "syllable_count": 2, "sentences": [{"text": "雨期に入ると、毎日のように雨が降る。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]に入[はい]ると、毎日[まいにち]のように雨[あめ]が降[ふ]る。", "sentence_source": "generated"}, {"text": "この国の雨期は六月から九月までだ。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "この国[くに]の雨期[うき]は六月[ろくがつ]から九月[くがつ]までだ。", "sentence_source": "generated"}, {"text": "雨期になると、川の水が増えて危ない。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]になると、川[かわ]の水[みず]が増[ふ]えて危[あぶ]ない。", "sentence_source": "generated"}, {"text": "雨期が終わって、やっと青い空が見えた。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]が終[お]わって、やっと青[あお]い空[そら]が見[み]えた。", "sentence_source": "generated"}, {"text": "雨期は洗濯物が乾かないので困る。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]は洗濯物[せんたくもの]が乾[かわ]かないので困[こま]る。", "sentence_source": "generated"}, {"text": "東南アジアでは、雨期と乾期がはっきり分かれている。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "東南[とうなん]アジアでは、雨期[うき]と乾期[かんき]がはっきり分[わ]かれている。", "sentence_source": "generated"}, {"text": "雨期の前に、屋根を直しておいた。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]の前[まえ]に、屋根[やね]を直[なお]しておいた。", "sentence_source": "generated"}, {"text": "雨期が長い年は、野菜が高くなる。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]が長[なが]い年[とし]は、野菜[やさい]が高[たか]くなる。", "sentence_source": "generated"}, {"text": "雨期のあいだは、山道を歩かないほうがいい。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]のあいだは、山道[やまみち]を歩[ある]かないほうがいい。", "sentence_source": "generated"}, {"text": "雨期が始まる前に、傘を買っておこう。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]が始[はじ]まる前[まえ]に、傘[かさ]を買[か]っておこう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雨期", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "雨がたくさん降る季節（梅雨など）を指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38398, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨期", "is_correct": true, "explanation": "正解。「雨期に入る」は季節の始まりを表す自然な言い方です。"}, {"text": "日曜日", "is_correct": false, "explanation": "「日曜日に入る」は季節ではないので、毎日雨が降る期間の始まりとして成り立ちません。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は時期を表さないので、「入る」と合わず文が成り立ちません。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は時期ではないので、「入る」の対象にならず不自然です。"}], "explanations": {"雨期": "正解。「雨期に入る」は季節の始まりを表す自然な言い方です。", "日曜日": "「日曜日に入る」は季節ではないので、毎日雨が降る期間の始まりとして成り立ちません。", "辞書": "辞書は時期を表さないので、「入る」と合わず文が成り立ちません。", "鍵": "鍵は時期ではないので、「入る」の対象にならず不自然です。"}, "sentence_index": 0, "correct_answer": "雨期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨期は三十分で止んで、やっと青い空が見えた。", "explanation": "ここは〈夕立〉の意味です。夕立は短時間で止む雨ですが、雨期は数か月続く季節なので、三十分で止むとは言えません。"}, {"text": "雨期が一晩中降って、川が増水した。", "explanation": "ここは〈大雨〉の意味です。大雨は降る雨の量を指しますが、雨期は季節の名前で、降る雨そのものではないので「降る」の主語になりません。"}, {"text": "雨期が回復して、やっと青い空が見えた。", "explanation": "ここは〈天気〉の意味です。天気は回復するものですが、雨期は季節の期間なので、回復する対象にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38398, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨期", "is_correct": true, "explanation": "正解。「雨期の前に」と、季節の始まりを示します。"}, {"text": "財布", "is_correct": false, "explanation": "「財布の前に屋根を直す」は成り立たず、不自然です。"}, {"text": "切手", "is_correct": false, "explanation": "切手は時期ではないので、「の前に」と結び付きません。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は時期ではないので、文として不自然です。"}], "explanations": {"雨期": "正解。「雨期の前に」と、季節の始まりを示します。", "財布": "「財布の前に屋根を直す」は成り立たず、不自然です。", "切手": "切手は時期ではないので、「の前に」と結び付きません。", "座布団": "座布団は時期ではないので、文として不自然です。"}, "sentence_index": 6, "correct_answer": "雨期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨期によると、明日は晴れるそうだ。", "explanation": "ここは〈天気予報〉の意味です。天気予報は「によると」で情報源を示せますが、雨期は季節の名で、情報を伝えるものではありません。"}, {"text": "雨期が吹いて、洗濯物が飛んだ。", "explanation": "ここは〈風〉の意味です。風は吹くものですが、雨期は季節なので、吹く主語にはなりません。"}, {"text": "雨期が晴れて、景色が見えた。", "explanation": "ここは〈霧〉の意味です。霧は晴れるものですが、雨期は一定の期間を指す季節で、晴れる対象ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38398, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨期を始まると、毎日のように雨が降る。", "corrected_sentence": "雨期が始まると、毎日のように雨が降る。", "error_description": "「始まる」は主語に「が」を伴う自動詞なので、「雨期」の後は「が」が正しいです。「を」では文が成り立ちません。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38398, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨期が始まって前に、屋根を直しておこう。", "corrected_sentence": "雨期が始まる前に、屋根を直しておこう。", "error_description": "「始まる」の活用が誤りです。「始まって」は「前に」と続かず、辞書形の「始まる」が正しいです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
