INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38399, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "降水量が多い季節。通常、一年の中で特定の時期に集中して雨が降る期間を指す。", "primary_collocate": null, "pronunciation": "うき", "ipa": "ɯki", "syllable_count": 2, "sentences": [{"text": "この地域では、雨期に一年の雨の大半が降る。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、雨期[うき]に一年[いちねん]の雨[あめ]の大半[たいはん]が降[ふ]る。", "sentence_source": "generated"}, {"text": "雨期には降水量が急に増える。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]には降水量[こうすいりょう]が急[きゅう]に増[ふ]える。", "sentence_source": "generated"}, {"text": "雨期と乾期では、農業のやり方が変わる。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]と乾期[かんき]では、農業[のうぎょう]のやり方[かた]が変[か]わる。", "sentence_source": "generated"}, {"text": "雨期の最中は、道路が水につかることがある。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]の最中[さなか]は、道路[どうろ]が水[みず]につかることがある。", "sentence_source": "generated"}, {"text": "今年の雨期は例年より早く始まった。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "今年[ことし]の雨期[うき]は例年[れいねん]より早[はや]く始[はじ]まった。", "sentence_source": "generated"}, {"text": "雨期が来る前に、ダムの水を減らしておく。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]が来[く]る前[まえ]に、ダムの水[みず]を減[へ]らしておく。", "sentence_source": "generated"}, {"text": "雨期の降水量は、乾期の十倍以上になる。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]の降水量[こうすいりょう]は、乾期[かんき]の十倍[じゅうばい]以上[いじょう]になる。", "sentence_source": "generated"}, {"text": "雨期になると、田んぼに水を引く作業が始まる。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]になると、田[た]んぼに水[みず]を引[ひ]く作業[さぎょう]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "雨期を過ぎると、気温が上がって暑くなる。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]を過[す]ぎると、気温[きおん]が上[あ]がって暑[あつ]くなる。", "sentence_source": "generated"}, {"text": "雨期の終わりごろには、川の水位が最も高くなる。", "target_word": "雨期", "complexity_tier": "T3", "furigana": "雨期[うき]の終[お]わりごろには、川[かわ]の水位[すいい]が最[もっと]も高[たか]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雨期", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "一年の特定の時期に降水量が集中する期間（乾期と対になる気候上の区分）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38399, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨期", "is_correct": true, "explanation": "正解。「雨期に一年の雨の大半が降る」と、季節を表す語が入ります。"}, {"text": "財布", "is_correct": false, "explanation": "財布に雨が降るのは成り立たず、文として不自然です。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書に雨が降るのは成り立たず、文として不自然です。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵に雨が降るのは成り立たず、文として合いません。"}], "explanations": {"雨期": "正解。「雨期に一年の雨の大半が降る」と、季節を表す語が入ります。", "財布": "財布に雨が降るのは成り立たず、文として不自然です。", "辞書": "辞書に雨が降るのは成り立たず、文として不自然です。", "鍵": "鍵に雨が降るのは成り立たず、文として合いません。"}, "sentence_index": 0, "correct_answer": "雨期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨期が一時間だけ降って、道路が乾いた。", "explanation": "ここは〈通り雨〉の意味です。通り雨は短時間だけ降って止む雨ですが、雨期は数か月続く季節なので、一時間だけ降ることはありません。"}, {"text": "雨期が排水口に流れ込んだ。", "explanation": "ここは〈雨水〉の意味です。雨水は流れる水ですが、雨期は季節の名前で、流れる液体ではありません。"}, {"text": "雨期が鳴って、停電した。", "explanation": "ここは〈雷〉の意味です。雷は鳴るものですが、雨期は季節の期間で、音を出すものではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38399, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨期", "is_correct": true, "explanation": "正解。「雨期の降水量」と、季節を表す語が入ります。"}, {"text": "財布", "is_correct": false, "explanation": "財布に降水量はなく、文として成り立ちません。"}, {"text": "切手", "is_correct": false, "explanation": "切手に降水量はなく、不自然です。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団に降水量はなく、文として成り立ちません。"}], "explanations": {"雨期": "正解。「雨期の降水量」と、季節を表す語が入ります。", "財布": "財布に降水量はなく、文として成り立ちません。", "切手": "切手に降水量はなく、不自然です。", "座布団": "座布団に降水量はなく、文として成り立ちません。"}, "sentence_index": 6, "correct_answer": "雨期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨期が起きて、川の水位が最も高くなった。", "explanation": "ここは〈洪水〉の意味です。洪水は突然起きる出来事ですが、雨期は季節の期間なので「起きる」とは言えません。"}, {"text": "雨期を量って、川の水位を調べた。", "explanation": "ここは〈雨量〉の意味です。雨量は量るものですが、雨期は季節の期間なので、量る対象にはなりません。"}, {"text": "雨期が上昇して雲になる。", "explanation": "ここは〈水蒸気〉の意味です。水蒸気は上昇して雲になりますが、雨期は季節なので、上昇する物体の主語にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38399, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨期を最中には、川の水が増えることがある。", "corrected_sentence": "雨期の最中には、川の水が増えることがある。", "error_description": "「最中」は「雨期の最中」と「の」で結びます。「を」では意味が通りません。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38399, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨期に入るて、川の水位が上がる。", "corrected_sentence": "雨期に入ると、川の水位が上がる。", "error_description": "「入る」の活用が誤りです。「入るて」は接続が成り立たず、「入ると」が正しいです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
