INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38400, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "空から水が下に落ちることです。", "primary_collocate": null, "pronunciation": "ふる", "ipa": "ɸɯɾɯ", "syllable_count": 2, "sentences": [{"text": "朝から雨が降っているので、傘を持って出かけた。", "target_word": "降っている", "complexity_tier": "T3", "furigana": "朝[あさ]から雨[あめ]が降[ふ]っているので、傘[かさ]を持[も]って出[で]かけた。", "sentence_source": "generated"}, {"text": "明日は夕方から雨が降るでしょう。", "target_word": "降る", "complexity_tier": "T3", "furigana": "明日[あした]は夕方[ゆうがた]から雨[あめ]が降[ふ]るでしょう。", "sentence_source": "generated"}, {"text": "昨夜、強い雨が降ったため、川の水が増えた。", "target_word": "降った", "complexity_tier": "T3", "furigana": "昨夜[さくや]、強[つよ]い雨[あめ]が降[ふ]ったため、川[かわ]の水[みず]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "空から冷たい水が降ってきて、顔がぬれた。", "target_word": "降ってきて", "complexity_tier": "T3", "furigana": "空[そら]から冷[つめ]たい水[みず]が降[ふ]ってきて、顔[かお]がぬれた。", "sentence_source": "generated"}, {"text": "雨が降らないので、畑の土がかわいている。", "target_word": "降らない", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らないので、畑[はたけ]の土[つち]がかわいている。", "sentence_source": "generated"}, {"text": "夏の午後は、急に雨が降ることがある。", "target_word": "降る", "complexity_tier": "T3", "furigana": "夏[なつ]の午後[ごご]は、急[きゅう]に雨[あめ]が降[ふ]ることがある。", "sentence_source": "generated"}, {"text": "雨が降ったら、運動会は教室で行います。", "target_word": "降ったら", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったら、運動会[うんどうかい]は教室[きょうしつ]で行[おこな]います。", "sentence_source": "generated"}, {"text": "ここは一年中ほとんど雨が降らない地域だ。", "target_word": "降らない", "complexity_tier": "T3", "furigana": "ここは一年中[いちねんじゅう]ほとんど雨[あめ]が降[ふ]らない地域[ちいき]だ。", "sentence_source": "generated"}, {"text": "山の上は、霧のような細かい雨が降る日が続いた。", "target_word": "降る", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は、霧[きり]のような細[こま]かい雨[あめ]が降[ふ]る日[ひ]が続[つづ]いた。", "sentence_source": "generated"}, {"text": "雨が降るとき、私は窓のそばで音を聞くのが好きだ。", "target_word": "降る", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]るとき、私[わたし]は窓[まど]のそばで音[おと]を聞[き]くのが好[す]きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "降る", "label": "辞書形"}, {"form": "降ります", "label": "丁寧形"}, {"form": "降らない", "label": "否定形"}, {"form": "降った", "label": "過去形"}, {"form": "降って", "label": "て形"}, {"form": "降れば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "空から水が落ちる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38400, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降っている", "is_correct": true, "explanation": "「雨が降っているので」の形で、今まさに雨が降っている状態を理由として表す。"}, {"text": "降って", "is_correct": false, "explanation": "て形のままでは「ので」に続かず、文が成り立たない。"}, {"text": "降ってきて", "is_correct": false, "explanation": "て形のため「ので」に続かず、不自然になる。"}, {"text": "降れば", "is_correct": false, "explanation": "仮定形では「ので」と続けられず、文が成り立たない。"}], "explanations": {"降っている": "「雨が降っているので」の形で、今まさに雨が降っている状態を理由として表す。", "降って": "て形のままでは「ので」に続かず、文が成り立たない。", "降ってきて": "て形のため「ので」に続かず、不自然になる。", "降れば": "仮定形では「ので」と続けられず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "降っている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は三階から階段を降った。", "explanation": "ここは〈降りる〉の意味。階段を下りる動作は降りると言い、「降る」は空から落ちる雨や雪に使う。"}, {"text": "コップに水を降った。", "explanation": "ここは〈注ぐ〉の意味。容器に液体を入れる動作は注ぐと言い、「降る」は使わない。"}, {"text": "窓のカーテンを降った。", "explanation": "ここは〈下げる〉の意味。カーテンを下へ動かすのは下げると言い、「降る」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38400, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降ったら", "is_correct": true, "explanation": "「雨が降ったら」の形で、条件を表して後ろの文に続く。"}, {"text": "降らせたら", "is_correct": false, "explanation": "使役形で、主語の「雨が」と合わない。"}, {"text": "降ろしたら", "is_correct": false, "explanation": "物を下ろす意味で、雨には使わない。"}, {"text": "降らされたら", "is_correct": false, "explanation": "使役受身は人に使うので、雨には使わない。"}], "explanations": {"降ったら": "「雨が降ったら」の形で、条件を表して後ろの文に続く。", "降らせたら": "使役形で、主語の「雨が」と合わない。", "降ろしたら": "物を下ろす意味で、雨には使わない。", "降らされたら": "使役受身は人に使うので、雨には使わない。"}, "sentence_index": 6, "correct_answer": "降ったら"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭に種を降った。", "explanation": "ここは〈撒く〉の意味。種を地面にまく動作は撒くと言い、「降る」は空から落ちる雨や雪に使う。"}, {"text": "釣り糸を降った。", "explanation": "ここは〈垂らす〉の意味。糸などを下へたらす動作は垂らすと言い、「降る」は使わない。"}, {"text": "トラックから荷物を降った。", "explanation": "ここは〈降ろす〉の意味。荷物を車から下ろす動作は降ろすと言い、「降る」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38400, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼ごろから雨が降ったに、試合は中止になった。", "corrected_sentence": "昼ごろから雨が降ったので、試合は中止になった。", "error_description": "助詞の誤り。「降ったに」の後に理由を示すには「ので」を使う。「に」は場所や時点を表し、理由にはならない（正：ので）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "降る", "is_correct": true, "explanation": "「明日は夕方から雨が降るでしょう」の辞書形で、未来の予測を表す。"}, {"text": "降って", "is_correct": false, "explanation": "て形では「降ってでしょう」となり、成り立たない。"}, {"text": "降れば", "is_correct": false, "explanation": "仮定形では「降ればでしょう」となり、不自然になる。"}, {"text": "降ります", "is_correct": false, "explanation": "丁寧形では「降りますでしょう」となり、「でしょう」と続かない。"}], "correct_form": "降る", "base_form": "降る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"降る": "「明日は夕方から雨が降るでしょう」の辞書形で、未来の予測を表す。", "降って": "て形では「降ってでしょう」となり、成り立たない。", "降れば": "仮定形では「降ればでしょう」となり、不自然になる。", "降ります": "丁寧形では「降りますでしょう」となり、「でしょう」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38400, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨が降らないを、畑の土が乾いた。", "corrected_sentence": "雨が降らないので、畑の土が乾いた。", "error_description": "助詞の誤り。「降らない」の後で理由を示すには「ので」を使う。「を」は目的語を示すため、動詞の後に付けると文が成り立たない（正：ので）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "降らない", "is_correct": true, "explanation": "「降らない地域」の否定の辞書形で、名詞「地域」を修飾し「ほとんど雨が降らない」と続く。"}, {"text": "降らず", "is_correct": false, "explanation": "連用形の否定で、名詞「地域」を直接修飾できない。"}, {"text": "降れ", "is_correct": false, "explanation": "命令形で、名詞「地域」を修飾できない。"}, {"text": "降らせる", "is_correct": false, "explanation": "使役形で「雨を降らせる」の形になり、主語の「雨が」と合わず、「降らせる地域」は成り立たない。"}], "correct_form": "降らない", "base_form": "降る", "form_label": "否定形", "sentence_index": 7, "explanations": {"降らない": "「降らない地域」の否定の辞書形で、名詞「地域」を修飾し「ほとんど雨が降らない」と続く。", "降らず": "連用形の否定で、名詞「地域」を直接修飾できない。", "降れ": "命令形で、名詞「地域」を修飾できない。", "降らせる": "使役形で「雨を降らせる」の形になり、主語の「雨が」と合わず、「降らせる地域」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
