INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38401, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "雨や雪などが空から下に落ちてくる。", "primary_collocate": null, "pronunciation": "ふる", "ipa": "ɸɯɾɯ", "syllable_count": 2, "sentences": [{"text": "夜になって雪が降ってきたので、散歩をやめた。", "target_word": "降ってきた", "complexity_tier": "T3", "furigana": "夜[よる]になって雪[ゆき]が降[ふ]ってきたので、散歩[さんぽ]をやめた。", "sentence_source": "generated"}, {"text": "北の町では、十一月から雪が降る。", "target_word": "降る", "complexity_tier": "T3", "furigana": "北[きた]の町[まち]では、十一月[じゅういちがつ]から雪[ゆき]が降[ふ]る。", "sentence_source": "generated"}, {"text": "雨が降る前に、洗濯物を中に入れた。", "target_word": "降る", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る前[まえ]に、洗濯物[せんたくもの]を中[なか]に入[い]れた。", "sentence_source": "generated"}, {"text": "一晩中雪が降って、朝には道が真っ白だった。", "target_word": "降って", "complexity_tier": "T3", "furigana": "一晩中[ひとばんじゅう]雪[ゆき]が降[ふ]って、朝[あさ]には道[みち]が真[ま]っ白[しろ]だった。", "sentence_source": "generated"}, {"text": "梅雨の時期は、毎日のように雨が降ります。", "target_word": "降ります", "complexity_tier": "T3", "furigana": "梅雨[つゆ]の時期[じき]は、毎日[まいにち]のように雨[あめ]が降[ふ]ります。", "sentence_source": "generated"}, {"text": "雪が降ると、子どもたちは外で遊びたがる。", "target_word": "降る", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]ると、子[こ]どもたちは外[そと]で遊[あそ]びたがる。", "sentence_source": "generated"}, {"text": "今年は雨があまり降らなかったので、水が足りない。", "target_word": "降らなかった", "complexity_tier": "T3", "furigana": "今年[ことし]は雨[あめ]があまり降[ふ]らなかったので、水[みず]が足[た]りない。", "sentence_source": "generated"}, {"text": "雪が降っているのに、彼は薄いコートで出かけた。", "target_word": "降っている", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]っているのに、彼[かれ]は薄[うす]いコートで出[で]かけた。", "sentence_source": "generated"}, {"text": "天気予報によると、午後から雨が降るそうだ。", "target_word": "降る", "complexity_tier": "T3", "furigana": "天気[てんき]予報[よほう]によると、午後[ごご]から雨[あめ]が降[ふ]るそうだ。", "sentence_source": "generated"}, {"text": "雪が降った日は、電車が遅れやすい。", "target_word": "降った", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]った日[ひ]は、電車[でんしゃ]が遅[おく]れやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "降る", "label": "辞書形"}, {"form": "降ります", "label": "丁寧形"}, {"form": "降らない", "label": "否定形"}, {"form": "降った", "label": "過去形"}, {"form": "降って", "label": "て形"}, {"form": "降れば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "雨や雪などが空から落ちてくる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38401, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降ってきた", "is_correct": true, "explanation": "「雪が降ってきたので」の形で、雪が降り始めた事実を理由として表す。"}, {"text": "降って", "is_correct": false, "explanation": "て形のままでは「ので」に続かず、文が成り立たない。"}, {"text": "降れば", "is_correct": false, "explanation": "仮定形では「ので」に続けられず、不自然になる。"}, {"text": "降ってきて", "is_correct": false, "explanation": "て形のため「ので」に続かず、文が成り立たない。"}], "explanations": {"降ってきた": "「雪が降ってきたので」の形で、雪が降り始めた事実を理由として表す。", "降って": "て形のままでは「ので」に続かず、文が成り立たない。", "降れば": "仮定形では「ので」に続けられず、不自然になる。", "降ってきて": "て形のため「ので」に続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "降ってきた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅で電車を降った。", "explanation": "ここは〈降りる〉の意味。乗り物から降りる動作は降りると言い、「降る」は空からの現象に使う。"}, {"text": "旗を降った。", "explanation": "ここは〈下げる〉の意味。旗を下へ動かすのは下げると言い、「降る」は使わない。"}, {"text": "財布を降った。", "explanation": "ここは〈落とす〉の意味。物を落とす動作は落とすと言い、「降る」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38401, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降らなかった", "is_correct": true, "explanation": "「雨があまり降らなかったので」の否定の過去形で、雨が少なかった事実を表す。"}, {"text": "降らせた", "is_correct": false, "explanation": "使役形で、「雨が降らせた」は主語と合わない。"}, {"text": "降ろした", "is_correct": false, "explanation": "物を下ろす意味で、雨には使わない。"}, {"text": "降りた", "is_correct": false, "explanation": "乗り物などから降りる意味で、雨には使わない。"}], "explanations": {"降らなかった": "「雨があまり降らなかったので」の否定の過去形で、雨が少なかった事実を表す。", "降らせた": "使役形で、「雨が降らせた」は主語と合わない。", "降ろした": "物を下ろす意味で、雨には使わない。", "降りた": "乗り物などから降りる意味で、雨には使わない。"}, "sentence_index": 6, "correct_answer": "降らなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍋に出汁を降った。", "explanation": "ここは〈注ぐ〉の意味。液体を器に入れる動作は注ぐと言い、「降る」は空からの現象に使う。"}, {"text": "崖にロープを降った。", "explanation": "ここは〈垂らす〉の意味。ロープなどを下へたらす動作は垂らすと言い、「降る」は使わない。"}, {"text": "車からベビーカーを降った。", "explanation": "ここは〈降ろす〉の意味。物を車から下ろす動作は降ろすと言い、「降る」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38401, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜になって雪が降ってきたに、散歩を取りやめた。", "corrected_sentence": "夜になって雪が降ってきたので、散歩を取りやめた。", "error_description": "助詞の誤り。「降ってきた」の後に理由を示すには「ので」を使う。「に」は場所や時点を表し、理由にはならない（正：ので）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "降る", "is_correct": true, "explanation": "「十一月から雪が降る」の辞書形で、習慣的な事実を表す。"}, {"text": "降って", "is_correct": false, "explanation": "て形では「雪が降って。」と文が終わらず、成り立たない。"}, {"text": "降れば", "is_correct": false, "explanation": "仮定形では文末にならず、事実を述べる文には合わない。"}, {"text": "降れ", "is_correct": false, "explanation": "命令形で、事実を述べる文には合わない。"}], "correct_form": "降る", "base_form": "降る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"降る": "「十一月から雪が降る」の辞書形で、習慣的な事実を表す。", "降って": "て形では「雪が降って。」と文が終わらず、成り立たない。", "降れば": "仮定形では文末にならず、事実を述べる文には合わない。", "降れ": "命令形で、事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38401, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年は雨があまり降ったので、田んぼの水が足りない。", "corrected_sentence": "今年は雨があまり降らなかったので、田んぼの水が足りない。", "error_description": "形の誤り。「あまり」は後に否定を伴うため、否定形「降らなかった」にする必要がある。「降った」では不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "降っている", "is_correct": true, "explanation": "「雪が降っているのに」の進行形で、今まさに雪が降っている状態を表す。"}, {"text": "降ります", "is_correct": false, "explanation": "丁寧形では「降りますのに」と続かず、不自然になる。"}, {"text": "降らせて", "is_correct": false, "explanation": "使役形で、主語「雪が」と合わず、文が成り立たない。"}, {"text": "降ろして", "is_correct": false, "explanation": "他動詞の「降ろす」で、主語の「雪が」と合わず文が成り立たない。"}], "correct_form": "降っている", "base_form": "降る", "form_label": "進行形（〜ている）", "sentence_index": 7, "explanations": {"降っている": "「雪が降っているのに」の進行形で、今まさに雪が降っている状態を表す。", "降ります": "丁寧形では「降りますのに」と続かず、不自然になる。", "降らせて": "使役形で、主語「雪が」と合わず、文が成り立たない。", "降ろして": "他動詞の「降ろす」で、主語の「雪が」と合わず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
