INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38402, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「カナートが古くなって」と主語を示す「が」。カナートが主語の文として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、古くなるのは自動詞的な変化で、ここでは合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点や相手を示すが、ここでは主語を表す必要があるので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここでは主語として使えないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「カナートが古くなって」と主語を示す「が」。カナートが主語の文として正しい。", "を": "「を」は目的語を示すが、古くなるのは自動詞的な変化で、ここでは合わない。", "に": "「に」は帰着点や相手を示すが、ここでは主語を表す必要があるので合わない。", "へ": "「へ」は方向を示すが、ここでは主語として使えないので合わない。"}, "error_tags": {"を": "目的語", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38402, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地下に作られた水路で、水を遠くへ運ぶ昔からの施設。", "primary_collocate": null, "pronunciation": "かなーと", "ipa": "kanaːto", "syllable_count": 4, "sentences": [{"text": "砂漠の国には、水を運ぶカナートという地下の水路があります。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "砂漠[さばく]の国[くに]には、水[みず]を運[はこ]ぶカナートという地下[ちか]の水路[すいろ]があります。", "sentence_source": "generated"}, {"text": "カナートは地下を通るので、水が太陽で蒸発しにくいです。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートは地下[ちか]を通[とお]るので、水[みず]が太陽[たいよう]で蒸発[じょうはつ]しにくいです。", "sentence_source": "generated"}, {"text": "イランでは、昔から山の水を村までカナートで運んできました。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "イランでは、昔[むかし]から山[やま]の水[みず]を村[むら]までカナートで運[はこ]んできました。", "sentence_source": "generated"}, {"text": "カナートを見学するために、乾燥した村を訪ねました。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートを見学[けんがく]するために、乾燥[かんそう]した村[むら]を訪[たず]ねました。", "sentence_source": "generated"}, {"text": "村の人たちは、カナートの掃除を毎年みんなでします。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "村[むら]の人[ひと]たちは、カナートの掃除[そうじ]を毎年[まいとし]みんなでします。", "sentence_source": "generated"}, {"text": "カナートの出口から、冷たくてきれいな水が流れてきます。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートの出口[でぐち]から、冷[つめ]たくてきれいな水[みず]が流[なが]れてきます。", "sentence_source": "generated"}, {"text": "地下に作ったカナートのおかげで、砂漠の畑でも野菜が育ちます。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "地下[ちか]に作[つく]ったカナートのおかげで、砂漠[さばく]の畑[はたけ]でも野菜[やさい]が育[そだ]ちます。", "sentence_source": "generated"}, {"text": "カナートが古くなって、流れる水の量が少なくなりました。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートが古[ふる]くなって、流[なが]れる水[みず]の量[りょう]が少[すく]なくなりました。", "sentence_source": "generated"}, {"text": "先生は、カナートの仕組みを図で説明してくれました。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "先生[せんせい]は、カナートの仕組[しく]みを図[ず]で説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "カナートを作るには、地面に深い穴をたくさん掘らなければなりません。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートを作[つく]るには、地面[じめん]に深[ふか]い穴[あな]をたくさん掘[ほ]らなければなりません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カナート", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "水を地下で運ぶ昔の水路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38402, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カナート", "is_correct": true, "explanation": "「水を運ぶカナートという地下の水路」と続き、定義どおりの地下水路を指す。"}, {"text": "ロバ", "is_correct": false, "explanation": "「ロバ」は動物で、水を運ぶ地下の水路の名前にはならない。"}, {"text": "ヤシ", "is_correct": false, "explanation": "「ヤシ」は植物で、地下の水路を指す語ではないので合わない。"}, {"text": "砂丘", "is_correct": false, "explanation": "「砂丘」は砂の丘を指し、地下の水路を表すものではないので合わない。"}], "explanations": {"カナート": "「水を運ぶカナートという地下の水路」と続き、定義どおりの地下水路を指す。", "ロバ": "「ロバ」は動物で、水を運ぶ地下の水路の名前にはならない。", "ヤシ": "「ヤシ」は植物で、地下の水路を指す語ではないので合わない。", "砂丘": "「砂丘」は砂の丘を指し、地下の水路を表すものではないので合わない。"}, "sentence_index": 0, "correct_answer": "カナート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "高いカナートに登りました。", "explanation": "ここは〈山〉の意味。カナートは地下の水路なので、登る対象にはならない。"}, {"text": "カナートを聞きました。", "explanation": "ここは〈ラジオ〉の意味。カナートは音を出さないので、「聞く」対象ではない。"}, {"text": "カナートを広げました。", "explanation": "ここは〈地図〉の意味。カナートは紙ではないので、「広げる」ものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38402, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カナート", "is_correct": true, "explanation": "「地下に作ったカナートのおかげで」と続き、地下に作られた水路として自然に合う。"}, {"text": "風呂", "is_correct": false, "explanation": "「地下に作った風呂」は水路ではなく、畑の野菜を育てる働きとも結びつかない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "「洗濯機」は家電で、地下に作って畑の水を運ぶ施設にはならない。"}, {"text": "金庫", "is_correct": false, "explanation": "「金庫」は貴重品を入れる箱で、畑の野菜を育てる働きとは関係しない。"}], "explanations": {"カナート": "「地下に作ったカナートのおかげで」と続き、地下に作られた水路として自然に合う。", "風呂": "「地下に作った風呂」は水路ではなく、畑の野菜を育てる働きとも結びつかない。", "洗濯機": "「洗濯機」は家電で、地下に作って畑の水を運ぶ施設にはならない。", "金庫": "「金庫」は貴重品を入れる箱で、畑の野菜を育てる働きとは関係しない。"}, "sentence_index": 6, "correct_answer": "カナート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カナートを一ページずつめくりました。", "explanation": "ここは〈本〉の意味。カナートは地下の水路なので、ページをめくって読むものではない。"}, {"text": "カナートを投げました。", "explanation": "ここは〈ボール〉の意味。カナートは投げられる物ではないので、「投げる」とは合わない。"}, {"text": "カナートで合格しました。", "explanation": "ここは〈試験〉の意味。カナートは試験ではないので、「合格」の場所や手段にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38402, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村の人たちは、毎年みんなでカナートに掃除をします。", "corrected_sentence": "村の人たちは、毎年みんなでカナートの掃除をします。", "error_description": "助詞の誤り。「カナートの掃除」と「の」で名詞をつなぐ必要がある。「に」では方向や相手になり、掃除の対象として合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38402, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔は、人の手でカナートに掘らなくてはいけませんでした。", "corrected_sentence": "昔は、人の手でカナートを掘らなくてはいけませんでした。", "error_description": "助詞の誤り。「掘る」の対象は「を」で示す。「に」では対象にならず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38403, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は手段を示す。カナートによって水を町まで引く、という文になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点を示すが、「引く」の手段とは結びつかず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、すでに「水を」があるので二重になり合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、水を引く手段としては成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「で」は手段を示す。カナートによって水を町まで引く、という文になる。", "に": "「に」は帰着点を示すが、「引く」の手段とは結びつかず、文が成り立たない。", "を": "「を」は目的語を示すが、すでに「水を」があるので二重になり合わない。", "と": "「と」は相手や並列を示すが、水を引く手段としては成り立たない。"}, "error_tags": {"に": "相手・帰着点", "を": "目的語", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38403, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「カナートの水」と所属を示す「の」。カナートから得られる水を指す文として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すが、水の所属を表せないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、水の所属を表す意味にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここでは水の所属を表せないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「カナートの水」と所属を示す「の」。カナートから得られる水を指す文として正しい。", "に": "「に」は方向や相手を示すが、水の所属を表せないので合わない。", "へ": "「へ」は方向を示すが、水の所属を表す意味にはならない。", "より": "「より」は比較を示すが、ここでは水の所属を表せないので合わない。"}, "error_tags": {"に": "相手・帰着点", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38403, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地下に作られた水路で、水を蒸発させずに遠くへ運ぶための伝統的な施設。", "primary_collocate": null, "pronunciation": "かなーと", "ipa": "kanaːto", "syllable_count": 4, "sentences": [{"text": "カナートは、水を蒸発させずに遠くまで運ぶ、昔からの施設です。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートは、水[みず]を蒸発[じょうはつ]させずに遠[とお]くまで運[はこ]ぶ、昔[むかし]からの施設[しせつ]です。", "sentence_source": "generated"}, {"text": "山のふもとの水を、カナートで町まで引いています。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "山[やま]のふもとの水[みず]を、カナートで町[まち]まで引[ひ]いています。", "sentence_source": "generated"}, {"text": "カナートが長い距離でも水を運べるのは、地面が少しずつ低くなっているからです。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートが長[なが]い距離[きょり]でも水[みず]を運[はこ]べるのは、地面[じめん]が少[すこ]しずつ低[ひく]くなっているからです。", "sentence_source": "generated"}, {"text": "乾燥した地域では、カナートが生活用水を支えてきました。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した地域[ちいき]では、カナートが生活用水[せいかつようすい]を支[ささ]えてきました。", "sentence_source": "generated"}, {"text": "世界遺産に登録されたカナートが、イランにあります。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "世界遺産[せかいいさん]に登録[とうろく]されたカナートが、イランにあります。", "sentence_source": "generated"}, {"text": "カナートの工事は、昔はとても危険な仕事でした。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートの工事[こうじ]は、昔[むかし]はとても危険[きけん]な仕事[しごと]でした。", "sentence_source": "generated"}, {"text": "機械のない時代に、人の手でカナートを掘りました。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "機械[きかい]のない時代[じだい]に、人[ひと]の手[て]でカナートを掘[ほ]りました。", "sentence_source": "generated"}, {"text": "カナートの水は、飲み水や畑の水に使われます。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートの水[みず]は、飲[の]み水[みず]や畑[はたけ]の水[みず]に使[つか]われます。", "sentence_source": "generated"}, {"text": "ポンプが増えて、カナートを使う村が少なくなりました。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "ポンプが増[ふ]えて、カナートを使[つか]う村[むら]が少[すく]なくなりました。", "sentence_source": "generated"}, {"text": "カナートは地下に作られているので、砂嵐の日でも水が汚れにくいです。", "target_word": "カナート", "complexity_tier": "T3", "furigana": "カナートは地下[ちか]に作[つく]られているので、砂嵐[すなあらし]の日[ひ]でも水[みず]が汚[よご]れにくいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カナート", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "水を遠くへ運ぶ伝統的な地下水路の施設", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38403, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カナート", "is_correct": true, "explanation": "「水を蒸発させずに遠くまで運ぶ、昔からの施設」と定義どおりに合う。"}, {"text": "ラクダ", "is_correct": false, "explanation": "「ラクダ」は動物で、水を運ぶ昔からの施設ではないので合わない。"}, {"text": "砂丘", "is_correct": false, "explanation": "「砂丘」は自然の地形で、人が作った水を運ぶ施設ではないので合わない。"}, {"text": "市場", "is_correct": false, "explanation": "「市場」は物を売買する場所で、水を蒸発させずに運ぶ施設ではないので合わない。"}], "explanations": {"カナート": "「水を蒸発させずに遠くまで運ぶ、昔からの施設」と定義どおりに合う。", "ラクダ": "「ラクダ」は動物で、水を運ぶ昔からの施設ではないので合わない。", "砂丘": "「砂丘」は自然の地形で、人が作った水を運ぶ施設ではないので合わない。", "市場": "「市場」は物を売買する場所で、水を蒸発させずに運ぶ施設ではないので合わない。"}, "sentence_index": 0, "correct_answer": "カナート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台所のカナートが壊れて、水が出ません。", "explanation": "ここは〈水道〉の意味。カナートは台所の設備ではないので、台所の水を止める設備としては合わない。"}, {"text": "カナートを閉めて、部屋を暗くしました。", "explanation": "ここは〈カーテン〉の意味。カナートは窓を覆う布ではないので、閉めて光を遮るものではない。"}, {"text": "カナートを開けて入りました。", "explanation": "ここは〈ドア〉の意味。カナートは出入りする戸ではないので、開けるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38403, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カナート", "is_correct": true, "explanation": "「機械のない時代に、人の手でカナートを掘った」と続き、地下水路を掘る対象として合う。"}, {"text": "ヤシ", "is_correct": false, "explanation": "「ヤシ」は植物で、人の手で掘る対象にはならないので合わない。"}, {"text": "金庫", "is_correct": false, "explanation": "「金庫」は箱状の道具で、人の手で掘る対象にはならないので合わない。"}, {"text": "ポスター", "is_correct": false, "explanation": "掲示用の印刷物で、人の手で掘る対象にはならない。"}], "explanations": {"カナート": "「機械のない時代に、人の手でカナートを掘った」と続き、地下水路を掘る対象として合う。", "ヤシ": "「ヤシ」は植物で、人の手で掘る対象にはならないので合わない。", "金庫": "「金庫」は箱状の道具で、人の手で掘る対象にはならないので合わない。", "ポスター": "掲示用の印刷物で、人の手で掘る対象にはならない。"}, "sentence_index": 6, "correct_answer": "カナート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カナートは、台所に置きます。", "explanation": "ここは〈ごみ箱〉の意味。カナートは置ける物ではないので、台所に置くことはない。"}, {"text": "カナートで字を書きます。", "explanation": "ここは〈ペン〉の意味。カナートは字を書く道具ではないので、「で」の手段にならない。"}, {"text": "カナートを研ぎました。", "explanation": "ここは〈包丁〉の意味。カナートは刃物ではないので、研いで切れ味を出すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38403, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その時代、村の人々はカナートが掘ってきました。", "corrected_sentence": "その時代、村の人々はカナートを掘ってきました。", "error_description": "助詞の誤り。「掘る」の対象は「を」で示す。「が」では主語になり、掘る対象の文として合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38403, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "機械のない昔、村の人がカナートに掘りました。", "corrected_sentence": "機械のない昔、村の人がカナートを掘りました。", "error_description": "助詞の誤り。「掘る」の対象は「を」で示す。「に」では対象にならず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38404, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『蒸発』が『早い』の主語になり、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "『蒸発を早い』では目的語になり、『早い』とつながらないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は場所や時を示すので、『蒸発に早い』とは続かない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『蒸発で早い』は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『蒸発』が『早い』の主語になり、文に合う。", "を": "『蒸発を早い』では目的語になり、『早い』とつながらないので合わない。", "に": "『に』は場所や時を示すので、『蒸発に早い』とは続かない。", "で": "『で』は手段や場所を示すので、『蒸発で早い』は文として成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・時", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38404, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『水の蒸発』で、『水』の蒸発であることを示す『の』。文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、『水へ蒸発』では意味が通らず合わない。"}, {"text": "を", "is_correct": false, "explanation": "『水を蒸発が速く』では『を』が目的語を示し、『蒸発が速い』の主語とつながらないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "『水で蒸発が速く』では『で』が手段や場所を示し、『水の蒸発』の所属の関係にならず文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "『水の蒸発』で、『水』の蒸発であることを示す『の』。文に合う。", "へ": "『へ』は方向を示すので、『水へ蒸発』では意味が通らず合わない。", "を": "『水を蒸発が速く』では『を』が目的語を示し、『蒸発が速い』の主語とつながらないので合わない。", "で": "『水で蒸発が速く』では『で』が手段や場所を示し、『水の蒸発』の所属の関係にならず文が成り立たない。"}, "error_tags": {"へ": "方向", "を": "目的語", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38404, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水などが空気の中に消えてなくなること。", "primary_collocate": null, "pronunciation": "じょうはつ", "ipa": "dʑoːhatsɯ", "syllable_count": 4, "sentences": [{"text": "洗濯物が乾くのは、水が蒸発するからです。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]が乾[かわ]くのは、水[みず]が蒸発[じょうはつ]するからです。", "sentence_source": "generated"}, {"text": "夏は暑いので、水たまりの蒸発が早い。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "夏[なつ]は暑[あつ]いので、水[みず]たまりの蒸発[じょうはつ]が早[はや]い。", "sentence_source": "generated"}, {"text": "鍋のふたを開けたままだと、スープの水が蒸発してしまう。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "鍋[なべ]のふたを開[あ]けたままだと、スープの水[みず]が蒸発[じょうはつ]してしまう。", "sentence_source": "generated"}, {"text": "朝にまいた水は、昼までに蒸発して地面が乾いた。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "朝[あさ]にまいた水[みず]は、昼[ひる]までに蒸発[じょうはつ]して地面[じめん]が乾[かわ]いた。", "sentence_source": "generated"}, {"text": "太陽の熱で海の水が蒸発し、雲になる。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "太陽[たいよう]の熱[ねつ]で海[うみ]の水[みず]が蒸発[じょうはつ]し、雲[くも]になる。", "sentence_source": "generated"}, {"text": "汗が蒸発するとき、体の熱が逃げて涼しくなる。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "汗[あせ]が蒸発[じょうはつ]するとき、体[からだ]の熱[ねつ]が逃[に]げて涼[すず]しくなる。", "sentence_source": "generated"}, {"text": "コップの水を窓辺に置いたら、数日で蒸発して少なくなった。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "コップの水[みず]を窓辺[まどべ]に置[お]いたら、数日[すうじつ]で蒸発[じょうはつ]して少[すく]なくなった。", "sentence_source": "generated"}, {"text": "風が強い日は、水の蒸発が速く、洗濯物がよく乾く。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、水[みず]の蒸発[じょうはつ]が速[はや]く、洗濯物[せんたくもの]がよく乾[かわ]く。", "sentence_source": "generated"}, {"text": "池の水が蒸発して、底が見えるようになった。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "池[いけ]の水[みず]が蒸発[じょうはつ]して、底[そこ]が見[み]えるようになった。", "sentence_source": "generated"}, {"text": "塩は、海水を蒸発させると取り出せる。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "塩[しお]は、海水[かいすい]を蒸発[じょうはつ]させると取[と]り出[だ]せる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒸発", "label": "基本形"}, {"form": "蒸発する", "label": "終止形"}, {"form": "蒸発した", "label": "過去形"}, {"form": "蒸発して", "label": "て形"}, {"form": "蒸発させる", "label": "使役形"}], "register": "一般", "sense_fingerprint": "水などが目に見えない形で空気中に出ていき、なくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38404, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蒸発", "is_correct": true, "explanation": "水が空気中に消えてなくなる意味で、文の内容に合う。"}, {"text": "感染", "is_correct": false, "explanation": "感染は病原体などが体に入り広がること。水の変化には使わない。"}, {"text": "出発", "is_correct": false, "explanation": "出発は目的地へ向かって出かけること。水は出発しないので合わない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集まっていた人々が別れること。水の変化には使えない。"}], "explanations": {"蒸発": "水が空気中に消えてなくなる意味で、文の内容に合う。", "感染": "感染は病原体などが体に入り広がること。水の変化には使わない。", "出発": "出発は目的地へ向かって出かけること。水は出発しないので合わない。", "解散": "解散は集まっていた人々が別れること。水の変化には使えない。"}, "sentence_index": 0, "correct_answer": "蒸発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夫は急に蒸発して、家に戻ってこなくなった。", "explanation": "ここは〈姿を消す（失踪する）〉の意味。人が突然いなくなることで、水などが空気中に消える変化の意味とは別なので合わない。"}, {"text": "砂糖を水に入れたら、蒸発して見えなくなった。", "explanation": "ここは〈溶ける〉の意味。砂糖は水に溶けて見えなくなるのであり、液体が気体になる蒸発とは別の変化なので合わない。"}, {"text": "氷が蒸発して、水になった。", "explanation": "ここは〈融解〉の意味。氷が溶けて水になる変化で、水が気体になる蒸発とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38404, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒸発", "is_correct": true, "explanation": "数日で水が空気中に消えて減るという意味で、文に合う。"}, {"text": "受験", "is_correct": false, "explanation": "受験は試験を受けること。水の変化には使わない。"}, {"text": "入院", "is_correct": false, "explanation": "入院は病院に入って治療を受けること。水の変化の話には合わない。"}, {"text": "噴火", "is_correct": false, "explanation": "噴火は火山が噴き出すこと。コップの水の変化には使わない。"}], "explanations": {"蒸発": "数日で水が空気中に消えて減るという意味で、文に合う。", "受験": "受験は試験を受けること。水の変化には使わない。", "入院": "入院は病院に入って治療を受けること。水の変化の話には合わない。", "噴火": "噴火は火山が噴き出すこと。コップの水の変化には使わない。"}, "sentence_index": 6, "correct_answer": "蒸発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷たいコップの表面で、水蒸気が蒸発して水滴になった。", "explanation": "ここは〈凝結〉の意味。水蒸気が冷えて液体に戻る変化で、液体が気体になる蒸発とは逆なので合わない。"}, {"text": "停電になって、部屋の電気が蒸発した。", "explanation": "ここは〈消える〉の意味。電気は液体ではないので、液体が気体になる蒸発とは合わない。"}, {"text": "お風呂に入ると、体の熱が蒸発して、ぽかぽかする。", "explanation": "ここは〈発散〉の意味。体の熱は液体ではないので、蒸発とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38404, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暑い日は、コップの水の蒸発を速い。", "corrected_sentence": "暑い日は、コップの水の蒸発が速い。", "error_description": "『蒸発』に続く助詞は『が』。『を』は目的語を示すので、形容詞『速い』の主語を表す位置には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38404, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜のうちに、皿の水が蒸発て乾いた。", "corrected_sentence": "夜のうちに、皿の水が蒸発して乾いた。", "error_description": "『蒸発』のて形は『蒸発して』。『蒸発て』は『し』が抜けた誤りで、正しくは『蒸発して』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
