INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38405, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "液体が気体になって、見えなくなること。", "primary_collocate": null, "pronunciation": "じょうはつ", "ipa": "dʑoːhatsɯ", "syllable_count": 4, "sentences": [{"text": "液体の水が蒸発すると、目に見えない水蒸気になる。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "液体[えきたい]の水[みず]が蒸発[じょうはつ]すると、目[め]に見[み]えない水蒸気[すいじょうき]になる。", "sentence_source": "generated"}, {"text": "アルコールは水より蒸発しやすい。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "アルコールは水[みず]より蒸発[じょうはつ]しやすい。", "sentence_source": "generated"}, {"text": "理科の実験で、食塩水を熱して水を蒸発させた。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "理科[りか]の実験[じっけん]で、食塩水[しょくえんすい]を熱[ねっ]して水[みず]を蒸発[じょうはつ]させた。", "sentence_source": "generated"}, {"text": "熱を加えると、液体の蒸発が速くなる。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "熱[ねつ]を加[くわ]えると、液体[えきたい]の蒸発[じょうはつ]が速[はや]くなる。", "sentence_source": "generated"}, {"text": "ガソリンは蒸発しやすいので、ふたをしっかり閉めてください。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "ガソリンは蒸発[じょうはつ]しやすいので、ふたをしっかり閉[し]めてください。", "sentence_source": "generated"}, {"text": "香水のびんを開けておくと、中身が蒸発して減る。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "香水[こうすい]のびんを開[あ]けておくと、中身[なかみ]が蒸発[じょうはつ]して減[へ]る。", "sentence_source": "generated"}, {"text": "蒸発した水は、冷えると再び水滴にもどる。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "蒸発[じょうはつ]した水[みず]は、冷[ひ]えると再[ふたた]び水滴[すいてき]にもどる。", "sentence_source": "generated"}, {"text": "消毒用のアルコールは、手につけるとすぐ蒸発する。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "消毒用[しょうどくよう]のアルコールは、手[て]につけるとすぐ蒸発[じょうはつ]する。", "sentence_source": "generated"}, {"text": "液体が蒸発するとき、まわりから熱をうばう。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "液体[えきたい]が蒸発[じょうはつ]するとき、まわりから熱[ねつ]をうばう。", "sentence_source": "generated"}, {"text": "実験では、蒸発して残った白い粒を調べた。", "target_word": "蒸発", "complexity_tier": "T3", "furigana": "実験[じっけん]では、蒸発[じょうはつ]して残[のこ]った白[しろ]い粒[つぶ]を調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒸発", "label": "基本形"}, {"form": "蒸発する", "label": "終止形"}, {"form": "蒸発した", "label": "過去形"}, {"form": "蒸発しやすい", "label": "形容詞化"}, {"form": "蒸発させる", "label": "使役形"}], "register": "学術", "sense_fingerprint": "液体が気体（蒸気）に変わる状態変化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T4: contains vocabulary far above tier T4: うばう (Zipf 1.43)']::text[], 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38405, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蒸発", "is_correct": true, "explanation": "液体が気体になって見えなくなる意味で、文の流れに合う。"}, {"text": "融解", "is_correct": false, "explanation": "融解は固体が液体になること。液体の水には使わない。"}, {"text": "振動", "is_correct": false, "explanation": "振動はものが小刻みに揺れること。水が水蒸気になる変化の説明には合わない。"}, {"text": "摩擦", "is_correct": false, "explanation": "摩擦は物どうしがこすれること。水蒸気への変化とは関係がない。"}], "explanations": {"蒸発": "液体が気体になって見えなくなる意味で、文の流れに合う。", "融解": "融解は固体が液体になること。液体の水には使わない。", "振動": "振動はものが小刻みに揺れること。水が水蒸気になる変化の説明には合わない。", "摩擦": "摩擦は物どうしがこすれること。水蒸気への変化とは関係がない。"}, "sentence_index": 0, "correct_answer": "蒸発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放っておいた牛乳が蒸発して、すっぱくなった。", "explanation": "ここは〈腐る〉の意味。牛乳がすっぱくなるのは腐敗で、液体が気体になる蒸発とは別の変化なので合わない。"}, {"text": "鉄を熱すると、固体の鉄が蒸発して液体になる。", "explanation": "ここは〈融解〉の意味。固体が液体になる変化で、液体が気体になる蒸発とは合わない。"}, {"text": "冷えた窓ガラスに、水蒸気が蒸発して水滴がついた。", "explanation": "ここは〈凝結〉の意味。水蒸気が冷えて水滴になる変化で、液体が気体になる蒸発とは逆なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38405, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒸発", "is_correct": true, "explanation": "液体が気体になった水という意味で、文の主語として合う。"}, {"text": "消毒", "is_correct": false, "explanation": "消毒は菌などを取り除くこと。水が水滴に戻る話には合わない。"}, {"text": "反射", "is_correct": false, "explanation": "反射は光や音がはね返ること。水の状態変化の話には合わない。"}, {"text": "凍結", "is_correct": false, "explanation": "凍結は液体が固まること。水滴に戻る文脈とは逆なので合わない。"}], "explanations": {"蒸発": "液体が気体になった水という意味で、文の主語として合う。", "消毒": "消毒は菌などを取り除くこと。水が水滴に戻る話には合わない。", "反射": "反射は光や音がはね返ること。水の状態変化の話には合わない。", "凍結": "凍結は液体が固まること。水滴に戻る文脈とは逆なので合わない。"}, "sentence_index": 6, "correct_answer": "蒸発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消しゴムで消すと、鉛筆の線が蒸発して消えた。", "explanation": "ここは〈消す〉の意味。鉛筆の線は固体で、液体が気体になる蒸発とは合わない。"}, {"text": "水が蒸発して、氷になった。", "explanation": "ここは〈凍結〉の意味。液体が固体になる変化で、気体になる蒸発とは逆なので合わない。"}, {"text": "泥水を布でこすと、泥が蒸発して、きれいな水だけが残る。", "explanation": "ここは〈ろ過〉の意味。泥をこして取り除くのがろ過で、液体が気体になる蒸発とは別の操作なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38405, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "加熱して、食塩水の水分を蒸発した。", "corrected_sentence": "加熱して、食塩水の水分を蒸発させた。", "error_description": "『蒸発』は水分などが自然に気体になる変化を表す。熱を加えて起こす場合は使役形の『蒸発させた』とする。『蒸発した』では他から働きかけた意味が抜けている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38405, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ガソリンは、室温でも蒸発に速い。", "corrected_sentence": "ガソリンは、室温でも蒸発が速い。", "error_description": "『蒸発』に続く助詞は主語を示す『が』。『に』は場所や時を示すので、形容詞『速い』の主語にはならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38406, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『私に』の『に』。くれるの受け手（話し手）を示すので、『私にくれると言った』が自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』。受け手は『に』で示すので、『私へくれる』は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す『から』。出どころを示すと『私からくれる』は話し手が与える側になり、文の意味が変わる。"}, {"text": "と", "is_correct": false, "explanation": "相手・共同を表す『と』。受け手にならず、『私とくれる』では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "『私に』の『に』。くれるの受け手（話し手）を示すので、『私にくれると言った』が自然。", "へ": "方向を表す『へ』。受け手は『に』で示すので、『私へくれる』は不自然。", "から": "起点を表す『から』。出どころを示すと『私からくれる』は話し手が与える側になり、文の意味が変わる。", "と": "相手・共同を表す『と』。受け手にならず、『私とくれる』では意味が通らない。"}, "error_tags": {"へ": "方向", "から": "起点", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38406, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38406, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が自分に何かをあげるときに使うことば。", "primary_collocate": null, "pronunciation": "くれる", "ipa": "kɯɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "友だちが誕生日にきれいな花をくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "友[とも]だちが 誕生日[たんじょうび]にきれいな 花[はな]をくれた。", "sentence_source": "generated"}, {"text": "兄は古い自転車を私にくれると言った。", "target_word": "くれる", "complexity_tier": "T3", "furigana": "兄[あに]は 古[ふる]い 自転車[じてんしゃ]を 私[わたし]にくれると 言[い]った。", "sentence_source": "generated"}, {"text": "祖母は毎年、みかんを私にくれる。", "target_word": "くれる", "complexity_tier": "T3", "furigana": "祖母[そぼ]は 毎年[まいとし]、みかんを 私[わたし]にくれる。", "sentence_source": "generated"}, {"text": "先生が私に新しいノートをくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "先生[せんせい]が 私[わたし]に 新[あたら]しいノートをくれた。", "sentence_source": "generated"}, {"text": "隣の人がお土産のお菓子をくれたので、すぐ食べた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "隣[となり]の 人[ひと]がお 土産[みやげ]のお 菓子[かし]をくれたので、すぐ 食[た]べた。", "sentence_source": "generated"}, {"text": "彼は私に何もくれなかったので、少しさびしかった。", "target_word": "くれなかった", "complexity_tier": "T3", "furigana": "彼[かれ]は 私[わたし]に 何[なに]もくれなかったので、 少[すこ]しさびしかった。", "sentence_source": "generated"}, {"text": "母が小さいかばんをくれたから、毎日使っている。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "母[はは]が 小[ちい]さいかばんをくれたから、 毎日[まいにち] 使[つか]っている。", "sentence_source": "generated"}, {"text": "田中さんは私にチケットを二枚くれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "田中[たなか]さんは 私[わたし]にチケットを 二枚[にまい]くれた。", "sentence_source": "generated"}, {"text": "だれもお金をくれないので、自分で働いた。", "target_word": "くれない", "complexity_tier": "T3", "furigana": "だれもお 金[かね]をくれないので、 自分[じぶん]で 働[はたら]いた。", "sentence_source": "generated"}, {"text": "あの人は私が困っているとき、傘をくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "あの 人[ひと]は 私[わたし]が 困[こま]っているとき、 傘[かさ]をくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "くれる", "label": "終止形・連体形"}, {"form": "くれた", "label": "過去形"}, {"form": "くれない", "label": "否定形"}, {"form": "くれます", "label": "丁寧形"}, {"form": "くれて", "label": "テ形"}, {"form": "くれれば", "label": "仮定形"}, {"form": "くれよう", "label": "意向形"}, {"form": "くれ", "label": "命令形"}], "register": "口語（普通体）", "sense_fingerprint": "他人が話し手（自分）に物を与える授与の動詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38406, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "くれた", "is_correct": true, "explanation": "過去形の『くれた』。友だちが話し手に花を与えた、という授与の意味になり、文の内容と合う。"}, {"text": "叫んだ", "is_correct": false, "explanation": "叫ぶは目的語を取らない動詞なので、『花を叫んだ』は文として成り立たない。"}, {"text": "答えた", "is_correct": false, "explanation": "答えるは『〜に答える』の形で、物を目的語に取らない。『花を答えた』は意味が通らない。"}, {"text": "眠った", "is_correct": false, "explanation": "眠るは目的語を取らない自動詞なので、『花を眠った』は不自然で成り立たない。"}], "explanations": {"くれた": "過去形の『くれた』。友だちが話し手に花を与えた、という授与の意味になり、文の内容と合う。", "叫んだ": "叫ぶは目的語を取らない動詞なので、『花を叫んだ』は文として成り立たない。", "答えた": "答えるは『〜に答える』の形で、物を目的語に取らない。『花を答えた』は意味が通らない。", "眠った": "眠るは目的語を取らない自動詞なので、『花を眠った』は不自然で成り立たない。"}, "sentence_index": 0, "correct_answer": "くれた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は妹に古い本をくれた。", "explanation": "ここは〈あげる〉の意味。くれるは相手が自分に与える言い方なので、自分が妹に与える文には使えない。"}, {"text": "私は図書館に、借りていた本をくれた。", "explanation": "ここは〈返す〉の意味。くれるは相手が自分に与える言い方なので、借りた本を図書館に戻す文には使えない。"}, {"text": "私は弟に宿題を手伝ってくれた。", "explanation": "ここは〈〜てあげる〉の意味。くれるは相手が自分に恩恵を与える言い方なので、自分が弟の宿題を手伝う文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38406, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "くれた", "is_correct": true, "explanation": "過去形の『くれた』。母が話し手にかばんを与えた、という理由の節になり、文に合う。"}, {"text": "飲んだ", "is_correct": false, "explanation": "飲むは液体などを対象にする動詞。かばんを飲むことはできないので、文が成り立たない。"}, {"text": "食べた", "is_correct": false, "explanation": "食べるは食べ物を対象にする動詞。かばんは食べられないので、意味が通らない。"}, {"text": "舐めた", "is_correct": false, "explanation": "舐めるは舌で触れる動作。『かばんを舐めた』は不自然で、理由の節として合わない。"}], "explanations": {"くれた": "過去形の『くれた』。母が話し手にかばんを与えた、という理由の節になり、文に合う。", "飲んだ": "飲むは液体などを対象にする動詞。かばんを飲むことはできないので、文が成り立たない。", "食べた": "食べるは食べ物を対象にする動詞。かばんは食べられないので、意味が通らない。", "舐めた": "舐めるは舌で触れる動作。『かばんを舐めた』は不自然で、理由の節として合わない。"}, "sentence_index": 6, "correct_answer": "くれた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降ってきたので、友だちに傘をくれた。", "explanation": "ここは〈あげる〉の意味。くれるは相手が自分に与える言い方なので、自分が友だちに傘を渡す文には使えない。"}, {"text": "出かける前に、子どもに財布をくれた。", "explanation": "ここは〈預ける〉の意味。くれるは物が自分に来ることを表すので、自分が子どもに財布を託す文には合わない。"}, {"text": "遠くに住む祖母に、荷物をくれた。", "explanation": "ここは〈送る〉の意味。くれるは相手が自分に与える言い方なので、自分が祖母に荷物を届ける文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38406, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちが私から誕生日の花をくれた。", "corrected_sentence": "友だちが私に誕生日の花をくれた。", "error_description": "『くれる』の受け手（私）は『に』で示す。『から』は出どころを表すので、『私から』と書くと受け手として意味が通らない。『私に』が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "くれる", "is_correct": true, "explanation": "終止形・連体形。『〜と言った』の中身は未来の内容なので、辞書形の『くれる』が正しい。"}, {"text": "くれて", "is_correct": false, "explanation": "テ形。『〜と言った』に続かず文が成り立たない"}, {"text": "くれれば", "is_correct": false, "explanation": "仮定形。条件節になり『と言った』に続かない"}, {"text": "くれます", "is_correct": false, "explanation": "丁寧形。普通体の文の中で『〜と』に続けるには、普通形の『くれる』が必要。"}], "correct_form": "くれる", "base_form": "くれる", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"くれる": "終止形・連体形。『〜と言った』の中身は未来の内容なので、辞書形の『くれる』が正しい。", "くれて": "テ形。『〜と言った』に続かず文が成り立たない", "くれれば": "仮定形。条件節になり『と言った』に続かない", "くれます": "丁寧形。普通体の文の中で『〜と』に続けるには、普通形の『くれる』が必要。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38406, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年、祖父は私に大きな本をくれた。", "corrected_sentence": "来年、祖父は私に大きな本をくれる。", "error_description": "『来年』は未来の時を表すので、過去形の『くれた』は合わない。未来の出来事には『くれる』を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "くれた", "is_correct": true, "explanation": "過去形。田中さんが私にチケットを二枚与えた、という過去の出来事を表すので文に合う。"}, {"text": "くれない", "is_correct": false, "explanation": "否定形。『くれなかった』なら過去の否定になるが、ここは与えた事実を述べる文なので意味が反対になる。"}, {"text": "くれ", "is_correct": false, "explanation": "命令形。『くれ』は強い命令になり、事実を述べる文末には合わない。"}, {"text": "くれよう", "is_correct": false, "explanation": "意向形。話し手の意志や推量を表し、『田中さんは』という第三者主語の事実文には合わない。"}], "correct_form": "くれた", "base_form": "くれる", "form_label": "過去形", "sentence_index": 7, "explanations": {"くれた": "過去形。田中さんが私にチケットを二枚与えた、という過去の出来事を表すので文に合う。", "くれない": "否定形。『くれなかった』なら過去の否定になるが、ここは与えた事実を述べる文なので意味が反対になる。", "くれ": "命令形。『くれ』は強い命令になり、事実を述べる文末には合わない。", "くれよう": "意向形。話し手の意志や推量を表し、『田中さんは』という第三者主語の事実文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
