INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38407, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「くれる」は、他人が自分（または自分の側の人）に何かを与えることを表す動詞です。話し手が受け取る側の立場から見た言い方で、恩恵や親しみを感じさせる表現です。", "primary_collocate": null, "pronunciation": "くれる", "ipa": "kɯɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "山田さんはうちの子におもちゃをくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "山田[やまだ]さんはうちの 子[こ]におもちゃをくれた。", "sentence_source": "generated"}, {"text": "隣の人が弟に果物をくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "隣[となり]の 人[ひと]が 弟[おとうと]に 果物[くだもの]をくれた。", "sentence_source": "generated"}, {"text": "先輩は妹に古い辞書をくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "先輩[せんぱい]は 妹[いもうと]に 古[ふる]い 辞書[じしょ]をくれた。", "sentence_source": "generated"}, {"text": "叔父は毎年、私たち家族にお米をくれる。", "target_word": "くれる", "complexity_tier": "T3", "furigana": "叔父[おじ]は 毎年[まいとし]、 私[わたし]たち 家族[かぞく]にお 米[こめ]をくれる。", "sentence_source": "generated"}, {"text": "友人が私たちにワインをくれたので、みんなで飲んだ。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "友人[ゆうじん]が 私[わたし]たちにワインをくれたので、みんなで 飲[の]んだ。", "sentence_source": "generated"}, {"text": "近所の人は、うちの犬にいつもおやつをくれる。", "target_word": "くれる", "complexity_tier": "T3", "furigana": "近所[きんじょ]の 人[ひと]は、うちの 犬[いぬ]にいつもおやつをくれる。", "sentence_source": "generated"}, {"text": "彼女は私の息子に手作りのセーターをくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は 私[わたし]の 息子[むすこ]に 手作[てづく]りのセーターをくれた。", "sentence_source": "generated"}, {"text": "姉の友だちが私にサッカーのボールをくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "姉[あね]の 友[とも]だちが 私[わたし]にサッカーのボールをくれた。", "sentence_source": "generated"}, {"text": "知らない人が娘にあめをくれたので、少し心配した。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "知[し]らない 人[ひと]が 娘[むすめ]にあめをくれたので、 少[すこ]し 心配[しんぱい]した。", "sentence_source": "generated"}, {"text": "店の人がサービスで、うちの子どもたちにジュースをくれた。", "target_word": "くれた", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]がサービスで、うちの子[こ]どもたちにジュースをくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "くれる", "label": "終止形・連体形"}, {"form": "くれた", "label": "過去形"}, {"form": "くれない", "label": "否定形"}, {"form": "くれます", "label": "丁寧形"}, {"form": "くれて", "label": "テ形"}, {"form": "くれれば", "label": "仮定形"}, {"form": "くれよう", "label": "意向形"}, {"form": "くれ", "label": "命令形"}], "register": "口語（普通体）", "sense_fingerprint": "他人が自分または身内に物を与える、受け手側から見た恩恵の授与", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38407, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "くれた", "is_correct": true, "explanation": "過去形の『くれた』。山田さんがうちの子に与えた、という授与の意味になり、文に合う。"}, {"text": "泣いた", "is_correct": false, "explanation": "泣くは目的語を取らない自動詞なので、『おもちゃを泣いた』は成り立たない。"}, {"text": "座った", "is_correct": false, "explanation": "座るは目的語を取らない自動詞なので、『おもちゃを座った』は不自然で通らない。"}, {"text": "怒った", "is_correct": false, "explanation": "怒るは感情を表す自動詞で、物を目的語に取らない。『おもちゃを怒った』は成立しない。"}], "explanations": {"くれた": "過去形の『くれた』。山田さんがうちの子に与えた、という授与の意味になり、文に合う。", "泣いた": "泣くは目的語を取らない自動詞なので、『おもちゃを泣いた』は成り立たない。", "座った": "座るは目的語を取らない自動詞なので、『おもちゃを座った』は不自然で通らない。", "怒った": "怒るは感情を表す自動詞で、物を目的語に取らない。『おもちゃを怒った』は成立しない。"}, "sentence_index": 0, "correct_answer": "くれた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は叔父に、会議の資料をくれた。", "explanation": "ここは〈渡す〉の意味。くれるは相手が自分に与える言い方なので、自分が叔父に物を渡す文には合わない。"}, {"text": "私は母に弁当を作ってくれた。", "explanation": "ここは〈〜てもらう〉の意味。くれるは相手が自分に恩恵を与える言い方なので、私が母に作ってもらう文には使えない。"}, {"text": "私は友人に道を教えてくれた。", "explanation": "ここは〈〜てあげる〉の意味。くれるは相手が自分に恩恵を与える言い方なので、自分が友人に道を教える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38407, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "くれた", "is_correct": true, "explanation": "過去形の『くれた』。彼女が話し手の息子にセーターを与えた、という授与の意味になり、文に合う。"}, {"text": "飲んだ", "is_correct": false, "explanation": "飲むは液体などを対象にする動詞。セーターを飲むことはできないため、文が成り立たない。"}, {"text": "食べた", "is_correct": false, "explanation": "食べるは食べ物を対象にする動詞。セーターは食べられないので、意味が通らない。"}, {"text": "舐めた", "is_correct": false, "explanation": "舐めるは舌で触れる動作。『セーターを舐めた』は不自然で、文脈に合わない。"}], "explanations": {"くれた": "過去形の『くれた』。彼女が話し手の息子にセーターを与えた、という授与の意味になり、文に合う。", "飲んだ": "飲むは液体などを対象にする動詞。セーターを飲むことはできないため、文が成り立たない。", "食べた": "食べるは食べ物を対象にする動詞。セーターは食べられないので、意味が通らない。", "舐めた": "舐めるは舌で触れる動作。『セーターを舐めた』は不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "くれた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、姉に自転車をくれた。", "explanation": "ここは〈あげる〉の意味。くれるは相手が自分に与える言い方なので、自分が姉に自転車を渡す文には合わない。"}, {"text": "友だちに本をくれた。", "explanation": "ここは〈返す〉の意味。くれるは相手が自分に与える言い方なので、借りた物を相手に戻す文には使えない。"}, {"text": "店に料理をくれた。", "explanation": "ここは〈届ける〉の意味。くれるは相手が自分に与える言い方なので、自分が店に料理を届ける文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38407, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩は私と、古い自転車をくれた。", "corrected_sentence": "先輩は私に、古い自転車をくれた。", "error_description": "『くれる』の受け手（私）は『に』で示す。『と』は一緒にいる相手を表すので、『私と』では受け手が示せず、文が成り立たない。『私に』が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "くれた", "is_correct": true, "explanation": "過去形。隣の人が弟に果物を与えた過去の出来事を表すので、文に合う。"}, {"text": "くれて", "is_correct": false, "explanation": "テ形。文を言い切れず文末に入らない"}, {"text": "くれれば", "is_correct": false, "explanation": "仮定形。条件節になり文が完結しない"}, {"text": "くれます", "is_correct": false, "explanation": "丁寧形。普通体の文の中で使うと文体が合わない。"}], "correct_form": "くれた", "base_form": "くれる", "form_label": "過去形", "sentence_index": 1, "explanations": {"くれた": "過去形。隣の人が弟に果物を与えた過去の出来事を表すので、文に合う。", "くれて": "テ形。文を言い切れず文末に入らない", "くれれば": "仮定形。条件節になり文が完結しない", "くれます": "丁寧形。普通体の文の中で使うと文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38407, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週、母は私たちにおもちゃをくれた。", "corrected_sentence": "来週、母は私たちにおもちゃをくれる。", "error_description": "『来週』は未来の時を表すので、過去形の『くれた』は合わない。未来の出来事には『くれる』を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "くれた", "is_correct": true, "explanation": "過去形。姉の友だちが私にボールを与えた過去の出来事を表すので、文に合う。"}, {"text": "くれない", "is_correct": false, "explanation": "否定形。『くれなかった』なら過去の否定になるが、ここは与えた事実を述べる文なので意味が反対になる。"}, {"text": "くれ", "is_correct": false, "explanation": "命令形。『くれ』は強い命令になり、事実を述べる文末には合わない。"}, {"text": "くれよう", "is_correct": false, "explanation": "意向形。話し手の意志や推量を表し、『姉の友だちが』という第三者主語の事実文には合わない。"}], "correct_form": "くれた", "base_form": "くれる", "form_label": "過去形", "sentence_index": 7, "explanations": {"くれた": "過去形。姉の友だちが私にボールを与えた過去の出来事を表すので、文に合う。", "くれない": "否定形。『くれなかった』なら過去の否定になるが、ここは与えた事実を述べる文なので意味が反対になる。", "くれ": "命令形。『くれ』は強い命令になり、事実を述べる文末には合わない。", "くれよう": "意向形。話し手の意志や推量を表し、『姉の友だちが』という第三者主語の事実文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
