INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38408, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "みんなが同じくらいになるようにすること。", "primary_collocate": null, "pronunciation": "きんとう", "ipa": "kʲiɴtoː", "syllable_count": 2, "sentences": [{"text": "兄弟でお金を均等に分けることにした。", "target_word": "均等", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]でお 金[かね]を 均等[きんとう]に 分[わ]けることにした。", "sentence_source": "generated"}, {"text": "仕事を均等にすれば、だれも疲れすぎない。", "target_word": "均等", "complexity_tier": "T3", "furigana": "仕事[しごと]を 均等[きんとう]にすれば、だれも 疲[つか]れすぎない。", "sentence_source": "generated"}, {"text": "先生は全員にチャンスを均等に与えようとしている。", "target_word": "均等", "complexity_tier": "T3", "furigana": "先生[せんせい]は 全員[ぜんいん]にチャンスを 均等[きんとう]に 与[あた]えようとしている。", "sentence_source": "generated"}, {"text": "ピザを六人で均等に切って、みんなで食べた。", "target_word": "均等", "complexity_tier": "T3", "furigana": "ピザを 六人[ろくにん]で 均等[きんとう]に 切[き]って、みんなで 食[た]べた。", "sentence_source": "generated"}, {"text": "当番を均等にするために、表を作った。", "target_word": "均等", "complexity_tier": "T3", "furigana": "当番[とうばん]を 均等[きんとう]にするために、 表[ひょう]を 作[つく]った。", "sentence_source": "generated"}, {"text": "部長は費用を均等に負担するよう頼んだ。", "target_word": "均等", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は 費用[ひよう]を 均等[きんとう]に 負担[ふたん]するよう 頼[たの]んだ。", "sentence_source": "generated"}, {"text": "不公平にならないよう、荷物を均等に持った。", "target_word": "均等", "complexity_tier": "T3", "furigana": "不公平[ふこうへい]にならないよう、 荷物[にもつ]を 均等[きんとう]に 持[も]った。", "sentence_source": "generated"}, {"text": "町は予算を各地区に均等に分けた。", "target_word": "均等", "complexity_tier": "T3", "furigana": "町[まち]は 予算[よさん]を 各地区[かくちく]に 均等[きんとう]に 分[わ]けた。", "sentence_source": "generated"}, {"text": "母はおかずを三人に均等に分けて、皿に入れた。", "target_word": "均等", "complexity_tier": "T3", "furigana": "母[はは]はおかずを 三人[さんにん]に 均等[きんとう]に 分[わ]けて、 皿[さら]に 入[い]れた。", "sentence_source": "generated"}, {"text": "負担を均等にしたいなら、みんなで話し合うべきだ。", "target_word": "均等", "complexity_tier": "T3", "furigana": "負担[ふたん]を 均等[きんとう]にしたいなら、みんなで 話[はな]し 合[あ]うべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "均等", "label": "基本形"}, {"form": "均等に", "label": "副詞的用法"}], "register": "口語（普通体）", "sense_fingerprint": "分け方や負担を、全員が同じくらいになるようにそろえること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38408, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均等", "is_correct": true, "explanation": "『均等に』の形で、同じ量ずつ分けるという意味になり、文に合う。"}, {"text": "大声", "is_correct": false, "explanation": "名詞。『大声に分ける』では副詞として成り立たず、意味が通らない。"}, {"text": "木製", "is_correct": false, "explanation": "材質を表す語で、分け方を表せないため、『木製に分ける』は不自然。"}, {"text": "小声", "is_correct": false, "explanation": "声の大きさを表す語で、『小声に分ける』は意味が通らない。"}], "explanations": {"均等": "『均等に』の形で、同じ量ずつ分けるという意味になり、文に合う。", "大声": "名詞。『大声に分ける』では副詞として成り立たず、意味が通らない。", "木製": "材質を表す語で、分け方を表せないため、『木製に分ける』は不自然。", "小声": "声の大きさを表す語で、『小声に分ける』は意味が通らない。"}, "sentence_index": 0, "correct_answer": "均等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "綱の上で体の均等を保つのは難しい。", "explanation": "ここは〈均衡〉（つり合いが取れた状態）の意味。『体の均衡を保つ』が正しく、均等は分け方や量をそろえる意味なので合わない。"}, {"text": "テストの均等点を出した。", "explanation": "ここは〈平均〉の意味。『平均点』は数の平均を表す語で、〈均等〉とは言わない。"}, {"text": "彼女は体の均等がとれている。", "explanation": "ここは〈均整〉（つり合いのとれた形）の意味。『均整がとれている』が正しく、〈均等〉では意味が変わる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38408, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均等", "is_correct": true, "explanation": "副詞の『均等に』。荷物を同じ程度に分けて持つ意味で、文に合う。"}, {"text": "陶器", "is_correct": false, "explanation": "焼き物を表す語で、『陶器に持った』は意味が通らない。"}, {"text": "花柄", "is_correct": false, "explanation": "模様を表す語で、持ち方を表せないため、『花柄に持った』は不自然。"}, {"text": "紙製", "is_correct": false, "explanation": "材質を表す語で、『紙製に持った』は副詞として成り立たない。"}], "explanations": {"均等": "副詞の『均等に』。荷物を同じ程度に分けて持つ意味で、文に合う。", "陶器": "焼き物を表す語で、『陶器に持った』は意味が通らない。", "花柄": "模様を表す語で、持ち方を表せないため、『花柄に持った』は不自然。", "紙製": "材質を表す語で、『紙製に持った』は副詞として成り立たない。"}, "sentence_index": 6, "correct_answer": "均等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "審判は、選手に対して均等な判断をした。", "explanation": "ここは〈公正〉の意味。判断の正しさには〈公正〉を使い、〈均等〉は数や量を同じにする意味なので合わない。"}, {"text": "彼は私と均等の能力を持っている。", "explanation": "ここは〈同等〉の意味。能力や程度が同じであることには〈同等〉を使い、〈均等〉は分け方に使うので合わない。"}, {"text": "この建物は、左右が均等な形をしている。", "explanation": "ここは〈対称〉の意味。左右が同じ形になることには〈対称〉を使い、〈均等〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38408, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人で、ケーキを均等で分けた。", "corrected_sentence": "三人で、ケーキを均等に分けた。", "error_description": "『均等』を動詞『分ける』にかけるときは副詞形の『均等に』。『均等で』は断定の形で、動詞を修飾できない。『均等に』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38408, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人で、費用を均等な負担することにした。", "corrected_sentence": "二人で、費用を均等に負担することにした。", "error_description": "『負担する』を修飾するには副詞形の『均等に』。『均等な』は名詞を修飾する形なので、動詞の前に置くと文が成り立たない。『均等に』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
