INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38409, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "数量や程度が、かたよりなく同じであること。", "primary_collocate": null, "pronunciation": "きんとう", "ipa": "kʲiɴtoː", "syllable_count": 4, "sentences": [{"text": "このケーキは六つに均等に切ってある。", "target_word": "均等", "complexity_tier": "T3", "furigana": "このケーキは 六[むっ]つに 均等[きんとう]に 切[き]ってある。", "sentence_source": "generated"}, {"text": "三つの山の高さは均等で、まるで同じに見える。", "target_word": "均等", "complexity_tier": "T3", "furigana": "三[みっ]つの 山[やま]の 高[たか]さは 均等[きんとう]で、まるで 同[おな]じに 見[み]える。", "sentence_source": "generated"}, {"text": "木を均等な間隔で植えた。", "target_word": "均等", "complexity_tier": "T3", "furigana": "木[き]を 均等[きんとう]な 間隔[かんかく]で 植[う]えた。", "sentence_source": "generated"}, {"text": "均等な厚さに切ると、肉がきれいに焼ける。", "target_word": "均等", "complexity_tier": "T3", "furigana": "均等[きんとう]な 厚[あつ]さに 切[き]ると、 肉[にく]がきれいに 焼[や]ける。", "sentence_source": "generated"}, {"text": "二つのグループの人数は均等だ。", "target_word": "均等", "complexity_tier": "T3", "furigana": "二[ふた]つのグループの 人数[にんずう]は 均等[きんとう]だ。", "sentence_source": "generated"}, {"text": "絵の具をうすく均等にぬると、色がきれいに出る。", "target_word": "均等", "complexity_tier": "T3", "furigana": "絵[え]の 具[ぐ]をうすく 均等[きんとう]にぬると、 色[いろ]がきれいに 出[で]る。", "sentence_source": "generated"}, {"text": "左右の長さが均等でないので、服が曲がって見える。", "target_word": "均等", "complexity_tier": "T3", "furigana": "左右[さゆう]の 長[なが]さが 均等[きんとう]でないので、 服[ふく]が 曲[ま]がって 見[み]える。", "sentence_source": "generated"}, {"text": "光が均等に当たる場所に、植物を置いた。", "target_word": "均等", "complexity_tier": "T3", "furigana": "光[ひかり]が 均等[きんとう]に 当[あ]たる 場所[ばしょ]に、 植物[しょくぶつ]を 置[お]いた。", "sentence_source": "generated"}, {"text": "リレーの四人の走る距離は均等だった。", "target_word": "均等", "complexity_tier": "T3", "furigana": "リレーの 四人[よにん]の 走[はし]る 距離[きょり]は 均等[きんとう]だった。", "sentence_source": "generated"}, {"text": "砂糖が均等に混ざっていないので、味にむらがある。", "target_word": "均等", "complexity_tier": "T3", "furigana": "砂糖[さとう]が 均等[きんとう]に 混[ま]ざっていないので、 味[あじ]にむらがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "均等だ", "label": "終止形"}, {"form": "均等な", "label": "連体形"}, {"form": "均等に", "label": "連用形"}, {"form": "均等で", "label": "テ形（連用中止）"}], "register": "口語（普通体）", "sense_fingerprint": "数量・大きさ・程度が、かたよりなくそろっている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38409, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均等", "is_correct": true, "explanation": "形状詞「均等」の語幹。「六つに均等に切る」で、同じ大きさに分けたことを表す。"}, {"text": "新鮮", "is_correct": false, "explanation": "〈新鮮〉は鮮度が高いことで、切り方の様子としては文が成り立たない。"}, {"text": "陽気", "is_correct": false, "explanation": "〈陽気〉は明るく楽しげな性質を表し、ケーキを切る様子には合わない。"}, {"text": "冷静", "is_correct": false, "explanation": "〈冷静〉は感情に流されない様子で、切り分けの説明にはならない。"}], "explanations": {"均等": "形状詞「均等」の語幹。「六つに均等に切る」で、同じ大きさに分けたことを表す。", "新鮮": "〈新鮮〉は鮮度が高いことで、切り方の様子としては文が成り立たない。", "陽気": "〈陽気〉は明るく楽しげな性質を表し、ケーキを切る様子には合わない。", "冷静": "〈冷静〉は感情に流されない様子で、切り分けの説明にはならない。"}, "sentence_index": 0, "correct_answer": "均等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の意見は、いつも均等でまっすぐだ。", "explanation": "考えが偏らず正しいことは〈公正〉。〈均等〉は数量や程度の同じさを表すので、意見の説明には使わない。"}, {"text": "彼と私は身分が均等だ。", "explanation": "身分や地位が同じであることは〈同格〉。〈均等〉は数量や程度がそろうことなので、身分の説明には使わない。"}, {"text": "急に強い風が吹き、体の均等を失ってよろめいた。", "explanation": "体のつり合いを失う場合は〈均衡〉を使う。〈均等〉は数量の同じさを表すので、体の釣り合いには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38409, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均等", "is_correct": true, "explanation": "形状詞「均等」の語幹。「〜でない」に続けて、長さが同じでないことを表す。"}, {"text": "大胆", "is_correct": false, "explanation": "〈大胆〉は思い切りのよさを表し、長さの状態を説明しない。"}, {"text": "豪快", "is_correct": false, "explanation": "〈豪快〉は勢いがよい様子を表し、左右の長さの説明には合わない。"}, {"text": "活発", "is_correct": false, "explanation": "〈活発〉は動きが盛んなことを表し、物の長さには使わない。"}], "explanations": {"均等": "形状詞「均等」の語幹。「〜でない」に続けて、長さが同じでないことを表す。", "大胆": "〈大胆〉は思い切りのよさを表し、長さの状態を説明しない。", "豪快": "〈豪快〉は勢いがよい様子を表し、左右の長さの説明には合わない。", "活発": "〈活発〉は動きが盛んなことを表し、物の長さには使わない。"}, "sentence_index": 6, "correct_answer": "均等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "両社は均等な立場で、長く取引を続けている。", "explanation": "立場や関係が同じことは〈対等〉。〈均等〉は数量の分け方の話なので、立場には使わない。"}, {"text": "双子の服は色も柄も均等で、見分けがつかない。", "explanation": "そっくりに同じであることは〈同じ〉で表す。〈均等〉は分けた数量がかたよりなく同じことなので、この意味では使わない。"}, {"text": "彼は、いつも均等で、感情を表に出さない。", "explanation": "穏やかで感情が変わらないことは〈冷静〉。〈均等〉は数量のかたよりがないことで、性格の説明には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38409, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この机の四本の脚は長さが均等くて、がたつかない。", "corrected_sentence": "この机の四本の脚は長さが均等で、がたつかない。", "error_description": "形状詞「均等」は形容詞のように「〜くて」では続けられない。正しくは「均等で」（テ形）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "均等", "is_correct": true, "explanation": "形状詞の語幹。「三つの山の高さは均等で」のように、「で」の前に置く形。"}, {"text": "均等な", "is_correct": false, "explanation": "連体形。名詞を直接修飾する形で、「で」の前には置けない。"}, {"text": "均等に", "is_correct": false, "explanation": "連用形。「均等にで」と続くので、この文では成り立たない。"}, {"text": "均等だ", "is_correct": false, "explanation": "終止形。文末で使う形で、「均等だで」と続けられない。"}], "correct_form": "均等", "base_form": "均等だ", "form_label": "語幹（テ形「で」の前）", "sentence_index": 1, "explanations": {"均等": "形状詞の語幹。「三つの山の高さは均等で」のように、「で」の前に置く形。", "均等な": "連体形。名詞を直接修飾する形で、「で」の前には置けない。", "均等に": "連用形。「均等にで」と続くので、この文では成り立たない。", "均等だ": "終止形。文末で使う形で、「均等だで」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38409, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この棚の段の間隔は均等なで、本が落ちにくい。", "corrected_sentence": "この棚の段の間隔は均等で、本が落ちにくい。", "error_description": "形状詞「均等」の後に連体形「な」は付けず、「均等で」とする。「均等なで」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "均等", "is_correct": true, "explanation": "形状詞の語幹。「光が均等に当たる」のように、後ろの「に」の前に置く形。"}, {"text": "均等で", "is_correct": false, "explanation": "テ形。「光が均等で当たる」と続けると文が成り立たない。"}, {"text": "均等だった", "is_correct": false, "explanation": "過去の断定形。「光が均等だった当たる」と続けると文が成り立たず、後ろの「に」にもつながらない。"}, {"text": "均等でない", "is_correct": false, "explanation": "否定形。「光が均等でない当たる」は文が成り立たず、同じ程度に当たるという文の内容とも逆になる。"}], "correct_form": "均等", "base_form": "均等だ", "form_label": "語幹（連用形「に」の前）", "sentence_index": 7, "explanations": {"均等": "形状詞の語幹。「光が均等に当たる」のように、後ろの「に」の前に置く形。", "均等で": "テ形。「光が均等で当たる」と続けると文が成り立たない。", "均等だった": "過去の断定形。「光が均等だった当たる」と続けると文が成り立たず、後ろの「に」にもつながらない。", "均等でない": "否定形。「光が均等でない当たる」は文が成り立たず、同じ程度に当たるという文の内容とも逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38410, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「収穫した小麦」が話題の主題になり、「小麦は、まず粒を乾かしてから保存する」と説明する形になる。"}, {"text": "に", "is_correct": false, "explanation": "「小麦に、まず粒を乾かして保存する」は相手の形で、保存の対象として意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「小麦へ、まず粒を乾かす」は方向の文にならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「小麦を、まず粒を乾かして」は目的語が二つ重なり、文が崩れる。"}], "correct_answer": "は", "explanations": {"は": "「収穫した小麦」が話題の主題になり、「小麦は、まず粒を乾かしてから保存する」と説明する形になる。", "に": "「小麦に、まず粒を乾かして保存する」は相手の形で、保存の対象として意味が通らない。", "へ": "「へ」は方向を示す。「小麦へ、まず粒を乾かす」は方向の文にならず不自然。", "を": "「小麦を、まず粒を乾かして」は目的語が二つ重なり、文が崩れる。"}, "error_tags": {"に": "相手", "へ": "方向", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38410, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「小麦」が食べられる対象となり、「食べに来ました」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「鳥が畑の小麦が食べに来ました」と主語が重なり、食べる対象を示せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「小麦で食べに来ました」は食べる対象を示せず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「小麦から食べに来ました」は食べる対象として意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「小麦」が食べられる対象となり、「食べに来ました」の目的語を示す。", "が": "「鳥が畑の小麦が食べに来ました」と主語が重なり、食べる対象を示せず不自然。", "で": "「で」は手段や場所を示す。「小麦で食べに来ました」は食べる対象を示せず不自然。", "から": "「から」は起点を示す。「小麦から食べに来ました」は食べる対象として意味が通らない。"}, "error_tags": {"が": "主語", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38410, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "パンやめんの材料になる、小さな茶色の粒です。", "primary_collocate": null, "pronunciation": "こむぎ", "ipa": "komɯɡi", "syllable_count": 3, "sentences": [{"text": "小麦は小さくて茶色い粒です。", "target_word": "小麦", "complexity_tier": "T2", "furigana": "小麦[こむぎ]は小[ちい]さくて茶色[ちゃいろ]い粒[つぶ]です。", "sentence_source": "generated"}, {"text": "収穫した小麦は、まず粒を乾かしてから保存します。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "収穫[しゅうかく]した小麦[こむぎ]は、まず粒[つぶ]を乾[かわ]かしてから保存[ほぞん]します。", "sentence_source": "generated"}, {"text": "畑の小麦が大きくなりました。", "target_word": "小麦", "complexity_tier": "T2", "furigana": "畑[はたけ]の小麦[こむぎ]が大[おお]きくなりました。", "sentence_source": "generated"}, {"text": "この店のうどんは、国産の小麦を使っています。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "この店[みせ]のうどんは、国産[こくさん]の小麦[こむぎ]を使[つか]っています。", "sentence_source": "generated"}, {"text": "小麦を水に入れると、少しやわらかくなります。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "小麦[こむぎ]を水[みず]に入[い]れると、少[すこ]しやわらかくなります。", "sentence_source": "generated"}, {"text": "秋になったので、畑に小麦の種をまきます。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "秋[あき]になったので、畑[はたけ]に小麦[こむぎ]の種[たね]をまきます。", "sentence_source": "generated"}, {"text": "小麦がたくさんとれたので、近所の人にも分けました。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "小麦[こむぎ]がたくさんとれたので、近所[きんじょ]の人[ひと]にも分[わ]けました。", "sentence_source": "generated"}, {"text": "鳥が畑の小麦を食べに来ました。", "target_word": "小麦", "complexity_tier": "T2", "furigana": "鳥[とり]が畑[はたけ]の小麦[こむぎ]を食[た]べに来[き]ました。", "sentence_source": "generated"}, {"text": "小麦からめんを作る工場を見学しました。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "小麦[こむぎ]からめんを作[つく]る工場[こうじょう]を見学[けんがく]しました。", "sentence_source": "generated"}, {"text": "弟は小麦のアレルギーがあるので、パンは食べられません。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "弟[おとうと]は小麦[こむぎ]のアレルギーがあるので、パンは食[た]べられません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小麦", "label": "基本形"}], "register": "polite", "sense_fingerprint": "パンやめんの材料になる茶色の粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38410, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小麦", "is_correct": true, "explanation": "パンやめんの材料になる、小さく茶色い粒を指す。主語として正しい。"}, {"text": "塩", "is_correct": false, "explanation": "塩は茶色い粒ではなく、「小さくて茶色い粒です」の説明に合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は茶色い粒として食材の説明にならず、この文の主語として合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は食べられる粒ではないので、「パンやめんの材料になる粒」の説明に合わない。"}], "explanations": {"小麦": "パンやめんの材料になる、小さく茶色い粒を指す。主語として正しい。", "塩": "塩は茶色い粒ではなく、「小さくて茶色い粒です」の説明に合わない。", "鉄": "鉄は茶色い粒として食材の説明にならず、この文の主語として合わない。", "紙": "紙は食べられる粒ではないので、「パンやめんの材料になる粒」の説明に合わない。"}, "sentence_index": 0, "correct_answer": "小麦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は、国産の小麦で食器を洗っています。", "explanation": "ここは小麦を〈洗剤〉のように食器を洗う道具として扱っている。小麦は食器を洗う物ではないので合わない。"}, {"text": "この店のケーキは、国産の小麦で甘くしています。", "explanation": "「甘くする」は砂糖などの甘味料に使う。小麦は甘味料ではないので、ここでは合わない。"}, {"text": "この店は、国産の小麦を貼っています。", "explanation": "ここは小麦を〈紙やテープ〉のように扱っている。小麦は貼る物ではないので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38410, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小麦", "is_correct": true, "explanation": "畑でとれる穀物で、たくさんとれたという主語として自然に成り立つ。"}, {"text": "音", "is_correct": false, "explanation": "音は作物ではないので、「たくさんとれた」と言えず、この文の主語として合わない。"}, {"text": "言葉", "is_correct": false, "explanation": "言葉は収穫できないので、「たくさんとれたので」の主語として意味が通らない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は収穫できないので、「たくさんとれたので、近所の人にも分けました」に合わない。"}], "explanations": {"小麦": "畑でとれる穀物で、たくさんとれたという主語として自然に成り立つ。", "音": "音は作物ではないので、「たくさんとれた」と言えず、この文の主語として合わない。", "言葉": "言葉は収穫できないので、「たくさんとれたので」の主語として意味が通らない。", "夢": "夢は収穫できないので、「たくさんとれたので、近所の人にも分けました」に合わない。"}, "sentence_index": 6, "correct_answer": "小麦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟は小麦の散歩に行きました。", "explanation": "ここは小麦を〈犬〉のように連れて歩くものとして扱っている。小麦は散歩させる物ではないので、ここでは合わない。"}, {"text": "ホットケーキは、小麦を卵と混ぜて作ります。", "explanation": "ここは〈小麦粉〉の意味。卵と混ぜて作るのは粉にした小麦粉で、穀物の小麦ではないので合わない。"}, {"text": "弟は小麦をかけて本を読みます。", "explanation": "ここは小麦を〈眼鏡〉のように身につけるものとして扱っている。小麦は身につけられないので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38410, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場のめんは、北海道産の小麦で使っています。", "corrected_sentence": "この工場のめんは、北海道産の小麦を使っています。", "error_description": "「使う」は「〜を使う」で、使う対象の「小麦」には「を」を使う。「で」は道具や手段を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38410, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は畑で小麦が育てて、毎年パンを焼きます。", "corrected_sentence": "祖母は畑で小麦を育てて、毎年パンを焼きます。", "error_description": "育てる対象の「小麦」には「を」を使う。「が」だと小麦が育てる主語になり、文の関係が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38411, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「日本一の小麦の産地」と、小麦を産地の名詞に結びつける連体修飾の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「日本一の小麦を産地として」では目的語の形になり、産地の説明として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「小麦に産地として知られている」は相手の形で、産地との関係が示せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「小麦で産地として」は手段の形で、産地の説明として意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「日本一の小麦の産地」と、小麦を産地の名詞に結びつける連体修飾の形になる。", "を": "「日本一の小麦を産地として」では目的語の形になり、産地の説明として成り立たない。", "に": "「小麦に産地として知られている」は相手の形で、産地との関係が示せず不自然。", "で": "「小麦で産地として」は手段の形で、産地の説明として意味が通らない。"}, "error_tags": {"を": "目的語", "に": "相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38411, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「小麦」が主語となり、「風に揺れている」動作の主体を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「小麦へ風に揺れている」は方向の文にならず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「小麦から風に揺れている」は起点の文として意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる文の形。「小麦より風に揺れている」は比較として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「小麦」が主語となり、「風に揺れている」動作の主体を示す。", "へ": "「へ」は方向を示す。「小麦へ風に揺れている」は方向の文にならず不自然。", "から": "「から」は起点を示す。「小麦から風に揺れている」は起点の文として意味が通らない。", "より": "「より」は比べる文の形。「小麦より風に揺れている」は比較として成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38411, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小麦粉の原料となる穀物。パンやパスタなどに加工される。", "primary_collocate": null, "pronunciation": "こむぎ", "ipa": "komɯɡi", "syllable_count": 3, "sentences": [{"text": "秋の畑では、一面に黄金色の小麦が実っている。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "秋[あき]の畑[はたけ]では、一面[いちめん]に黄金色[こがねいろ]の小麦[こむぎ]が実[みの]っている。", "sentence_source": "generated"}, {"text": "北海道は日本一の小麦の産地として知られている。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "北海道[ほっかいどう]は日本一[にほんいち]の小麦[こむぎ]の産地[さんち]として知[し]られている。", "sentence_source": "generated"}, {"text": "小麦は秋に種をまき、初夏に収穫する。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "小麦[こむぎ]は秋[あき]に種[たね]をまき、初夏[しょか]に収穫[しゅうかく]する。", "sentence_source": "generated"}, {"text": "この農家は農薬を使わずに小麦を育てている。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "この農家[のうか]は農薬[のうやく]を使[つか]わずに小麦[こむぎ]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "収穫した小麦を挽いて粉にすると、パンやうどんの材料になる。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "収穫[しゅうかく]した小麦[こむぎ]を挽[ひ]いて粉[こな]にすると、パンやうどんの材料[ざいりょう]になる。", "sentence_source": "generated"}, {"text": "外国から買う小麦の値段が上がったため、パンも値上がりした。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "外国[がいこく]から買[か]う小麦[こむぎ]の値段[ねだん]が上[あ]がったため、パンも値上[ねあ]がりした。", "sentence_source": "generated"}, {"text": "小麦にはグルテンが含まれるので、アレルギーのある人は注意が必要だ。", "target_word": "小麦", "complexity_tier": "T4", "furigana": "小麦[こむぎ]にはグルテンが含[ふく]まれるので、アレルギーのある人[ひと]は注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "黄金色に実った小麦が、風に揺れている。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "黄金色[こがねいろ]に実[みの]った小麦[こむぎ]が、風[かぜ]に揺[ゆ]れている。", "sentence_source": "generated"}, {"text": "国内で使われる小麦の多くは、外国から輸入されている。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "国内[こくない]で使[つか]われる小麦[こむぎ]の多[おお]くは、外国[がいこく]から輸入[ゆにゅう]されている。", "sentence_source": "generated"}, {"text": "小麦ではなく米の粉を使ったパンも、最近は人気がある。", "target_word": "小麦", "complexity_tier": "T3", "furigana": "小麦[こむぎ]ではなく米[こめ]の粉[こな]を使[つか]ったパンも、最近[さいきん]は人気[にんき]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小麦", "label": "基本形"}], "register": "plain", "sense_fingerprint": "小麦粉の原料になる穀物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5d03ae9-b159-42d0-9195-de0f63374e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38411, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小麦", "is_correct": true, "explanation": "畑で実る穀物を指す「小麦」が主語になり、黄金色に実っている文として成り立つ。"}, {"text": "石", "is_correct": false, "explanation": "石は植物ではないので、畑で実ることはなく、この文には合わない。"}, {"text": "塩", "is_correct": false, "explanation": "塩は植物ではないので、畑で実る文の主語にならない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は植物ではないので、黄金色に実るという文には合わない。"}], "explanations": {"小麦": "畑で実る穀物を指す「小麦」が主語になり、黄金色に実っている文として成り立つ。", "石": "石は植物ではないので、畑で実ることはなく、この文には合わない。", "塩": "塩は植物ではないので、畑で実る文の主語にならない。", "鉄": "鉄は植物ではないので、黄金色に実るという文には合わない。"}, "sentence_index": 0, "correct_answer": "小麦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寿司職人が小麦を握っている。", "explanation": "ここは小麦を〈ご飯〉と同じように扱っている。ご飯は握って形にするが、小麦は握れる食材ではないので、ここでは合わない。"}, {"text": "子どもが小麦を一杯飲んだ。", "explanation": "ここは小麦を〈飲み物〉のように扱っている。小麦は穀物で、一杯飲むものではないので合わない。"}, {"text": "小麦を水で溶いて、薄く焼く。", "explanation": "ここは〈小麦粉〉の意味。水で溶いて薄く焼くのは粉にした小麦粉で、穀物の小麦は溶けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38411, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小麦", "is_correct": true, "explanation": "小麦にはグルテンが含まれ、アレルギーに注意が必要な食材として使われる。"}, {"text": "水", "is_correct": false, "explanation": "水にグルテンが含まれるとは言えず、「グルテンが含まれるので」の主語として意味が通らない。"}, {"text": "空気", "is_correct": false, "explanation": "空気にグルテンが含まれるとは言えず、文の主語として成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "紙にグルテンが含まれるとは言えず、アレルギーの注意として意味が通らない。"}], "explanations": {"小麦": "小麦にはグルテンが含まれ、アレルギーに注意が必要な食材として使われる。", "水": "水にグルテンが含まれるとは言えず、「グルテンが含まれるので」の主語として意味が通らない。", "空気": "空気にグルテンが含まれるとは言えず、文の主語として成り立たない。", "紙": "紙にグルテンが含まれるとは言えず、アレルギーの注意として意味が通らない。"}, "sentence_index": 6, "correct_answer": "小麦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小麦は毎晩、布団で眠る。", "explanation": "ここは小麦を〈人や動物〉のように扱っている。小麦は穀物で、布団で眠ることはないので合わない。"}, {"text": "祖母が小麦を抱いて、あやした。", "explanation": "ここは小麦を〈赤ちゃん〉のように扱っている。小麦は抱いてあやす相手ではないので、ここでは合わない。"}, {"text": "海で小麦が泳いでいる。", "explanation": "ここは小麦を〈魚や人〉のように自分で動く生き物として扱っている。小麦は海で泳がないので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38411, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この農家は秋に小麦が種をまき、初夏に収穫する。", "corrected_sentence": "この農家は秋に小麦の種をまき、初夏に収穫する。", "error_description": "「小麦の種」と言うときは「の」で結ぶ。「小麦が」とすると小麦が種をまく主語になり、文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38411, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パンを作るのに使う小麦に、農家は畑で育てている。", "corrected_sentence": "パンを作るのに使う小麦を、農家は畑で育てている。", "error_description": "育てる対象の「小麦」には「を」を使う。「に」では相手の形になり、育てる対象として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2131f5d9-2af0-4630-957e-e15b1965985f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38412, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "対象。「作物に水をやる」で、水をやる相手を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的格。「水を」がすでにあるため、「を」が二重になり文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主格。「作物が水をやる」では主語が不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段。「作物で水をやる」は意味が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "対象。「作物に水をやる」で、水をやる相手を表す。", "を": "目的格。「水を」がすでにあるため、「を」が二重になり文が成り立たない。", "が": "主格。「作物が水をやる」では主語が不自然になる。", "で": "場所・手段。「作物で水をやる」は意味が成り立たない。"}, "error_tags": {"を": "目的語の重複", "が": "主語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
