INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38412, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "畑で育てる食べ物や植物のこと。", "primary_collocate": null, "pronunciation": "さくもつ", "ipa": "sakɯmotsɯ", "syllable_count": 4, "sentences": [{"text": "祖父は畑でいろいろな作物を育てています。", "target_word": "作物", "complexity_tier": "T3", "furigana": "祖父[そふ]は畑[はたけ]でいろいろな作物[さくもつ]を育[そだ]てています。", "sentence_source": "generated"}, {"text": "夏は暑いので、作物に毎日水をやります。", "target_word": "作物", "complexity_tier": "T3", "furigana": "夏[なつ]は暑[あつ]いので、作物[さくもつ]に毎日[まいにち]水[みず]をやります。", "sentence_source": "generated"}, {"text": "作物が大きくなったら、みんなで収穫します。", "target_word": "作物", "complexity_tier": "T3", "furigana": "作物[さくもつ]が大[おお]きくなったら、みんなで収穫[しゅうかく]します。", "sentence_source": "generated"}, {"text": "雨がたくさん降って、畑の作物が元気に育ちました。", "target_word": "作物", "complexity_tier": "T3", "furigana": "雨[あめ]がたくさん降[ふ]って、畑[はたけ]の作物[さくもつ]が元気[げんき]に育[そだ]ちました。", "sentence_source": "generated"}, {"text": "この畑では、トマトやナスなどの作物を作っています。", "target_word": "作物", "complexity_tier": "T3", "furigana": "この畑[はたけ]では、トマトやナスなどの作物[さくもつ]を作[つく]っています。", "sentence_source": "generated"}, {"text": "虫が多くて、作物の葉が食べられてしまいました。", "target_word": "作物", "complexity_tier": "T3", "furigana": "虫[むし]が多[おお]くて、作物[さくもつ]の葉[は]が食[た]べられてしまいました。", "sentence_source": "generated"}, {"text": "冬は寒すぎて、畑でほとんど作物が育ちません。", "target_word": "作物", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]すぎて、畑[はたけ]でほとんど作物[さくもつ]が育[そだ]ちません。", "sentence_source": "generated"}, {"text": "農家の人は朝早く、作物の様子を見に行きます。", "target_word": "作物", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は朝[あさ]早[はや]く、作物[さくもつ]の様子[ようす]を見[み]に行[い]きます。", "sentence_source": "generated"}, {"text": "学校の畑で育てた作物を、給食で食べました。", "target_word": "作物", "complexity_tier": "T3", "furigana": "学校[がっこう]の畑[はたけ]で育[そだ]てた作物[さくもつ]を、給食[きゅうしょく]で食[た]べました。", "sentence_source": "generated"}, {"text": "霜が降りる前に、作物にビニールをかけておきましょう。", "target_word": "作物", "complexity_tier": "T3", "furigana": "霜[しも]が降[お]りる前[まえ]に、作物[さくもつ]にビニールをかけておきましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "作物", "label": "基本形"}], "register": "中立", "sense_fingerprint": "畑で育てるトマトや野菜などの食べ物や植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38412, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作物", "is_correct": true, "explanation": "名詞。畑で育てる植物を指し、「育てています」の対象として文が成り立つ。"}, {"text": "天候", "is_correct": false, "explanation": "名詞。気象を指すので、育てる対象としては意味が合わない。"}, {"text": "雨", "is_correct": false, "explanation": "名詞。降るものなので、育てる対象としては合わない。"}, {"text": "気温", "is_correct": false, "explanation": "名詞。測るものなので、育てる対象としては合わない。"}], "explanations": {"作物": "名詞。畑で育てる植物を指し、「育てています」の対象として文が成り立つ。", "天候": "名詞。気象を指すので、育てる対象としては意味が合わない。", "雨": "名詞。降るものなので、育てる対象としては合わない。", "気温": "名詞。測るものなので、育てる対象としては合わない。"}, "sentence_index": 0, "correct_answer": "作物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この牧場では、羊を作物として毛を刈っている。", "explanation": "ここは〈家畜〉の意味。作物は植物を指すので、羊には使わない。"}, {"text": "その研究は大きな作物を残した。", "explanation": "ここは〈成果〉の意味。作物は畑で育てる植物で、研究の結果には使わない。"}, {"text": "川では石を作物として採取している。", "explanation": "ここは〈石〉の意味。作物は植物を指すので、石には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
