INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38414, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときに、どうやったらうまくいくか考えること。", "primary_collocate": null, "pronunciation": "くふう", "ipa": "kɯ̥ɸɯː", "syllable_count": 3, "sentences": [{"text": "工夫が大事だ。", "target_word": "工夫", "complexity_tier": "T1", "furigana": "工夫[くふう]が大事[だいじ]だ。", "sentence_source": "generated"}, {"text": "毎日、工夫しています。", "target_word": "工夫", "complexity_tier": "T2", "furigana": "毎日[まいにち]、工夫[くふう]しています。", "sentence_source": "generated"}, {"text": "勉強のやり方を工夫した。", "target_word": "工夫", "complexity_tier": "T2", "furigana": "勉強[べんきょう]のやり方[かた]を工夫[くふう]した。", "sentence_source": "generated"}, {"text": "雨の日は、遊び方に工夫が必要です。", "target_word": "工夫", "complexity_tier": "T2", "furigana": "雨[あめ]の日[ひ]は、遊[あそ]び方[かた]に工夫[くふう]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "もう少し工夫すれば、早く終わるはずだ。", "target_word": "工夫", "complexity_tier": "T4", "furigana": "もう少[すこ]し工夫[くふう]すれば、早[はや]く終[お]わるはずだ。", "sentence_source": "generated"}, {"text": "小さな工夫で、毎日の生活が楽になった。", "target_word": "工夫", "complexity_tier": "T3", "furigana": "小[ちい]さな工夫[くふう]で、毎日[まいにち]の生活[せいかつ]が楽[らく]になった。", "sentence_source": "generated"}, {"text": "工夫して、忘れ物をなくすようにしている。", "target_word": "工夫", "complexity_tier": "T3", "furigana": "工夫[くふう]して、忘[わす]れ物[もの]をなくすようにしている。", "sentence_source": "generated"}, {"text": "彼は教え方を工夫することで、生徒の成績を上げた。", "target_word": "工夫", "complexity_tier": "T4", "furigana": "彼[かれ]は教[おし]え方[かた]を工夫[くふう]することで、生徒[せいと]の成績[せいせき]を上[あ]げた。", "sentence_source": "generated"}, {"text": "どんな工夫をしたら、もっとうまくいくか考えている。", "target_word": "工夫", "complexity_tier": "T4", "furigana": "どんな工夫[くふう]をしたら、もっとうまくいくか考[かんが]えている。", "sentence_source": "generated"}, {"text": "工夫と練習を続けた人だけが、この難しい曲を弾けるようになる。", "target_word": "工夫", "complexity_tier": "T5", "furigana": "工夫[くふう]と練習[れんしゅう]を続[つづ]けた人[ひと]だけが、この難[むずか]しい曲[きょく]を弾[ひ]けるようになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工夫する", "label": "派生"}, {"form": "工夫して", "label": "活用"}, {"form": "工夫した", "label": "活用"}, {"form": "工夫すれば", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | うまくやる方法を考えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
