INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38415, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足りる」は「～が足りない」の形をとるので「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「足りません」は「を」で対象をとれず、非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「工夫へ足りません」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、「工夫と足りません」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「足りる」は「～が足りない」の形をとるので「が」が正しい。", "を": "「足りません」は「を」で対象をとれず、非文になる。", "へ": "「へ」は方向を表し、「工夫へ足りません」は成り立たない。", "と": "「と」は並列や相手を表し、「工夫と足りません」は成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38415, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「努力と工夫の結果」で、名詞をつなぐ「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「工夫を結果です」は非文で、「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「工夫へ結果です」は方向の助詞が合わず非文。"}, {"text": "に", "is_correct": false, "explanation": "「工夫に結果です」は「結果です」とつながらず非文。"}], "correct_answer": "の", "explanations": {"の": "「努力と工夫の結果」で、名詞をつなぐ「の」が正しい。", "を": "「工夫を結果です」は非文で、「を」は使えない。", "へ": "「工夫へ結果です」は方向の助詞が合わず非文。", "に": "「工夫に結果です」は「結果です」とつながらず非文。"}, "error_tags": {"を": "object", "へ": "direction", "に": "target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38415, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目的を達成するために、方法や手段を考え出したり、改良したりすること。", "primary_collocate": null, "pronunciation": "くふう", "ipa": "kɯ̥ɸɯː", "syllable_count": 3, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "工夫", "complexity_tier": "T6", "furigana": "成功[せいこう]の鍵[かぎ]は、商品[しょうひん]の魅力[みりょく]を伝[つた]える写真[しゃしん]の工夫[くふう]と、ターゲット層[そう]に届[とど]けるマーケティングです。", "sentence_source": "mined"}, {"text": "この説明には工夫が足りません。", "target_word": "工夫", "complexity_tier": "T2", "furigana": "この説明[せつめい]には工夫[くふう]が足[た]りません。", "sentence_source": "generated"}, {"text": "母は野菜を食べやすくする工夫をしています。", "target_word": "工夫", "complexity_tier": "T3", "furigana": "母[はは]は野菜[やさい]を食[た]べやすくする工夫[くふう]をしています。", "sentence_source": "generated"}, {"text": "少しの工夫で、部屋が広く見えます。", "target_word": "工夫", "complexity_tier": "T2", "furigana": "少[すこ]しの工夫[くふう]で、部屋[へや]が広[ひろ]く見[み]えます。", "sentence_source": "generated"}, {"text": "先生は、授業を楽しくするために工夫している。", "target_word": "工夫", "complexity_tier": "T3", "furigana": "先生[せんせい]は、授業[じゅぎょう]を楽[たの]しくするために工夫[くふう]している。", "sentence_source": "generated"}, {"text": "この箱には、持ち運びやすくする工夫がある。", "target_word": "工夫", "complexity_tier": "T3", "furigana": "この箱[はこ]には、持[も]ち運[はこ]びやすくする工夫[くふう]がある。", "sentence_source": "generated"}, {"text": "工夫すれば、安く作ることができる。", "target_word": "工夫", "complexity_tier": "T4", "furigana": "工夫[くふう]すれば、安[やす]く作[つく]ることができる。", "sentence_source": "generated"}, {"text": "努力と工夫の結果です。", "target_word": "工夫", "complexity_tier": "T2", "furigana": "努力[どりょく]と工夫[くふう]の結果[けっか]です。", "sentence_source": "generated"}, {"text": "工夫を重ねて、ようやく新しい道具が完成した。", "target_word": "工夫", "complexity_tier": "T3", "furigana": "工夫[くふう]を重[かさ]ねて、ようやく新[あたら]しい道具[どうぐ]が完成[かんせい]した。", "sentence_source": "generated"}, {"text": "よく工夫されたデザインが賞を取った。", "target_word": "工夫", "complexity_tier": "T4", "furigana": "よく工夫[くふう]されたデザインが賞[しょう]を取[と]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工夫する", "label": "派生"}, {"form": "工夫して", "label": "活用"}, {"form": "工夫した", "label": "活用"}, {"form": "工夫される", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 方法や手段を考え改良すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38415, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "工夫", "is_correct": true, "explanation": "「くふう」は見出し語そのもの。"}, {"text": "古風", "is_correct": false, "explanation": "「こふう」は最初の音が「こ」で、「くふう」と一音違う別の語。"}, {"text": "苦労", "is_correct": false, "explanation": "「くろう」は二音目が「ろ」で、「くふう」と一音違う別の語。"}, {"text": "苦闘", "is_correct": false, "explanation": "「くとう」は二音目が「と」で、「くふう」と一音違う別の語。"}, {"text": "気風", "is_correct": false, "explanation": "「きふう」は最初の音が「き」で、「くふう」と一音違う別の語。"}], "explanations": {"工夫": "「くふう」は見出し語そのもの。", "古風": "「こふう」は最初の音が「こ」で、「くふう」と一音違う別の語。", "苦労": "「くろう」は二音目が「ろ」で、「くふう」と一音違う別の語。", "苦闘": "「くとう」は二音目が「と」で、「くふう」と一音違う別の語。", "気風": "「きふう」は最初の音が「き」で、「くふう」と一音違う別の語。"}, "sentence_index": null, "correct_answer": "工夫"}, "level_3": {"options": [{"text": "工夫", "is_correct": true, "explanation": "魅力を伝えるための写真の「工夫」で、意味が合う。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、写真の重さは魅力を伝える鍵として意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「魅力を伝える写真の季節」では意味が合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、写真の湿度は魅力を伝えることと関係せず意味が合わない。"}], "explanations": {"工夫": "魅力を伝えるための写真の「工夫」で、意味が合う。", "重さ": "形は合うが、写真の重さは魅力を伝える鍵として意味が合わない。", "季節": "形は合うが、「魅力を伝える写真の季節」では意味が合わない。", "湿度": "形は合うが、写真の湿度は魅力を伝えることと関係せず意味が合わない。"}, "sentence_index": 0, "correct_answer": "工夫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、工夫を食べてから学校に行きます。", "explanation": "「工夫」は考えや方法のことで、食べ物ではないので「食べる」の目的語にならない。"}, {"text": "昨日の台風で、工夫が大きく壊れました。", "explanation": "「工夫」は形のある物のように壊れるものではなく、具体物として使うのは誤り。"}, {"text": "工夫の高さは百メートルです。", "explanation": "「工夫」は考えや方法で、高さを測れる建物や山のような物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38415, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "工夫", "is_correct": true, "explanation": "「くふう」は見出し語そのもの。"}, {"text": "家風", "is_correct": false, "explanation": "「かふう」は最初の音が「か」で、「くふう」と一音違う別の語。"}, {"text": "駆動", "is_correct": false, "explanation": "「くどう」は二音目が「ど」で、「くふう」と一音違う別の語。"}, {"text": "供養", "is_correct": false, "explanation": "「くよう」は二音目が「よ」で、「くふう」と一音違う別の語。"}], "explanations": {"工夫": "「くふう」は見出し語そのもの。", "家風": "「かふう」は最初の音が「か」で、「くふう」と一音違う別の語。", "駆動": "「くどう」は二音目が「ど」で、「くふう」と一音違う別の語。", "供養": "「くよう」は二音目が「よ」で、「くふう」と一音違う別の語。"}, "sentence_index": null, "correct_answer": "工夫"}, "level_3": {"options": [{"text": "工夫", "is_correct": true, "explanation": "「工夫すれば安く作れる」で、意味が合う。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除すれば」は形は合うが、それで安く作れるという意味にならない。"}, {"text": "昼寝", "is_correct": false, "explanation": "「昼寝すれば」は形は合うが、安く作ることにつながらず意味が合わない。"}, {"text": "遅刻", "is_correct": false, "explanation": "「遅刻すれば」は形は合うが、安く作れる理由にならず意味が合わない。"}], "explanations": {"工夫": "「工夫すれば安く作れる」で、意味が合う。", "掃除": "「掃除すれば」は形は合うが、それで安く作れるという意味にならない。", "昼寝": "「昼寝すれば」は形は合うが、安く作ることにつながらず意味が合わない。", "遅刻": "「遅刻すれば」は形は合うが、安く作れる理由にならず意味が合わない。"}, "sentence_index": 6, "correct_answer": "工夫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工夫は冷蔵庫の中で冷やすとおいしいです。", "explanation": "「工夫」は考えや方法で、冷やして味わう食べ物ではない。"}, {"text": "試合に負けて、悔しくて工夫が出た。", "explanation": "「出る」のは涙などで、考えや方法である「工夫」は体から出ない。"}, {"text": "父は毎朝、新聞と工夫を読んでいます。", "explanation": "「工夫」は読む対象の文章ではなく、「読む」の目的語として使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38415, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は掃除が楽になる工夫をあります。", "corrected_sentence": "母は掃除が楽になる工夫をしています。", "error_description": "「工夫を」に続く動詞が「あります」では誤り。「工夫をする」の形にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38415, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道具には、使いやすくする工夫にされている。", "corrected_sentence": "この道具には、使いやすくする工夫がされている。", "error_description": "「工夫」は「される」の主語なので、助詞は「に」ではなく「が」。「工夫がされている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
