INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38416, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの百のこと。", "primary_collocate": null, "pronunciation": "なんびゃく", "ipa": "naɴbʲaku", "syllable_count": 4, "sentences": [{"text": "図書館には、古い本が何百もあります。", "target_word": "何百", "complexity_tier": "T3", "furigana": "図書館[としょかん]には、古[ふる]い本[ほん]が何百[なんびゃく]もあります。", "sentence_source": "generated"}, {"text": "山の上から見ると、何百という家の屋根が見えた。", "target_word": "何百", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]から見[み]ると、何百[なんびゃく]という家[いえ]の屋根[やね]が見[み]えた。", "sentence_source": "generated"}, {"text": "この店では、毎日何百も売れるパンがあるそうです。", "target_word": "何百", "complexity_tier": "T3", "furigana": "この店[みせ]では、毎日[まいにち]何百[なんびゃく]も売[う]れるパンがあるそうです。", "sentence_source": "generated"}, {"text": "祭りの夜、川に何百ものランタンが浮かんだ。", "target_word": "何百", "complexity_tier": "T3", "furigana": "祭[まつ]りの夜[よる]、川[かわ]に何百[なんびゃく]ものランタンが浮[う]かんだ。", "sentence_source": "generated"}, {"text": "手紙を何百も書いて、やっと全員に送り終えた。", "target_word": "何百", "complexity_tier": "T3", "furigana": "手紙[てがみ]を何百[なんびゃく]も書[か]いて、やっと全員[ぜんいん]に送[おく]り終[お]えた。", "sentence_source": "generated"}, {"text": "森の中には、何百ものホタルが光っていた。", "target_word": "何百", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]には、何百[なんびゃく]ものホタルが光[ひか]っていた。", "sentence_source": "generated"}, {"text": "一度に何百も注文が来て、店は大いそがしだった。", "target_word": "何百", "complexity_tier": "T3", "furigana": "一度[いちど]に何百[なんびゃく]も注文[ちゅうもん]が来[き]て、店[みせ]は大[おお]いそがしだった。", "sentence_source": "generated"}, {"text": "駅前の広場に、何百もの人が集まっている。", "target_word": "何百", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の広場[ひろば]に、何百[なんびゃく]もの人[ひと]が集[あつ]まっている。", "sentence_source": "generated"}, {"text": "畑には何百もの花が咲いていて、とてもきれいだ。", "target_word": "何百", "complexity_tier": "T3", "furigana": "畑[はたけ]には何百[なんびゃく]もの花[はな]が咲[さ]いていて、とてもきれいだ。", "sentence_source": "generated"}, {"text": "彼は昔の写真を何百も集めている。", "target_word": "何百", "complexity_tier": "T3", "furigana": "彼[かれ]は昔[むかし]の写真[しゃしん]を何百[なんびゃく]も集[あつ]めている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "何百", "label": "基本形"}, {"form": "何百も", "label": "強調"}, {"form": "何百もの", "label": "連体形"}, {"form": "何百という", "label": "連体形"}], "register": "一般", "sense_fingerprint": "百がいくつも集まった、はっきりしない多い数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: いそがし (Zipf 1.83)']::text[], 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38416, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "何百", "is_correct": true, "explanation": "『何百も』で本がたくさんあることを表し、文に合う。"}, {"text": "何時", "is_correct": false, "explanation": "何時は時刻や時期をたずねる語。本の数の強調には使えない。"}, {"text": "何番", "is_correct": false, "explanation": "何番は順番をたずねる語。本の数には合わない。"}, {"text": "何人", "is_correct": false, "explanation": "何人は人の数を表す語。本の数には使えない。"}], "explanations": {"何百": "『何百も』で本がたくさんあることを表し、文に合う。", "何時": "何時は時刻や時期をたずねる語。本の数の強調には使えない。", "何番": "何番は順番をたずねる語。本の数には合わない。", "何人": "何人は人の数を表す語。本の数には使えない。"}, "sentence_index": 0, "correct_answer": "何百"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あなたは、何百が一番好きですか。", "explanation": "ここは〈何〉（ものをたずねる語）の意味。何百は数量の多さを表すので、『何が一番好きか』をたずねる語としては使わない。"}, {"text": "会場には、ちょうど何百人の客が来た。", "explanation": "ここは〈ちょうど百〉の意味。『何百』は数がはっきりしない多さを表すので、『ちょうど』とは合わない。"}, {"text": "畑には何百が咲いている。", "explanation": "ここは花そのものを指す名詞の用法。『何百』は数量を表す語で、『何百もの花』の形でしか花を修飾できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38416, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何百", "is_correct": true, "explanation": "『一度に何百も』で注文が多く来たことを表し、文に合う。"}, {"text": "何月", "is_correct": false, "explanation": "何月は月をたずねる語。注文の数には合わない。"}, {"text": "何歳", "is_correct": false, "explanation": "何歳は年齢をたずねる語。注文には使わない。"}, {"text": "何語", "is_correct": false, "explanation": "何語は言語名をたずねる語。注文の数の強調にはならない。"}], "explanations": {"何百": "『一度に何百も』で注文が多く来たことを表し、文に合う。", "何月": "何月は月をたずねる語。注文の数には合わない。", "何歳": "何歳は年齢をたずねる語。注文には使わない。", "何語": "何語は言語名をたずねる語。注文の数の強調にはならない。"}, "sentence_index": 6, "correct_answer": "何百"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日は写真を、きっかり何百枚整理した。", "explanation": "ここは〈きっかり〉（数を正確に示す）の意味。何百は数がはっきりしない多さを表すので、正確な数を示す『きっかり』とは合わない。"}, {"text": "彼は昔の写真を何百が持っている。", "explanation": "『何百』は数量を表す語で、『写真』そのものを指す名詞としては使えない。"}, {"text": "彼は昔の写真を何百で集めている。", "explanation": "『何百』に『で』を付けて手段を表すのは不自然。『何百も集めている』の形が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38416, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りの会場には、何百を人が集まっている。", "corrected_sentence": "祭りの会場には、何百もの人が集まっている。", "error_description": "『何百』に続く『もの』を『を』に変えた誤り。『何百もの人』と人を修飾するのが正しく、目的語の『を』は文に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38416, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方、一度に何百だ注文が来た。", "corrected_sentence": "夕方、一度に何百もの注文が来た。", "error_description": "『何百』は名詞なので、名詞を修飾するには『もの』が必要。『何百もの注文』と修飾するのが正しく、『だ』のままでは修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
