INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38417, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数が百の何倍もあること。非常に多い数量を表す。", "primary_collocate": null, "pronunciation": "なんびゃく", "ipa": "naɴbʲaku", "syllable_count": 4, "sentences": [{"text": "工場では、毎日何百もの部品を作っている。", "target_word": "何百", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、毎日[まいにち]何百[なんびゃく]もの部品[ぶひん]を作[つく]っている。", "sentence_source": "generated"}, {"text": "何百もの質問が届いて、先生は答えきれなかった。", "target_word": "何百", "complexity_tier": "T3", "furigana": "何百[なんびゃく]もの質問[しつもん]が届[とど]いて、先生[せんせい]は答[こた]えきれなかった。", "sentence_source": "generated"}, {"text": "何百ものファンが、空港で歌手を待っていた。", "target_word": "何百", "complexity_tier": "T3", "furigana": "何百[なんびゃく]ものファンが、空港[くうこう]で歌手[かしゅ]を待[ま]っていた。", "sentence_source": "generated"}, {"text": "海岸には、何百もの貝がらが落ちていた。", "target_word": "何百", "complexity_tier": "T3", "furigana": "海岸[かいがん]には、何百[なんびゃく]もの貝[かい]がらが落[お]ちていた。", "sentence_source": "generated"}, {"text": "この町には、何百という古い神社がある。", "target_word": "何百", "complexity_tier": "T3", "furigana": "この町[まち]には、何百[なんびゃく]という古[ふる]い神社[じんじゃ]がある。", "sentence_source": "generated"}, {"text": "大雨のあと、何百もの家が水につかった。", "target_word": "何百", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のあと、何百[なんびゃく]もの家[いえ]が水[みず]につかった。", "sentence_source": "generated"}, {"text": "彼女の部屋には、何百もの人形が並んでいる。", "target_word": "何百", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の部屋[へや]には、何百[なんびゃく]もの人形[にんぎょう]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "新しい店には、開店の日に何百もの客が来た。", "target_word": "何百", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]には、開店[かいてん]の日[ひ]に何百[なんびゃく]もの客[きゃく]が来[き]た。", "sentence_source": "generated"}, {"text": "空を見上げると、何百もの星が輝いていた。", "target_word": "何百", "complexity_tier": "T3", "furigana": "空[そら]を見上[みあ]げると、何百[なんびゃく]もの星[ほし]が輝[かがや]いていた。", "sentence_source": "generated"}, {"text": "朝からずっと、何百ものメールを読んで返事を書いた。", "target_word": "何百", "complexity_tier": "T3", "furigana": "朝[あさ]からずっと、何百[なんびゃく]ものメールを読[よ]んで返事[へんじ]を書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "何百", "label": "基本形"}, {"form": "何百も", "label": "強調"}, {"form": "何百もの", "label": "連体形"}, {"form": "何百という", "label": "連体形"}], "register": "一般", "sense_fingerprint": "百の何倍にもなる、非常に多い数量を強調する言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: 貝がら (Zipf 1.93)']::text[], 'c97a8239-3cf4-4e80-8342-64a5a5f3c741') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38417, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "何百", "is_correct": true, "explanation": "『毎日何百もの』で部品が非常に多いことを表し、文に合う。"}, {"text": "何時", "is_correct": false, "explanation": "何時は時刻をたずねる語。部品の数には合わない。"}, {"text": "何語", "is_correct": false, "explanation": "何語は言語名をたずねる語。ここには合わない。"}, {"text": "何歳", "is_correct": false, "explanation": "何歳は年齢をたずねる語。部品には使わない。"}], "explanations": {"何百": "『毎日何百もの』で部品が非常に多いことを表し、文に合う。", "何時": "何時は時刻をたずねる語。部品の数には合わない。", "何語": "何語は言語名をたずねる語。ここには合わない。", "何歳": "何歳は年齢をたずねる語。部品には使わない。"}, "sentence_index": 0, "correct_answer": "何百"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の好きな何百は、すしです。", "explanation": "ここは〈何〉（ものを指す語）の意味。何百は数量の多さを表すので、ものを指す『何』とは合わない。"}, {"text": "この箱には、ちょうど何百個の部品が入っている。", "explanation": "ここは〈ちょうど百〉の意味。『何百』は数がはっきりしない多さを表すので、『ちょうど』とは合わない。"}, {"text": "倉庫には何百が並んでいる。", "explanation": "『何百』は数量を表す語で、『箱』そのものを指す名詞としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38417, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何百", "is_correct": true, "explanation": "『何百もの』で人形がたくさん並んでいることを表し、文に合う。"}, {"text": "何番", "is_correct": false, "explanation": "何番は順番をたずねる語。人形の数には合わない。"}, {"text": "何人", "is_correct": false, "explanation": "何人は人の数をたずねる語。人形には使えない。"}, {"text": "何月", "is_correct": false, "explanation": "何月は月をたずねる語。ここには合わない。"}], "explanations": {"何百": "『何百もの』で人形がたくさん並んでいることを表し、文に合う。", "何番": "何番は順番をたずねる語。人形の数には合わない。", "何人": "何人は人の数をたずねる語。人形には使えない。", "何月": "何月は月をたずねる語。ここには合わない。"}, "sentence_index": 6, "correct_answer": "何百"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議には、ぴったり何百人が集まった。", "explanation": "ここは〈ぴったり〉（数を正確に示す）の意味。何百は数がはっきりしない多さを表すので、正確な数とは合わない。"}, {"text": "朝からずっと、何百を読んで返事を書いた。", "explanation": "『何百』は数量を表す語で、『何百ものメール』の形でなければ目的語として不自然。"}, {"text": "朝からずっと、きっかり何百通のメールを読んで返事を書いた。", "explanation": "ここは〈きっかり〉の意味で数を正確に示す。『何百』は数がはっきりしない多さを表すので、正確な数の『きっかり』とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38417, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "倉庫には、毎日何百で箱が届く。", "corrected_sentence": "倉庫には、毎日何百もの箱が届く。", "error_description": "『もの』を『で』に変えた誤り。『何百もの箱』と修飾するのが正しく、『で』は手段や場所を示すので文に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38417, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の本棚には、何百な絵本が並んでいる。", "corrected_sentence": "彼女の本棚には、何百もの絵本が並んでいる。", "error_description": "『何百』は名詞なので『な』では続かない。『もの』を使って『何百もの絵本』と修飾するのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a06ad3fe-6c2c-4a3a-98f6-985ce675e452') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38418, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「四年に一度」の「に」は、間隔を表す格助詞で、四年という期間に続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すため、「四年を一度になります」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「四年と一度」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「四年へ一度」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「四年に一度」の「に」は、間隔を表す格助詞で、四年という期間に続く。", "を": "「を」は目的語を示すため、「四年を一度になります」は成り立たない。", "と": "「と」は並列や相手を示すため、「四年と一度」は不自然。", "へ": "「へ」は方向を示すため、「四年へ一度」は成り立たない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38418, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38418, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一年の長さ。", "primary_collocate": null, "pronunciation": "ねん", "ipa": "neɴ", "syllable_count": 2, "sentences": [{"text": "このカレンダーは、一年の長さを三百六十五日として作られています。", "target_word": "年", "complexity_tier": "T3", "furigana": "このカレンダーは、一年[いちねん]の長[なが]さを三百[さんびゃく]六十五日[ろくじゅうごにち]として作[つく]られています。", "sentence_source": "generated"}, {"text": "四年に一度、一年が三百六十六日になります。", "target_word": "年", "complexity_tier": "T3", "furigana": "四年[よねん]に一度[いちど]、一年[いちねん]が三百[さんびゃく]六十六日[ろくじゅうろくにち]になります。", "sentence_source": "generated"}, {"text": "病気で入院して、二年があっという間に過ぎました。", "target_word": "年", "complexity_tier": "T3", "furigana": "病気[びょうき]で入院[にゅういん]して、二年[にねん]があっという間[ま]に過[す]ぎました。", "sentence_source": "generated"}, {"text": "木が実をつけるまでには、少なくとも五年はかかります。", "target_word": "年", "complexity_tier": "T3", "furigana": "木[き]が実[み]をつけるまでには、少[すく]なくとも五年[ごねん]はかかります。", "sentence_source": "generated"}, {"text": "彼は十年も同じ会社で働き続けています。", "target_word": "年", "complexity_tier": "T3", "furigana": "彼[かれ]は十年[じゅうねん]も同[おな]じ会社[かいしゃ]で働[はたら]き続[つづ]けています。", "sentence_source": "generated"}, {"text": "契約は一年ごとに更新するので、来月手続きをします。", "target_word": "年", "complexity_tier": "T3", "furigana": "契約[けいやく]は一年[いちねん]ごとに更新[こうしん]するので、来月[らいげつ]手続[てつづ]きをします。", "sentence_source": "generated"}, {"text": "三年も待ったのだから、もう少しだけ我慢しましょう。", "target_word": "年", "complexity_tier": "T3", "furigana": "三年[さんねん]も待[ま]ったのだから、もう少[すこ]しだけ我慢[がまん]しましょう。", "sentence_source": "generated"}, {"text": "母は半年ではなく、まるまる一年かけて布を織りました。", "target_word": "年", "complexity_tier": "T3", "furigana": "母[はは]は半年[はんとし]ではなく、まるまる一年[いちねん]かけて布[ぬの]を織[お]りました。", "sentence_source": "generated"}, {"text": "この制度ができてから、まだ二年しかたっていません。", "target_word": "年", "complexity_tier": "T3", "furigana": "この制度[せいど]ができてから、まだ二年[にねん]しかたっていません。", "sentence_source": "generated"}, {"text": "大人になると、一年があっという間に過ぎてしまいます。", "target_word": "年", "complexity_tier": "T3", "furigana": "大人[おとな]になると、一[いち]年[ねん]があっという間[あっというま]に過[す]ぎてしまいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年", "label": "基本形"}], "register": "中立", "sense_fingerprint": "一年という期間の長さ。数字の後ろにつけて、何年続くか、何年かかるかを表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38418, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年", "is_correct": true, "explanation": "「一年の長さ」は、一年という期間の長さを表すので空所に入る。"}, {"text": "冊", "is_correct": false, "explanation": "「冊」は本を数える単位で、「一冊の長さ」とは言わない。"}, {"text": "台", "is_correct": false, "explanation": "「台」は機械や車を数える単位で、「一台の長さ」とは言わない。"}, {"text": "階", "is_correct": false, "explanation": "「階」は建物のフロアを数える単位で、「一階の長さ」とは言わない。"}], "explanations": {"年": "「一年の長さ」は、一年という期間の長さを表すので空所に入る。", "冊": "「冊」は本を数える単位で、「一冊の長さ」とは言わない。", "台": "「台」は機械や車を数える単位で、「一台の長さ」とは言わない。", "階": "「階」は建物のフロアを数える単位で、「一階の長さ」とは言わない。"}, "sentence_index": 0, "correct_answer": "年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一年の長さは二十四時間です。", "explanation": "ここは〈一日〉の意味。一日の長さは二十四時間と言うので、〈一年〉の長さとしては合わない。"}, {"text": "ゆで卵は十年で固まります。", "explanation": "ここは〈分〉の意味。ゆで卵が固まる時間は分単位なので、〈年〉の長さとしては合わない。"}, {"text": "ボタンを押すと、一年でランプが点いた。", "explanation": "ここは〈秒〉（ごく短い時間）の意味。ランプが点く時間は秒単位なので、〈年〉の長さとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38418, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年", "is_correct": true, "explanation": "「三年も待った」は三年という期間の意味になるので空所に入る。"}, {"text": "円", "is_correct": false, "explanation": "「円」は金額の単位で、「三円も待った」は成り立たない。"}, {"text": "軒", "is_correct": false, "explanation": "「軒」は家を数える単位で、「三軒も待った」は期間を表さない。"}, {"text": "缶", "is_correct": false, "explanation": "「缶」は缶詰などを数える単位で、「三缶も待った」は期間を表さない。"}], "explanations": {"年": "「三年も待った」は三年という期間の意味になるので空所に入る。", "円": "「円」は金額の単位で、「三円も待った」は成り立たない。", "軒": "「軒」は家を数える単位で、「三軒も待った」は期間を表さない。", "缶": "「缶」は缶詰などを数える単位で、「三缶も待った」は期間を表さない。"}, "sentence_index": 6, "correct_answer": "年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一年の雨が、あっという間に止んでしまいました。", "explanation": "ここは〈一週間〉の意味。一回の雨が続く期間に〈年〉は合わない。"}, {"text": "彼は一年の迷いもなく、答えを出した。", "explanation": "ここは〈秒〉の意味。迷いの長さを表す文脈で〈年〉は使わない。"}, {"text": "電気ポットのお湯は一年で沸く。", "explanation": "ここは〈分〉（短い時間）の意味。お湯が沸く時間は分単位で表すので、〈年〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38418, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この暦では一年を長さを三百六十五日とします。", "corrected_sentence": "この暦では一年の長さを三百六十五日とします。", "error_description": "誤：「を」、正：「の」。「一年の長さ」のように名詞をつなぐ場合は「の」を使う。「一年を長さを」は「を」が二つ続いていて誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38418, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一年が長さは三百六十五日です。", "corrected_sentence": "一年の長さは三百六十五日です。", "error_description": "誤：「が」、正：「の」。「一年の長さ」のように名詞どうしをつなぐ場合は「の」を使う。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38419, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「過ぎる」の主語を示す格助詞で、「三年が過ぎました」と続く。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「三年と過ぎました」は主語を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「三年へ過ぎました」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は時点や対象を示すため、「三年に過ぎました」は主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「過ぎる」の主語を示す格助詞で、「三年が過ぎました」と続く。", "と": "「と」は並列や相手を示すため、「三年と過ぎました」は主語を示せず不自然。", "へ": "「へ」は方向を示すため、「三年へ過ぎました」は成り立たない。", "に": "「に」は時点や対象を示すため、「三年に過ぎました」は主語として成り立たない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "に": "時点・対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38419, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38419, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間の単位の一つで、地球が太陽の周りを一周するのにかかる約365日の期間。", "primary_collocate": null, "pronunciation": "ねん", "ipa": "neɴ", "syllable_count": 2, "sentences": [{"text": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "target_word": "年", "complexity_tier": "T3", "furigana": "最初[さいしょ]の一年[いちねん]は、美[うつく]しい田園[でんえん]風景[ふうけい]とは裏腹[うらはら]に、泥[どろ]にまみれた過酷[かこく]な肉体[にくたい]労働[ろうどう]の連続[れんぞく]でした。", "sentence_source": "mined"}, {"text": "日本に来てから、もう三年が過ぎました。", "target_word": "年", "complexity_tier": "T3", "furigana": "日本[にほん]に来[き]てから、もう三年[さんねん]が過[す]ぎました。", "sentence_source": "generated"}, {"text": "二〇二五年の春、私は新しい仕事を始めました。", "target_word": "年", "complexity_tier": "T3", "furigana": "二〇二五年[にせんにじゅうごねん]の春[はる]、私[わたし]は新[あたら]しい仕事[しごと]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "一年を通して、この地域の気温はあまり変わりません。", "target_word": "年", "complexity_tier": "T3", "furigana": "一年[いちねん]を通[とお]して、この地域[ちいき]の気温[きおん]はあまり変[か]わりません。", "sentence_source": "generated"}, {"text": "地球が太陽を一周するのに、およそ一年かかります。", "target_word": "年", "complexity_tier": "T3", "furigana": "地球[ちきゅう]が太陽[たいよう]を一周[いっしゅう]するのに、およそ一年[いちねん]かかります。", "sentence_source": "generated"}, {"text": "留学は二年の予定でしたが、もう半年延ばしました。", "target_word": "年", "complexity_tier": "T3", "furigana": "留学[りゅうがく]は二年[にねん]の予定[よてい]でしたが、もう半年[はんとし]延[の]ばしました。", "sentence_source": "generated"}, {"text": "彼は十年の修業を終えて、ようやく自分の店を持ちました。", "target_word": "年", "complexity_tier": "T3", "furigana": "彼[かれ]は十年[じゅうねん]の修業[しゅぎょう]を終[お]えて、ようやく自分[じぶん]の店[みせ]を持[も]ちました。", "sentence_source": "generated"}, {"text": "大学は四年あるので、焦らずに進路を考えるつもりです。", "target_word": "年", "complexity_tier": "T3", "furigana": "大学[だいがく]は四年[よねん]あるので、焦[あせ]らずに進路[しんろ]を考[かんが]えるつもりです。", "sentence_source": "generated"}, {"text": "一年の終わりに、家族で大掃除をします。", "target_word": "年", "complexity_tier": "T3", "furigana": "一年[いちねん]の終[お]わりに、家族[かぞく]で大掃除[おおそうじ]をします。", "sentence_source": "generated"}, {"text": "工事が始まって五年、ようやく橋が完成しました。", "target_word": "年", "complexity_tier": "T3", "furigana": "工事[こうじ]が始[はじ]まって五年[ごねん]、ようやく橋[はし]が完成[かんせい]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年", "label": "基本形"}], "register": "中立", "sense_fingerprint": "地球が太陽を一周する約365日の期間を表す時間の単位。数字の後ろにつけて「〜年」と数える。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 田園 (Zipf 3.16), 裏腹 (Zipf 3.38), 過酷 (Zipf 3.82)']::text[], '86233c54-5a66-4e9d-b895-a19e815d5771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38419, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年", "is_correct": true, "explanation": "「最初の一年」は、一年という期間を表すので空所に入る。"}, {"text": "人", "is_correct": false, "explanation": "「人」は人を数える単位で、期間の「一年」には入らない。"}, {"text": "枚", "is_correct": false, "explanation": "「枚」は薄い物を数える単位で、期間を表す語にはならない。"}, {"text": "匹", "is_correct": false, "explanation": "「匹」は動物を数える単位で、期間を表す語にはならない。"}], "explanations": {"年": "「最初の一年」は、一年という期間を表すので空所に入る。", "人": "「人」は人を数える単位で、期間の「一年」には入らない。", "枚": "「枚」は薄い物を数える単位で、期間を表す語にはならない。", "匹": "「匹」は動物を数える単位で、期間を表す語にはならない。"}, "sentence_index": 0, "correct_answer": "年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "シャッターを押すと、画面は一年で切り替わる。", "explanation": "ここは〈秒〉（ごく短い時間）の意味。画面の切り替えは秒単位なので、〈年〉は合わない。"}, {"text": "今日は一年仕事をして、とても疲れた。", "explanation": "ここは〈一日〉（一日の長さ）の意味。一日分の仕事を〈年〉で言うことはない。"}, {"text": "昼ご飯を一年で食べ終えた。", "explanation": "ここは〈分〉（短い時間）の意味。食事を終える時間は分単位で表すので、〈年〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38419, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年", "is_correct": true, "explanation": "「十年の修業」は十年という期間の意味になるので空所に入る。"}, {"text": "円", "is_correct": false, "explanation": "「円」は金額の単位で、期間の「十」とは続かない。"}, {"text": "冊", "is_correct": false, "explanation": "「冊」は本などを数える単位で、修業の期間には使わない。"}, {"text": "軒", "is_correct": false, "explanation": "「軒」は家を数える単位で、修業の期間には使わない。"}], "explanations": {"年": "「十年の修業」は十年という期間の意味になるので空所に入る。", "円": "「円」は金額の単位で、期間の「十」とは続かない。", "冊": "「冊」は本などを数える単位で、修業の期間には使わない。", "軒": "「軒」は家を数える単位で、修業の期間には使わない。"}, "sentence_index": 6, "correct_answer": "年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車は五年遅れて到着しました。", "explanation": "ここは〈分〉の意味。電車の遅れは分単位で表すので、〈年〉は使わない。"}, {"text": "信号は三年ごとに変わります。", "explanation": "ここは〈秒〉の意味。信号が変わる間隔は秒単位なので、〈年〉は合わない。"}, {"text": "夏休みは三年あります。", "explanation": "ここは〈週〉の意味。夏休みの長さは週単位で表すので、〈年〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38419, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この仕事を始めてから、もう三年の過ぎました。", "corrected_sentence": "この仕事を始めてから、もう三年が過ぎました。", "error_description": "誤：「の」、正：「が」。「過ぎる」の主語は「三年が」で示す。「三年の過ぎました」は述語と結べない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38419, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は戦後の五年が農業に捧げました。", "corrected_sentence": "祖父は戦後の五年を農業に捧げました。", "error_description": "誤：「が」、正：「を」。「捧げる」の目的語は「五年を」で示すので「を」が正しい。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a2c5e38-048a-4052-99d9-866aca58b5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
