INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38420, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「認める」は、いいことだと考えるという意味です。", "primary_collocate": null, "pronunciation": "みとめる", "ipa": "mitomeɾɯ", "syllable_count": 4, "sentences": [{"text": "先生は彼の努力を認めて、ほめてくれた。", "target_word": "認めて", "complexity_tier": "T3", "furigana": "先生[せんせい]は彼[かれ]の努力[どりょく]を認[みと]めて、ほめてくれた。", "sentence_source": "generated"}, {"text": "私は彼の才能を認めているが、性格は少し苦手だ。", "target_word": "認めている", "complexity_tier": "T3", "furigana": "私[わたし]は彼[かれ]の才能[さいのう]を認[みと]めているが、性格[せいかく]は少[すこ]し苦手[にがて]だ。", "sentence_source": "generated"}, {"text": "社長は新しい企画のよさを認め、すぐ実行を決めた。", "target_word": "認め", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は新[あたら]しい企画[きかく]のよさを認[みと]め、すぐ実行[じっこう]を決[き]めた。", "sentence_source": "generated"}, {"text": "母はやっと私の夢を認めてくれた。", "target_word": "認めて", "complexity_tier": "T3", "furigana": "母[はは]はやっと私[わたし]の夢[ゆめ]を認[みと]めてくれた。", "sentence_source": "generated"}, {"text": "彼の実力は、ライバルも認めるほど高い。", "target_word": "認める", "complexity_tier": "T3", "furigana": "彼[かれ]の実力[じつりょく]は、ライバルも認[みと]めるほど高[たか]い。", "sentence_source": "generated"}, {"text": "上司に認められて、新しい仕事を任された。", "target_word": "認められて", "complexity_tier": "T3", "furigana": "上司[じょうし]に認[みと]められて、新[あたら]しい仕事[しごと]を任[まか]された。", "sentence_source": "generated"}, {"text": "町の人々は、彼女の活躍を認めるようになった。", "target_word": "認める", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]は、彼女[かのじょ]の活躍[かつやく]を認[みと]めるようになった。", "sentence_source": "generated"}, {"text": "結果を出せば、周りも君を認めるはずだ。", "target_word": "認める", "complexity_tier": "T3", "furigana": "結果[けっか]を出[だ]せば、周[まわ]りも君[きみ]を認[みと]めるはずだ。", "sentence_source": "generated"}, {"text": "彼の作品は、多くの専門家に認められている。", "target_word": "認められている", "complexity_tier": "T3", "furigana": "彼[かれ]の作品[さくひん]は、多[おお]くの専門家[せんもんか]に認[みと]められている。", "sentence_source": "generated"}, {"text": "自分のよいところを認めると、気持ちが楽になる。", "target_word": "認める", "complexity_tier": "T3", "furigana": "自分[じぶん]のよいところを認[みと]めると、気持[きも]ちが楽[らく]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "認める", "label": "辞書形"}, {"form": "認めます", "label": "丁寧形"}, {"form": "認めない", "label": "否定形"}, {"form": "認めた", "label": "過去形"}, {"form": "認めて", "label": "て形"}, {"form": "認められる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "人やものの良さや価値をよいと評価する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38420, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "認めて", "is_correct": true, "explanation": "「努力を認めて、ほめてくれた」のて形で、評価した上でほめたという流れをつなぐ。"}, {"text": "認めない", "is_correct": false, "explanation": "否定形のため、て形にならず「、ほめてくれた」と続かない。"}, {"text": "認めます", "is_correct": false, "explanation": "丁寧形で、「ほめてくれた」と続けると文体が合わず成り立たない。"}, {"text": "認めよう", "is_correct": false, "explanation": "意志形で、後ろの文と続かず成り立たない。"}], "explanations": {"認めて": "「努力を認めて、ほめてくれた」のて形で、評価した上でほめたという流れをつなぐ。", "認めない": "否定形のため、て形にならず「、ほめてくれた」と続かない。", "認めます": "丁寧形で、「ほめてくれた」と続けると文体が合わず成り立たない。", "認めよう": "意志形で、後ろの文と続かず成り立たない。"}, "sentence_index": 0, "correct_answer": "認めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "やかんでお湯を認めた。", "explanation": "ここは〈沸かす〉の意味。湯を沸かす動作は沸かすと言い、「認める」は人やものの良さを評価する意味でしか使わない。"}, {"text": "ボウルの中で卵白を認めた。", "explanation": "ここは〈泡立てる〉の意味。卵白を泡立てる動作は泡立てると言い、「認める」は人や作品の良さを評価する意味で、卵の加工には使わない。"}, {"text": "鍋でだしを認めた。", "explanation": "ここは〈取る〉の意味。だしをとる動作は「取る」と言い、「認める」は人やものの良さを評価する意味で、だしには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38420, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "認める", "is_correct": true, "explanation": "「彼女の活躍を認めるようになった」の辞書形で、「ようになった」と自然に続く。"}, {"text": "認めろ", "is_correct": false, "explanation": "命令形のため、「〜ようになった」と続かない。"}, {"text": "認めれば", "is_correct": false, "explanation": "仮定形のため、「〜ようになった」と続かない。"}, {"text": "認めず", "is_correct": false, "explanation": "否定の連用形のため、「ようになった」に続かない。"}], "explanations": {"認める": "「彼女の活躍を認めるようになった」の辞書形で、「ようになった」と自然に続く。", "認めろ": "命令形のため、「〜ようになった」と続かない。", "認めれば": "仮定形のため、「〜ようになった」と続かない。", "認めず": "否定の連用形のため、「ようになった」に続かない。"}, "sentence_index": 6, "correct_answer": "認める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鍋でバターを認めた。", "explanation": "ここは〈溶かす〉の意味。バターを熱で溶かす動作は溶かすと言い、「認める」は評価する意味で、食材の状態変化には使わない。"}, {"text": "蛇口で水を認めた。", "explanation": "ここは〈出す〉の意味。蛇口から水を出す動作は出すと言い、「認める」は評価する意味で、水の流れには使わない。"}, {"text": "作業台で生地を認めた。", "explanation": "ここは〈こねる〉の意味。生地をこねる動作はこねると言い、「認める」は評価する意味で、生地の加工には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38420, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は彼の努力を認めるて、すぐにほめてくれた。", "corrected_sentence": "先生は彼の努力を認めて、すぐにほめてくれた。", "error_description": "活用の誤り。「認める」のて形は「認めて」（語幹「認め」＋「て」）。辞書形に「て」を付けた「認めるて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "認めている", "is_correct": true, "explanation": "「認めているが」の継続の形で、今も才能を評価している状態を表す。"}, {"text": "認め", "is_correct": false, "explanation": "連用形のため「が」で文をつなげず、不自然になる。"}, {"text": "認めて", "is_correct": false, "explanation": "て形では「認めてが」となり、文が成り立たない。"}, {"text": "認めたら", "is_correct": false, "explanation": "条件形では「認めたらが」となり、文が成り立たない。"}], "correct_form": "認めている", "base_form": "認める", "form_label": "〜ている形", "sentence_index": 1, "explanations": {"認めている": "「認めているが」の継続の形で、今も才能を評価している状態を表す。", "認め": "連用形のため「が」で文をつなげず、不自然になる。", "認めて": "て形では「認めてが」となり、文が成り立たない。", "認めたら": "条件形では「認めたらが」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38420, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の人々は、彼女の努力を認めるにようになった。", "corrected_sentence": "町の人々は、彼女の努力を認めるようになった。", "error_description": "余計な助詞の誤り。「認めるようになった」の「ように」の前には助詞「に」を入れない（正：認めるようになった）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "認める", "is_correct": true, "explanation": "「認めるはずだ」の辞書形で、推量の「はずだ」に続く。"}, {"text": "認めて", "is_correct": false, "explanation": "て形では「認めてはずだ」となり、推量の「はずだ」と続かない。"}, {"text": "認めるな", "is_correct": false, "explanation": "禁止の命令形で、推量の「はずだ」と続かない。"}, {"text": "認めよ", "is_correct": false, "explanation": "文語的な命令形で、「はずだ」に続かない。"}], "correct_form": "認める", "base_form": "認める", "form_label": "辞書形", "sentence_index": 7, "explanations": {"認める": "「認めるはずだ」の辞書形で、推量の「はずだ」に続く。", "認めて": "て形では「認めてはずだ」となり、推量の「はずだ」と続かない。", "認めるな": "禁止の命令形で、推量の「はずだ」と続かない。", "認めよ": "文語的な命令形で、「はずだ」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38421, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「罪を認めた」の「罪」は動詞「認めた」の目的語なので、目的語を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「罪が認めた」となり、罪が主語になって意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「罪に認めた」は目的語を示す形として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「罪で認めた」は手段や場所を表すが、「認める」の対象を示すには「を」が必要。"}], "correct_answer": "を", "explanations": {"を": "「罪を認めた」の「罪」は動詞「認めた」の目的語なので、目的語を示す「を」が入る。", "が": "「罪が認めた」となり、罪が主語になって意味が通らない。", "に": "「罪に認めた」は目的語を示す形として成り立たない。", "で": "「罪で認めた」は手段や場所を表すが、「認める」の対象を示すには「を」が必要。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "否定する", "is_correct": true, "explanation": "「認める」の反対で、事実や正しさを認めないという意味の対義語。"}, {"text": "眺める", "is_correct": false, "explanation": "じっと見るという意味で、認めることの反対の関係にはない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる意味で、認めることとは関係がない。"}, {"text": "勧める", "is_correct": false, "explanation": "すすめる意味で、認めることの対義語ではない。"}], "correct_answer": "否定する", "explanations": {"否定する": "「認める」の反対で、事実や正しさを認めないという意味の対義語。", "眺める": "じっと見るという意味で、認めることの反対の関係にはない。", "運ぶ": "物を移動させる意味で、認めることとは関係がない。", "勧める": "すすめる意味で、認めることの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38421, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「負けを認める」の「負け」は「認める」の目的語なので、「を」が入る。"}, {"text": "へ", "is_correct": false, "explanation": "「負けへ認める」は方向を示すが、目的語を示す形としては成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」なので、「負けから認める」では意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「負けの認める」は名詞に続く形で、動詞「認める」には続かない。"}], "correct_answer": "を", "explanations": {"を": "「負けを認める」の「負け」は「認める」の目的語なので、「を」が入る。", "へ": "「負けへ認める」は方向を示すが、目的語を示す形としては成り立たない。", "から": "起点を表す「から」なので、「負けから認める」では意味が通らない。", "の": "「負けの認める」は名詞に続く形で、動詞「認める」には続かない。"}, "error_tags": {"へ": "方向", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "否定する", "is_correct": true, "explanation": "「認めなければ」の反対で、失敗を認めないという意味の対義語。"}, {"text": "比べる", "is_correct": false, "explanation": "二つを照らし合わせる意味で、認めることの反対の関係にはない。"}, {"text": "届ける", "is_correct": false, "explanation": "物を相手に渡す意味で、認めることとは関係がない。"}, {"text": "作る", "is_correct": false, "explanation": "新たに生み出す意味で、認めることの対義語ではない。"}], "correct_answer": "否定する", "explanations": {"否定する": "「認めなければ」の反対で、失敗を認めないという意味の対義語。", "比べる": "二つを照らし合わせる意味で、認めることの反対の関係にはない。", "届ける": "物を相手に渡す意味で、認めることとは関係がない。", "作る": "新たに生み出す意味で、認めることの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38421, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「認める」は、ある事柄が正しいとか、価値があると判断して、受け入れることです。", "primary_collocate": null, "pronunciation": "みとめる", "ipa": "mitomeɾɯ", "syllable_count": 4, "sentences": [{"text": "彼は自分の間違いを認めて、みんなに謝った。", "target_word": "認めて", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の間違[まちが]いを認[みと]めて、みんなに謝[あやま]った。", "sentence_source": "generated"}, {"text": "裁判で、被告は罪を認めた。", "target_word": "認めた", "complexity_tier": "T3", "furigana": "裁判[さいばん]で、被告[ひこく]は罪[つみ]を認[みと]めた。", "sentence_source": "generated"}, {"text": "この研究の価値は、専門家にも広く認められている。", "target_word": "認められている", "complexity_tier": "T3", "furigana": "この研究[けんきゅう]の価値[かち]は、専門家[せんもんか]にも広[ひろ]く認[みと]められている。", "sentence_source": "generated"}, {"text": "会社は事実を認めず、説明を避けている。", "target_word": "認めず", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は事実[じじつ]を認[みと]めず、説明[せつめい]を避[さ]けている。", "sentence_source": "generated"}, {"text": "審査の結果、この申請は正式に認められた。", "target_word": "認められた", "complexity_tier": "T3", "furigana": "審査[しんさ]の結果[けっか]、この申請[しんせい]は正式[せいしき]に認[みと]められた。", "sentence_source": "generated"}, {"text": "彼の意見が正しいことを、私は素直に認めた。", "target_word": "認めた", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]が正[ただ]しいことを、私[わたし]は素直[すなお]に認[みと]めた。", "sentence_source": "generated"}, {"text": "国は、その団体を正式な組織として認めた。", "target_word": "認めた", "complexity_tier": "T3", "furigana": "国[くに]は、その団体[だんたい]を正式[せいしき]な組織[そしき]として認[みと]めた。", "sentence_source": "generated"}, {"text": "負けを認めるのは悔しいが、相手のほうが上手だった。", "target_word": "認める", "complexity_tier": "T3", "furigana": "負[ま]けを認[みと]めるのは悔[くや]しいが、相手[あいて]のほうが上手[じょうず]だった。", "sentence_source": "generated"}, {"text": "新しい説の正しさは、まだ学会では認められていない。", "target_word": "認められていない", "complexity_tier": "T3", "furigana": "新[あたら]しい説[せつ]の正[ただ]しさは、まだ学会[がっかい]では認[みと]められていない。", "sentence_source": "generated"}, {"text": "失敗を認めなければ、次の一歩は踏み出せない。", "target_word": "認めなければ", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を認[みと]めなければ、次[つぎ]の一歩[いっぽ]は踏[ふ]み出[だ]せない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "認める", "label": "辞書形"}, {"form": "認めます", "label": "丁寧形"}, {"form": "認めない", "label": "否定形"}, {"form": "認めた", "label": "過去形"}, {"form": "認めて", "label": "て形"}, {"form": "認められる", "label": "受身形"}], "register": "中立", "sense_fingerprint": "事柄を正しいと判断して受け入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38421, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "認めて", "is_correct": true, "explanation": "て形で、「間違いを認めて、謝った」と順に続く流れに合う正解。"}, {"text": "認めよう", "is_correct": false, "explanation": "意志形なので、後ろの「謝った」と文がつながらない。"}, {"text": "認めさせ", "is_correct": false, "explanation": "使役の連用形で、「認めさせ、謝った」では主語の行為が変わり、自分で間違いを認めた内容と合わない。"}, {"text": "認められて", "is_correct": false, "explanation": "受身形なので「間違いが認められて」となり、「自分の間違いを」を目的語にする文型と合わない。"}], "explanations": {"認めて": "て形で、「間違いを認めて、謝った」と順に続く流れに合う正解。", "認めよう": "意志形なので、後ろの「謝った」と文がつながらない。", "認めさせ": "使役の連用形で、「認めさせ、謝った」では主語の行為が変わり、自分で間違いを認めた内容と合わない。", "認められて": "受身形なので「間違いが認められて」となり、「自分の間違いを」を目的語にする文型と合わない。"}, "sentence_index": 0, "correct_answer": "認めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母に長い手紙を認めた。", "explanation": "ここは〈したためる・書く〉の意味。認めるは正しさや価値を受け入れる意味なので、手紙を書く場面では使わない。"}, {"text": "旅行の思い出を日記に認めた。", "explanation": "ここは〈書き記す〉の意味。認めるは受け入れる意味なので、日記を書く場面では使わない。"}, {"text": "母の誕生日に、祝いのカードに言葉を認めて渡した。", "explanation": "ここは〈したためる〉の意味。認めるは受け入れる意味なので、カードに書く場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38421, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "認めた", "is_correct": true, "explanation": "過去形で、国が団体を正式な組織として認めたという完了の出来事を表す正解。"}, {"text": "認めて", "is_correct": false, "explanation": "て形なので、文を終えられず「国は…として認めて。」と文が切れない。"}, {"text": "認めず", "is_correct": false, "explanation": "中止形なので、文を終えられず「認めず。」と文が切れない。"}, {"text": "認められ", "is_correct": false, "explanation": "受身の連用形なので、文を終えられず、主語と目的語の関係も合わない。"}], "explanations": {"認めた": "過去形で、国が団体を正式な組織として認めたという完了の出来事を表す正解。", "認めて": "て形なので、文を終えられず「国は…として認めて。」と文が切れない。", "認めず": "中止形なので、文を終えられず「認めず。」と文が切れない。", "認められ": "受身の連用形なので、文を終えられず、主語と目的語の関係も合わない。"}, "sentence_index": 6, "correct_answer": "認めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母に近況を認めた手紙を送った。", "explanation": "ここは〈したためる〉の意味。認めるは正しさや価値を受け入れる意味なので、手紙を書く場面では使わない。"}, {"text": "旅先から友人に絵葉書を認めた。", "explanation": "ここは〈したためる〉の意味。認めるは受け入れる意味なので、絵葉書を書く場面では使わない。"}, {"text": "留学中の弟に長い手紙を認めた。", "explanation": "ここは〈したためる〉の意味。認めるは受け入れる意味なので、手紙を書く場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38421, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒の努力を認めに、ほめた。", "corrected_sentence": "先生は生徒の努力を認めて、ほめた。", "error_description": "誤りは「認めに」。正しくは「認めて」（て形）で、「認めて、ほめた」と動作を順に続ける。「認めに」は活用の形として成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "認めた", "is_correct": true, "explanation": "過去形で、被告が罪を認めたという完了した行為を表す。"}, {"text": "認めない", "is_correct": false, "explanation": "否定形なので、被告は罪を認めなかったという意味になり、文の内容と逆になる。"}, {"text": "認められた", "is_correct": false, "explanation": "受身の過去形で「罪が認められた」となり、罪を認めた主体が被告であるという文の意味とは合わない。"}, {"text": "認めて", "is_correct": false, "explanation": "て形なので、文が「被告は罪を認めて。」と途中で切れ、過去の完了を表せない。"}], "correct_form": "認めた", "base_form": "認める", "form_label": "過去形", "sentence_index": 1, "explanations": {"認めた": "過去形で、被告が罪を認めたという完了した行為を表す。", "認めない": "否定形なので、被告は罪を認めなかったという意味になり、文の内容と逆になる。", "認められた": "受身の過去形で「罪が認められた」となり、罪を認めた主体が被告であるという文の意味とは合わない。", "認めて": "て形なので、文が「被告は罪を認めて。」と途中で切れ、過去の完了を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38421, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は私の進路に認めた。", "corrected_sentence": "母は私の進路を認めた。", "error_description": "誤りは「進路に」。「認める」は他動詞なので、対象は「を」で示す。「に」は方向や場所を表す助詞で、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "認める", "is_correct": true, "explanation": "辞書形で、「負けを認めるのは」と名詞のように「のは」に続く正解。"}, {"text": "認めて", "is_correct": false, "explanation": "て形なので、「認めてのは」と「のは」に続かない。"}, {"text": "認めれば", "is_correct": false, "explanation": "仮定形なので、「認めればのは」と「のは」に続かない。"}, {"text": "認められ", "is_correct": false, "explanation": "受身の連用形なので、「のは」に続かず、主語も変わってしまう。"}], "correct_form": "認める", "base_form": "認める", "form_label": "辞書形", "sentence_index": 7, "explanations": {"認める": "辞書形で、「負けを認めるのは」と名詞のように「のは」に続く正解。", "認めて": "て形なので、「認めてのは」と「のは」に続かない。", "認めれば": "仮定形なので、「認めればのは」と「のは」に続かない。", "認められ": "受身の連用形なので、「のは」に続かず、主語も変わってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38422, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「知恵をしぼって」の「を」は、しぼる対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「知恵がしぼって」となり、知恵がしぼるという主語になって不自然。"}, {"text": "に", "is_correct": false, "explanation": "「知恵にしぼって」では、しぼる対象として「に」が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「知恵としぼって」は「知恵として」の意味になり、しぼる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「知恵をしぼって」の「を」は、しぼる対象を示す。", "が": "「知恵がしぼって」となり、知恵がしぼるという主語になって不自然。", "に": "「知恵にしぼって」では、しぼる対象として「に」が合わない。", "と": "「知恵としぼって」は「知恵として」の意味になり、しぼる対象を示せない。"}, "error_tags": {"が": "主語の誤用", "に": "対象の誤用", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38422, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「知恵がある」の「が」は、ある対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「知恵へある」は方向を示す形になり、存在を表す「ある」と合わない。"}, {"text": "から", "is_correct": false, "explanation": "「知恵からある」は起点を示すが、存在の文として意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「知恵よりある」は比較の形になり、「ある」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「知恵がある」の「が」は、ある対象を示す。", "へ": "「知恵へある」は方向を示す形になり、存在を表す「ある」と合わない。", "から": "「知恵からある」は起点を示すが、存在の文として意味が通らない。", "より": "「知恵よりある」は比較の形になり、「ある」の主語を示せない。"}, "error_tags": {"へ": "方向の誤用", "から": "起点の誤用", "より": "比較の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38422, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものをうまくつかうための、よい考え。", "primary_collocate": null, "pronunciation": "ちえ", "ipa": "tɕie", "syllable_count": 2, "sentences": [{"text": "水を無駄にしないための知恵を、祖母から教わった。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "水[みず]を無駄[むだ]にしないための知恵[ちえ]を、祖母[そぼ]から教[おそ]わった。", "sentence_source": "generated"}, {"text": "狭い部屋でも広く使えるように、知恵をしぼって家具を並べた。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "狭[せま]い部屋[へや]でも広[ひろ]く使[つか]えるように、知恵[ちえ]をしぼって家具[かぐ]を並[なら]べた。", "sentence_source": "generated"}, {"text": "この箱は、荷物を重ねるときの知恵から生まれた形だ。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "この箱[はこ]は、荷物[にもつ]を重[かさ]ねるときの知恵[ちえ]から生[う]まれた形[かたち]だ。", "sentence_source": "generated"}, {"text": "母は古い新聞紙を靴の湿気取りに使うという知恵を教えてくれた。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "母[はは]は古[ふる]い新聞紙[しんぶんし]を靴[くつ]の湿気取[しっけと]りに使[つか]うという知恵[ちえ]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "子どもたちは知恵を出して、一つのボールでみんなが遊べる方法を考えた。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "子[こ]どもたちは知恵[ちえ]を出[だ]して、一[ひと]つのボールでみんなが遊[あそ]べる方法[ほうほう]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "空き缶を植木鉢に使うのは、ものを大切にする知恵だと思う。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "空[あ]き缶[かん]を植木鉢[うえきばち]に使[つか]うのは、ものを大切[たいせつ]にする知恵[ちえ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "この道具には、長く使う人たちの知恵が詰まっている。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "この道具[どうぐ]には、長[なが]く使[つか]う人[ひと]たちの知恵[ちえ]が詰[つ]まっている。", "sentence_source": "generated"}, {"text": "彼は限られたお金を上手に使う知恵がある。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "彼[かれ]は限[かぎ]られたお金[かね]を上手[じょうず]に使[つか]う知恵[ちえ]がある。", "sentence_source": "generated"}, {"text": "雨の日に傘がなくても、ビニール袋で荷物をぬらさない知恵が役に立った。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]に傘[かさ]がなくても、ビニール袋[ぶくろ]で荷物[にもつ]をぬらさない知恵[ちえ]が役[やく]に立[た]った。", "sentence_source": "generated"}, {"text": "先輩は、せまい台所を使いやすくする知恵を見せてくれた。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "先輩[せんぱい]は、せまい台所[だいどころ]を使[つか]いやすくする知恵[ちえ]を見[み]せてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知恵", "label": "基本形"}], "register": "標準的な書き言葉", "sense_fingerprint": "ものや道具をうまく使うための、くふうやよい考え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: ぬらさ (Zipf 1.65)']::text[], '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38422, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知恵", "is_correct": true, "explanation": "正解。「水を無駄にしないための知恵」として、ものをうまく使う工夫を表す。"}, {"text": "音楽", "is_correct": false, "explanation": "「水を無駄にしないための音楽」は意味が通らず、教わる内容として合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「水を無駄にしないための体重」は成り立たず、水の使い方の文脈に合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは水を無駄にしない工夫の対象にならず、「教わった」内容として合わない。"}], "explanations": {"知恵": "正解。「水を無駄にしないための知恵」として、ものをうまく使う工夫を表す。", "音楽": "「水を無駄にしないための音楽」は意味が通らず、教わる内容として合わない。", "体重": "「水を無駄にしないための体重」は成り立たず、水の使い方の文脈に合わない。", "夕焼け": "夕焼けは水を無駄にしない工夫の対象にならず、「教わった」内容として合わない。"}, "sentence_index": 0, "correct_answer": "知恵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "知恵は、紙を切るための道具だ。", "explanation": "ここは「ハサミ」（道具）の意味。知恵は物ではなく、ものを使う工夫なので、道具とは言えない。"}, {"text": "知恵は、喉が痛くなる病気だ。", "explanation": "ここは「風邪」（病気）の意味。知恵は病気ではないので、喉が痛くなるものとは言えない。"}, {"text": "知恵は、決まった道を走る乗り物だ。", "explanation": "ここは「バス」（乗り物）の意味。知恵は乗り物ではないので、道を走るものとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38422, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知恵", "is_correct": true, "explanation": "正解。「長く使う人たちの知恵」として、道具の使い方に蓄えられた工夫を表す。"}, {"text": "土砂", "is_correct": false, "explanation": "「長く使う人たちの土砂が詰まっている」は意味が通らず、道具の文脈に合わない。"}, {"text": "試験", "is_correct": false, "explanation": "「長く使う人たちの試験が詰まっている」は成り立たず、道具の説明として合わない。"}, {"text": "花火", "is_correct": false, "explanation": "「長く使う人たちの花火が詰まっている」は意味が通らず、道具に詰まるものとして合わない。"}], "explanations": {"知恵": "正解。「長く使う人たちの知恵」として、道具の使い方に蓄えられた工夫を表す。", "土砂": "「長く使う人たちの土砂が詰まっている」は意味が通らず、道具の文脈に合わない。", "試験": "「長く使う人たちの試験が詰まっている」は成り立たず、道具の説明として合わない。", "花火": "「長く使う人たちの花火が詰まっている」は意味が通らず、道具に詰まるものとして合わない。"}, "sentence_index": 6, "correct_answer": "知恵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "知恵は、小麦粉と水で作る食べ物だ。", "explanation": "ここは「パン」（食べ物）の意味。知恵は食べ物ではないので、小麦粉と水で作るとは言えない。"}, {"text": "知恵は、子どもが勉強する建物だ。", "explanation": "ここは「学校」（建物）の意味。知恵は建物ではないので、子どもが勉強する場所とは言えない。"}, {"text": "知恵は、空から落ちてくる水滴だ。", "explanation": "ここは「雨」（天気）の意味。知恵は空から落ちてくるものではないので、水滴とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38422, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、古い箱を棚として使う知恵を食べてくれた。", "corrected_sentence": "祖母は、古い箱を棚として使う知恵を教えてくれた。", "error_description": "「知恵」と組む動詞は「教える」など。「食べる」は合わないので、正しくは「教えてくれた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38422, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は、狭い玄関を広く使う知恵に教えてくれた。", "corrected_sentence": "母は、狭い玄関を広く使う知恵を教えてくれた。", "error_description": "「教える」の対象は「を」で示す。「に」は教わる相手を示すので誤りで、正しくは「知恵を教えてくれた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38423, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「知恵のおかげで」の「の」は、名詞「おかげ」につなぐ連体の「の」で、知恵が原因であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「知恵を、おかげで」となり、直後の「おかげで」とつながらず文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「知恵が、おかげで」となると知恵が主語になり、「おかげで」の原因を示す文として意味がつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「知恵に、おかげで」は対象を示す形になり、「おかげで」と結びつかない。"}], "correct_answer": "の", "explanations": {"の": "正解。「知恵のおかげで」の「の」は、名詞「おかげ」につなぐ連体の「の」で、知恵が原因であることを示す。", "を": "「知恵を、おかげで」となり、直後の「おかげで」とつながらず文が成り立たない。", "が": "「知恵が、おかげで」となると知恵が主語になり、「おかげで」の原因を示す文として意味がつながらない。", "に": "「知恵に、おかげで」は対象を示す形になり、「おかげで」と結びつかない。"}, "error_tags": {"を": "目的語の重複", "が": "主語の誤用", "に": "対象の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38423, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「生活の知恵が豊かで」の「が」は、豊かだという状態の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「生活の知恵と豊かで」は並列にならず、「豊かで」の主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「知恵へ豊かで」は方向を示す形になり、豊かだという状態の主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「生活の知恵の豊かで」は所属を示すだけで、「豊かで」の主語を示せず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「生活の知恵が豊かで」の「が」は、豊かだという状態の主語を示す。", "と": "「生活の知恵と豊かで」は並列にならず、「豊かで」の主語を示せない。", "へ": "「知恵へ豊かで」は方向を示す形になり、豊かだという状態の主語として成り立たない。", "の": "「生活の知恵の豊かで」は所属を示すだけで、「豊かで」の主語を示せず文が成り立たない。"}, "error_tags": {"と": "並列の誤用", "へ": "方向の誤用", "の": "所属の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38423, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を上手に判断し、適切に処理する能力や知識。経験から得られた実用的な知識や判断力。", "primary_collocate": null, "pronunciation": "ちえ", "ipa": "tɕie", "syllable_count": 2, "sentences": [{"text": "この建設には、当時の建築工学の知恵が結集されています。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "この建設[けんせつ]には、当時[とうじ]の建築工学[けんちくこうがく]の知恵[ちえ]が結集[けっしゅう]されています。", "sentence_source": "mined"}, {"text": "おばあちゃんの知恵のおかげで、古い服をきれいに直すことができた。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "おばあちゃんの知恵[ちえ]のおかげで、古[ふる]い服[ふく]をきれいに直[なお]すことができた。", "sentence_source": "generated"}, {"text": "彼は困ったとき、いつも知恵を働かせて問題を解決する。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "彼[かれ]は困[こま]ったとき、いつも知恵[ちえ]を働[はたら]かせて問題[もんだい]を解決[かいけつ]する。", "sentence_source": "generated"}, {"text": "この村の人々は、長い経験から得た知恵で厳しい冬を乗りこえてきた。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "この村[むら]の人々[ひとびと]は、長[なが]い経験[けいけん]から得[え]た知恵[ちえ]で厳[きび]しい冬[ふゆ]を乗[の]りこえてきた。", "sentence_source": "generated"}, {"text": "みんなで知恵を出し合えば、よい方法が見つかるはずだ。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "みんなで知恵[ちえ]を出[だ]し合[あ]えば、よい方法[ほうほう]が見[み]つかるはずだ。", "sentence_source": "generated"}, {"text": "年を取った人の知恵には、本には書かれていない大切な教えがある。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "年[とし]を取[と]った人[ひと]の知恵[ちえ]には、本[ほん]には書[か]かれていない大切[たいせつ]な教[おし]えがある。", "sentence_source": "generated"}, {"text": "昔の人は、暑さをやわらげる知恵として、家に深い軒を作った。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、暑[あつ]さをやわらげる知恵[ちえ]として、家[いえ]に深[ふか]い軒[のき]を作[つく]った。", "sentence_source": "generated"}, {"text": "彼女は生活の知恵が豊かで、少ない材料でおいしい料理を作る。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は生活[せいかつ]の知恵[ちえ]が豊[ゆた]かで、少[すく]ない材料[ざいりょう]でおいしい料理[りょうり]を作[つく]る。", "sentence_source": "generated"}, {"text": "災害のとき、地域の知恵が人々の命を守ることがある。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、地域[ちいき]の知恵[ちえ]が人々[ひとびと]の命[いのち]を守[まも]ることがある。", "sentence_source": "generated"}, {"text": "新しい仕事では、知識だけでなく現場で使える知恵も必要だ。", "target_word": "知恵", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]では、知識[ちしき]だけでなく現場[げんば]で使[つか]える知恵[ちえ]も必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知恵", "label": "基本形"}], "register": "標準的な書き言葉", "sense_fingerprint": "経験から得た、物事を適切に判断し処理する実用的な知識・判断力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 乗りこえ (Zipf 1.63)','sentence 4 above tier T3: contains vocabulary far above tier T3: 出し合え (Zipf 1.3)']::text[], '21e4fc6d-cea0-417b-8165-be5b5a112aa0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38423, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知恵", "is_correct": true, "explanation": "正解。「建築工学の知恵」として、建設に集められた実用的な知識・判断力を示す。"}, {"text": "電気", "is_correct": false, "explanation": "「建築工学の電気が結集」は意味が通らず、建設に集められるものとして合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「建築工学の砂糖が結集」は成り立たず、建設の文脈に合わない。"}, {"text": "湿気", "is_correct": false, "explanation": "湿気は建築工学の成果として結集されるものではなく、文の意味に合わない。"}], "explanations": {"知恵": "正解。「建築工学の知恵」として、建設に集められた実用的な知識・判断力を示す。", "電気": "「建築工学の電気が結集」は意味が通らず、建設に集められるものとして合わない。", "砂糖": "「建築工学の砂糖が結集」は成り立たず、建設の文脈に合わない。", "湿気": "湿気は建築工学の成果として結集されるものではなく、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "知恵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の別れのあと、知恵はしばらく胸の奥で静かに痛んでいた。", "explanation": "ここは「悲しみ」（感情）の意味。知恵は判断や処理の能力で、胸が痛む感情ではない。"}, {"text": "彼は長い山道を一日中歩き続けられるほど知恵がある。", "explanation": "ここは「体力」（体の力）の意味。知恵は頭で判断し処理する力で、山道を歩き続ける体力のことは指さないので合わない。"}, {"text": "祖父が残してくれた知恵は、小さな家一軒だった。", "explanation": "ここは「財産」の意味。知恵は物や財産ではなく能力・知識なので、家一軒を指す言い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38423, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知恵", "is_correct": true, "explanation": "正解。「暑さをやわらげる知恵」として、暑さをやわらげる工夫という実用的な判断を示す。"}, {"text": "悲鳴", "is_correct": false, "explanation": "「暑さをやわらげる悲鳴」は成り立たず、暑さへの対処を表す文に合わない。"}, {"text": "恋愛", "is_correct": false, "explanation": "「暑さをやわらげる恋愛」は意味が通らず、家の軒の文脈に合わない。"}, {"text": "練習", "is_correct": false, "explanation": "「暑さをやわらげる練習」は意味が通らず、暑さを防ぐ工夫として合わない。"}], "explanations": {"知恵": "正解。「暑さをやわらげる知恵」として、暑さをやわらげる工夫という実用的な判断を示す。", "悲鳴": "「暑さをやわらげる悲鳴」は成り立たず、暑さへの対処を表す文に合わない。", "恋愛": "「暑さをやわらげる恋愛」は意味が通らず、家の軒の文脈に合わない。", "練習": "「暑さをやわらげる練習」は意味が通らず、暑さを防ぐ工夫として合わない。"}, "sentence_index": 6, "correct_answer": "知恵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この知恵は、ごみを強い力で吸い込む。", "explanation": "ここは「掃除機」（機械）の意味。知恵は能力なので、ごみを吸い込む機械の働きは言えない。"}, {"text": "知恵は、海上で発達して強い風と雨をもたらす。", "explanation": "ここは「台風」（天気）の意味。知恵は空の現象ではないので、風や雨をもたらすとは言えない。"}, {"text": "知恵は、血液を全身に送り出すポンプの役割をしている。", "explanation": "ここは「心臓」（臓器）の意味。知恵は体の器官ではないので、血液を送るとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38423, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は仕事で困ったとき、知恵が働かせて乗りこえた。", "corrected_sentence": "父は仕事で困ったとき、知恵を働かせて乗りこえた。", "error_description": "「働かせる」の目的語は「を」で示す。「知恵が働かせて」の「が」は誤りで、正しくは「知恵を働かせて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38423, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は困ったとき、知恵を食べて乗り越えた。", "corrected_sentence": "彼女は困ったとき、知恵を絞って乗り越えた。", "error_description": "「知恵」と組む動詞は「絞る」「働かせる」など。「食べる」は合わないので、正しくは「知恵を絞って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb121d0f-78e4-45de-917e-3033e99aa380') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
