INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38424, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをするときに、いい結果が出るように助けてくれること。", "primary_collocate": null, "pronunciation": "やくだつ", "ipa": "jakɯdatsɯ", "syllable_count": 4, "sentences": [{"text": "この辞書は、日本語を勉強するときに役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "この辞書[じしょ]は、日本語[にほんご]を勉強[べんきょう]するときに役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "旅行の前に調べた情報が、現地でとても役立った。", "target_word": "役立った", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]に調[しら]べた情報[じょうほう]が、現地[げんち]でとても役立[やくだ]った。", "sentence_source": "generated"}, {"text": "先生のアドバイスは、試験の準備に役立った。", "target_word": "役立った", "complexity_tier": "T3", "furigana": "先生[せんせい]のアドバイスは、試験[しけん]の準備[じゅんび]に役立[やくだ]った。", "sentence_source": "generated"}, {"text": "このアプリは、料理を作るときに役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "このアプリは、料理[りょうり]を作[つく]るときに役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "地図が役立って、迷わずに駅へ着けた。", "target_word": "役立って", "complexity_tier": "T3", "furigana": "地図[ちず]が役立[やくだ]って、迷[まよ]わずに駅[えき]へ着[つ]けた。", "sentence_source": "generated"}, {"text": "子どものころの経験が、今の仕事に役立っている。", "target_word": "役立っている", "complexity_tier": "T3", "furigana": "子[こ]どものころの経験[けいけん]が、今[いま]の仕事[しごと]に役立[やくだ]っている。", "sentence_source": "generated"}, {"text": "古い新聞紙は、窓をふくときに役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "古[ふる]い新聞紙[しんぶんし]は、窓[まど]をふくときに役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "メモを取っておいたので、あとで見直すときに役立った。", "target_word": "役立った", "complexity_tier": "T3", "furigana": "メモを取[と]っておいたので、あとで見直[みなお]すときに役立[やくだ]った。", "sentence_source": "generated"}, {"text": "友達が貸してくれた本は、レポートを書くのに役立った。", "target_word": "役立った", "complexity_tier": "T3", "furigana": "友達[ともだち]が貸[か]してくれた本[ほん]は、レポートを書[か]くのに役立[やくだ]った。", "sentence_source": "generated"}, {"text": "簡単な英語でも、海外では十分に役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "簡単[かんたん]な英語[えいご]でも、海外[かいがい]では十分[じゅうぶん]に役立[やくだ]つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "役立つ", "label": "辞書形"}, {"form": "役立ちます", "label": "ます形"}, {"form": "役立たない", "label": "ない形"}, {"form": "役立った", "label": "た形"}, {"form": "役立って", "label": "て形"}], "register": "neutral", "sense_fingerprint": "物事をするときに、よい結果が出るよう助けになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38424, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "役立つ", "is_correct": true, "explanation": "正解。「勉強するときに役立つ」は、道具などが目的に有効であることを示す自然な言い方です。"}, {"text": "逆らう", "is_correct": false, "explanation": "「勉強するときに逆らう」は成り立たず、文として不自然です。"}, {"text": "眠る", "is_correct": false, "explanation": "「勉強するときに眠る」は、文の意味が通りません。"}, {"text": "怒る", "is_correct": false, "explanation": "「勉強するときに怒る」は不自然で、文の意味が通りません。"}], "explanations": {"役立つ": "正解。「勉強するときに役立つ」は、道具などが目的に有効であることを示す自然な言い方です。", "逆らう": "「勉強するときに逆らう」は成り立たず、文として不自然です。", "眠る": "「勉強するときに眠る」は、文の意味が通りません。", "怒る": "「勉強するときに怒る」は不自然で、文の意味が通りません。"}, "sentence_index": 0, "correct_answer": "役立つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の言葉は、私の気持ちに役立った。", "explanation": "ここは〈慰める〉の意味です。慰めるは相手の気持ちを和らげることですが、役立つは道具や知識が目的に有効に働くことを表すので、気持ちに役立つとは言えません。"}, {"text": "その子は映画の主役に役立った。", "explanation": "ここは〈演じる〉の意味です。主役を演じるは役を務めることですが、役立つは有効に働くことなので、役の担当は表せません。"}, {"text": "その靴は、私の服の色に役立った。", "explanation": "ここは〈合う〉の意味です。服の色と靴の色が合うと言うときは「合う」を使います。役立つは目的に有効に働くことなので、色の釣り合いは表せません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38424, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "役立つ", "is_correct": true, "explanation": "正解。「窓をふくときに役立つ」は、道具が目的に有効に働くことを示します。"}, {"text": "転ぶ", "is_correct": false, "explanation": "「窓をふくときに転ぶ」は成り立たず、文として不自然です。"}, {"text": "謝る", "is_correct": false, "explanation": "「窓をふくときに謝る」は文が成り立ちません。"}, {"text": "泣く", "is_correct": false, "explanation": "「窓をふくときに泣く」は不自然で、文の意味が通りません。"}], "explanations": {"役立つ": "正解。「窓をふくときに役立つ」は、道具が目的に有効に働くことを示します。", "転ぶ": "「窓をふくときに転ぶ」は成り立たず、文として不自然です。", "謝る": "「窓をふくときに謝る」は文が成り立ちません。", "泣く": "「窓をふくときに泣く」は不自然で、文の意味が通りません。"}, "sentence_index": 6, "correct_answer": "役立つ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その大きな音は、近所の人に役立った。", "explanation": "ここは〈困らせる〉の意味です。困らせるは迷惑をかけることですが、役立つは有効に働くことなので、迷惑には使えません。"}, {"text": "その店は、客が多くて役立った。", "explanation": "ここは〈儲かる〉の意味です。儲かるは利益が出ることですが、役立つは有効に働くことを表すので、もうけの意味には使えません。"}, {"text": "その石は、窓ガラスに役立った。", "explanation": "ここは〈割る〉の意味です。割るは窓ガラスを砕く動作ですが、役立つは物が有効に働くことを表すので、窓を割る意味にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38424, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いタオルは、掃除をするときを役立つ。", "corrected_sentence": "古いタオルは、掃除をするときに役立つ。", "error_description": "「役立つ」は「に」を伴います。「を」は目的語の助詞で、ここでは不自然です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "役立った", "is_correct": true, "explanation": "正解。「役立った」は、過去の出来事を述べるた形です。"}, {"text": "役立ったら", "is_correct": false, "explanation": "条件形で、文末に置くと文が完結しません。"}, {"text": "役立とう", "is_correct": false, "explanation": "意志形で、物が主語の文末には合わず、文が完結しません。"}, {"text": "役立って", "is_correct": false, "explanation": "て形は文を続けるための形で、文末の過去としては働きません。"}], "correct_form": "役立った", "base_form": "役立つ", "form_label": "た形", "sentence_index": 1, "explanations": {"役立った": "正解。「役立った」は、過去の出来事を述べるた形です。", "役立ったら": "条件形で、文末に置くと文が完結しません。", "役立とう": "意志形で、物が主語の文末には合わず、文が完結しません。", "役立って": "て形は文を続けるための形で、文末の過去としては働きません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38424, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ノートは、テストの前に見直すときに役立つた。", "corrected_sentence": "ノートは、テストの前に見直すときに役立った。", "error_description": "「役立つ」の活用が誤りです。「役立つた」は「つ」と「た」が混ざった形で、「役立った」が正しいです。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "役立った", "is_correct": true, "explanation": "正解。「役立った」は、過去の出来事を述べるた形です。"}, {"text": "役立ち", "is_correct": false, "explanation": "連用形で、文末に置くと文が完結しないので不正解。"}, {"text": "役立てて", "is_correct": false, "explanation": "他動詞「役立てる」のて形で、この文の主語には合わず、文も完結しない。"}, {"text": "役立ちながら", "is_correct": false, "explanation": "「ながら」は同時の動作を表す形で、文末に置けず、文が完結しない。"}], "correct_form": "役立った", "base_form": "役立つ", "form_label": "た形", "sentence_index": 7, "explanations": {"役立った": "正解。「役立った」は、過去の出来事を述べるた形です。", "役立ち": "連用形で、文末に置くと文が完結しないので不正解。", "役立てて": "他動詞「役立てる」のて形で、この文の主語には合わず、文も完結しない。", "役立ちながら": "「ながら」は同時の動作を表す形で、文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
