INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38425, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある目的に対して有効に働くこと。", "primary_collocate": null, "pronunciation": "やくだつ", "ipa": "jakɯdatsɯ", "syllable_count": 4, "sentences": [{"text": "防災ラジオは、停電のときに役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "防災[ぼうさい]ラジオは、停電[ていでん]のときに役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "非常用の水は、地震のあとに役立った。", "target_word": "役立った", "complexity_tier": "T3", "furigana": "非常用[ひじょうよう]の水[みず]は、地震[じしん]のあとに役立[やくだ]った。", "sentence_source": "generated"}, {"text": "小さなライトでも、暗い道では役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "小[ちい]さなライトでも、暗[くら]い道[みち]では役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "その知識は、研究にそのまま役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "その知識[ちしき]は、研究[けんきゅう]にそのまま役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "古いタオルは、掃除にも役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "古[ふる]いタオルは、掃除[そうじ]にも役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "経験を生かせば、チームの目標に役立つはずだ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "経験[けいけん]を生[い]かせば、チームの目標[もくひょう]に役立[やくだ]つはずだ。", "sentence_source": "generated"}, {"text": "この道具は、庭の手入れにとても役立っている。", "target_word": "役立っている", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は、庭[にわ]の手入[ていれ]れにとても役立[やくだ]っている。", "sentence_source": "generated"}, {"text": "薬箱があって、けがをしたときに役立った。", "target_word": "役立った", "complexity_tier": "T3", "furigana": "薬箱[くすりばこ]があって、けがをしたときに役立[やくだ]った。", "sentence_source": "generated"}, {"text": "計算が速いことは、会計の仕事で役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "計算[けいさん]が速[はや]いことは、会計[かいけい]の仕事[しごと]で役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "外国で働くとき、語学力はきっと役立つ。", "target_word": "役立つ", "complexity_tier": "T3", "furigana": "外国[がいこく]で働[はたら]くとき、語学力[ごがくりょく]はきっと役立[やくだ]つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "役立つ", "label": "辞書形"}, {"form": "役立ちます", "label": "ます形"}, {"form": "役立たない", "label": "ない形"}, {"form": "役立った", "label": "た形"}, {"form": "役立って", "label": "て形"}], "register": "neutral", "sense_fingerprint": "ある目的に対して、道具・知識などが有効に働く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38425, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "役立つ", "is_correct": true, "explanation": "正解。「停電のときに役立つ」は、道具が目的に有効に働くことを示します。"}, {"text": "逆らう", "is_correct": false, "explanation": "「停電のときに逆らう」は成り立たず、文として不自然です。"}, {"text": "眠る", "is_correct": false, "explanation": "「停電のときに眠る」は文の意味が通りません。"}, {"text": "怒る", "is_correct": false, "explanation": "「停電のときに怒る」は不自然で、文の意味が通りません。"}], "explanations": {"役立つ": "正解。「停電のときに役立つ」は、道具が目的に有効に働くことを示します。", "逆らう": "「停電のときに逆らう」は成り立たず、文として不自然です。", "眠る": "「停電のときに眠る」は文の意味が通りません。", "怒る": "「停電のときに怒る」は不自然で、文の意味が通りません。"}, "sentence_index": 0, "correct_answer": "役立つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は、大きな声で役立った。", "explanation": "ここは〈叫ぶ〉の意味です。叫ぶは大きな声を出すことですが、役立つは有効に働くことなので、声を出す動作は表せません。"}, {"text": "鳥が、屋根から役立った。", "explanation": "ここは〈飛ぶ〉の意味です。飛ぶは空中を移動することですが、役立つは有効に働くことなので、移動の意味にはなりません。"}, {"text": "私は、プールで役立った。", "explanation": "ここは〈泳ぐ〉の意味です。泳ぐは水の中で体を動かすことですが、役立つは有効に働くことなので、泳ぐ動作は表せません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38425, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "役立っている", "is_correct": true, "explanation": "正解。「役立っている」は、今も道具が有効に働いている状態を示します。"}, {"text": "笑っている", "is_correct": false, "explanation": "「庭の手入れにとても笑っている」は文の意味が通りません。"}, {"text": "驚いている", "is_correct": false, "explanation": "「庭の手入れにとても驚いている」は不自然です。"}, {"text": "迷っている", "is_correct": false, "explanation": "「庭の手入れにとても迷っている」は文の意味が通りません。"}], "explanations": {"役立っている": "正解。「役立っている」は、今も道具が有効に働いている状態を示します。", "笑っている": "「庭の手入れにとても笑っている」は文の意味が通りません。", "驚いている": "「庭の手入れにとても驚いている」は不自然です。", "迷っている": "「庭の手入れにとても迷っている」は文の意味が通りません。"}, "sentence_index": 6, "correct_answer": "役立っている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私はバスに役立った。", "explanation": "ここは〈乗る〉の意味です。乗るは乗り物に入ることですが、役立つは目的に有効に働くことなので、乗り物に入る動作は表せません。"}, {"text": "強風が屋根に役立った。", "explanation": "ここは〈壊す〉の意味です。壊すは物を壊れさせることですが、役立つは物が有効に働くことなので、壊れる結果は表せません。"}, {"text": "コップに役立った。", "explanation": "ここは〈割る〉の意味です。割るは物を砕く動作ですが、役立つは物が有効に働くことを表すので、砕く動作は表せません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38425, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "非常用の水は、断水のときを役立った。", "corrected_sentence": "非常用の水は、断水のときに役立った。", "error_description": "「役立つ」は「に」を伴います。「を」は目的語の助詞で、ここでは不自然です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "役立った", "is_correct": true, "explanation": "正解。「役立った」は、過去の出来事を述べるた形です。"}, {"text": "役立ったら", "is_correct": false, "explanation": "条件形で、文末に置くと文が完結しません。"}, {"text": "役立とう", "is_correct": false, "explanation": "意志形で、物が主語の文末には合わず、文が完結しません。"}, {"text": "役立って", "is_correct": false, "explanation": "て形は文を続けるための形で、文末の過去としては働きません。"}], "correct_form": "役立った", "base_form": "役立つ", "form_label": "た形", "sentence_index": 1, "explanations": {"役立った": "正解。「役立った」は、過去の出来事を述べるた形です。", "役立ったら": "条件形で、文末に置くと文が完結しません。", "役立とう": "意志形で、物が主語の文末には合わず、文が完結しません。", "役立って": "て形は文を続けるための形で、文末の過去としては働きません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38425, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道具は、庭の掃除にもよく役立てている。", "corrected_sentence": "この道具は、庭の掃除にもよく役立っている。", "error_description": "「役立つ」は自動詞なので「役立っている」が正しいです。「役立てる」は他動詞で目的語を伴う必要があるため、ここでは文が成り立ちません。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "役立った", "is_correct": true, "explanation": "正解。「役立った」は、過去の出来事を述べるた形です。"}, {"text": "役立たせ", "is_correct": false, "explanation": "使役の語幹で、文末に置けず、文が完結しないので不正解。"}, {"text": "役立てて", "is_correct": false, "explanation": "他動詞「役立てる」のて形で、この文の主語には合わず、文も完結しない。"}, {"text": "役立ちながら", "is_correct": false, "explanation": "「ながら」は同時の動作を表す形で、文末に置けず、文が完結しない。"}], "correct_form": "役立った", "base_form": "役立つ", "form_label": "た形", "sentence_index": 7, "explanations": {"役立った": "正解。「役立った」は、過去の出来事を述べるた形です。", "役立たせ": "使役の語幹で、文末に置けず、文が完結しないので不正解。", "役立てて": "他動詞「役立てる」のて形で、この文の主語には合わず、文も完結しない。", "役立ちながら": "「ながら」は同時の動作を表す形で、文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38426, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ネットで」で、知る手段を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ネットを世界の様子が知れる」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は手段を示せない。"}, {"text": "まで", "is_correct": false, "explanation": "「ネットまで」は手段を表せず、意味が合わない。"}], "correct_answer": "で", "explanations": {"で": "「ネットで」で、知る手段を示す。", "を": "「ネットを世界の様子が知れる」は文が成り立たない。", "へ": "方向の「へ」は手段を示せない。", "まで": "「ネットまで」は手段を表せず、意味が合わない。"}, "error_tags": {"を": "object", "へ": "direction", "まで": "extent"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38426, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「気持ちが知れる」で、わかる内容を主語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は主語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「気持ちに知れて」は知る内容を示せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「気持ちで知れて」は手段の意味になり、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「気持ちが知れる」で、わかる内容を主語として示す。", "へ": "方向の「へ」は主語を示せない。", "に": "「気持ちに知れて」は知る内容を示せず、文が成り立たない。", "で": "「気持ちで知れて」は手段の意味になり、文が成り立たない。"}, "error_tags": {"へ": "direction", "に": "target", "で": "instrument"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38426, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「知れる」は「知ることができる」という意味です。", "primary_collocate": null, "pronunciation": "しれる", "ipa": "ɕiɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "この本で歴史が知れます。", "target_word": "知れます", "complexity_tier": "T2", "furigana": "この本[ほん]で歴史[れきし]が知[し]れます。", "sentence_source": "generated"}, {"text": "ネットで世界の様子が知れる。", "target_word": "知れる", "complexity_tier": "T3", "furigana": "ネットで世界[せかい]の様子[ようす]が知[し]れる。", "sentence_source": "generated"}, {"text": "地図を見ると、場所が知れる。", "target_word": "知れる", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ると、場所[ばしょ]が知[し]れる。", "sentence_source": "generated"}, {"text": "調べれば、本当のことが知れるはずだ。", "target_word": "知れる", "complexity_tier": "T4", "furigana": "調[しら]べれば、本当[ほんとう]のことが知[し]れるはずだ。", "sentence_source": "generated"}, {"text": "結果が知れる。", "target_word": "知れる", "complexity_tier": "T1", "furigana": "結果[けっか]が知[し]れる。", "sentence_source": "generated"}, {"text": "この展示で昔の暮らしが知れた。", "target_word": "知れた", "complexity_tier": "T3", "furigana": "この展示[てんじ]で昔[むかし]の暮[く]らしが知[し]れた。", "sentence_source": "generated"}, {"text": "この資料を読めば、町の歴史が知れる。", "target_word": "知れる", "complexity_tier": "T4", "furigana": "この資料[しりょう]を読[よ]めば、町[まち]の歴史[れきし]が知[し]れる。", "sentence_source": "generated"}, {"text": "手紙を読んで、母の気持ちが知れてうれしかった。", "target_word": "知れて", "complexity_tier": "T5", "furigana": "手紙[てがみ]を読[よ]んで、母[はは]の気持[きも]ちが知[し]れてうれしかった。", "sentence_source": "generated"}, {"text": "長く付き合ってみて、初めて相手の良さが知れるものだ。", "target_word": "知れる", "complexity_tier": "T5", "furigana": "長[なが]く付[つ]き合[あ]ってみて、初[はじ]めて相手[あいて]の良[よ]さが知[し]れるものだ。", "sentence_source": "generated"}, {"text": "本だけでは、本当のことは知れない。", "target_word": "知れない", "complexity_tier": "T3", "furigana": "本[ほん]だけでは、本当[ほんとう]のことは知[し]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知れて", "label": "活用"}, {"form": "知れた", "label": "活用"}, {"form": "知れない", "label": "活用"}, {"form": "知れます", "label": "活用"}, {"form": "知れれば", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 知ることができる可能の意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38426, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "知れる", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "切れる", "is_correct": false, "explanation": "しときの一音だけが違う別語。"}, {"text": "入れる", "is_correct": false, "explanation": "しといの一音だけが違う別語。"}, {"text": "慣れる", "is_correct": false, "explanation": "しとなの一音だけが違う別語。"}, {"text": "閉める", "is_correct": false, "explanation": "れとめの一音だけが違う別語。"}], "explanations": {"知れる": "見出し語そのもの。", "切れる": "しときの一音だけが違う別語。", "入れる": "しといの一音だけが違う別語。", "慣れる": "しとなの一音だけが違う別語。", "閉める": "れとめの一音だけが違う別語。"}, "sentence_index": null, "correct_answer": "知れる"}, "level_3": {"options": [{"text": "知れます", "is_correct": true, "explanation": "本で歴史を知ることができるという意味に合う。"}, {"text": "泳げます", "is_correct": false, "explanation": "形は合うが、歴史が泳げるでは意味が合わない。"}, {"text": "光ります", "is_correct": false, "explanation": "形は合うが、歴史が光るでは意味が合わない。"}, {"text": "眠れます", "is_correct": false, "explanation": "形は合うが、歴史が眠れるでは意味が合わない。"}], "explanations": {"知れます": "本で歴史を知ることができるという意味に合う。", "泳げます": "形は合うが、歴史が泳げるでは意味が合わない。", "光ります": "形は合うが、歴史が光るでは意味が合わない。", "眠れます": "形は合うが、歴史が眠れるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "知れます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地図がなくても、重い荷物が知れる。", "explanation": "持てるという意味に「知れる」は使えず、意味が合わない。"}, {"text": "ここから遠くの富士山が知れる。", "explanation": "視界に入る意味は「見える」で、「知れる」は合わない。"}, {"text": "この靴は小さくて、足が知れない。", "explanation": "足が入らない意味に「知れない」は使えず、用法が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38426, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "知れる", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "触れる", "is_correct": false, "explanation": "しとふの一音だけが違う別語。"}, {"text": "折れる", "is_correct": false, "explanation": "しとおの一音だけが違う別語。"}, {"text": "割れる", "is_correct": false, "explanation": "しとわの一音だけが違う別語。"}, {"text": "揺れる", "is_correct": false, "explanation": "しとゆの一音だけが違う別語。"}], "explanations": {"知れる": "見出し語そのもの。", "触れる": "しとふの一音だけが違う別語。", "折れる": "しとおの一音だけが違う別語。", "割れる": "しとわの一音だけが違う別語。", "揺れる": "しとゆの一音だけが違う別語。"}, "sentence_index": null, "correct_answer": "知れる"}, "level_3": {"options": [{"text": "知れる", "is_correct": true, "explanation": "資料を読めば町の歴史を知ることができるという意味に合う。"}, {"text": "泳げる", "is_correct": false, "explanation": "形は合うが、歴史が泳げるでは意味が合わない。"}, {"text": "走れる", "is_correct": false, "explanation": "形は合うが、歴史が走れるでは意味が合わない。"}, {"text": "飛べる", "is_correct": false, "explanation": "形は合うが、歴史が飛べるでは意味が合わない。"}], "explanations": {"知れる": "資料を読めば町の歴史を知ることができるという意味に合う。", "泳げる": "形は合うが、歴史が泳げるでは意味が合わない。", "走れる": "形は合うが、歴史が走れるでは意味が合わない。", "飛べる": "形は合うが、歴史が飛べるでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "知れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この橋は古くて、車は知れない。", "explanation": "通れない意味に「知れない」は使えず、意味が合わない。"}, {"text": "鼻がつまって、花のにおいが知れない。", "explanation": "においをかげない意味に「知れない」は合わない。"}, {"text": "疲れて、もう一歩も知れない。", "explanation": "歩けない意味に「知れない」は使えず、用法が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38426, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この辞書で言葉の意味に知れます。", "corrected_sentence": "この辞書で言葉の意味が知れます。", "error_description": "知ることができる内容は「に」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "知れる", "is_correct": true, "explanation": "文末の終止形で「様子が知れる」と合う。"}, {"text": "知れて", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "知れれば", "is_correct": false, "explanation": "仮定形なので、ここで文が終わらない。"}, {"text": "知れろ", "is_correct": false, "explanation": "命令形なので文に合わない。"}], "correct_form": "知れる", "base_form": "知れる", "form_label": "終止形", "sentence_index": 1, "explanations": {"知れる": "文末の終止形で「様子が知れる」と合う。", "知れて": "て形では文が終わらない。", "知れれば": "仮定形なので、ここで文が終わらない。", "知れろ": "命令形なので文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38426, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実際に行けば、現地の暮らしへ知れるはずです。", "corrected_sentence": "実際に行けば、現地の暮らしが知れるはずです。", "error_description": "知ることができる内容は方向の「へ」ではなく「が」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "知れて", "is_correct": true, "explanation": "「気持ちが知れてうれしかった」とつながるて形。"}, {"text": "知れる", "is_correct": false, "explanation": "終止形では「うれしかった」にそのまま続かない。"}, {"text": "知れれば", "is_correct": false, "explanation": "仮定形で、過去の感情と合わない。"}, {"text": "知れよう", "is_correct": false, "explanation": "意志の形で、うれしかったにつながらない。"}], "correct_form": "知れて", "base_form": "知れる", "form_label": "て形", "sentence_index": 7, "explanations": {"知れて": "「気持ちが知れてうれしかった」とつながるて形。", "知れる": "終止形では「うれしかった」にそのまま続かない。", "知れれば": "仮定形で、過去の感情と合わない。", "知れよう": "意志の形で、うれしかったにつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38427, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人柄が知れる」で、わかる内容を主語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は主語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「人柄に知れます」では、わかる内容を示せず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、文末の「知れます」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「人柄が知れる」で、わかる内容を主語として示す。", "へ": "方向の「へ」は主語を示せない。", "に": "「人柄に知れます」では、わかる内容を示せず文が成り立たない。", "の": "「の」は名詞をつなぐ助詞で、文末の「知れます」の主語を示せない。"}, "error_tags": {"へ": "direction", "に": "case_confusion", "の": "genitive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠れる", "is_correct": true, "explanation": "知られず見えなくなる意味で、反対になる。"}, {"text": "分かる", "is_correct": false, "explanation": "わかる意味で、類義語に近い。"}, {"text": "気づく", "is_correct": false, "explanation": "気がつく意味で反対ではない。"}, {"text": "伝わる", "is_correct": false, "explanation": "広く知られる意味で反対ではない。"}], "correct_answer": "隠れる", "explanations": {"隠れる": "知られず見えなくなる意味で、反対になる。", "分かる": "わかる意味で、類義語に近い。", "気づく": "気がつく意味で反対ではない。", "伝わる": "広く知られる意味で反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38427, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「字から」で、わかる根拠を示す。"}, {"text": "を", "is_correct": false, "explanation": "「字を、育ちが知れた」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「字へ」では根拠にならず、文が成り立たない。"}, {"text": "まで", "is_correct": false, "explanation": "「字まで」は根拠を示せず、意味が合わない。"}], "correct_answer": "から", "explanations": {"から": "「字から」で、わかる根拠を示す。", "を": "「字を、育ちが知れた」は文が成り立たない。", "へ": "「字へ」では根拠にならず、文が成り立たない。", "まで": "「字まで」は根拠を示せず、意味が合わない。"}, "error_tags": {"を": "object", "へ": "direction", "まで": "extent"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "秘める", "is_correct": true, "explanation": "人に知らせず隠す意味で、反対になる。"}, {"text": "悟る", "is_correct": false, "explanation": "理解する意味で反対ではない。"}, {"text": "気づく", "is_correct": false, "explanation": "気がつく意味で反対ではない。"}, {"text": "見つかる", "is_correct": false, "explanation": "発覚する意味で、反対ではない。"}], "correct_answer": "秘める", "explanations": {"秘める": "人に知らせず隠す意味で、反対になる。", "悟る": "理解する意味で反対ではない。", "気づく": "気がつく意味で反対ではない。", "見つかる": "発覚する意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38427, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「知れる」は、自然にわかる、または知ることが可能であるという意味の動詞です。", "primary_collocate": null, "pronunciation": "しれる", "ipa": "ɕiɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "彼の住所はすぐに知れた。", "target_word": "知れた", "complexity_tier": "T2", "furigana": "彼[かれ]の住所[じゅうしょ]はすぐに知[し]れた。", "sentence_source": "generated"}, {"text": "彼の人柄が知れます。", "target_word": "知れます", "complexity_tier": "T2", "furigana": "彼[かれ]の人柄[ひとがら]が知[し]れます。", "sentence_source": "generated"}, {"text": "秘密が世間に知れてしまった。", "target_word": "知れて", "complexity_tier": "T3", "furigana": "秘密[ひみつ]が世間[せけん]に知[し]れてしまった。", "sentence_source": "generated"}, {"text": "話せば、その人の考えが知れる。", "target_word": "知れる", "complexity_tier": "T3", "furigana": "話[はな]せば、その人[ひと]の考[かんが]えが知[し]れる。", "sentence_source": "generated"}, {"text": "嘘が知れたら、信用をなくすだろう。", "target_word": "知れたら", "complexity_tier": "T4", "furigana": "嘘[うそ]が知[し]れたら、信用[しんよう]をなくすだろう。", "sentence_source": "generated"}, {"text": "気心が知れた友人と旅行した。", "target_word": "知れた", "complexity_tier": "T3", "furigana": "気心[きごころ]が知[し]れた友人[ゆうじん]と旅行[りょこう]した。", "sentence_source": "generated"}, {"text": "底が知れない人です。", "target_word": "知れない", "complexity_tier": "T3", "furigana": "底[そこ]が知[し]れない人[ひと]です。", "sentence_source": "generated"}, {"text": "手紙の字から、彼女の育ちが知れた。", "target_word": "知れた", "complexity_tier": "T3", "furigana": "手紙[てがみ]の字[じ]から、彼女[かのじょ]の育[そだ]ちが知[し]れた。", "sentence_source": "generated"}, {"text": "計画が外に知れないように、会議は夜に開かれた。", "target_word": "知れない", "complexity_tier": "T5", "furigana": "計画[けいかく]が外[そと]に知[し]れないように、会議[かいぎ]は夜[よる]に開[ひら]かれた。", "sentence_source": "generated"}, {"text": "事情が知れた。", "target_word": "知れた", "complexity_tier": "T1", "furigana": "事情[じじょう]が知[し]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知れて", "label": "活用"}, {"form": "知れた", "label": "活用"}, {"form": "知れない", "label": "活用"}, {"form": "知れます", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 物事が自然と人に分かる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5211d9c-157e-40de-b755-e90087d97fda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
