INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38427, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "知れる", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "触れる", "is_correct": false, "explanation": "しとふの一音だけが違う別語。"}, {"text": "折れる", "is_correct": false, "explanation": "しとおの一音だけが違う別語。"}, {"text": "割れる", "is_correct": false, "explanation": "しとわの一音だけが違う別語。"}, {"text": "揺れる", "is_correct": false, "explanation": "しとゆの一音だけが違う別語。"}], "explanations": {"知れる": "見出し語そのもの。", "触れる": "しとふの一音だけが違う別語。", "折れる": "しとおの一音だけが違う別語。", "割れる": "しとわの一音だけが違う別語。", "揺れる": "しとゆの一音だけが違う別語。"}, "sentence_index": null, "correct_answer": "知れる"}, "level_3": {"options": [{"text": "知れない", "is_correct": true, "explanation": "「底が知れない人」で、深さがわからない意味に合う。"}, {"text": "歩けない", "is_correct": false, "explanation": "形は合うが、底が歩けない人では意味が合わない。"}, {"text": "眠れない", "is_correct": false, "explanation": "形は合うが、底が眠れない人では意味が合わない。"}, {"text": "食べない", "is_correct": false, "explanation": "形は合うが、底が食べない人では意味が合わない。"}], "explanations": {"知れない": "「底が知れない人」で、深さがわからない意味に合う。", "歩けない": "形は合うが、底が歩けない人では意味が合わない。", "眠れない": "形は合うが、底が眠れない人では意味が合わない。", "食べない": "形は合うが、底が食べない人では意味が合わない。"}, "sentence_index": 6, "correct_answer": "知れない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は昨日、私に事情を知れた。", "explanation": "「知れる」は自然にわかる意味で、人に教える動作には使えない。"}, {"text": "雨で道が知れて、足が濡れた。", "explanation": "道が濡れる意味に「知れる」は使えず、意味が合わない。"}, {"text": "大きな音がして、ドアが知れた。", "explanation": "ドアが開く出来事に「知れる」は使えず、用法が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38427, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "悪い噂が町じゅうを知れてしまった。", "corrected_sentence": "悪い噂が町じゅうに知れてしまった。", "error_description": "広まる先を示す助詞は「を」ではなく「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "知れます", "is_correct": true, "explanation": "文末の丁寧形で「人柄が知れます」と合う。"}, {"text": "知れて", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "知れず", "is_correct": false, "explanation": "否定の連用形で、文末に合わない。"}, {"text": "知れれば", "is_correct": false, "explanation": "仮定形で、文末に合わない。"}], "correct_form": "知れます", "base_form": "知れる", "form_label": "ます形", "sentence_index": 1, "explanations": {"知れます": "文末の丁寧形で「人柄が知れます」と合う。", "知れて": "て形では文が終わらない。", "知れず": "否定の連用形で、文末に合わない。", "知れれば": "仮定形で、文末に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38427, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人の仲が先生に知れるてしまった。", "corrected_sentence": "二人の仲が先生に知れてしまった。", "error_description": "「てしまう」の前は「知れる」ではなく「知れて」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "知れた", "is_correct": true, "explanation": "過去の文末で「育ちが知れた」と合う。"}, {"text": "知れ", "is_correct": false, "explanation": "連用形のままでは文が終わらない。"}, {"text": "知れろ", "is_correct": false, "explanation": "命令形なので文に合わない。"}, {"text": "知れたり", "is_correct": false, "explanation": "「たり」は並べる形で、文末に合わない。"}], "correct_form": "知れた", "base_form": "知れる", "form_label": "た形", "sentence_index": 7, "explanations": {"知れた": "過去の文末で「育ちが知れた」と合う。", "知れ": "連用形のままでは文が終わらない。", "知れろ": "命令形なので文に合わない。", "知れたり": "「たり」は並べる形で、文末に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b8fb9dc-8519-4141-82f0-8afe6c53eb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38428, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「入る」の到着点は「に」で示す。「雪の多い地帯に入ります」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は場所を「を」で目的語にしない。「地帯を入ります」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所や手段を示す。到着点を表す「に」が必要なので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「雪の多い地帯が入ります」は文法上は主語として成り立つが、地帯が入るという意味が不自然で、到着点を表す「に」が合う。"}], "correct_answer": "に", "explanations": {"に": "「入る」の到着点は「に」で示す。「雪の多い地帯に入ります」が正しい。", "を": "「入る」は場所を「を」で目的語にしない。「地帯を入ります」は不自然。", "で": "「で」は動作の場所や手段を示す。到着点を表す「に」が必要なので合わない。", "が": "「が」は主語を示す。「雪の多い地帯が入ります」は文法上は主語として成り立つが、地帯が入るという意味が不自然で、到着点を表す「に」が合う。"}, "error_tags": {"を": "対象", "で": "場所・手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38428, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38428, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある場所の、広い範囲のことを言います。", "primary_collocate": null, "pronunciation": "ちたい", "ipa": "tɕitai", "syllable_count": 3, "sentences": [{"text": "このあたりは雨が少なく、乾いた地帯が広がっています。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "このあたりは雨[あめ]が少[すく]なく、乾[かわ]いた地帯[ちたい]が広[ひろ]がっています。", "sentence_source": "generated"}, {"text": "山を越えると、雪の多い地帯に入ります。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "山[やま]を越[こ]えると、雪[ゆき]の多[おお]い地帯[ちたい]に入[はい]ります。", "sentence_source": "generated"}, {"text": "川の近くの低い地帯は、大雨のときに水があふれやすい。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "川[かわ]の近[ちか]くの低[ひく]い地帯[ちたい]は、大雨[おおあめ]のときに水[みず]があふれやすい。", "sentence_source": "generated"}, {"text": "地図を見ると、南の広い地帯は森になっている。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ると、南[みなみ]の広[ひろ]い地帯[ちたい]は森[もり]になっている。", "sentence_source": "generated"}, {"text": "火山のまわりの地帯では、温泉がたくさん出る。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "火山[かざん]のまわりの地帯[ちたい]では、温泉[おんせん]がたくさん出[で]る。", "sentence_source": "generated"}, {"text": "北の寒い地帯では、冬は川が凍ります。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "北[きた]の寒[さむ]い地帯[ちたい]では、冬[ふゆ]は川[かわ]が凍[こお]ります。", "sentence_source": "generated"}, {"text": "広い草原が広がる地帯を、馬の群れが走っていった。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "広[ひろ]い草原[そうげん]が広[ひろ]がる地帯[ちたい]を、馬[うま]の群[む]れが走[はし]っていった。", "sentence_source": "generated"}, {"text": "この地帯は風が強いので、風力発電に向いている。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "この地帯[ちたい]は風[かぜ]が強[つよ]いので、風力[ふうりょく]発電[はつでん]に向[む]いている。", "sentence_source": "generated"}, {"text": "海に近い地帯は、夏でも少し涼しい。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "海[うみ]に近[ちか]い地帯[ちたい]は、夏[なつ]でも少[すこ]し涼[すず]しい。", "sentence_source": "generated"}, {"text": "地震が多い地帯なので、家は丈夫に作られています。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "地震[じしん]が多[おお]い地帯[ちたい]なので、家[いえ]は丈夫[じょうぶ]に作[つく]られています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地帯", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある場所の広い範囲、広がりのある土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38428, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地帯", "is_correct": true, "explanation": "乾いた広がりのある土地を表す語で、ここに入ると文意が通る。"}, {"text": "地震", "is_correct": false, "explanation": "揺れを指す語で、乾いた土地が広がるという文には合わない。"}, {"text": "地図", "is_correct": false, "explanation": "紙に描いたものを指すので、乾いた地図が広がるとは言わない。"}, {"text": "答案", "is_correct": false, "explanation": "書いた答えのことで、土地の広がりを表す語ではない。"}], "explanations": {"地帯": "乾いた広がりのある土地を表す語で、ここに入ると文意が通る。", "地震": "揺れを指す語で、乾いた土地が広がるという文には合わない。", "地図": "紙に描いたものを指すので、乾いた地図が広がるとは言わない。", "答案": "書いた答えのことで、土地の広がりを表す語ではない。"}, "sentence_index": 0, "correct_answer": "地帯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "着物に赤い地帯を締めて行こう。", "explanation": "ここは〈帯〉の意味。地帯は土地の区域を指すので、着物を締める帯の意味では使わない。"}, {"text": "転んで、地帯に手をついてしまった。", "explanation": "ここは〈地面〉の意味。地帯は広がりのある土地を指すので、手をつく地表には使わない。"}, {"text": "部屋の地帯に、本棚を置いた。", "explanation": "ここは〈一角〉の意味。地帯は広い区域を指すので、部屋の中の狭い場所には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38428, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地帯", "is_correct": true, "explanation": "草原が広がる広い区域を表す語で、ここに入ると文意が通る。"}, {"text": "地下水", "is_correct": false, "explanation": "地下にある水のことで、馬の群れが走る広い土地を表さない。"}, {"text": "地層", "is_correct": false, "explanation": "地面の層を指す語で、馬の群れが走る場所の説明には合わない。"}, {"text": "答弁", "is_correct": false, "explanation": "国会などでの回答を指すので、草原の文脈では意味が通らない。"}], "explanations": {"地帯": "草原が広がる広い区域を表す語で、ここに入ると文意が通る。", "地下水": "地下にある水のことで、馬の群れが走る広い土地を表さない。", "地層": "地面の層を指す語で、馬の群れが走る場所の説明には合わない。", "答弁": "国会などでの回答を指すので、草原の文脈では意味が通らない。"}, "sentence_index": 6, "correct_answer": "地帯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国境に沿って地帯を引いた。", "explanation": "ここは〈線〉の意味。地帯は面の広がりを指すので、境界の線を引く場合には使わない。"}, {"text": "会議の地帯は三十分ほどだった。", "explanation": "ここは〈時間〉の意味。地帯は場所の広がりを指すので、会議の長さには使わない。"}, {"text": "コップの地帯に水をそそいだ。", "explanation": "ここは〈中〉の意味。地帯は広がりのある土地を指すので、コップのような容器の中には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38428, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "砂漠の地帯を、水を運ぶ道があります。", "corrected_sentence": "砂漠の地帯に、水を運ぶ道があります。", "error_description": "「ある」で存在する場所は「に」で示す。「地帯を」は誤りで、正しくは「地帯に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38428, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山あいの地帯を、大量の米が保管されている。", "corrected_sentence": "山あいの地帯に、大量の米が保管されている。", "error_description": "「保管されている」の場所は「に」で示す。「地帯を」は場所を表せず、誤りで、正しくは「地帯に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38429, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「で」は場所を示し、「この地帯では」と場所で話題を限定する。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「この地帯が犬を連れて入ってはいけません」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。「地帯を入ってはいけません」は文として合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する。「この地帯のは」と後ろの「は」が続かず不自然。"}], "correct_answer": "で", "explanations": {"で": "「で」は場所を示し、「この地帯では」と場所で話題を限定する。", "が": "「が」は主語を示す。「この地帯が犬を連れて入ってはいけません」は成り立たない。", "を": "「を」は動作の対象を示す。「地帯を入ってはいけません」は文として合わない。", "の": "「の」は名詞を修飾する。「この地帯のは」と後ろの「は」が続かず不自然。"}, "error_tags": {"が": "主語", "を": "対象", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38429, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38429, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "特定の性質や特徴を持つ、区切られた地域や区域。", "primary_collocate": null, "pronunciation": "ちたい", "ipa": "tɕitai", "syllable_count": 3, "sentences": [{"text": "戦争が終わっても、国境の近くは危険な地帯のままだった。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "戦争[せんそう]が終[お]わっても、国境[こっきょう]の近[ちか]くは危険[きけん]な地帯[ちたい]のままだった。", "sentence_source": "generated"}, {"text": "この地帯では、犬を連れて入ってはいけません。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "この地帯[ちたい]では、犬[いぬ]を連[つ]れて入[はい]ってはいけません。", "sentence_source": "generated"}, {"text": "町の北側は、米作りが盛んな地帯として知られている。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "町[まち]の北側[きたがわ]は、米作[こめづく]りが盛[さか]んな地帯[ちたい]として知[し]られている。", "sentence_source": "generated"}, {"text": "二つの国の間にある地帯には、兵士も住民もいない。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]の間[あいだ]にある地帯[ちたい]には、兵士[へいし]も住民[じゅうみん]もいない。", "sentence_source": "generated"}, {"text": "工場が多く集まった地帯なので、夜でも明るい。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "工場[こうじょう]が多[おお]く集[あつ]まった地帯[ちたい]なので、夜[よる]でも明[あか]るい。", "sentence_source": "generated"}, {"text": "看板に「この先は立ち入り禁止の地帯です」と書いてあった。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "看板[かんばん]に「この先[さき]は立[た]ち入[い]り禁止[きんし]の地帯[ちたい]です」と書[か]いてあった。", "sentence_source": "generated"}, {"text": "川ぞいの、家が集まっている地帯に避難の指示が出た。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "川[かわ]ぞいの、家[いえ]が集[あつ]まっている地帯[ちたい]に避難[ひなん]の指示[しじ]が出[で]た。", "sentence_source": "generated"}, {"text": "砂漠のこの地帯だけは、地下水があって緑が多い。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "砂漠[さばく]のこの地帯[ちたい]だけは、地下水[ちかすい]があって緑[みどり]が多[おお]い。", "sentence_source": "generated"}, {"text": "農薬を使わない地帯として、この地域は有名です。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "農薬[のうやく]を使[つか]わない地帯[ちたい]として、この地域[ちいき]は有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "古い建物が残っている地帯は、散歩する人でにぎわう。", "target_word": "地帯", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]が残[のこ]っている地帯[ちたい]は、散歩[さんぽ]する人[ひと]でにぎわう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地帯", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "特定の性質や役割で区切られた地域・区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38429, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地帯", "is_correct": true, "explanation": "ある性質で区切られた区域を表し、危険な区域のままだったという文に合う。"}, {"text": "地図", "is_correct": false, "explanation": "紙に描いたものを指すので、「危険な地図のまま」とは言わない。"}, {"text": "答案", "is_correct": false, "explanation": "書いた答えのことで、国境の状況を述べる文には合わない。"}, {"text": "答弁", "is_correct": false, "explanation": "国会などでの回答を指すので、国境の危険を表す文では意味が通らない。"}], "explanations": {"地帯": "ある性質で区切られた区域を表し、危険な区域のままだったという文に合う。", "地図": "紙に描いたものを指すので、「危険な地図のまま」とは言わない。", "答案": "書いた答えのことで、国境の状況を述べる文には合わない。", "答弁": "国会などでの回答を指すので、国境の危険を表す文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "地帯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの国の間には、川が地帯として流れている。", "explanation": "ここは〈境界線〉の意味。地帯は面の広がりを指すので、細い川のような一本の線には合わない。"}, {"text": "着物の上から、赤い地帯を締めた。", "explanation": "ここは〈帯〉の意味。地帯は土地の区域を指すので、着物を締める帯の意味では使わない。"}, {"text": "テストで地帯を取った。", "explanation": "ここは〈点数〉の意味。地帯は区域を指すので、テストの得点には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38429, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地帯", "is_correct": true, "explanation": "家が集まる、区切られた区域を表し、避難指示の対象という文に合う。"}, {"text": "地下水", "is_correct": false, "explanation": "地下にある水のことで、避難指示が出される区域とは関係がない。"}, {"text": "地層", "is_correct": false, "explanation": "地面の層を指すので、避難指示の対象になる区域の説明には合わない。"}, {"text": "地震", "is_correct": false, "explanation": "揺れを指す語で、区域を表さないので「避難の指示が出た」の対象にはならない。"}], "explanations": {"地帯": "家が集まる、区切られた区域を表し、避難指示の対象という文に合う。", "地下水": "地下にある水のことで、避難指示が出される区域とは関係がない。", "地層": "地面の層を指すので、避難指示の対象になる区域の説明には合わない。", "地震": "揺れを指す語で、区域を表さないので「避難の指示が出た」の対象にはならない。"}, "sentence_index": 6, "correct_answer": "地帯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の地帯は三十分ほどだった。", "explanation": "ここは〈時間〉の意味。地帯は場所の広がりを指すので、会議の長さには使わない。"}, {"text": "参加者の地帯が増えた。", "explanation": "ここは〈数〉の意味。地帯は区域を指すので、人数の増加には使わない。"}, {"text": "鍋の地帯に水を入れた。", "explanation": "ここは〈中〉の意味。地帯は広がりのある土地を指すので、鍋のような容器の中には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38429, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地帯で立ち入る人は、許可が必要です。", "corrected_sentence": "この地帯に立ち入る人は、許可が必要です。", "error_description": "「立ち入る」の到着点は「に」で示す。「で」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38429, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場が集まる地帯を、新しい道路ができた。", "corrected_sentence": "工場が集まる地帯に、新しい道路ができた。", "error_description": "「できる」の場所は「に」で示す。「地帯を」は誤りで、正しくは「地帯に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38430, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。「長年の夢」のように、「長年」と「夢」をつなぐ。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「長年が夢がかなった」では主語が二つになり、成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「長年を夢がかなった」では、動作の対象が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。「長年で夢がやっとかなった」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。「長年の夢」のように、「長年」と「夢」をつなぐ。", "が": "主格の「が」。「長年が夢がかなった」では主語が二つになり、成り立たない。", "を": "目的語の「を」。「長年を夢がかなった」では、動作の対象が成り立たない。", "で": "手段・場所の「で」。「長年で夢がやっとかなった」は成り立たない。"}, "error_tags": {"が": "主格（主語を示す）", "を": "対格（目的語を示す）", "に": "位置・時点の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38430, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。「長年の習慣」のように、「長年」と「習慣」をつなぐ。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。「長年で習慣で」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。ここには方向を示す語がないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「長年より習慣で」では比べる対象が成立しない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。「長年の習慣」のように、「長年」と「習慣」をつなぐ。", "で": "手段・場所の「で」。「長年で習慣で」は成り立たない。", "へ": "方向の「へ」。ここには方向を示す語がないので合わない。", "より": "比較の「より」。「長年より習慣で」では比べる対象が成立しない。"}, "error_tags": {"で": "手段・場所の格", "へ": "方向の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38430, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「長年」とは、とても長い時間のことを言います。何年もずっと続いているときに使います。", "primary_collocate": null, "pronunciation": "ながねん", "ipa": "naɡaneɴ", "syllable_count": 4, "sentences": [{"text": "父は長年、同じ会社で働いている。", "target_word": "長年", "complexity_tier": "T3", "furigana": "父[ちち]は 長年[ながねん]、 同[おな]じ 会社[かいしゃ]で 働[はたら]いている。", "sentence_source": "generated"}, {"text": "長年の夢がやっとかなった。", "target_word": "長年", "complexity_tier": "T3", "furigana": "長年[ながねん]の 夢[ゆめ]がやっとかなった。", "sentence_source": "generated"}, {"text": "祖母は長年使った古いミシンを大切にしている。", "target_word": "長年", "complexity_tier": "T3", "furigana": "祖母[そぼ]は 長年[ながねん] 使[つか]った 古[ふる]いミシンを 大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "長年の努力が実って、試験に合格した。", "target_word": "長年", "complexity_tier": "T3", "furigana": "長年[ながねん]の 努力[どりょく]が 実[みの]って、 試験[しけん]に 合格[ごうかく]した。", "sentence_source": "generated"}, {"text": "長年住んだ町を離れるのは、さびしい。", "target_word": "長年", "complexity_tier": "T3", "furigana": "長年[ながねん] 住[す]んだ 町[まち]を 離[はな]れるのは、さびしい。", "sentence_source": "generated"}, {"text": "彼とは長年の友人で、何でも話せる。", "target_word": "長年", "complexity_tier": "T3", "furigana": "彼[かれ]とは 長年[ながねん]の 友人[ゆうじん]で、 何[なん]でも 話[はな]せる。", "sentence_source": "generated"}, {"text": "先生は長年、子どもたちに英語を教えてきた。", "target_word": "長年", "complexity_tier": "T3", "furigana": "先生[せんせい]は 長年[ながねん]、 子[こ]どもたちに 英語[えいご]を 教[おし]えてきた。", "sentence_source": "generated"}, {"text": "長年の習慣で、朝五時に自然と目が覚める。", "target_word": "長年", "complexity_tier": "T3", "furigana": "長年[ながねん]の 習慣[しゅうかん]で、 朝[あさ] 五時[ごじ]に 自然[しぜん]と 目[め]が 覚[さ]める。", "sentence_source": "generated"}, {"text": "この店は長年、地元の人に愛されている。", "target_word": "長年", "complexity_tier": "T3", "furigana": "この 店[みせ]は 長年[ながねん]、 地元[じもと]の 人[ひと]に 愛[あい]されている。", "sentence_source": "generated"}, {"text": "長年悩んでいた問題が、ようやく解決した。", "target_word": "長年", "complexity_tier": "T3", "furigana": "長年[ながねん] 悩[なや]んでいた 問題[もんだい]が、ようやく 解決[かいけつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "長年", "label": "基本形"}, {"form": "長年の", "label": "連体用法"}], "register": "口語（普通体）", "sense_fingerprint": "何年もの長い間、ずっと続いてきた期間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38430, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "長年", "is_correct": true, "explanation": "何年もの長い期間を表す。「父は長年、同じ会社で働いている」で、長く続いていることを示す。"}, {"text": "一瞬", "is_correct": false, "explanation": "ほんの短い時間を表し、何年も働き続けている期間には合わない。"}, {"text": "数分", "is_correct": false, "explanation": "数分では働き続けている期間にならず、文の意味が合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "物を表す名詞で、働いている期間を表せない。"}], "explanations": {"長年": "何年もの長い期間を表す。「父は長年、同じ会社で働いている」で、長く続いていることを示す。", "一瞬": "ほんの短い時間を表し、何年も働き続けている期間には合わない。", "数分": "数分では働き続けている期間にならず、文の意味が合わない。", "手紙": "物を表す名詞で、働いている期間を表せない。"}, "sentence_index": 0, "correct_answer": "長年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長年の努力が一晩で実って、試験に合格した。", "explanation": "〈長年〉は何年も続いた努力に使う語。努力が一晩で実るような短い期間は〈短期〉で表し、〈長年〉は合わない。"}, {"text": "長年、ちょっと待ってください。すぐ戻ります。", "explanation": "〈長年〉は何年もの長い期間を表す。数分の待ち時間には〈少々〉などを使うので、ここでは合わない。"}, {"text": "長年のロープを切って、橋を作った。", "explanation": "〈長年〉は時間の長さを表す語。ロープの長さには〈長い〉を使うので、この意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38430, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "長年", "is_correct": true, "explanation": "何年もの長い期間を表す。「先生は長年、英語を教えてきた」で、長く続けてきたことを示す。"}, {"text": "名刺", "is_correct": false, "explanation": "物を表す名詞で、英語を教えてきた期間を表せない。"}, {"text": "小包", "is_correct": false, "explanation": "物を表す名詞で、期間の説明にはならない。"}, {"text": "食器", "is_correct": false, "explanation": "物を表す名詞で、教え続けた期間には合わない。"}], "explanations": {"長年": "何年もの長い期間を表す。「先生は長年、英語を教えてきた」で、長く続けてきたことを示す。", "名刺": "物を表す名詞で、英語を教えてきた期間を表せない。", "小包": "物を表す名詞で、期間の説明にはならない。", "食器": "物を表す名詞で、教え続けた期間には合わない。"}, "sentence_index": 6, "correct_answer": "長年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長年悩んでいた問題が一度きりで消えて、みんなほっとした。", "explanation": "〈長年〉は何年も続くこと。一度きりで終わる出来事には〈一回限り〉を使うので、〈長年〉は合わない。"}, {"text": "長年の休みが取れたので、旅行に行った。", "explanation": "休みの長さには〈長期〉を使う。〈長年〉は何年にもわたる期間のことで、数週間の休みには合わない。"}, {"text": "長年の雨で、川の水が増えた。", "explanation": "雨が降り続く時間には〈長雨〉を使う。〈長年〉は何年もの期間を表すので、雨には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38430, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は長年に経験を生かして、味を守っている。", "corrected_sentence": "この店は長年の経験を生かして、味を守っている。", "error_description": "「長年」に続けるのは「の」。「に」は時点や場所を示すので、「長年に経験」は不自然。正しくは「長年の経験」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38430, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの作家は長年を経験をもとに、小説を書き続けている。", "corrected_sentence": "あの作家は長年の経験をもとに、小説を書き続けている。", "error_description": "「長年」に続けるのは「の」。「を」は目的語に付くので、「長年を経験」は成り立たない。正しくは「長年の経験」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
