INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38432, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38432, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所から別の場所へ、道を通って行くこと。", "primary_collocate": null, "pronunciation": "わたる", "ipa": "wataɾɯ", "syllable_count": 3, "sentences": [{"text": "道路を渡るときは、かならず右と左を見ましょう。", "target_word": "渡る", "complexity_tier": "T3", "furigana": "道路[どうろ]を渡[わた]るときは、かならず右[みぎ]と左[ひだり]を見[み]ましょう。", "sentence_source": "generated"}, {"text": "赤信号なのに道を渡った人が、車にひかれそうになった。", "target_word": "渡った", "complexity_tier": "T3", "furigana": "赤信号[あかしんごう]なのに道[みち]を渡[わた]った人[ひと]が、車[くるま]にひかれそうになった。", "sentence_source": "generated"}, {"text": "細い道を渡って、森の中の小さな神社へ向かった。", "target_word": "渡って", "complexity_tier": "T3", "furigana": "細[ほそ]い道[みち]を渡[わた]って、森[もり]の中[なか]の小[ちい]さな神社[じんじゃ]へ向[む]かった。", "sentence_source": "generated"}, {"text": "学校の前の道を渡ると、公園の入り口が見えてくる。", "target_word": "渡る", "complexity_tier": "T3", "furigana": "学校[がっこう]の前[まえ]の道[みち]を渡[わた]ると、公園[こうえん]の入[い]り口[ぐち]が見[み]えてくる。", "sentence_source": "generated"}, {"text": "向こう側の店へ行くには、広い通りを渡らなければならない。", "target_word": "渡らなければ", "complexity_tier": "T4", "furigana": "向[む]こう側[がわ]の店[みせ]へ行[い]くには、広[ひろ]い通[とお]りを渡[わた]らなければならない。", "sentence_source": "generated"}, {"text": "犬が急に道を渡ろうとしたので、あわててひもを引いた。", "target_word": "渡ろう", "complexity_tier": "T3", "furigana": "犬[いぬ]が急[きゅう]に道[みち]を渡[わた]ろうとしたので、あわててひもを引[ひ]いた。", "sentence_source": "generated"}, {"text": "雨の日は、すべりやすい横断歩道を慎重に渡った。", "target_word": "渡った", "complexity_tier": "T4", "furigana": "雨[あめ]の日[ひ]は、すべりやすい横断歩道[おうだんほどう]を慎重[しんちょう]に渡[わた]った。", "sentence_source": "generated"}, {"text": "兄は道を渡った先にある図書館で、毎週本を借りている。", "target_word": "渡った", "complexity_tier": "T3", "furigana": "兄[あに]は道[みち]を渡[わた]った先[さき]にある図書館[としょかん]で、毎週[まいしゅう]本[ほん]を借[か]りている。", "sentence_source": "generated"}, {"text": "車が来ないのを確かめてから、私は静かな通りを渡った。", "target_word": "渡った", "complexity_tier": "T3", "furigana": "車[くるま]が来[こ]ないのを確[たし]かめてから、私[わたし]は静[しず]かな通[とお]りを渡[わた]った。", "sentence_source": "generated"}, {"text": "足の悪いおばあさんの手を引いて、一緒に道を渡ってあげた。", "target_word": "渡って", "complexity_tier": "T3", "furigana": "足[あし]の悪[わる]いおばあさんの手[て]を引[ひ]いて、一緒[いっしょ]に道[みち]を渡[わた]ってあげた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "渡る", "label": "終止形"}, {"form": "渡り", "label": "連用形"}, {"form": "渡った", "label": "過去形"}, {"form": "渡って", "label": "テ形"}, {"form": "渡らない", "label": "否定形"}, {"form": "渡れば", "label": "仮定形"}, {"form": "渡れる", "label": "可能形"}, {"form": "渡ろう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "道路や通りを横切って、向こう側へ行く(道を渡る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38432, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渡る", "is_correct": true, "explanation": "辞書形。「道路を渡るときは」の形で、道を横切る動作を表す。"}, {"text": "渡って", "is_correct": false, "explanation": "テ形。「渡ってときは」では文が成り立たず、ここには入らない。"}, {"text": "渡れば", "is_correct": false, "explanation": "仮定形。「渡れば」に続けると「ときは」の形が崩れ、文が合わない。"}, {"text": "渡らず", "is_correct": false, "explanation": "否定の連用形。「渡らずときは」では文が成り立たず、意味も通らない。"}], "explanations": {"渡る": "辞書形。「道路を渡るときは」の形で、道を横切る動作を表す。", "渡って": "テ形。「渡ってときは」では文が成り立たず、ここには入らない。", "渡れば": "仮定形。「渡れば」に続けると「ときは」の形が崩れ、文が合わない。", "渡らず": "否定の連用形。「渡らずときは」では文が成り立たず、意味も通らない。"}, "sentence_index": 0, "correct_answer": "渡る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車を渡って、大阪へ行った。", "explanation": "ここは「乗る」の意味。電車に乗って移動するのは「乗る」を使い、「渡る」は道や橋を通って行くことに使う。"}, {"text": "狭いトンネルを渡ると、海が見えた。", "explanation": "ここは「くぐる」の意味。トンネルを通り抜けるのは「くぐる」で、「渡る」は合わない。"}, {"text": "急な崖を渡って、谷底へ下りた。", "explanation": "ここは「下りる」の意味。崖を下りるのは「下りる」で、「渡る」は道や橋を越えて向こう側へ行くときに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38432, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渡った", "is_correct": true, "explanation": "過去形。「慎重に渡った」で、過去に横断歩道を渡った行為を表す。"}, {"text": "渡り", "is_correct": false, "explanation": "連用形。「慎重に渡り」では文が続かず、意味も通らない。"}, {"text": "渡って", "is_correct": false, "explanation": "テ形。文末に立てず、「慎重に渡って。」では文が終わらない。"}, {"text": "渡れない", "is_correct": false, "explanation": "否定の可能形。渡れなかったという意味になり、慎重に渡ったという文と逆になる。"}], "explanations": {"渡った": "過去形。「慎重に渡った」で、過去に横断歩道を渡った行為を表す。", "渡り": "連用形。「慎重に渡り」では文が続かず、意味も通らない。", "渡って": "テ形。文末に立てず、「慎重に渡って。」では文が終わらない。", "渡れない": "否定の可能形。渡れなかったという意味になり、慎重に渡ったという文と逆になる。"}, "sentence_index": 6, "correct_answer": "渡った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は手紙を先生へ渡った。", "explanation": "ここは「渡す」の意味。「渡る」は自動詞で物には使えず、物を人に手渡すときは「渡す」を使う。"}, {"text": "急な山道を渡って、頂上まで上がった。", "explanation": "ここは「のぼる」の意味。山道を上がるのは「のぼる」で、「渡る」は合わない。"}, {"text": "風邪が家族全員に渡ってしまった。", "explanation": "ここは「移る」（うつる）の意味。風邪や病気が人にうつるときは「移る」を使い、「渡る」は道や橋を越えて移動するときに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38432, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "交差点で、道に渡るときは右を見る。", "corrected_sentence": "交差点で、道を渡るときは右を見る。", "error_description": "誤: 「道に渡る」（に）。正: 「道を渡る」（を）。「渡る」は通過する場所を「を」で表す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "渡った", "is_correct": true, "explanation": "過去形。「渡った人」で、過去に道を渡った事実を表す。"}, {"text": "渡って", "is_correct": false, "explanation": "テ形。「渡って人」と名詞に続かず、文が成り立たない。"}, {"text": "渡ろう", "is_correct": false, "explanation": "意志形。人の行為の事実を表せず、「ひかれそうになった」の文と合わない。"}, {"text": "渡らない", "is_correct": false, "explanation": "否定形。「渡らない人」では、道を渡ったという事実と逆になる。"}], "correct_form": "渡った", "base_form": "渡る", "form_label": "過去形", "sentence_index": 1, "explanations": {"渡った": "過去形。「渡った人」で、過去に道を渡った事実を表す。", "渡って": "テ形。「渡って人」と名詞に続かず、文が成り立たない。", "渡ろう": "意志形。人の行為の事実を表せず、「ひかれそうになった」の文と合わない。", "渡らない": "否定形。「渡らない人」では、道を渡ったという事実と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38432, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は道を渡れた先の公園で、毎週犬を散歩させている。", "corrected_sentence": "姉は道を渡った先の公園で、毎週犬を散歩させている。", "error_description": "誤: 「渡れた」（可能形）。正: 「渡った」（過去形）。実際に道を渡った行為を述べるので、可能形は合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "渡った", "is_correct": true, "explanation": "過去形。「渡った先にある」で、道を渡り終えた後の場所を表す。"}, {"text": "渡り", "is_correct": false, "explanation": "連用形。「渡り先」と続かず、文の構造が成り立たない。"}, {"text": "渡れ", "is_correct": false, "explanation": "命令形。図書館の場所を説明する文とは合わない。"}, {"text": "渡れない", "is_correct": false, "explanation": "否定の可能形。渡れなかったという意味になり、図書館に通う文脈と合わない。"}], "correct_form": "渡った", "base_form": "渡る", "form_label": "過去形", "sentence_index": 7, "explanations": {"渡った": "過去形。「渡った先にある」で、道を渡り終えた後の場所を表す。", "渡り": "連用形。「渡り先」と続かず、文の構造が成り立たない。", "渡れ": "命令形。図書館の場所を説明する文とは合わない。", "渡れない": "否定の可能形。渡れなかったという意味になり、図書館に通う文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38433, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「渡ると」の「と」。条件を表し、後ろの「駅はすぐそこです」につながる。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。動詞に直接つくと、条件の意味にならず文が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「渡る」の直後には方向を示す助詞は続かず、文の構造が合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。動詞の直後には続かず、「橋を」は名詞にかかる形で、ここの文の構造と合わない。"}], "correct_answer": "と", "explanations": {"と": "「渡ると」の「と」。条件を表し、後ろの「駅はすぐそこです」につながる。", "で": "手段・場所の「で」。動詞に直接つくと、条件の意味にならず文が合わない。", "へ": "方向の「へ」。「渡る」の直後には方向を示す助詞は続かず、文の構造が合わない。", "を": "目的語の「を」。動詞の直後には続かず、「橋を」は名詞にかかる形で、ここの文の構造と合わない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38433, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38433, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所から別の場所へ、道や橋などを通って移動する。", "primary_collocate": null, "pronunciation": "わたる", "ipa": "wataɾɯ", "syllable_count": 3, "sentences": [{"text": "強い風の日は、高い橋を渡るときに十分注意しよう。", "target_word": "渡る", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]の日[ひ]は、高[たか]い橋[はし]を渡[わた]るときに十分[じゅうぶん]注意[ちゅうい]しよう。", "sentence_source": "generated"}, {"text": "川にかかる橋を渡ると、駅はすぐそこです。", "target_word": "渡る", "complexity_tier": "T3", "furigana": "川[かわ]にかかる橋[はし]を渡[わた]ると、駅[えき]はすぐそこです。", "sentence_source": "generated"}, {"text": "ゆれる吊り橋を、子どもたちは手をつないで渡った。", "target_word": "渡った", "complexity_tier": "T3", "furigana": "ゆれる吊[つ]り橋[ばし]を、子[こ]どもたちは手[て]をつないで渡[わた]った。", "sentence_source": "generated"}, {"text": "大きな橋を渡って、私たちは隣の町へ行った。", "target_word": "渡って", "complexity_tier": "T3", "furigana": "大[おお]きな橋[はし]を渡[わた]って、私[わたし]たちは隣[となり]の町[まち]へ行[い]った。", "sentence_source": "generated"}, {"text": "この橋は古いので、一人ずつ渡ってください。", "target_word": "渡って", "complexity_tier": "T3", "furigana": "この橋[はし]は古[ふる]いので、一人[ひとり]ずつ渡[わた]ってください。", "sentence_source": "generated"}, {"text": "踏切を渡るときは、左右をよく見なければいけない。", "target_word": "渡る", "complexity_tier": "T3", "furigana": "踏切[ふみきり]を渡[わた]るときは、左右[さゆう]をよく見[み]なければいけない。", "sentence_source": "generated"}, {"text": "川が増水していたので、橋を渡らずに遠回りして帰った。", "target_word": "渡らず", "complexity_tier": "T4", "furigana": "川[かわ]が増水[ぞうすい]していたので、橋[はし]を渡[わた]らずに遠回[とおまわ]りして帰[かえ]った。", "sentence_source": "generated"}, {"text": "川の向こう岸へ行くには、あの長い橋を渡るしかない。", "target_word": "渡る", "complexity_tier": "T3", "furigana": "川[かわ]の向[む]こう岸[ぎし]へ行[い]くには、あの長[なが]い橋[はし]を渡[わた]るしかない。", "sentence_source": "generated"}, {"text": "母は歩道橋を渡って、向かいのパン屋に入っていった。", "target_word": "渡って", "complexity_tier": "T3", "furigana": "母[はは]は歩道橋[ほどうきょう]を渡[わた]って、向[む]かいのパン屋[や]に入[はい]っていった。", "sentence_source": "generated"}, {"text": "この木の橋は細くて、車では渡れない。", "target_word": "渡れない", "complexity_tier": "T3", "furigana": "この木[き]の橋[はし]は細[ほそ]くて、車[くるま]では渡[わた]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "渡る", "label": "終止形"}, {"form": "渡り", "label": "連用形"}, {"form": "渡った", "label": "過去形"}, {"form": "渡って", "label": "テ形"}, {"form": "渡らない", "label": "否定形"}, {"form": "渡れば", "label": "仮定形"}, {"form": "渡れる", "label": "可能形"}, {"form": "渡ろう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "橋・道などを通って、川や通りの向こう側へ移動する(橋を渡る)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e51e670-b7a9-44dc-bcb5-6ee950cd5d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38433, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渡る", "is_correct": true, "explanation": "辞書形。「高い橋を渡るときに」の形で、橋を通って向こう側へ行く動作を表す。"}, {"text": "渡って", "is_correct": false, "explanation": "テ形。「渡ってときに」では文が成り立たず、ここには入らない。"}, {"text": "渡れば", "is_correct": false, "explanation": "仮定形。「渡ればときに」と続かず、文が崩れる。"}, {"text": "渡らず", "is_correct": false, "explanation": "否定の連用形。「渡らずときに」では文が成り立たず、意味も通らない。"}], "explanations": {"渡る": "辞書形。「高い橋を渡るときに」の形で、橋を通って向こう側へ行く動作を表す。", "渡って": "テ形。「渡ってときに」では文が成り立たず、ここには入らない。", "渡れば": "仮定形。「渡ればときに」と続かず、文が崩れる。", "渡らず": "否定の連用形。「渡らずときに」では文が成り立たず、意味も通らない。"}, "sentence_index": 0, "correct_answer": "渡る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "橋の下を渡って、川辺の小屋へ入った。", "explanation": "ここは「くぐる」（下を通り抜ける）の意味。渡るは川や道を越えて向こう側へ行くことなので、橋の下を通るだけでは合わない。"}, {"text": "彼は長い山を渡って、村へ向かった。", "explanation": "ここは「越える」の意味。山や峠を越えるときは「越える」を使い、「渡る」は川や道などに使う。"}, {"text": "急な崖を渡って、谷底へ下りた。", "explanation": "ここは「下りる」の意味。崖を下りるのは「下りる」で、「渡る」は道や橋を越えて向こう側へ行くときに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38433, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渡らず", "is_correct": true, "explanation": "否定の連用形。「橋を渡らずに」で、橋を通らずに遠回りしたという文になる。"}, {"text": "渡れば", "is_correct": false, "explanation": "仮定形。「渡れば」は渡ることができればの意味になり、遠回りした文脈と合わない。"}, {"text": "渡りたかった", "is_correct": false, "explanation": "願望の過去形。橋を渡りたかったという希望の文になり、遠回りした事実と合わない。"}, {"text": "渡り", "is_correct": false, "explanation": "連用形。「橋を渡り遠回り」では文が続かず、意味も通らない。"}], "explanations": {"渡らず": "否定の連用形。「橋を渡らずに」で、橋を通らずに遠回りしたという文になる。", "渡れば": "仮定形。「渡れば」は渡ることができればの意味になり、遠回りした文脈と合わない。", "渡りたかった": "願望の過去形。橋を渡りたかったという希望の文になり、遠回りした事実と合わない。", "渡り": "連用形。「橋を渡り遠回り」では文が続かず、意味も通らない。"}, "sentence_index": 6, "correct_answer": "渡らず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この細い路地は、車では渡れない。", "explanation": "ここは「通る」の意味。路地のように道の中を進む場合は「通る」を使い、「渡る」は川や道を越える場合に使う。"}, {"text": "彼は去年、隣の町へ渡った。", "explanation": "ここは「引っ越す」の意味。住まいを変えて移るのは「引っ越す」を使い、「渡る」は道や橋などを越えて行くことに使う。"}, {"text": "階段を渡って、二階へ上がった。", "explanation": "ここは「上る」の意味。階段は上るもので、「渡る」の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38433, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族は古い橋に渡って、山の村へ向かった。", "corrected_sentence": "家族は古い橋を渡って、山の村へ向かった。", "error_description": "誤: 「橋に渡る」（に）。正: 「橋を渡る」（を）。「渡る」は通過する場所を「を」で表す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "渡る", "is_correct": true, "explanation": "終止形。「橋を渡ると、駅は」の「と」の前に置かれる形で、文の条件を表す。"}, {"text": "渡って", "is_correct": false, "explanation": "テ形。「渡ってと」と条件の形に続かず、文が成り立たない。"}, {"text": "渡ろう", "is_correct": false, "explanation": "意志形。「〜と」の条件には続かず、文が成り立たない。"}, {"text": "渡らず", "is_correct": false, "explanation": "否定の連用形。「渡らずと」では条件文にならず、文が成り立たない。"}], "correct_form": "渡る", "base_form": "渡る", "form_label": "終止形", "sentence_index": 1, "explanations": {"渡る": "終止形。「橋を渡ると、駅は」の「と」の前に置かれる形で、文の条件を表す。", "渡って": "テ形。「渡ってと」と条件の形に続かず、文が成り立たない。", "渡ろう": "意志形。「〜と」の条件には続かず、文が成り立たない。", "渡らず": "否定の連用形。「渡らずと」では条件文にならず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38433, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは川を渡ろって、向こう岸の林へ行った。", "corrected_sentence": "子どもたちは川を渡って、向こう岸の林へ行った。", "error_description": "誤: 「渡ろって」（渡ろう＋って）。正: 「渡って」（テ形）。「渡ろ」は意志形で、続く「って」とつながらない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "渡る", "is_correct": true, "explanation": "終止形。「〜しかない」の前には辞書形が続き、この文の形に合う。"}, {"text": "渡り", "is_correct": false, "explanation": "連用形。「渡りしかない」では文が続かず、意味も通らない。"}, {"text": "渡らず", "is_correct": false, "explanation": "否定の連用形。「渡らずしかない」では意味が通らず、文の形が合わない。"}, {"text": "渡らない", "is_correct": false, "explanation": "否定形。「渡らないしかない」は二重の否定になり、この文の意味と合わない。"}], "correct_form": "渡る", "base_form": "渡る", "form_label": "終止形", "sentence_index": 7, "explanations": {"渡る": "終止形。「〜しかない」の前には辞書形が続き、この文の形に合う。", "渡り": "連用形。「渡りしかない」では文が続かず、意味も通らない。", "渡らず": "否定の連用形。「渡らずしかない」では意味が通らず、文の形が合わない。", "渡らない": "否定形。「渡らないしかない」は二重の否定になり、この文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2d106d-2a56-4b53-905b-e81d97b29ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38434, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「問題に直面する」と、直面する対象を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「直面する」は「を」を取らないので不適切。"}, {"text": "で", "is_correct": false, "explanation": "「で」では直面する対象を示せず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「彼は」が主語なので、「問題が」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「問題に直面する」と、直面する対象を「に」で示す。", "を": "「直面する」は「を」を取らないので不適切。", "で": "「で」では直面する対象を示せず、文が成り立たない。", "が": "「彼は」が主語なので、「問題が」は文として成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "で": "wrong_case", "が": "double_subject"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "回避", "is_correct": true, "explanation": "困難に出会う「直面」に対し、それを避ける「回避」は反対の意味。"}, {"text": "遭遇", "is_correct": false, "explanation": "困難などに出会う意味で、「直面」に近い。"}, {"text": "対峙", "is_correct": false, "explanation": "正面から向き合う意味で、反対ではない。"}, {"text": "直視", "is_correct": false, "explanation": "目をそらさず見る意味で、「直面」に近い。"}], "correct_answer": "回避", "explanations": {"回避": "困難に出会う「直面」に対し、それを避ける「回避」は反対の意味。", "遭遇": "困難などに出会う意味で、「直面」に近い。", "対峙": "正面から向き合う意味で、反対ではない。", "直視": "目をそらさず見る意味で、「直面」に近い。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38434, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「環境に直面する」と、直面する対象を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「直面する」は「を」を取らないので不適切。"}, {"text": "が", "is_correct": false, "explanation": "「環境が直面する」では主語と対象の関係が合わない。"}, {"text": "の", "is_correct": false, "explanation": "「環境の直面すると」では動詞に続かず、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「環境に直面する」と、直面する対象を「に」で示す。", "を": "「直面する」は「を」を取らないので不適切。", "が": "「環境が直面する」では主語と対象の関係が合わない。", "の": "「環境の直面すると」では動詞に続かず、文として成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "が": "wrong_subject", "の": "wrong_connector"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逃避", "is_correct": true, "explanation": "問題に出会う「直面」に対し、そこから逃げる「逃避」は反対の意味。"}, {"text": "対決", "is_correct": false, "explanation": "正面から立ち向かう意味で、反対ではない。"}, {"text": "直視", "is_correct": false, "explanation": "目をそらさず見る意味で、「直面」に近い。"}, {"text": "解決", "is_correct": false, "explanation": "問題を片づける意味で、反対の関係ではない。"}], "correct_answer": "逃避", "explanations": {"逃避": "問題に出会う「直面」に対し、そこから逃げる「逃避」は反対の意味。", "対決": "正面から立ち向かう意味で、反対ではない。", "直視": "目をそらさず見る意味で、「直面」に近い。", "解決": "問題を片づける意味で、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38434, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "困ったことや難しいことに出会うこと。", "primary_collocate": null, "pronunciation": "ちょくめん", "ipa": "tɕokɯmeɴ", "syllable_count": 4, "sentences": [{"text": "困難に直面する。", "target_word": "直面する", "complexity_tier": "T1", "furigana": "困難[こんなん]に直面[ちょくめん]する。", "sentence_source": "generated"}, {"text": "彼は問題に直面しました。", "target_word": "直面しました", "complexity_tier": "T2", "furigana": "彼[かれ]は問題[もんだい]に直面[ちょくめん]しました。", "sentence_source": "generated"}, {"text": "みんな同じ問題に直面しました。", "target_word": "直面しました", "complexity_tier": "T2", "furigana": "みんな同[おな]じ問題[もんだい]に直面[ちょくめん]しました。", "sentence_source": "generated"}, {"text": "今、難しい仕事に直面しています。", "target_word": "直面しています", "complexity_tier": "T3", "furigana": "今[いま]、難[むずか]しい仕事[しごと]に直面[ちょくめん]しています。", "sentence_source": "generated"}, {"text": "直面した問題を、先生に相談した。", "target_word": "直面した", "complexity_tier": "T3", "furigana": "直面[ちょくめん]した問題[もんだい]を、先生[せんせい]に相談[そうだん]した。", "sentence_source": "generated"}, {"text": "旅行中、思いがけないトラブルに直面した。", "target_word": "直面した", "complexity_tier": "T3", "furigana": "旅行中[りょこうちゅう]、思[おも]いがけないトラブルに直面[ちょくめん]した。", "sentence_source": "generated"}, {"text": "直面する困難を、友達と乗り越えたい。", "target_word": "直面する", "complexity_tier": "T3", "furigana": "直面[ちょくめん]する困難[こんなん]を、友達[ともだち]と乗[の]り越[こ]えたい。", "sentence_source": "generated"}, {"text": "新しい環境に直面すると、不安になるのは当然だ。", "target_word": "直面すると", "complexity_tier": "T4", "furigana": "新[あたら]しい環境[かんきょう]に直面[ちょくめん]すると、不安[ふあん]になるのは当然[とうぜん]だ。", "sentence_source": "generated"}, {"text": "彼は何度も壁に直面したが、あきらめなかった。", "target_word": "直面した", "complexity_tier": "T4", "furigana": "彼[かれ]は何度[なんど]も壁[かべ]に直面[ちょくめん]したが、あきらめなかった。", "sentence_source": "generated"}, {"text": "問題に直面したら、一人で悩まずに相談してください。", "target_word": "直面したら", "complexity_tier": "T4", "furigana": "問題[もんだい]に直面[ちょくめん]したら、一人[ひとり]で悩[なや]まずに相談[そうだん]してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直面する", "label": "活用"}, {"form": "直面した", "label": "活用"}, {"form": "直面して", "label": "活用"}, {"form": "直面している", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 困難な物事に出会うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38434, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直面", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "直線", "is_correct": false, "explanation": "「め」が「せ」に変わる一拍違いの語。"}, {"text": "直前", "is_correct": false, "explanation": "「め」が「ぜ」に変わる一拍違いの語。"}, {"text": "直進", "is_correct": false, "explanation": "「め」が「し」に変わる一拍違いの語。"}], "explanations": {"直面": "見出し語そのもの。", "直線": "「め」が「せ」に変わる一拍違いの語。", "直前": "「め」が「ぜ」に変わる一拍違いの語。", "直進": "「め」が「し」に変わる一拍違いの語。"}, "sentence_index": null, "correct_answer": "直面"}, "level_3": {"options": [{"text": "直面する", "is_correct": true, "explanation": "「困難」に出会うという意味で自然に合う。"}, {"text": "乾杯する", "is_correct": false, "explanation": "形は合うが意味が合わない。困難に乾杯するは不自然。"}, {"text": "入学する", "is_correct": false, "explanation": "形は合うが意味が合わない。困難に入学することはできない。"}, {"text": "出発する", "is_correct": false, "explanation": "形は合うが意味が合わない。困難に出発するとは言わない。"}], "explanations": {"直面する": "「困難」に出会うという意味で自然に合う。", "乾杯する": "形は合うが意味が合わない。困難に乾杯するは不自然。", "入学する": "形は合うが意味が合わない。困難に入学することはできない。", "出発する": "形は合うが意味が合わない。困難に出発するとは言わない。"}, "sentence_index": 0, "correct_answer": "直面する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、駅で偶然、昔の友達に直面した。", "explanation": "「直面」は困難に出会う意味。人と偶然会う場面には使えない。"}, {"text": "来月の楽しい旅行に直面していて、わくわくしている。", "explanation": "楽しい予定には「直面」を使わない。困難な状況にだけ使う。"}, {"text": "彼は難しい問題を直面しました。", "explanation": "「直面する」は「問題に」のように「に」を取る。「を」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
