INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38435, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "目の前に困難な状況や問題が現れること。", "primary_collocate": null, "pronunciation": "ちょくめん", "ipa": "tɕokɯmeɴ", "syllable_count": 4, "sentences": [{"text": "我々が直面する環境的限界を超越するため、CCUSの社会実装は、産業構造の転換を支える要石として、その存在感をさらに増していくであろう。", "target_word": "直面する", "complexity_tier": "T6", "furigana": "我々[われわれ]が直面[ちょくめん]する環境的[かんきょうてき]限界[げんかい]を超越[ちょうえつ]するため、CCUSの社会[しゃかい]実装[じっそう]は、産業[さんぎょう]構造[こうぞう]の転換[てんかん]を支[ささ]える要石[かなめいし]として、その存在感[そんざいかん]をさらに増[ま]していくであろう。", "sentence_source": "mined"}, {"text": "問題に直面した。", "target_word": "直面した", "complexity_tier": "T1", "furigana": "問題[もんだい]に直面[ちょくめん]した。", "sentence_source": "generated"}, {"text": "私たちは困難に直面しました。", "target_word": "直面しました", "complexity_tier": "T2", "furigana": "私[わたし]たちは困難[こんなん]に直面[ちょくめん]しました。", "sentence_source": "generated"}, {"text": "会社は危機に直面しています。", "target_word": "直面しています", "complexity_tier": "T2", "furigana": "会社[かいしゃ]は危機[きき]に直面[ちょくめん]しています。", "sentence_source": "generated"}, {"text": "直面する問題から目をそらさない。", "target_word": "直面する", "complexity_tier": "T3", "furigana": "直面[ちょくめん]する問題[もんだい]から目[め]をそらさない。", "sentence_source": "generated"}, {"text": "彼は初めて大きな失敗に直面している。", "target_word": "直面している", "complexity_tier": "T3", "furigana": "彼[かれ]は初[はじ]めて大[おお]きな失敗[しっぱい]に直面[ちょくめん]している。", "sentence_source": "generated"}, {"text": "現実に直面して、彼女は言葉を失った。", "target_word": "直面して", "complexity_tier": "T3", "furigana": "現実[げんじつ]に直面[ちょくめん]して、彼女[かのじょ]は言葉[ことば]を失[うしな]った。", "sentence_source": "generated"}, {"text": "直面した課題を一つずつ解決していこう。", "target_word": "直面した", "complexity_tier": "T3", "furigana": "直面[ちょくめん]した課題[かだい]を一[ひと]つずつ解決[かいけつ]していこう。", "sentence_source": "generated"}, {"text": "厳しい現実に直面すれば、人は成長するものだ。", "target_word": "直面すれば", "complexity_tier": "T4", "furigana": "厳[きび]しい現実[げんじつ]に直面[ちょくめん]すれば、人[ひと]は成長[せいちょう]するものだ。", "s