INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38435, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直面", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "直販", "is_correct": false, "explanation": "ちょくはん。「め」が「は」に変わる一拍違いの語。"}, {"text": "帳面", "is_correct": false, "explanation": "最初の「く」が「う」に変わる一拍違いの語。"}, {"text": "勅命", "is_correct": false, "explanation": "最後の「ん」が「い」に変わる一拍違いの語。"}], "explanations": {"直面": "見出し語そのもの。", "直販": "ちょくはん。「め」が「は」に変わる一拍違いの語。", "帳面": "最初の「く」が「う」に変わる一拍違いの語。", "勅命": "最後の「ん」が「い」に変わる一拍違いの語。"}, "sentence_index": null, "correct_answer": "直面"}, "level_3": {"options": [{"text": "直面して", "is_correct": true, "explanation": "現実に出会って言葉を失うという流れに合う。"}, {"text": "入学して", "is_correct": false, "explanation": "形は合うが意味が合わない。現実に入学することはできない。"}, {"text": "乾杯して", "is_correct": false, "explanation": "形は合うが意味が合わない。言葉を失う理由として不自然。"}, {"text": "出発して", "is_correct": false, "explanation": "形は合うが意味が合わない。現実に出発するとは言わない。"}], "explanations": {"直面して": "現実に出会って言葉を失うという流れに合う。", "入学して": "形は合うが意味が合わない。現実に入学することはできない。", "乾杯して": "形は合うが意味が合わない。言葉を失う理由として不自然。", "出発して": "形は合うが意味が合わない。現実に出発するとは言わない。"}, "sentence_index": 6, "correct_answer": "直面して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は大好きな歌手に直面して、サインをもらった。", "explanation": "「直面」は困難や問題に出会う時に使う。好きな人に会う場面には使えない。"}, {"text": "彼女は友達の誕生日パーティーに直面している。", "explanation": "楽しい行事に「直面」は使えない。「参加」などが適切。"}, {"text": "地方の自治体は、少子化を直面している。", "explanation": "「直面する」は対象を「に」で取る。「を」を使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38435, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちは厳しい状況を直面しました。", "corrected_sentence": "私たちは厳しい状況に直面しました。", "error_description": "「直面する」は対象を「に」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38435, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多くの企業が人手不足で直面している。", "corrected_sentence": "多くの企業が人手不足に直面している。", "error_description": "「直面する」の対象は「に」で示す。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38438, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主格の「が」。「降水が続いた」で、続いた主体である降水を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。続くという動作の対象にはならないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。「降水で続いた」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」。「降水と続いた」では不自然。"}], "correct_answer": "が", "explanations": {"が": "主格の「が」。「降水が続いた」で、続いた主体である降水を示す。", "を": "目的語の「を」。続くという動作の対象にはならないので合わない。", "で": "手段・場所の「で」。「降水で続いた」では文が成り立たない。", "と": "共同・引用の「と」。「降水と続いた」では不自然。"}, "error_tags": {"を": "対格（目的語）", "で": "手段・場所の格", "と": "共同・引用の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38438, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主格の「が」。「激しい降水があった」で、あった主体である降水を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「降水へあった」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「降水からあった」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「降水よりあった」では比べる対象が成立しない。"}], "correct_answer": "が", "explanations": {"が": "主格の「が」。「激しい降水があった」で、あった主体である降水を示す。", "へ": "方向の「へ」。「降水へあった」では文が成り立たない。", "から": "起点の「から」。「降水からあった」では文が成り立たない。", "より": "比較の「より」。「降水よりあった」では比べる対象が成立しない。"}, "error_tags": {"へ": "方向の格", "から": "起点の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38438, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "空から水が落ちてくることです。", "primary_collocate": null, "pronunciation": "こうすい", "ipa": "koːsɯi", "syllable_count": 4, "sentences": [{"text": "明日は関東で降水の可能性が高いそうです。", "target_word": "降水", "complexity_tier": "T3", "furigana": "明日[あした]は関東[かんとう]で降水[こうすい]の可能性[かのうせい]が高[たか]いそうです。", "sentence_source": "generated"}, {"text": "降水が続いたため、川の水かさが増えた。", "target_word": "降水", "complexity_tier": "T3", "furigana": "降水[こうすい]が続[つづ]いたため、川[かわ]の水[みず]かさが増[ふ]えた。", "sentence_source": "generated"}, {"text": "今年の夏は降水が少なく、畑の野菜が元気がない。", "target_word": "降水", "complexity_tier": "T3", "furigana": "今年[ことし]の夏[なつ]は降水[こうすい]が少[すく]なく、畑[はたけ]の野菜[やさい]が元気[げんき]がない。", "sentence_source": "generated"}, {"text": "気象庁は午後から降水があると発表した。", "target_word": "降水", "complexity_tier": "T3", "furigana": "気象庁[きしょうちょう]は午後[ごご]から降水[こうすい]があると発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "山の近くでは、降水が急に始まることがある。", "target_word": "降水", "complexity_tier": "T3", "furigana": "山[やま]の近[ちか]くでは、降水[こうすい]が急[きゅう]に始[はじ]まることがある。", "sentence_source": "generated"}, {"text": "降水のない日が続いて、ダムの水が減っている。", "target_word": "降水", "complexity_tier": "T3", "furigana": "降水[こうすい]のない日[ひ]が続[つづ]いて、ダムの水[みず]が減[へ]っている。", "sentence_source": "generated"}, {"text": "降水の心配はないので、傘は持たなくていいでしょう。", "target_word": "降水", "complexity_tier": "T3", "furigana": "降水[こうすい]の心配[しんぱい]はないので、傘[かさ]は持[も]たなくていいでしょう。", "sentence_source": "generated"}, {"text": "台風の影響で、各地で激しい降水があった。", "target_word": "降水", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、各地[かくち]で激[はげ]しい降水[こうすい]があった。", "sentence_source": "generated"}, {"text": "降水があった翌朝は、空気がきれいに感じる。", "target_word": "降水", "complexity_tier": "T3", "furigana": "降水[こうすい]があった翌朝[よくあさ]は、空気[くうき]がきれいに感[かん]じる。", "sentence_source": "generated"}, {"text": "天気予報では、夜遅くに降水が始まると言っていた。", "target_word": "降水", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]では、夜遅[よるおそ]くに降水[こうすい]が始[はじ]まると言[い]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "降水", "label": "基本形"}, {"form": "降水の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "空から水が降ってくる気象現象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38438, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "空から落ちてくる雨や雪のこと。「降水の可能性」として、雨や雪が降る見込みを表す。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合を表す語で、「可能性が高い」とは組み合わない。"}, {"text": "風速", "is_correct": false, "explanation": "風の速さを表す語で、降る見込みの説明には合わない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、降るかどうかの可能性の語にはならない。"}], "explanations": {"降水": "空から落ちてくる雨や雪のこと。「降水の可能性」として、雨や雪が降る見込みを表す。", "湿度": "空気中の水分の割合を表す語で、「可能性が高い」とは組み合わない。", "風速": "風の速さを表す語で、降る見込みの説明には合わない。", "気温": "空気の温度を表す語で、降るかどうかの可能性の語にはならない。"}, "sentence_index": 0, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "株価が急に降水して、多くの人が損をした。", "explanation": "株価などが下がることは〈降下〉。〈降水〉は空から落ちる水を指す気象の語なので、株価には使わない。"}, {"text": "午後から降水が積もって、道路が白くなる見込みだ。", "explanation": "積もるのは雪で、雪の場合は〈降雪〉を使う。〈降水〉は雨や雪を含む総称なので、積もる様子の説明には合わない。"}, {"text": "溶液の底に白い粉が降水した。", "explanation": "溶液から固体が底に沈むことは〈沈殿〉。〈降水〉は空から落ちる水の意味なので、化学の現象には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38438, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "雨や雪のこと。「降水の心配」として、傘が必要かどうかと結びつく。"}, {"text": "残業", "is_correct": false, "explanation": "仕事を延長すること。傘の必要性の話とは関係しない。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まること。傘を持つかどうかの話とは結びつかない。"}, {"text": "配送", "is_correct": false, "explanation": "商品を届けること。傘の話には合わない。"}], "explanations": {"降水": "雨や雪のこと。「降水の心配」として、傘が必要かどうかと結びつく。", "残業": "仕事を延長すること。傘の必要性の話とは関係しない。", "停電": "電気が止まること。傘を持つかどうかの話とは結びつかない。", "配送": "商品を届けること。傘の話には合わない。"}, "sentence_index": 6, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天気予報では、夜遅くに降水が上がると言っていた。", "explanation": "雨がやむことは〈雨が上がる〉と言うが、〈降水〉は空から落ちる水の語で、〈上がる〉とは合わない。"}, {"text": "夜遅くに、近くの降水を見に行った。", "explanation": "景色の滝を言うなら〈滝〉を使う。〈降水〉は空から落ちる水の気象語で、名所の滝には使わない。"}, {"text": "庭に降水をかけて、花に水をやった。", "explanation": "人が水をまくことは〈散水〉。〈降水〉は空から落ちる水なので、人がかける水には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38438, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今夜は山沿いで降水に量が増える見込みです。", "corrected_sentence": "今夜は山沿いで降水の量が増える見込みです。", "error_description": "「降水」と「量」をつなぐのは「の」。「に」は場所や時点を示すので、「降水に量」は不自然。正しくは「降水の量」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38438, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この山道では、降水な多い日は足元が滑りやすい。", "corrected_sentence": "この山道では、降水の多い日は足元が滑りやすい。", "error_description": "「降水」は名詞なので「の」で「多い」に続ける。「な」は形容動詞の語尾なので、「降水な」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38439, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「降水が多い」の〈が〉で、降水が主語になり文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は他動詞の目的語につくので、形容詞「多い」の文には合わない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は行き先や相手を表すので、「降水に多い」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や原因を表すので、「降水で多い」は述語と合わない。"}], "correct_answer": "が", "explanations": {"が": "「降水が多い」の〈が〉で、降水が主語になり文が成り立つ。", "を": "〈を〉は他動詞の目的語につくので、形容詞「多い」の文には合わない。", "に": "〈に〉は行き先や相手を表すので、「降水に多い」は文として成り立たない。", "で": "〈で〉は手段や原因を表すので、「降水で多い」は述語と合わない。"}, "error_tags": {"を": "目的語", "に": "相手・方向", "で": "手段・原因"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38439, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「降水がある」の〈が〉で、存在するものを主語として示す。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や相手を表すので、「降水とある」は存在の文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は移動の方向を表すので、「降水へある」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表すので、「降水からある」は存在の文に合わない。"}], "correct_answer": "が", "explanations": {"が": "「降水がある」の〈が〉で、存在するものを主語として示す。", "と": "〈と〉は並列や相手を表すので、「降水とある」は存在の文に合わない。", "へ": "〈へ〉は移動の方向を表すので、「降水へある」は成り立たない。", "から": "〈から〉は起点を表すので、「降水からある」は存在の文に合わない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38439, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "雨や雪など、空から地面に落ちてくる水のこと。", "primary_collocate": null, "pronunciation": "こうすい", "ipa": "koːsɯi", "syllable_count": 4, "sentences": [{"text": "冬の北国では、降水の多くが雪になる。", "target_word": "降水", "complexity_tier": "T3", "furigana": "冬[ふゆ]の北国[きたぐに]では、降水[こうすい]の多[おお]くが雪[ゆき]になる。", "sentence_source": "generated"}, {"text": "この地域は一年を通して降水が多い。", "target_word": "降水", "complexity_tier": "T3", "furigana": "この地域[ちいき]は一年[いちねん]を通[とお]して降水[こうすい]が多[おお]い。", "sentence_source": "generated"}, {"text": "降水があると、野外の運動会は中止になります。", "target_word": "降水", "complexity_tier": "T3", "furigana": "降水[こうすい]があると、野外[やがい]の運動会[うんどうかい]は中止[ちゅうし]になります。", "sentence_source": "generated"}, {"text": "雨や雪などの降水は、川や海の水の元になる。", "target_word": "降水", "complexity_tier": "T3", "furigana": "雨[あめ]や雪[ゆき]などの降水[こうすい]は、川[かわ]や海[うみ]の水[みず]の元[もと]になる。", "sentence_source": "generated"}, {"text": "今日は降水の心配がないので、洗濯物を外に干した。", "target_word": "降水", "complexity_tier": "T3", "furigana": "今日[きょう]は降水[こうすい]の心配[しんぱい]がないので、洗濯物[せんたくもの]を外[そと]に干[ほ]した。", "sentence_source": "generated"}, {"text": "砂漠は降水がほとんどないため、植物が少ない。", "target_word": "降水", "complexity_tier": "T3", "furigana": "砂漠[さばく]は降水[こうすい]がほとんどないため、植物[しょくぶつ]が少[すく]ない。", "sentence_source": "generated"}, {"text": "昨日の降水で、道路がぬれて滑りやすい。", "target_word": "降水", "complexity_tier": "T3", "furigana": "昨日[きのう]の降水[こうすい]で、道路[どうろ]がぬれて滑[すべ]りやすい。", "sentence_source": "generated"}, {"text": "梅雨の時期は、毎日のように降水がある。", "target_word": "降水", "complexity_tier": "T3", "furigana": "梅雨[つゆ]の時期[じき]は、毎日[まいにち]のように降水[こうすい]がある。", "sentence_source": "generated"}, {"text": "気温が下がると、降水が雨から雪に変わる。", "target_word": "降水", "complexity_tier": "T3", "furigana": "気温[きおん]が下[さ]がると、降水[こうすい]が雨[あめ]から雪[ゆき]に変[か]わる。", "sentence_source": "generated"}, {"text": "降水が足りないと、農家は水の心配をする。", "target_word": "降水", "complexity_tier": "T3", "furigana": "降水[こうすい]が足[た]りないと、農家[のうか]は水[みず]の心配[しんぱい]をする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "降水", "label": "基本形"}], "register": "標準", "sense_fingerprint": "雨や雪など地面に落ちてくる水そのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38439, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "「降水の多くが雪になる」の「降水」は、空から落ちてくる水を指すので入る。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水蒸気の度合いで、雪になる量の話には合わない。"}, {"text": "気圧", "is_correct": false, "explanation": "気圧は空気が押す力のことで、雪になるものではないので合わない。"}, {"text": "風速", "is_correct": false, "explanation": "風速は風の速さのことで、「雪になる」という文の主語にならない。"}], "explanations": {"降水": "「降水の多くが雪になる」の「降水」は、空から落ちてくる水を指すので入る。", "湿度": "湿度は空気中の水蒸気の度合いで、雪になる量の話には合わない。", "気圧": "気圧は空気が押す力のことで、雪になるものではないので合わない。", "風速": "風速は風の速さのことで、「雪になる」という文の主語にならない。"}, "sentence_index": 0, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飛行機がゆっくり降水して、空港に着いた。", "explanation": "ここは〈降下〉の意味。降水は空から落ちる水のことで、飛行機の動きには使わないので合わない。"}, {"text": "朝は降水が十度しかないので、コートを着て出かけた。", "explanation": "ここは〈気温〉の意味。降水は水のことで、温度の高さは言えないので合わない。"}, {"text": "熱があり、降水が三十九度もあったので病院へ行った。", "explanation": "ここは〈体温〉の意味。降水は空から落ちる水なので、人の体の熱には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38439, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "「昨日の降水で、道路がぬれて滑りやすい」の原因は雨や雪などの降水なので入る。"}, {"text": "雑草", "is_correct": false, "explanation": "雑草は植物のことで、道路をぬらす原因にはならないので合わない。"}, {"text": "砂利", "is_correct": false, "explanation": "砂利は石の粒で、道路をぬらす原因にはならないので合わない。"}, {"text": "寒暖差", "is_correct": false, "explanation": "寒暖差は気温の差のことで、道路がぬれる直接の原因にはならないので合わない。"}], "explanations": {"降水": "「昨日の降水で、道路がぬれて滑りやすい」の原因は雨や雪などの降水なので入る。", "雑草": "雑草は植物のことで、道路をぬらす原因にはならないので合わない。", "砂利": "砂利は石の粒で、道路をぬらす原因にはならないので合わない。", "寒暖差": "寒暖差は気温の差のことで、道路がぬれる直接の原因にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "強い降水で肌が焼けて、ひりひりする。", "explanation": "ここは〈日差し〉の意味。降水は空から落ちる水のことで、光の強さは言えないので合わない。"}, {"text": "夏の夕方は庭で降水をして、さっぱりした。", "explanation": "ここは〈行水〉の意味。降水は水が落ちてくることで、体を洗う行為は表せないので合わない。"}, {"text": "スープの降水が減るまで煮込んだ。", "explanation": "ここは〈水分〉の意味。降水は空から落ちる水のことで、料理の中の水分には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38439, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨夜の降水を、地面がぬれている。", "corrected_sentence": "昨夜の降水で、地面がぬれている。", "error_description": "「降水」に続く助詞の誤り。雨で地面がぬれた原因は〈で〉で表す。〈を〉は目的語につく助詞で、原因を表せないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38439, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏は降水を少なく、畑の水不足が心配だ。", "corrected_sentence": "夏は降水が少なく、畑の水不足が心配だ。", "error_description": "「降水」につく格助詞の誤り。「降水」は主語になるので〈が〉を使う。〈を〉は目的語につく助詞なので、「少ない」の文には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
