INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38440, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ふつうとはちがって、とても大きいことや小さいこと。", "primary_collocate": null, "pronunciation": "きょくたん", "ipa": "kʲokɯtaɴ", "syllable_count": 4, "sentences": [{"text": "今年の夏は、極端に暑い日が続いた。", "target_word": "極端", "complexity_tier": "T3", "furigana": "今年[ことし]の夏[なつ]は、極端[きょくたん]に暑[あつ]い日[ひ]が続[つづ]いた。", "sentence_source": "generated"}, {"text": "この服はサイズが極端に小さくて、着られません。", "target_word": "極端", "complexity_tier": "T3", "furigana": "この服[ふく]はサイズが極端[きょくたん]に小[ちい]さくて、着[き]られません。", "sentence_source": "generated"}, {"text": "極端な寒さのせいで、湖が凍ってしまった。", "target_word": "極端", "complexity_tier": "T3", "furigana": "極端[きょくたん]な寒[さむ]さのせいで、湖[みずうみ]が凍[こお]ってしまった。", "sentence_source": "generated"}, {"text": "兄と弟は、背の高さが極端にちがう。", "target_word": "極端", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]は、背[せ]の高[たか]さが極端[きょくたん]にちがう。", "sentence_source": "generated"}, {"text": "極端に安い値段の商品は、品質が心配だ。", "target_word": "極端", "complexity_tier": "T3", "furigana": "極端[きょくたん]に安[やす]い値段[ねだん]の商品[しょうひん]は、品質[ひんしつ]が心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "砂漠では昼と夜の気温差が極端に大きい。", "target_word": "極端", "complexity_tier": "T3", "furigana": "砂漠[さばく]では昼[ひる]と夜[よる]の気温差[きおんさ]が極端[きょくたん]に大[おお]きい。", "sentence_source": "generated"}, {"text": "極端に狭い部屋で、荷物を置く場所がなかった。", "target_word": "極端", "complexity_tier": "T3", "furigana": "極端[きょくたん]に狭[せま]い部屋[へや]で、荷物[にもつ]を置[お]く場所[ばしょ]がなかった。", "sentence_source": "generated"}, {"text": "彼の声は極端に小さくて、後ろの席まで聞こえなかった。", "target_word": "極端", "complexity_tier": "T3", "furigana": "彼[かれ]の声[こえ]は極端[きょくたん]に小[ちい]さくて、後[うし]ろの席[せき]まで聞[き]こえなかった。", "sentence_source": "generated"}, {"text": "極端な暑さの日は、外での運動を控えましょう。", "target_word": "極端", "complexity_tier": "T3", "furigana": "極端[きょくたん]な暑[あつ]さの日[ひ]は、外[そと]での運動[うんどう]を控[ひか]えましょう。", "sentence_source": "generated"}, {"text": "今月は極端に忙しくて、休む時間がほとんどない。", "target_word": "極端", "complexity_tier": "T3", "furigana": "今月[こんげつ]は極端[きょくたん]に忙[いそが]しくて、休[やす]む時間[じかん]がほとんどない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "極端", "label": "基本形"}, {"form": "極端な", "label": "連体形"}, {"form": "極端に", "label": "連用形"}, {"form": "極端だ", "label": "終止形"}], "register": "標準", "sense_fingerprint": "大きさや程度がふつうよりずっと大きい、または小さいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38440, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "極端", "is_correct": true, "explanation": "「極端に暑い日が続いた」の〈極端に〉で、普通より程度がずっと大きいことを表すので入る。"}, {"text": "静粛", "is_correct": false, "explanation": "静粛は「静かなさま」で、暑さの程度を表せないので合わない。"}, {"text": "自由", "is_correct": false, "explanation": "自由は制限がないさまで、暑さの程度を表せないので合わない。"}, {"text": "律儀", "is_correct": false, "explanation": "律儀は真面目で義理堅いさまで、天候の程度には使えないので合わない。"}], "explanations": {"極端": "「極端に暑い日が続いた」の〈極端に〉で、普通より程度がずっと大きいことを表すので入る。", "静粛": "静粛は「静かなさま」で、暑さの程度を表せないので合わない。", "自由": "自由は制限がないさまで、暑さの程度を表せないので合わない。", "律儀": "律儀は真面目で義理堅いさまで、天候の程度には使えないので合わない。"}, "sentence_index": 0, "correct_answer": "極端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の意見はいつも極端で、話し合いがまとまらない。", "explanation": "ここは〈考えが偏る〉の語義。程度の大きさを表す語義では、意見の偏りは言えないので合わない。"}, {"text": "好ききらいが極端で、野菜はまったく食べない。", "explanation": "ここは〈好みが偏る〉の語義。程度の大きさを表す語義では、好ききらいの偏りは言えないので合わない。"}, {"text": "極端な考え方は、周りの人を困らせることがある。", "explanation": "ここは〈考えが偏る〉の語義。程度の大きさを表す語義では、考えの偏りは表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38440, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "極端", "is_correct": true, "explanation": "「極端に狭い部屋」の〈極端に〉で、普通より程度がずっと小さいことを表すので入る。"}, {"text": "陰気", "is_correct": false, "explanation": "陰気は暗く沈んださまで、部屋の広さの程度には使えないので合わない。"}, {"text": "豪快", "is_correct": false, "explanation": "豪快は勢いがよいさまで、部屋の広さの程度を表せないので合わない。"}, {"text": "円満", "is_correct": false, "explanation": "円満は争いがなく穏やかなさまで、部屋の広さの程度には合わない。"}], "explanations": {"極端": "「極端に狭い部屋」の〈極端に〉で、普通より程度がずっと小さいことを表すので入る。", "陰気": "陰気は暗く沈んださまで、部屋の広さの程度には使えないので合わない。", "豪快": "豪快は勢いがよいさまで、部屋の広さの程度を表せないので合わない。", "円満": "円満は争いがなく穏やかなさまで、部屋の広さの程度には合わない。"}, "sentence_index": 6, "correct_answer": "極端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は何でも極端にやりすぎる性格だ。", "explanation": "ここは〈やり方が偏る〉の語義。程度の大きさを表す語義では、やり方の偏りは言えないので合わない。"}, {"text": "「全部か、まったくなしか」というのは極端な言い方だ。", "explanation": "ここは〈言い方が偏る〉の語義。程度の大きさを表す語義では、言い方の偏りは表せないので合わない。"}, {"text": "極端に走らず、真ん中の案を選びましょう。", "explanation": "ここは〈行動が偏る〉の語義。程度の大きさを表す語義では、行動の偏りは言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38440, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨量が極端な少ない年は、農作物の育ちが悪い。", "corrected_sentence": "雨量が極端に少ない年は、農作物の育ちが悪い。", "error_description": "「極端」の活用形の誤り。後ろの動詞「少ない」を修飾するので連用形〈極端に〉が正しい。連体形〈極端な〉では「少ない」にかからず誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "極端", "is_correct": true, "explanation": "「サイズが極端に小さい」の〈極端〉で、語幹に〈に〉をつけて程度を表すので入る。"}, {"text": "極端な", "is_correct": false, "explanation": "連体形で、〈サイズが〜に小さい〉の位置には入らず、名詞を修飾する形なので合わない。"}, {"text": "極端だ", "is_correct": false, "explanation": "断定の終止形で、〈に小さくて〉と続かないので合わない。"}, {"text": "極端で", "is_correct": false, "explanation": "て形で、〈に〉の前に置くと〈サイズが極端でに小さい〉となり文が成り立たないので合わない。"}], "correct_form": "極端", "base_form": "極端", "form_label": "語幹（〜に の前）", "sentence_index": 1, "explanations": {"極端": "「サイズが極端に小さい」の〈極端〉で、語幹に〈に〉をつけて程度を表すので入る。", "極端な": "連体形で、〈サイズが〜に小さい〉の位置には入らず、名詞を修飾する形なので合わない。", "極端だ": "断定の終止形で、〈に小さくて〉と続かないので合わない。", "極端で": "て形で、〈に〉の前に置くと〈サイズが極端でに小さい〉となり文が成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38440, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖の水位が極端で下がった年は、漁ができなかった。", "corrected_sentence": "湖の水位が極端に下がった年は、漁ができなかった。", "error_description": "「極端」の後ろの格助詞・活用形の誤り。動詞「下がる」を修飾するので連用形〈極端に〉が正しい。〈極端で〉は述語の形で、文が続かないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "極端", "is_correct": true, "explanation": "「彼の声は極端に小さい」の〈極端〉で、語幹に〈に〉をつけて程度を表すので入る。"}, {"text": "極端だった", "is_correct": false, "explanation": "過去の断定形で、〈に小さくて〉と続かないので合わない。"}, {"text": "極端ではない", "is_correct": false, "explanation": "否定の形で、〈声は極端ではなく〉となり〈に小さくて〉の位置には入らないので合わない。"}, {"text": "極端だろう", "is_correct": false, "explanation": "推量の形で、〈に小さくて〉と続かないので合わない。"}], "correct_form": "極端", "base_form": "極端", "form_label": "語幹（〜に の前）", "sentence_index": 7, "explanations": {"極端": "「彼の声は極端に小さい」の〈極端〉で、語幹に〈に〉をつけて程度を表すので入る。", "極端だった": "過去の断定形で、〈に小さくて〉と続かないので合わない。", "極端ではない": "否定の形で、〈声は極端ではなく〉となり〈に小さくて〉の位置には入らないので合わない。", "極端だろう": "推量の形で、〈に小さくて〉と続かないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38441, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "簡単", "is_correct": false, "explanation": "手間や難しさが少ない様子。程度が普通から離れる意味の対義語ではない。"}, {"text": "穏健", "is_correct": true, "explanation": "極端の対義語。意見や行動が過激でなく穏やかな様子を表し、この文の「極端」と対になる。"}, {"text": "丁寧", "is_correct": false, "explanation": "行き届いて注意深い様子。極端の反対語ではない。"}, {"text": "鮮明", "is_correct": false, "explanation": "はっきりしている様子。程度の大小とは関係がなく、対義語ではない。"}], "correct_answer": "穏健", "explanations": {"簡単": "手間や難しさが少ない様子。程度が普通から離れる意味の対義語ではない。", "穏健": "極端の対義語。意見や行動が過激でなく穏やかな様子を表し、この文の「極端」と対になる。", "丁寧": "行き届いて注意深い様子。極端の反対語ではない。", "鮮明": "はっきりしている様子。程度の大小とは関係がなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38441, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "活発", "is_correct": false, "explanation": "動きが盛んな様子。程度の大きさの対義語にはならない。"}, {"text": "適度", "is_correct": true, "explanation": "極端の対義語。程度が普通の範囲にとどまる様子を表し、極端な運動と対になる。"}, {"text": "確実", "is_correct": false, "explanation": "たしかで間違いがない様子。極端とは対義の関係にない。"}, {"text": "必要", "is_correct": false, "explanation": "なくてはならない様子。程度の離れ方とは関係がなく、対義語ではない。"}], "correct_answer": "適度", "explanations": {"活発": "動きが盛んな様子。程度の大きさの対義語にはならない。", "適度": "極端の対義語。程度が普通の範囲にとどまる様子を表し、極端な運動と対になる。", "確実": "たしかで間違いがない様子。極端とは対義の関係にない。", "必要": "なくてはならない様子。程度の離れ方とは関係がなく、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38441, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "程度が普通から大きく離れているさま。", "primary_collocate": null, "pronunciation": "きょくたん", "ipa": "kʲokɯtaɴ", "syllable_count": 4, "sentences": [{"text": "彼の意見は極端で、だれも賛成しなかった。", "target_word": "極端", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は極端[きょくたん]で、だれも賛成[さんせい]しなかった。", "sentence_source": "generated"}, {"text": "極端な暑さで、外に出られなかった。", "target_word": "極端", "complexity_tier": "T3", "furigana": "極端[きょくたん]な暑[あつ]さで、外[そと]に出[で]られなかった。", "sentence_source": "generated"}, {"text": "食べる量を極端に減らすと、体をこわします。", "target_word": "極端", "complexity_tier": "T3", "furigana": "食[た]べる量[りょう]を極端[きょくたん]に減[へ]らすと、体[からだ]をこわします。", "sentence_source": "generated"}, {"text": "勉強ばかりで遊ばないのは、少し極端だと思う。", "target_word": "極端", "complexity_tier": "T3", "furigana": "勉強[べんきょう]ばかりで遊[あそ]ばないのは、少[すこ]し極端[きょくたん]だと思[おも]う。", "sentence_source": "generated"}, {"text": "白か黒かで決めるのは極端な考え方だ。", "target_word": "極端", "complexity_tier": "T3", "furigana": "白[しろ]か黒[くろ]かで決[き]めるのは極端[きょくたん]な考[かんが]え方[かた]だ。", "sentence_source": "generated"}, {"text": "今年は雨が極端に少なくて、川の水が減った。", "target_word": "極端", "complexity_tier": "T3", "furigana": "今年[ことし]は雨[あめ]が極端[きょくたん]に少[すく]なくて、川[かわ]の水[みず]が減[へ]った。", "sentence_source": "generated"}, {"text": "極端な例をあげると、一日に二時間しか寝ない人もいる。", "target_word": "極端", "complexity_tier": "T3", "furigana": "極端[きょくたん]な例[れい]をあげると、一日[いちにち]に二時間[にじかん]しか寝[ね]ない人[ひと]もいる。", "sentence_source": "generated"}, {"text": "兄は極端な寒がりで、夏でもセーターを着ている。", "target_word": "極端", "complexity_tier": "T3", "furigana": "兄[あに]は極端[きょくたん]な寒[さむ]がりで、夏[なつ]でもセーターを着[き]ている。", "sentence_source": "generated"}, {"text": "値段が極端に安い商品は、品質が心配だ。", "target_word": "極端", "complexity_tier": "T3", "furigana": "値段[ねだん]が極端[きょくたん]に安[やす]い商品[しょうひん]は、品質[ひんしつ]が心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "急に走ると体に悪いので、極端な運動は避けたほうがいい。", "target_word": "極端", "complexity_tier": "T3", "furigana": "急[きゅう]に走[はし]ると体[からだ]に悪[わる]いので、極端[きょくたん]な運動[うんどう]は避[さ]けたほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "極端", "label": "基本形"}, {"form": "極端な", "label": "連体形"}, {"form": "極端に", "label": "連用形"}, {"form": "極端で", "label": "連用形（で）"}], "register": "neutral", "sense_fingerprint": "程度や考え方が普通の範囲から大きくはずれているさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38441, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元気", "is_correct": false, "explanation": "活力がある様子。意見の性質を表す語としては文が不自然。"}, {"text": "極端", "is_correct": true, "explanation": "程度が普通から大きく離れていることを表し、だれも賛成しなかったという結果と筋が通る。"}, {"text": "幸せ", "is_correct": false, "explanation": "満ち足りた気持ちを表す語で、意見の性質には合わない。"}, {"text": "大丈夫", "is_correct": false, "explanation": "問題がないさまを表す語で、意見の評価として文が通じない。"}], "explanations": {"元気": "活力がある様子。意見の性質を表す語としては文が不自然。", "極端": "程度が普通から大きく離れていることを表し、だれも賛成しなかったという結果と筋が通る。", "幸せ": "満ち足りた気持ちを表す語で、意見の性質には合わない。", "大丈夫": "問題がないさまを表す語で、意見の評価として文が通じない。"}, "sentence_index": 0, "correct_answer": "極端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の考えは、彼の考えと極端だ。", "explanation": "ここは〈異なる〉の意味。極端は程度が普通から大きく外れることを表し、二者の違いを言う場面では使わない。"}, {"text": "この料理は極端で、すぐにできる。", "explanation": "ここは〈手軽〉の意味。手軽は手間がかからない様子で、極端は程度が普通から大きく外れることなので、手間の少なさには合わない。"}, {"text": "その子は足取りが極端で、ぴょんぴょん跳ねていた。", "explanation": "ここは〈軽やか〉の意味。軽やかは身が軽く動きが滑らかな様子で、極端は程度の大きさを表すので、足取りの軽さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38441, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鮮やか", "is_correct": false, "explanation": "色や印象がはっきりしている様子で、例の性質としては合わない。"}, {"text": "極端", "is_correct": true, "explanation": "程度が普通から大きく離れている例を表し、一日二時間しか寝ない人を示すので合う。"}, {"text": "気軽", "is_correct": false, "explanation": "気楽で負担がない様子で、例をあげる文脈では不自然。"}, {"text": "静か", "is_correct": false, "explanation": "物音がしない様子で、例の性質を表すには結びつかない。"}], "explanations": {"鮮やか": "色や印象がはっきりしている様子で、例の性質としては合わない。", "極端": "程度が普通から大きく離れている例を表し、一日二時間しか寝ない人を示すので合う。", "気軽": "気楽で負担がない様子で、例をあげる文脈では不自然。", "静か": "物音がしない様子で、例の性質を表すには結びつかない。"}, "sentence_index": 6, "correct_answer": "極端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この布は極端で、手洗いが必要だ。", "explanation": "ここは〈繊細〉の意味。繊細は細かく壊れやすい様子で、極端は程度が普通から大きく外れることなので、布の質感には合わない。"}, {"text": "この道路は極端で、車が走りやすい。", "explanation": "ここは〈滑らか〉の意味。滑らかは凹凸が少ない様子で、極端は程度が普通から大きく離れることを表すので、道路の状態には合わない。"}, {"text": "この計算は極端で、誤差がない。", "explanation": "ここは〈厳密〉の意味。厳密は細部まで正確な様子で、極端は程度の大きさを表すので、計算の正確さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38441, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この靴は値段が極端を安くて、すぐ壊れた。", "corrected_sentence": "この靴は値段が極端に安くて、すぐ壊れた。", "error_description": "「極端に安い」のように、程度を表す副詞として形容詞を修飾する形なので「極端」に付くのは「に」。「を」は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "極端な", "is_correct": true, "explanation": "連体形。文中の『極端な暑さ』は、この語に『な』が付いて『暑さ』を修飾する形。"}, {"text": "極端に", "is_correct": false, "explanation": "連用形。『極端に暑い』のように動詞・形容詞を修飾する形で、名詞『暑さ』の前には置けない。"}, {"text": "極端だ", "is_correct": false, "explanation": "断定の終止形。『極端だ暑さ』と名詞を修飾できず、文が成り立たない。"}, {"text": "極端さ", "is_correct": false, "explanation": "名詞化した形。『極端さ暑さ』と続けると、名詞が二つ並んで意味が通らない。"}], "correct_form": "極端な", "base_form": "極端", "form_label": "連体形", "sentence_index": 1, "explanations": {"極端な": "連体形。文中の『極端な暑さ』は、この語に『な』が付いて『暑さ』を修飾する形。", "極端に": "連用形。『極端に暑い』のように動詞・形容詞を修飾する形で、名詞『暑さ』の前には置けない。", "極端だ": "断定の終止形。『極端だ暑さ』と名詞を修飾できず、文が成り立たない。", "極端さ": "名詞化した形。『極端さ暑さ』と続けると、名詞が二つ並んで意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38441, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部屋の温度は極端くて、暑さで眠れない。", "corrected_sentence": "この部屋の温度は極端で、暑さで眠れない。", "error_description": "「極端」は形状詞なので、形容詞の活用「くて」は付かない。断定・連続を表す「で」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "極端な", "is_correct": true, "explanation": "連体形。文中の『極端な寒がり』は、この語に『な』が付いて『寒がり』を修飾する形。"}, {"text": "極端だった", "is_correct": false, "explanation": "過去形。『極端だった寒がり』と過去の性質として述べる形になり、今も続く性質を表す文と合わない。"}, {"text": "極端なら", "is_correct": false, "explanation": "仮定の形（なら）。『極端なら寒がり』と名詞を修飾できず、条件の意味にもならない。"}, {"text": "極端ではない", "is_correct": false, "explanation": "否定形。『極端ではない寒がり』と打ち消すと、夏でもセーターを着るという文の内容と逆になる。"}], "correct_form": "極端な", "base_form": "極端", "form_label": "連体形", "sentence_index": 7, "explanations": {"極端な": "連体形。文中の『極端な寒がり』は、この語に『な』が付いて『寒がり』を修飾する形。", "極端だった": "過去形。『極端だった寒がり』と過去の性質として述べる形になり、今も続く性質を表す文と合わない。", "極端なら": "仮定の形（なら）。『極端なら寒がり』と名詞を修飾できず、条件の意味にもならない。", "極端ではない": "否定形。『極端ではない寒がり』と打ち消すと、夏でもセーターを着るという文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38442, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穏やかに", "is_correct": true, "explanation": "類語辞典で「激しい」の対義語に挙がる「穏やか」の副詞形。揺れの勢いが弱い様子を表し、「激しく揺れる」の反対になる。"}, {"text": "豊かに", "is_correct": false, "explanation": "量が多く満ちている意味で、勢いの強さの対義語ではない。"}, {"text": "鮮やかに", "is_correct": false, "explanation": "色や動きが際立つ意味で、勢いの強さの対義語ではない。"}, {"text": "明らかに", "is_correct": false, "explanation": "はっきりしている意味で、激しさとは対になる関係にない。"}], "correct_answer": "穏やかに", "explanations": {"穏やかに": "類語辞典で「激しい」の対義語に挙がる「穏やか」の副詞形。揺れの勢いが弱い様子を表し、「激しく揺れる」の反対になる。", "豊かに": "量が多く満ちている意味で、勢いの強さの対義語ではない。", "鮮やかに": "色や動きが際立つ意味で、勢いの強さの対義語ではない。", "明らかに": "はっきりしている意味で、激しさとは対になる関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38442, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穏やか", "is_correct": true, "explanation": "類語辞典で「激しい」の対義語に挙がる語。運動の勢いが弱い様子を表し、「激しい運動」と反対になる。"}, {"text": "手軽", "is_correct": false, "explanation": "手間がかからない意味で、勢いの強さの対義語ではない。"}, {"text": "確か", "is_correct": false, "explanation": "たしかであるという意味で、激しさとは対になる関係にない。"}, {"text": "賑やか", "is_correct": false, "explanation": "人が多く活気がある意味で、勢いの強さの対義語ではない。"}], "correct_answer": "穏やか", "explanations": {"穏やか": "類語辞典で「激しい」の対義語に挙がる語。運動の勢いが弱い様子を表し、「激しい運動」と反対になる。", "手軽": "手間がかからない意味で、勢いの強さの対義語ではない。", "確か": "たしかであるという意味で、激しさとは対になる関係にない。", "賑やか": "人が多く活気がある意味で、勢いの強さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38442, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "とても強い力や勢いがあること。", "primary_collocate": null, "pronunciation": "はげしい", "ipa": "hagꜜeɕiː", "syllable_count": 4, "sentences": [{"text": "昨日の夜は、激しい雨が降った。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "昨日[きのう]の夜[よる]は、激[はげ]しい雨[あめ]が降[ふ]った。", "sentence_source": "generated"}, {"text": "川の流れが激しくて、とても渡れない。", "target_word": "激しくて", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れが激[はげ]しくて、とても渡[わた]れない。", "sentence_source": "generated"}, {"text": "激しい風で、木の枝が折れた。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "激[はげ]しい風[かぜ]で、木[き]の枝[えだ]が折[お]れた。", "sentence_source": "generated"}, {"text": "激しく揺れる船の中で、気分が悪くなった。", "target_word": "激しく", "complexity_tier": "T3", "furigana": "激[はげ]しく揺[ゆ]れる船[ふね]の中[なか]で、気分[きぶん]が悪[わる]くなった。", "sentence_source": "generated"}, {"text": "波が激しい日は、海に入らないほうがいい。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "波[なみ]が激[はげ]しい日[ひ]は、海[うみ]に入[はい]らないほうがいい。", "sentence_source": "generated"}, {"text": "激しい雷の音に、犬が驚いて走り回った。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "激[はげ]しい雷[かみなり]の音[おと]に、犬[いぬ]が驚[おどろ]いて走[はし]り回[まわ]った。", "sentence_source": "generated"}, {"text": "火は激しく燃え上がり、すぐに家全体に広がった。", "target_word": "激しく", "complexity_tier": "T3", "furigana": "火[ひ]は激[はげ]しく燃[も]え上[あ]がり、すぐに家全体[いえぜんたい]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "彼は激しい勢いでドアを開けた。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "彼[かれ]は激[はげ]しい勢[いきお]いでドアを開[あ]けた。", "sentence_source": "generated"}, {"text": "雪が激しく降っているので、電車が止まった。", "target_word": "激しく", "complexity_tier": "T3", "furigana": "雪[ゆき]が激[はげ]しく降[ふ]っているので、電車[でんしゃ]が止[と]まった。", "sentence_source": "generated"}, {"text": "激しい運動をしたあとは、水をたくさん飲もう。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "激[はげ]しい運動[うんどう]をしたあとは、水[みず]をたくさん飲[の]もう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "激しい", "label": "基本形"}, {"form": "激しく", "label": "連用形"}, {"form": "激しかった", "label": "過去形"}, {"form": "激しくない", "label": "否定形"}, {"form": "激しければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "雨・風・波・火などの自然現象や動きの力や勢いがとても強い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 燃え上がり (Zipf 2.21)']::text[], '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38442, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激しい", "is_correct": true, "explanation": "連体形で「雨」を修飾し、雨の強さを表すので文の意味に合う。"}, {"text": "穏やか", "is_correct": false, "explanation": "形容動詞の語幹のままでは「雨」を修飾できない。「穏やかな雨」にするには「な」が必要で、空所には入らない。"}, {"text": "豊か", "is_correct": false, "explanation": "語幹のままでは「雨」につながらない。「豊かな雨」とすると雨量が多い意味になり、文の内容とも合わない。"}, {"text": "激しさ", "is_correct": false, "explanation": "名詞の「激しさ」は「雨」を直接修飾できず、「激しさ雨」は成り立たない。"}], "explanations": {"激しい": "連体形で「雨」を修飾し、雨の強さを表すので文の意味に合う。", "穏やか": "形容動詞の語幹のままでは「雨」を修飾できない。「穏やかな雨」にするには「な」が必要で、空所には入らない。", "豊か": "語幹のままでは「雨」につながらない。「豊かな雨」とすると雨量が多い意味になり、文の内容とも合わない。", "激しさ": "名詞の「激しさ」は「雨」を直接修飾できず、「激しさ雨」は成り立たない。"}, "sentence_index": 0, "correct_answer": "激しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この学校は生徒の入れ替わりが激しくて、先生も大変だ。", "explanation": "ここは〈程度が大きい〉の意味。勢いや力の強さではなく、変化の度合いを表す別義。"}, {"text": "この料理は激しい味がして、一口で目が覚めた。", "explanation": "ここは〈強烈〉の意味。激しいは勢いや動きに使い、味の強さを表す語としては合わない。"}, {"text": "彼女は激しい笑顔で、子どもたちを安心させた。", "explanation": "ここは〈明るい〉〈やさしい〉の意味。激しいは勢いや力の強さを表すので、やわらかい笑顔には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38442, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激しく", "is_correct": true, "explanation": "連用形の副詞で、動詞「燃え上がり」を修飾し、火の勢いを表すので文に合う。"}, {"text": "激しかった", "is_correct": false, "explanation": "過去の形で、動詞の前に副詞として置けない。「火は激しかった燃え上がり」は成り立たない。"}, {"text": "激しければ", "is_correct": false, "explanation": "仮定形は「もし激しければ」という条件節を作るため、動詞の前に置くと文が成り立たない。"}, {"text": "激しくない", "is_correct": false, "explanation": "否定形は「燃え上がり」を修飾できない。また「激しさがない」という意味になり、文の内容と食い違う。"}], "explanations": {"激しく": "連用形の副詞で、動詞「燃え上がり」を修飾し、火の勢いを表すので文に合う。", "激しかった": "過去の形で、動詞の前に副詞として置けない。「火は激しかった燃え上がり」は成り立たない。", "激しければ": "仮定形は「もし激しければ」という条件節を作るため、動詞の前に置くと文が成り立たない。", "激しくない": "否定形は「燃え上がり」を修飾できない。また「激しさがない」という意味になり、文の内容と食い違う。"}, "sentence_index": 6, "correct_answer": "激しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜は激しく寝たので、朝までぐっすり眠れた。", "explanation": "ここは〈深く〉の意味。激しいは勢いや力の強さを表すので、眠りの深さには使わない。"}, {"text": "この国は激しい面積で、一日では歩けない。", "explanation": "ここは〈大きい〉の意味。激しいは勢いや力の強さを表すので、広さを言う場合には使わない。"}, {"text": "この料理は激しい甘さで、子どもも大喜びだ。", "explanation": "ここは〈濃い〉の意味。激しいは勢いの強さを表すので、甘さの程度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38442, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "激しく雨で、道が濡れた。", "corrected_sentence": "激しい雨で、道が濡れた。", "error_description": "「雨」を修飾する形は連用形の「激しく」ではなく、連体形の「激しい」。副詞の形では名詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "激しくて", "is_correct": true, "explanation": "て形で理由を表し、流れが激しいので渡れないという文の意味に合う。"}, {"text": "激しくなかった", "is_correct": false, "explanation": "過去の否定形で、「なかった、とても渡れない」と続けると流れが激しくなかったことになり、渡れない理由と食い違う。"}, {"text": "激しくなく", "is_correct": false, "explanation": "中止形で続けると流れが激しくないことになり、渡れない理由と反対になる。"}, {"text": "激しかろう", "is_correct": false, "explanation": "推量形は「激しいだろう」という推測になり、事実として流れの状態を述べる文には合わない。"}], "correct_form": "激しくて", "base_form": "激しい", "form_label": "て形", "sentence_index": 1, "explanations": {"激しくて": "て形で理由を表し、流れが激しいので渡れないという文の意味に合う。", "激しくなかった": "過去の否定形で、「なかった、とても渡れない」と続けると流れが激しくなかったことになり、渡れない理由と食い違う。", "激しくなく": "中止形で続けると流れが激しくないことになり、渡れない理由と反対になる。", "激しかろう": "推量形は「激しいだろう」という推測になり、事実として流れの状態を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38442, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "激しさ運動をしたあとは、水をたっぷり飲もう。", "corrected_sentence": "激しい運動をしたあとは、水をたっぷり飲もう。", "error_description": "名詞「激しさ」は「運動」を直接修飾できない。連体形の「激しい」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "激しい", "is_correct": true, "explanation": "連体形で「勢い」を修飾し、ドアを勢いよく開けたという文の意味に合う。"}, {"text": "激しく", "is_correct": false, "explanation": "副詞形は名詞「勢い」を直接修飾できず、ここでは形が合わない。"}, {"text": "激しくて", "is_correct": false, "explanation": "て形は名詞「勢い」を直接修飾できず、「激しくて勢い」は成り立たない。"}, {"text": "激しければ", "is_correct": false, "explanation": "仮定形は「もし激しければ」という条件を表す。事実を述べる文には合わない。"}], "correct_form": "激しい", "base_form": "激しい", "form_label": "連体形", "sentence_index": 7, "explanations": {"激しい": "連体形で「勢い」を修飾し、ドアを勢いよく開けたという文の意味に合う。", "激しく": "副詞形は名詞「勢い」を直接修飾できず、ここでは形が合わない。", "激しくて": "て形は名詞「勢い」を直接修飾できず、「激しくて勢い」は成り立たない。", "激しければ": "仮定形は「もし激しければ」という条件を表す。事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
