INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38443, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "程度が非常に大きいさま。", "primary_collocate": null, "pronunciation": "はげしい", "ipa": "hagꜜeɕiː", "syllable_count": 4, "sentences": [{"text": "二つのチームは、最後まで激しい試合を続けた。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "二[ふた]つのチームは、最後[さいご]まで激[はげ]しい試合[しあい]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "兄と弟は、ささいなことで激しい言い争いになった。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]は、ささいなことで激[はげ]しい言[い]い争[あらそ]いになった。", "sentence_source": "generated"}, {"text": "都会では、人の出入りが激しい。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "都会[とかい]では、人[ひと]の出入[でい]りが激[はげ]しい。", "sentence_source": "generated"}, {"text": "この町は車の往来が激しくて、道を渡るのが怖い。", "target_word": "激しくて", "complexity_tier": "T3", "furigana": "この町[まち]は車[くるま]の往来[おうらい]が激[はげ]しくて、道[みち]を渡[わた]るのが怖[こわ]い。", "sentence_source": "generated"}, {"text": "彼女は感情の起伏が激しく、周りの人が困っている。", "target_word": "激しく", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は感情[かんじょう]の起伏[きふく]が激[はげ]しく、周[まわ]りの人[ひと]が困[こま]っている。", "sentence_source": "generated"}, {"text": "値段の競争が激しいので、どの店も安く売っている。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "値段[ねだん]の競争[きょうそう]が激[はげ]しいので、どの店[みせ]も安[やす]く売[う]っている。", "sentence_source": "generated"}, {"text": "激しい痛みで、夜は眠れなかった。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "激[はげ]しい痛[いた]みで、夜[よる]は眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "彼は激しい怒りを感じて、席を立った。", "target_word": "激しい", "complexity_tier": "T3", "furigana": "彼[かれ]は激[はげ]しい怒[いか]りを感[かん]じて、席[せき]を立[た]った。", "sentence_source": "generated"}, {"text": "昨日は寒暖の差が激しくて、体調をくずした。", "target_word": "激しくて", "complexity_tier": "T3", "furigana": "昨日[きのう]は寒暖[かんだん]の差[さ]が激[はげ]しくて、体調[たいちょう]をくずした。", "sentence_source": "generated"}, {"text": "激しく泣いたせいで、目が赤くなった。", "target_word": "激しく", "complexity_tier": "T3", "furigana": "激[はげ]しく泣[な]いたせいで、目[め]が赤[あか]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "激しい", "label": "基本形"}, {"form": "激しく", "label": "連用形"}, {"form": "激しかった", "label": "過去形"}, {"form": "激しくない", "label": "否定形"}, {"form": "激しければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "競争・感情・変化・痛みなどの程度が非常に大きい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38443, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激しい", "is_correct": true, "explanation": "連体形で「試合」を修飾し、競り合いの程度が大きいという文の意味に合う。"}, {"text": "穏やか", "is_correct": false, "explanation": "語幹のままでは「試合」を修飾できない。「穏やかな試合」にするには「な」が必要。"}, {"text": "豊か", "is_correct": false, "explanation": "語幹のままでは「試合」につながらない。「豊かな試合」は内容の意味が変わり、文に合わない。"}, {"text": "激しさ", "is_correct": false, "explanation": "名詞の「激しさ」は「試合」を直接修飾できず、「激しさの試合」としても不自然。"}], "explanations": {"激しい": "連体形で「試合」を修飾し、競り合いの程度が大きいという文の意味に合う。", "穏やか": "語幹のままでは「試合」を修飾できない。「穏やかな試合」にするには「な」が必要。", "豊か": "語幹のままでは「試合」につながらない。「豊かな試合」は内容の意味が変わり、文に合わない。", "激しさ": "名詞の「激しさ」は「試合」を直接修飾できず、「激しさの試合」としても不自然。"}, "sentence_index": 0, "correct_answer": "激しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "激しい風が吹いて、窓ガラスがガタガタと鳴った。", "explanation": "ここは〈勢いが強い〉の意味。風の力の強さを言う別義で、程度の大きさとは違う。"}, {"text": "激しい波が岸を叩いて、海岸の砂が削られた。", "explanation": "ここも〈勢いが強い〉の意味。波の力の強さを言う別義で、程度の大きさとは違う。"}, {"text": "激しい雨が降って、川の水があふれた。", "explanation": "ここも〈勢いが強い〉の意味。雨の勢いを言う別義で、程度の大きさとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
